-- Tenant-owned OIDC/SAML administration ABI. All public entry points reinstall
-- neither identity nor authority: callers must first use app.set_tenant_context,
-- and every function rechecks the live human membership and exact permission.

-- The JIT retention helper is owned by the isolated audit-operations role, while
-- its two SECURITY DEFINER trigger guards run as the migration role. Permit only
-- that internal call chain; runtime roles remain unable to execute the helper.
GRANT EXECUTE ON FUNCTION app.private_ldap_jit_run_is_retention_eligible_v1(uuid,uuid)
TO periapsis_migrator;
--> statement-breakpoint

-- Keep the process-readiness key inventory symmetric across LDAP, platform
-- federation, and tenant federation. Dependency tables are locked before the
-- keyring to preserve the existing fail-closed, deadlock-safe v3 ordering.
CREATE OR REPLACE FUNCTION app.verify_identity_keyring_v3(
  p_versions integer[],
  p_verifiers bytea[],
  p_active_version integer
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  BEGIN
    LOCK TABLE public.tenant_ldap_directory_operation_runs,
      public.tenant_ldap_provider_secrets,
      public.tenant_ldap_external_identities,
      public.tenant_ldap_external_identity_subject_aliases,
      public.tenant_oidc_client_secrets,
      public.tenant_saml_sp_keys,
      public.tenant_federated_external_identities,
      public.tenant_federated_external_identity_aliases,
      public.tenant_federated_authentication_transactions,
      public.tenant_saml_session_materials,
      public.platform_oidc_client_secrets,
      public.platform_saml_sp_keys,
      public.platform_federated_external_identities,
      public.platform_federated_external_identity_aliases,
      public.tenant_platform_oidc_authentication_transactions
      IN SHARE MODE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RETURN false;
  END;
  LOCK TABLE public.identity_keyring_versions IN EXCLUSIVE MODE;

  IF EXISTS (
    SELECT 1
    FROM public.tenant_ldap_directory_operation_runs AS operation
    LEFT JOIN public.identity_keyring_versions AS keyring
      ON keyring.key_version = operation.bind_secret_key_version
    WHERE operation.status = 'started'
      AND operation.expires_at > transaction_timestamp()
      AND (
        keyring.key_version IS NULL
        OR keyring.retired_at IS NOT NULL
        OR NOT operation.bind_secret_key_version = ANY(p_versions)
      )
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_oidc_client_secrets AS secret
    WHERE secret.retired_at IS NULL
      AND NOT secret.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_saml_sp_keys AS sp_key
    WHERE sp_key.retired_at IS NULL
      AND NOT sp_key.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_federated_external_identities AS identity
    WHERE identity.retired_at IS NULL
      AND NOT identity.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_federated_external_identities AS identity
    WHERE NOT EXISTS (
      SELECT 1
      FROM ONLY public.tenant_federated_external_identity_aliases AS alias
      WHERE alias.tenant_id = identity.tenant_id
        AND alias.provider_id = identity.provider_id
        AND alias.external_identity_id = identity.id
        AND alias.key_version = ANY(p_versions)
        AND (identity.retired_at IS NOT NULL OR alias.retired_at IS NULL)
    )
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_federated_authentication_transactions AS transaction
    WHERE transaction.state IN ('pending','claimed')
      AND transaction.expires_at > transaction_timestamp()
      AND transaction.verifier_key_version IS NOT NULL
      AND NOT transaction.verifier_key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_saml_session_materials AS material
    WHERE material.key_version IS NOT NULL
      AND material.ciphertext IS NOT NULL
      AND NOT material.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_oidc_client_secrets AS secret
    WHERE secret.retired_at IS NULL
      AND NOT secret.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_saml_sp_keys AS sp_key
    WHERE sp_key.retired_at IS NULL
      AND NOT sp_key.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_federated_external_identities AS identity
    WHERE identity.retired_at IS NULL
      AND NOT identity.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_federated_external_identities AS identity
    WHERE NOT EXISTS (
      SELECT 1
      FROM ONLY public.platform_federated_external_identity_aliases AS alias
      WHERE alias.platform_provider_id = identity.platform_provider_id
        AND alias.external_identity_id = identity.id
        AND alias.key_version = ANY(p_versions)
        AND (identity.retired_at IS NOT NULL OR alias.retired_at IS NULL)
    )
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_platform_oidc_authentication_transactions AS transaction
    WHERE transaction.state IN ('pending','claimed')
      AND transaction.expires_at > transaction_timestamp()
      AND NOT transaction.verifier_key_version = ANY(p_versions)
  ) THEN
    RETURN false;
  END IF;

  RETURN app.verify_identity_keyring_v2(
    p_versions, p_verifiers, p_active_version
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_tenant_federation_assert_actor_v1(
  p_request jsonb,
  p_permission text
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  actor_membership uuid;
BEGIN
  actor_membership := app.current_tenant_membership_id();
  IF app.private_mfa_require_uuidv7_v1(p_request ->> 'membershipId') IS DISTINCT FROM actor_membership
     OR p_permission NOT IN ('identity_provider.read','identity_provider.manage',
       'identity_mapping.manage','identity_policy.manage','role.grant')
     OR NOT app.current_tenant_human_has_exact_permission_v3(
       p_permission, 'tenant'
     ) THEN
    RAISE EXCEPTION 'tenant federation authority is required'
      USING ERRCODE = '42501';
  END IF;
  RETURN actor_membership;
END;
$function$;
