-- Federation administration uses the same canonical input kernel at the Go,
-- web, and database boundaries.  These helpers deliberately operate on
-- Unicode scalar values (PostgreSQL text is already valid UTF-8).
CREATE FUNCTION app.private_federation_oidc_client_id_valid_v1(p_value text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
PARALLEL SAFE
SET search_path = pg_catalog
AS $function$
  SELECT octet_length(convert_to(p_value, 'UTF8')) BETWEEN 1 AND 512
    AND p_value !~ U&'[\0001-\0020\007F-\00A0\1680\2000-\200A\2028\2029\202F\205F\3000]';
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_federation_oidc_scopes_valid_v1(
  p_scopes text[],
  p_allow_refresh boolean
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
STRICT
PARALLEL SAFE
SET search_path = pg_catalog
AS $function$
  SELECT cardinality(p_scopes) <= 31
    AND array_position(p_scopes, NULL) IS NULL
    AND array_position(p_scopes, 'openid') IS NULL
    AND p_allow_refresh =
      (array_position(p_scopes, 'offline_access') IS NOT NULL)
    AND NOT EXISTS (
      SELECT 1 FROM unnest(p_scopes) AS scope(value)
      WHERE octet_length(scope.value) NOT BETWEEN 1 AND 128
        OR scope.value !~ '^[!-~]+$'
        OR scope.value ~ '["\\]'
    )
    AND cardinality(p_scopes) = (
      SELECT count(DISTINCT scope.value)::integer
      FROM unnest(p_scopes) AS scope(value)
    );
$function$;
