CREATE FUNCTION app.private_federation_discovery_has_userinfo_v1(
  p_document bytea
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
STRICT
PARALLEL SAFE
SET search_path = pg_catalog, app
AS $function$
DECLARE
  v_document jsonb;
  v_endpoint text;
BEGIN
  v_document := convert_from(p_document, 'UTF8')::jsonb;
  IF jsonb_typeof(v_document) <> 'object'
     OR jsonb_typeof(v_document -> 'userinfo_endpoint') <> 'string' THEN
    RETURN false;
  END IF;
  v_endpoint := v_document ->> 'userinfo_endpoint';
  RETURN app.private_platform_identity_uri_is_canonical_v1(
    v_endpoint, true, true, 4096
  );
EXCEPTION WHEN data_exception OR invalid_text_representation THEN
  RETURN false;
END;
