-- Direct platform login can rotate refresh tokens, but its current execution
-- path never performs UserInfo. Tenant-bound executions retain that capability.
DO $platform_oidc_direct_activation_capability_v1$
DECLARE
  v_definition text;
  v_old text := E'     AND NOT configuration.allow_refresh_token\n';
  v_new text := E'     AND NOT configuration.use_user_info\n';
BEGIN
  SELECT pg_get_functiondef(
    'app.private_platform_oidc_direct_activation_available_v1(uuid)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
     OR strpos(substr(v_definition,strpos(v_definition,v_old) + length(v_old)),v_old) > 0 THEN
    RAISE EXCEPTION 'unexpected direct platform OIDC activation predecessor';
  END IF;
  EXECUTE replace(v_definition,v_old,v_new);
END;
$platform_oidc_direct_activation_capability_v1$;
