-- Pin the bounded public SLO projection at authority issuance.  The encrypted
-- session envelope remains row-bound while later policy/metadata revisions can
-- no longer redirect an already-authenticated session during logout.
DO $tenant_saml_logout_configuration_pin_v1$
DECLARE
  v_definition text;
  v_old text := $old$
  INSERT INTO public.tenant_saml_session_materials (
    id, tenant_id, session_id, continuation_id, user_id,
    provider_id, binding_id, provider_kind, external_identity_id,
    session_index_digest, aad_version, key_version, ciphertext, created_at
  ) VALUES (
    v_material_id, p_tenant_id, v_session_id, v_continuation_id,
    p_user_id, p_provider_id, p_binding_id, 'saml',
    p_external_identity_id, p_session_index_digest, 2,
    v_key_version, v_ciphertext, p_applied_at
  );$old$;
  v_new text := $new$
  INSERT INTO public.tenant_saml_session_materials (
    id, tenant_id, session_id, continuation_id, user_id,
    provider_id, binding_id, provider_kind, external_identity_id,
    session_index_digest, aad_version, key_version, ciphertext,
    logout_configuration, created_at
  ) VALUES (
    v_material_id, p_tenant_id, v_session_id, v_continuation_id,
    p_user_id, p_provider_id, p_binding_id, 'saml',
    p_external_identity_id, p_session_index_digest, 2,
    v_key_version, v_ciphertext,
    app.private_saml_logout_configuration_record_v1(
      p_tenant_id,p_provider_id,p_binding_id
    ),p_applied_at
  );$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.private_federated_issue_authority_v1(jsonb,uuid,uuid,uuid,bigint,bigint,bigint,uuid,uuid,public.auth_provider_kind,bigint,timestamp with time zone,bytea)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
     OR strpos(substr(v_definition,strpos(v_definition,v_old) + length(v_old)),v_old) > 0 THEN
    RAISE EXCEPTION 'unexpected tenant SAML material issuance predecessor';
  END IF;
  EXECUTE replace(v_definition,v_old,v_new);
END;
$tenant_saml_logout_configuration_pin_v1$;
