CREATE OR REPLACE FUNCTION app.guard_saml_session_material_v2()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.aad_version <> 2 OR NEW.logout_configuration IS NULL
       OR NEW.logout_disposition <> 'available'
       OR NEW.logout_operation_run_id IS NOT NULL
       OR NEW.logout_claimed_at IS NOT NULL
       OR jsonb_typeof(NEW.logout_configuration) <> 'object'
       OR pg_column_size(NEW.logout_configuration) NOT BETWEEN 2 AND 6291456
       OR NOT EXISTS (
         SELECT 1
         FROM public.tenant_federated_authentication_transactions AS transaction
         WHERE transaction.tenant_id = NEW.tenant_id
           AND transaction.operation_run_id = NEW.id
           AND transaction.protocol = 'saml'
           AND transaction.provider_id = NEW.provider_id
           AND transaction.binding_id = NEW.binding_id
           AND transaction.provider_kind = 'saml'
           AND transaction.state = 'pending'
       ) THEN
      RAISE EXCEPTION 'SAML material identity is unavailable'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.scrubbed_at IS NULL AND NEW.scrubbed_at IS NOT NULL THEN
    IF current_setting('app.saml_material_scrub_v1',true) <> 'on'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.session_id IS DISTINCT FROM OLD.session_id
       OR NEW.continuation_id IS DISTINCT FROM OLD.continuation_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.binding_id IS DISTINCT FROM OLD.binding_id
       OR NEW.provider_kind IS DISTINCT FROM OLD.provider_kind
       OR NEW.external_identity_id IS DISTINCT FROM OLD.external_identity_id
       OR NEW.aad_version IS DISTINCT FROM OLD.aad_version
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.logout_disposition IS DISTINCT FROM OLD.logout_disposition
       OR NEW.logout_operation_run_id IS DISTINCT FROM OLD.logout_operation_run_id
       OR NEW.logout_claimed_at IS DISTINCT FROM OLD.logout_claimed_at
       OR NEW.key_version IS NOT NULL OR NEW.ciphertext IS NOT NULL
       OR NEW.session_index_digest IS NOT NULL
       OR NEW.logout_configuration IS NOT NULL THEN
      RAISE EXCEPTION 'invalid SAML material scrub'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.scrubbed_at IS NOT NULL THEN
    RAISE EXCEPTION 'scrubbed SAML material is immutable'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.logout_disposition IS DISTINCT FROM OLD.logout_disposition
     OR NEW.logout_operation_run_id IS DISTINCT FROM OLD.logout_operation_run_id
     OR NEW.logout_claimed_at IS DISTINCT FROM OLD.logout_claimed_at THEN
    IF current_setting('app.saml_logout_claim_v1',true) <> 'on'
       OR OLD.logout_disposition <> 'available'
       OR OLD.logout_operation_run_id IS NOT NULL
       OR OLD.logout_claimed_at IS NOT NULL
       OR NEW.logout_disposition NOT IN ('claimed','skipped')
       OR (uuid_extract_version(NEW.logout_operation_run_id) = 7) IS NOT TRUE
       OR NEW.logout_operation_run_id = NEW.id
       OR NEW.logout_claimed_at < NEW.created_at
       OR date_trunc('microseconds',NEW.logout_claimed_at)
            <> NEW.logout_claimed_at THEN
      RAISE EXCEPTION 'invalid SAML logout material claim'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF OLD.aad_version <> 2 OR NEW.aad_version <> 2
     OR NEW.id IS DISTINCT FROM OLD.id
     OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
     OR NEW.binding_id IS DISTINCT FROM OLD.binding_id
     OR NEW.provider_kind IS DISTINCT FROM OLD.provider_kind
     OR NEW.external_identity_id IS DISTINCT FROM OLD.external_identity_id
     OR NEW.session_index_digest IS DISTINCT FROM OLD.session_index_digest
     OR NEW.logout_configuration IS DISTINCT FROM OLD.logout_configuration
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'SAML material immutable identity changed'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;
