CREATE FUNCTION app.private_tenant_federation_configured_v1(
  p_tenant_id uuid,
  p_provider_id uuid,
  p_kind public.auth_provider_kind
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  SELECT CASE p_kind
    WHEN 'oidc' THEN EXISTS (
      SELECT 1
      FROM public.tenant_oidc_provider_configurations AS configuration
      WHERE configuration.tenant_id = p_tenant_id
        AND configuration.provider_id = p_provider_id
        AND app.private_federation_oidc_client_id_valid_v1(
          configuration.client_id
        )
        AND app.private_federation_oidc_scopes_valid_v1(
          configuration.extra_scopes, configuration.allow_refresh_token
        )
        AND EXISTS (
          SELECT 1
          FROM public.tenant_oidc_client_secrets AS secret
          JOIN public.identity_keyring_versions AS keyring
            ON keyring.key_version = secret.key_version
           AND keyring.retired_at IS NULL
          WHERE secret.tenant_id = configuration.tenant_id
            AND secret.provider_id = configuration.provider_id
            AND secret.revision = configuration.client_secret_revision
            AND secret.retired_at IS NULL
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_oidc_discovery_snapshots AS discovery
          WHERE discovery.tenant_id = configuration.tenant_id
            AND discovery.provider_id = configuration.provider_id
            AND discovery.revision = configuration.discovery_revision
            AND discovery.fresh_until > statement_timestamp()
            AND (NOT configuration.use_user_info
              OR app.private_federation_discovery_has_userinfo_v1(
                discovery.document
              ))
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_oidc_jwks_snapshots AS jwks
          WHERE jwks.tenant_id = configuration.tenant_id
            AND jwks.provider_id = configuration.provider_id
            AND jwks.revision = configuration.jwks_revision
            AND jwks.fresh_until > statement_timestamp()
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_oidc_claim_rules AS claim
          WHERE claim.tenant_id = configuration.tenant_id
            AND claim.provider_id = configuration.provider_id
            AND claim.kind = 'profile' AND claim.profile_field = 'username'
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_oidc_claim_rules AS claim
          WHERE claim.tenant_id = configuration.tenant_id
            AND claim.provider_id = configuration.provider_id
            AND claim.kind = 'amr' AND claim.claim_name = 'amr'
        )
        AND configuration.use_user_info = EXISTS (
          SELECT 1 FROM public.tenant_oidc_claim_rules AS claim
          WHERE claim.tenant_id = configuration.tenant_id
            AND claim.provider_id = configuration.provider_id
            AND claim.source = 'userinfo'
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.tenant_oidc_claim_rules AS claim
          WHERE claim.tenant_id = configuration.tenant_id
            AND claim.provider_id = configuration.provider_id
            AND (
              (claim.kind IN ('scalar','profile','groups')
                AND claim.claim_name IN (
                  'iss','sub','aud','azp','exp','iat','nbf','auth_time',
                  'nonce','at_hash','acr','amr'
                ))
              OR (claim.kind IN ('acr','amr') AND (
                claim.source <> 'id_token'
                OR claim.claim_name <> claim.kind
                OR claim.required
              ))
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.tenant_oidc_claim_rules AS claim
          WHERE claim.tenant_id = configuration.tenant_id
            AND claim.provider_id = configuration.provider_id
          GROUP BY claim.source, claim.kind
          HAVING (claim.kind = 'scalar' AND count(*) > 16)
            OR (claim.kind = 'profile' AND count(*) > 8)
            OR (claim.kind = 'groups' AND count(*) > 1)
            OR (claim.kind IN ('acr','amr') AND count(*) > 1)
        )
    )
    WHEN 'saml' THEN EXISTS (
      SELECT 1
      FROM public.tenant_saml_provider_configurations AS configuration
      WHERE configuration.tenant_id = p_tenant_id
        AND configuration.provider_id = p_provider_id
        AND configuration.expected_entity_id <> configuration.sp_entity_id
        AND app.private_federation_xml10_text_valid_v1(
          configuration.expected_entity_id
        )
        AND app.private_federation_xml10_text_valid_v1(
          coalesce(configuration.subject_attribute_name, '')
        )
        AND app.private_federation_xml10_text_valid_v1(
          coalesce(configuration.subject_attribute_name_format, '')
        )
        AND NOT EXISTS (
          SELECT 1 FROM unnest(configuration.requested_authn_contexts)
            AS context(value)
          WHERE NOT app.private_federation_xml10_text_valid_v1(context.value)
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_saml_metadata_snapshots AS metadata
           WHERE metadata.tenant_id = configuration.tenant_id
             AND metadata.provider_id = configuration.provider_id
             AND metadata.revision = configuration.metadata_revision
             AND metadata.maximum_valid_until > statement_timestamp()
        )
        AND EXISTS (
          SELECT 1
          FROM public.tenant_saml_sp_keys AS key
          JOIN public.identity_keyring_versions AS keyring
            ON keyring.key_version = key.key_version
           AND keyring.retired_at IS NULL
          WHERE key.tenant_id = configuration.tenant_id
            AND key.provider_id = configuration.provider_id
            AND key.revision = configuration.sp_key_revision
            AND key.retired_at IS NULL
        )
        AND (
          SELECT count(*) BETWEEN 1 AND 8
            AND bool_and(certificate.not_before IS NOT NULL
              AND certificate.not_after IS NOT NULL
              AND certificate.not_before <= statement_timestamp()
              AND certificate.not_after > statement_timestamp())
          FROM public.tenant_saml_sp_keys AS key
          JOIN public.tenant_saml_sp_certificates AS certificate
            ON certificate.tenant_id = key.tenant_id
           AND certificate.key_id = key.id
          WHERE key.tenant_id = configuration.tenant_id
            AND key.provider_id = configuration.provider_id
            AND key.revision = configuration.sp_key_revision
            AND key.retired_at IS NULL
        )
        AND EXISTS (
          SELECT 1 FROM public.tenant_saml_attribute_rules AS attribute
          WHERE attribute.tenant_id = configuration.tenant_id
            AND attribute.provider_id = configuration.provider_id
            AND attribute.kind = 'profile' AND attribute.profile_field = 'username'
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.tenant_saml_attribute_rules AS attribute
          WHERE attribute.tenant_id = configuration.tenant_id
            AND attribute.provider_id = configuration.provider_id
            AND (NOT app.private_federation_xml10_text_valid_v1(
                attribute.attribute_name
              ) OR NOT app.private_federation_xml10_text_valid_v1(
                attribute.attribute_name_format
              ))
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.tenant_saml_attribute_rules AS attribute
          WHERE attribute.tenant_id = configuration.tenant_id
            AND attribute.provider_id = configuration.provider_id
          GROUP BY attribute.kind
          HAVING (attribute.kind = 'scalar' AND count(*) > 32)
            OR (attribute.kind = 'profile' AND count(*) > 16)
            OR (attribute.kind = 'groups' AND count(*) > 1)
        )
        AND (
          SELECT count(*) <= 64
            AND count(*) = count(DISTINCT rule.exact_value)
            AND coalesce(bool_and(
              rule.exact_value IS NOT NULL
              AND cardinality(rule.required_values) = 0
              AND app.private_federation_evidence_text_valid_v1(
                rule.exact_value, 1, 4096
              )
              AND app.private_federation_xml10_text_valid_v1(rule.exact_value)
              AND rule.exact_value = ANY(
                configuration.requested_authn_contexts
              )
            ), true)
          FROM public.tenant_federated_trust_rules AS rule
          WHERE rule.tenant_id = configuration.tenant_id
            AND rule.provider_id = configuration.provider_id
            AND rule.provider_kind = 'saml'
            AND rule.retired_at IS NULL
        )
    )
    ELSE false
  END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_tenant_saml_single_logout_configured_v1(
  p_document bytea
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
STRICT
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  document_text text;
BEGIN
  document_text := convert_from(p_document, 'UTF8');
  IF NOT xml_is_well_formed_document(document_text) THEN
    RETURN false;
  END IF;
  RETURN cardinality(xpath(
    '/*[local-name() = "EntityDescriptor" and namespace-uri() = "urn:oasis:names:tc:SAML:2.0:metadata"]/*[local-name() = "IDPSSODescriptor" and namespace-uri() = "urn:oasis:names:tc:SAML:2.0:metadata"]/*[local-name() = "SingleLogoutService" and namespace-uri() = "urn:oasis:names:tc:SAML:2.0:metadata"]',
    xmlparse(document document_text)
  )) > 0;
EXCEPTION WHEN data_exception THEN
  RETURN false;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_tenant_federation_provider_document_v1(
  p_tenant_id uuid,
  p_provider_id uuid
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  SELECT jsonb_build_object(
    'id', provider.id,
    'tenantId', provider.tenant_id,
    'key', provider.key,
    'displayName', provider.display_name,
    'description', provider.description,
    'kind', provider.kind,
    'enabled', provider.enabled,
    'configured', app.private_tenant_federation_configured_v1(
      provider.tenant_id, provider.id, provider.kind
    ),
    'binding', jsonb_build_object(
      'id', binding.id,
      'loginKey', binding.key,
      'enabled', binding.enabled,
      'version', binding.version,
      'updatedAt', binding.updated_at
    ),
    'archivedAt', provider.archived_at,
    'version', provider.version,
    'createdAt', provider.created_at,
    'updatedAt', provider.updated_at,
    'configurationRevision', policy.configuration_revision,
    'securityRevision', policy.security_revision,
    'planRevision', policy.plan_revision,
    'assurancePolicyRevision', policy.assurance_policy_revision,
    'jitMode', policy.jit_mode,
    'noMatchPolicy', policy.no_match_policy,
    'oidc', CASE WHEN provider.kind = 'oidc' THEN jsonb_build_object(
      'issuer', oidc.issuer,
      'clientId', oidc.client_id,
      'redirectUri', oidc.redirect_uri,
      'postLogoutRedirectUri', oidc.post_logout_redirect_uri,
      'extraScopes', oidc.extra_scopes,
      'allowRefreshToken', oidc.allow_refresh_token,
      'useUserInfo', oidc.use_user_info,
      'clientSecretPresent', EXISTS (
        SELECT 1 FROM public.tenant_oidc_client_secrets AS secret
        WHERE secret.tenant_id = oidc.tenant_id
          AND secret.provider_id = oidc.provider_id
          AND secret.revision = oidc.client_secret_revision
          AND secret.retired_at IS NULL
      ),
      'clientSecretRevision', oidc.client_secret_revision,
      'discoveryRevision', oidc.discovery_revision,
      'jwksRevision', oidc.jwks_revision
    ) ELSE NULL END,
    'saml', CASE WHEN provider.kind = 'saml' THEN jsonb_build_object(
      'expectedEntityId', saml.expected_entity_id,
      'spEntityId', saml.sp_entity_id,
      'acsUrl', saml.acs_url,
      'spKeyPresent', EXISTS (
        SELECT 1 FROM public.tenant_saml_sp_keys AS key
        WHERE key.tenant_id = saml.tenant_id
          AND key.provider_id = saml.provider_id
          AND key.revision = saml.sp_key_revision
          AND key.retired_at IS NULL
      ),
      'spKeyRevision', saml.sp_key_revision,
      'metadataRevision', saml.metadata_revision,
      'redirectSignatureAlgorithm', saml.redirect_signature_algorithm,
      'signaturePolicy', saml.signature_policy,
      'encryptionPolicy', saml.encryption_policy,
      'requestedAuthnContexts', saml.requested_authn_contexts,
      'subjectSource', saml.subject_source,
      'subjectAttributeName', saml.subject_attribute_name,
      'subjectAttributeNameFormat', saml.subject_attribute_name_format,
      'clockSkewSeconds', saml.clock_skew_nanoseconds / 1000000000,
      'maxAuthenticationAgeSeconds', saml.max_authentication_age_nanoseconds / 1000000000,
      'singleLogoutConfigured', EXISTS (
        SELECT 1 FROM public.tenant_saml_metadata_snapshots AS metadata
        WHERE metadata.tenant_id = saml.tenant_id
          AND metadata.provider_id = saml.provider_id
          AND metadata.revision = saml.metadata_revision
          AND app.private_tenant_saml_single_logout_configured_v1(metadata.document)
      )
    ) ELSE NULL END
  )
  FROM public.tenant_auth_providers AS provider
  JOIN public.tenant_auth_provider_bindings AS binding
    ON binding.tenant_id = provider.tenant_id
   AND binding.provider_id = provider.id
  JOIN public.tenant_federated_provider_policies AS policy
    ON policy.tenant_id = provider.tenant_id
   AND policy.provider_id = provider.id
   AND policy.binding_id = binding.id
   AND policy.provider_kind = provider.kind
  LEFT JOIN public.tenant_oidc_provider_configurations AS oidc
    ON oidc.tenant_id = provider.tenant_id
   AND oidc.provider_id = provider.id
   AND provider.kind = 'oidc'
  LEFT JOIN public.tenant_saml_provider_configurations AS saml
    ON saml.tenant_id = provider.tenant_id
   AND saml.provider_id = provider.id
   AND provider.kind = 'saml'
  WHERE provider.tenant_id = p_tenant_id
    AND provider.id = p_provider_id
    AND provider.kind IN ('oidc','saml');
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_revoke_tenant_federated_provider_sessions_v1(
  p_tenant_id uuid,
  p_provider_id uuid,
  p_reason text
)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  affected integer;
BEGIN
  UPDATE public.auth_sessions AS session
  SET revoked_at = transaction_timestamp(),
      revoke_reason = left(coalesce(nullif(btrim(p_reason), ''),
        'federated provider security revision changed'), 500)
  WHERE session.active_tenant_id = p_tenant_id
    AND session.revoked_at IS NULL
    AND EXISTS (
      SELECT 1 FROM public.auth_session_federated_provenance AS provenance
      WHERE provenance.tenant_id = p_tenant_id
        AND provenance.provider_id = p_provider_id
        AND provenance.session_id = session.id
    );
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.list_tenant_federated_auth_providers_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  after_id uuid;
  page_limit integer;
  include_archived boolean;
  result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['after','limit','includeArchived'],
    ARRAY['limit','includeArchived'], 1024
  );
  PERFORM app.current_tenant_membership_id();
  IF NOT app.current_tenant_human_has_exact_permission_v3(
    'identity_provider.read', 'tenant'
  ) THEN
    RAISE EXCEPTION 'identity_provider.read tenant scope is required'
      USING ERRCODE = '42501';
  END IF;
  after_id := CASE WHEN p_request -> 'after' = 'null'::jsonb THEN NULL
    ELSE app.private_mfa_require_uuidv7_v1(p_request ->> 'after') END;
  page_limit := (p_request ->> 'limit')::integer;
  include_archived := (p_request ->> 'includeArchived')::boolean;
  IF page_limit NOT BETWEEN 1 AND 101 OR include_archived IS NULL THEN
    RAISE EXCEPTION 'invalid tenant federation inventory request'
      USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(jsonb_agg(
    app.private_tenant_federation_provider_document_v1(context_tenant, provider.id)
    ORDER BY provider.id
  ), '[]'::jsonb)
  INTO result
  FROM (
    SELECT candidate.id
    FROM public.tenant_auth_providers AS candidate
    WHERE candidate.tenant_id = context_tenant
      AND candidate.kind IN ('oidc','saml')
      AND (include_archived OR candidate.archived_at IS NULL)
      AND (after_id IS NULL OR candidate.id > after_id)
    ORDER BY candidate.id
    LIMIT page_limit
  ) AS provider;
  RETURN result;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.get_tenant_federated_auth_provider_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['providerId'], ARRAY['providerId'], 256
  );
  PERFORM app.current_tenant_membership_id();
  IF NOT app.current_tenant_human_has_exact_permission_v3(
    'identity_provider.read', 'tenant'
  ) THEN
    RAISE EXCEPTION 'identity_provider.read tenant scope is required'
      USING ERRCODE = '42501';
  END IF;
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  result := app.private_tenant_federation_provider_document_v1(context_tenant, target_provider_id);
  IF result IS NULL THEN
    RAISE EXCEPTION 'tenant federated provider was not found'
      USING ERRCODE = 'P0002';
  END IF;
  RETURN result;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_tenant_federation_append_audit_v1(
  p_request jsonb,
  p_action text,
  p_resource_type text,
  p_resource_id uuid,
  p_before jsonb,
  p_after jsonb,
  p_metadata jsonb
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  audit jsonb := p_request -> 'audit';
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    audit,
    ARRAY['requestId','correlationId','remoteAddress','userAgent','authenticationMethod'],
    ARRAY['requestId','correlationId','userAgent','authenticationMethod'],
    4096
  );
  IF length(audit ->> 'userAgent') NOT BETWEEN 1 AND 1024
     OR length(audit ->> 'authenticationMethod') NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'invalid tenant federation audit envelope'
      USING ERRCODE = '22023';
  END IF;
  PERFORM app.append_tenant_authorization_audit(
    uuidv7(), p_action, p_resource_type, p_resource_id,
    app.private_mfa_require_uuidv7_v1(audit ->> 'requestId'),
    app.private_mfa_require_uuidv7_v1(audit ->> 'correlationId'),
    CASE WHEN audit -> 'remoteAddress' IS NULL OR audit -> 'remoteAddress' = 'null'::jsonb
      THEN NULL ELSE (audit ->> 'remoteAddress')::inet END,
    audit ->> 'userAgent', audit ->> 'authenticationMethod',
    p_before, p_after, coalesce(p_metadata, '{}'::jsonb)
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.create_tenant_federated_auth_provider_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  command_id uuid;
  target_provider_id uuid;
  new_binding_id uuid;
  target_provider_kind public.auth_provider_kind;
  idempotency_key_digest bytea;
  semantic_request_digest bytea;
  existing_command public.tenant_authorization_commands%ROWTYPE;
  oidc jsonb;
  saml jsonb;
  reason text;
  result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','commandId','providerId','bindingId','idempotencyDigest',
      'requestDigest','kind','key','loginKey','displayName','description','jitMode',
      'noMatchPolicy','oidc','saml','oidcRedirectUri','samlAcsUrl','samlSpMetadataBaseUrl',
      'reason','occurredAt','audit'],
    ARRAY['membershipId','commandId','providerId','bindingId','idempotencyDigest',
      'requestDigest','kind','key','loginKey','displayName','description','jitMode',
      'noMatchPolicy','oidcRedirectUri','samlAcsUrl','samlSpMetadataBaseUrl',
      'reason','occurredAt','audit'], 131072
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  command_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'commandId');
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  new_binding_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'bindingId');
  IF command_id IN (target_provider_id, new_binding_id) OR target_provider_id = new_binding_id THEN
    RAISE EXCEPTION 'tenant federation identifiers must be distinct'
      USING ERRCODE = '22023';
  END IF;
  target_provider_kind := (p_request ->> 'kind')::public.auth_provider_kind;
  IF target_provider_kind NOT IN ('oidc','saml') THEN
    RAISE EXCEPTION 'tenant federation provider kind is invalid'
      USING ERRCODE = '22023';
  END IF;
  oidc := p_request -> 'oidc';
  saml := p_request -> 'saml';
  IF NOT (p_request ? 'oidc') OR NOT (p_request ? 'saml')
     OR (target_provider_kind = 'oidc' AND (oidc = 'null'::jsonb OR saml <> 'null'::jsonb))
     OR (target_provider_kind = 'saml' AND (saml = 'null'::jsonb OR oidc <> 'null'::jsonb)) THEN
    RAISE EXCEPTION 'tenant federation subtype document is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF target_provider_kind = 'oidc' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      oidc,
      ARRAY['issuer','clientId','postLogoutRedirectUri','extraScopes','allowRefreshToken','useUserInfo'],
      ARRAY['issuer','clientId','postLogoutRedirectUri','extraScopes','allowRefreshToken','useUserInfo'],
      32768
    );
  ELSE
    PERFORM app.private_mfa_assert_json_object_v1(
      saml,
      ARRAY['expectedEntityId','redirectSignatureAlgorithm','signaturePolicy','encryptionPolicy',
        'requestedAuthnContexts','subjectSource','subjectAttributeName','subjectAttributeNameFormat',
        'clockSkewSeconds','maxAuthenticationAgeSeconds'],
      ARRAY['expectedEntityId','redirectSignatureAlgorithm','signaturePolicy','encryptionPolicy',
        'requestedAuthnContexts','subjectSource','clockSkewSeconds','maxAuthenticationAgeSeconds'],
      32768
    );
  END IF;
  reason := btrim(p_request ->> 'reason');
  IF NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant federation mutation reason is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT app.private_platform_identity_uri_is_canonical_v1(
       p_request ->> 'samlSpMetadataBaseUrl', true, false, 2048
     ) OR p_request ->> 'samlSpMetadataBaseUrl' !~ '/api/v1/auth/federated/saml$'
     OR octet_length(p_request ->> 'samlSpMetadataBaseUrl') +
       octet_length(p_request ->> 'loginKey') + 75 > 2048 THEN
    RAISE EXCEPTION 'tenant SAML SP metadata base URL is invalid'
      USING ERRCODE = '22023';
  END IF;
  idempotency_key_digest := decode(p_request ->> 'idempotencyDigest', 'base64');
  semantic_request_digest := decode(p_request ->> 'requestDigest', 'base64');
  IF octet_length(idempotency_key_digest) <> 32 OR octet_length(semantic_request_digest) <> 32 THEN
    RAISE EXCEPTION 'tenant federation command digest is invalid'
      USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.tenant_authorization_commands AS command
  WHERE command.tenant_id = context_tenant
    AND command.actor_membership_id = actor_membership
    AND command.operation = 'identity_provider.create'
    AND command.key_digest = idempotency_key_digest
    AND command.expires_at <= transaction_timestamp();

  SELECT command.* INTO existing_command
  FROM public.tenant_authorization_commands AS command
  WHERE command.tenant_id = context_tenant
    AND command.actor_membership_id = actor_membership
    AND command.operation = 'identity_provider.create'
    AND command.key_digest = idempotency_key_digest
  FOR UPDATE;
  IF FOUND THEN
    IF existing_command.request_digest IS DISTINCT FROM semantic_request_digest THEN
      RAISE EXCEPTION 'tenant federation idempotency key was reused'
        USING ERRCODE = '23505',
          CONSTRAINT = 'tenant_authorization_commands_replay_key';
    END IF;
    result := app.private_tenant_federation_provider_document_v1(
      context_tenant, existing_command.result_resource_id
    );
    IF result IS NULL THEN
      RAISE EXCEPTION 'tenant federation replay target is unavailable'
        USING ERRCODE = '55000';
    END IF;
    RETURN jsonb_build_object('provider', result, 'replayed', true);
  END IF;

  INSERT INTO public.tenant_auth_providers (
    id, tenant_id, key, display_name, description, kind, enabled,
    created_by_membership_id, updated_by_membership_id
  ) VALUES (
    target_provider_id, context_tenant, p_request ->> 'key',
    p_request ->> 'displayName', p_request ->> 'description', target_provider_kind,
    false, actor_membership, actor_membership
  );
  PERFORM app.private_create_tenant_auth_provider_login_claim_v1(
    context_tenant, 'tenant_provider', new_binding_id, p_request ->> 'loginKey'
  );
  INSERT INTO public.tenant_auth_provider_bindings (
    id, tenant_id, binding_family, provider_id, key, enabled,
    created_by_membership_id, updated_by_membership_id
  ) VALUES (
    new_binding_id, context_tenant, 'tenant_provider', target_provider_id,
    p_request ->> 'loginKey', false, actor_membership, actor_membership
  );
  INSERT INTO public.tenant_federated_provider_policies (
    tenant_id, provider_id, binding_id, provider_kind,
    configuration_revision, security_revision, plan_revision,
    assurance_policy_revision, jit_mode, no_match_policy, enabled
  ) VALUES (
    context_tenant, target_provider_id, new_binding_id, target_provider_kind,
    1, 1, 1, 1, p_request ->> 'jitMode', p_request ->> 'noMatchPolicy', false
  );

  IF target_provider_kind = 'oidc' THEN
    INSERT INTO public.tenant_oidc_provider_configurations (
      tenant_id, provider_id, provider_kind, issuer, client_id, redirect_uri,
      post_logout_redirect_uri, extra_scopes, allow_refresh_token, use_user_info,
      client_secret_revision, discovery_revision, jwks_revision, version
    ) VALUES (
      context_tenant, target_provider_id, 'oidc', oidc ->> 'issuer', oidc ->> 'clientId',
      p_request ->> 'oidcRedirectUri', oidc ->> 'postLogoutRedirectUri',
      ARRAY(SELECT jsonb_array_elements_text(oidc -> 'extraScopes')),
      (oidc ->> 'allowRefreshToken')::boolean,
      (oidc ->> 'useUserInfo')::boolean, 1, 1, 1, 1
    );
    INSERT INTO public.tenant_oidc_claim_rules (
      tenant_id, provider_id, source, sequence, kind, claim_name, profile_field, required
    ) VALUES
      (context_tenant, target_provider_id, 'id_token', 0, 'profile', 'preferred_username', 'username', true),
      (context_tenant, target_provider_id, 'id_token', 1, 'profile', 'email', 'email', false),
      (context_tenant, target_provider_id, 'id_token', 2, 'profile', 'name', 'display_name', false),
      (context_tenant, target_provider_id, 'id_token', 3, 'groups', 'groups', NULL, false),
      (context_tenant, target_provider_id, 'id_token', 4, 'scalar', 'roles', NULL, false),
      (context_tenant, target_provider_id, 'id_token', 5, 'acr', 'acr', NULL, false),
      (context_tenant, target_provider_id, 'id_token', 6, 'amr', 'amr', NULL, false);
  ELSE
    INSERT INTO public.tenant_saml_provider_configurations (
      tenant_id, provider_id, provider_kind, expected_entity_id, sp_entity_id,
      acs_url, sp_key_revision, metadata_revision, redirect_signature_algorithm,
      signature_policy, encryption_policy, decryption_key_versions,
      requested_authn_contexts, subject_source, subject_attribute_name,
      subject_attribute_name_format, clock_skew_nanoseconds,
      max_authentication_age_nanoseconds, version
    ) VALUES (
      context_tenant, target_provider_id, 'saml', saml ->> 'expectedEntityId',
      (p_request ->> 'samlSpMetadataBaseUrl') || '/' ||
        (SELECT tenant.slug FROM public.tenants AS tenant WHERE tenant.id = context_tenant) || '/' ||
        (p_request ->> 'loginKey') || '/metadata',
      p_request ->> 'samlAcsUrl', 1, 1,
      saml ->> 'redirectSignatureAlgorithm', saml ->> 'signaturePolicy',
      saml ->> 'encryptionPolicy', ARRAY[]::integer[],
      ARRAY(SELECT jsonb_array_elements_text(saml -> 'requestedAuthnContexts')),
      saml ->> 'subjectSource', saml ->> 'subjectAttributeName',
      saml ->> 'subjectAttributeNameFormat',
      (saml ->> 'clockSkewSeconds')::bigint * 1000000000,
      (saml ->> 'maxAuthenticationAgeSeconds')::bigint * 1000000000, 1
    );
    INSERT INTO public.tenant_saml_attribute_rules (
      tenant_id, provider_id, sequence, kind, attribute_name,
      attribute_name_format, profile_field, required
    ) VALUES
      (context_tenant, target_provider_id, 0, 'profile', 'username',
        'urn:oasis:names:tc:SAML:2.0:attrname-format:basic', 'username', true),
      (context_tenant, target_provider_id, 1, 'profile', 'email',
        'urn:oasis:names:tc:SAML:2.0:attrname-format:basic', 'email', false),
      (context_tenant, target_provider_id, 2, 'profile', 'displayName',
        'urn:oasis:names:tc:SAML:2.0:attrname-format:basic', 'display_name', false),
      (context_tenant, target_provider_id, 3, 'groups', 'groups',
        'urn:oasis:names:tc:SAML:2.0:attrname-format:basic', NULL, false);
  END IF;

  INSERT INTO public.tenant_authorization_commands (
    id, tenant_id, actor_membership_id, operation, key_digest,
    request_digest, result_resource_id, result_version
  ) VALUES (
    command_id, context_tenant, actor_membership, 'identity_provider.create',
    idempotency_key_digest, semantic_request_digest, target_provider_id, 1
  );
  result := app.private_tenant_federation_provider_document_v1(context_tenant, target_provider_id);
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.federated.created',
    'identity_provider', target_provider_id, NULL,
    jsonb_build_object(
      'id', target_provider_id, 'key', p_request ->> 'key', 'kind', target_provider_kind,
      'enabled', false, 'configured', false, 'version', 1
    ), jsonb_build_object('reason', reason, 'idempotent_replay', false)
  );
  RETURN jsonb_build_object('provider', result, 'replayed', false);
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.update_tenant_federated_auth_provider_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  oidc_configuration public.tenant_oidc_provider_configurations%ROWTYPE;
  saml_configuration public.tenant_saml_provider_configurations%ROWTYPE;
  oidc jsonb;
  saml jsonb;
  reason text;
  desired_enabled boolean;
  configuration_changed boolean := false;
  next_configuration_revision bigint;
  next_epoch_sequence integer;
  new_source_id uuid;
  new_epoch_id uuid;
  revoked_sessions integer;
  before_document jsonb;
  after_document jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','expectedVersion','displayName','description',
      'enabled','jitMode','noMatchPolicy','oidc','saml','oidcRedirectUri','samlAcsUrl',
      'samlSpMetadataBaseUrl','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','expectedVersion','displayName','description',
      'enabled','jitMode','noMatchPolicy','oidcRedirectUri','samlAcsUrl',
      'samlSpMetadataBaseUrl','reason','occurredAt','audit'], 131072
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  desired_enabled := (p_request ->> 'enabled')::boolean;
  reason := btrim(p_request ->> 'reason');
  IF expected_version < 1 OR desired_enabled IS NULL
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant federation update envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT app.private_platform_identity_uri_is_canonical_v1(
       p_request ->> 'samlSpMetadataBaseUrl', true, false, 2048
     ) OR p_request ->> 'samlSpMetadataBaseUrl' !~ '/api/v1/auth/federated/saml$' THEN
    RAISE EXCEPTION 'tenant SAML SP metadata base URL is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id
    AND candidate.kind IN ('oidc','saml')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found'
      USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant federated provider cannot be changed'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant federated provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  IF provider.version >= 2147483647 THEN
    RAISE EXCEPTION 'tenant federated provider version is exhausted'
      USING ERRCODE = '55000';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF octet_length(p_request ->> 'samlSpMetadataBaseUrl') +
       octet_length(binding.key) + 75 > 2048 THEN
    RAISE EXCEPTION 'tenant SAML SP entity ID is too long'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.version >= 2147483647 OR binding.auth_revision >= 2147483647
     OR greatest(policy.configuration_revision, policy.security_revision,
       policy.plan_revision, policy.assurance_policy_revision) >= 9007199254740991 THEN
    RAISE EXCEPTION 'tenant federation revision is exhausted'
      USING ERRCODE = '55000';
  END IF;
  before_document := app.private_tenant_federation_provider_document_v1(
    context_tenant, target_provider_id
  );
  oidc := p_request -> 'oidc';
  saml := p_request -> 'saml';
  IF NOT (p_request ? 'oidc') OR NOT (p_request ? 'saml')
     OR (provider.kind = 'oidc' AND (oidc = 'null'::jsonb OR saml <> 'null'::jsonb))
     OR (provider.kind = 'saml' AND (saml = 'null'::jsonb OR oidc <> 'null'::jsonb)) THEN
    RAISE EXCEPTION 'tenant federation subtype cannot change'
      USING ERRCODE = '22023';
  END IF;

  IF provider.kind = 'oidc' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      oidc,
      ARRAY['issuer','clientId','postLogoutRedirectUri','extraScopes','allowRefreshToken','useUserInfo'],
      ARRAY['issuer','clientId','postLogoutRedirectUri','extraScopes','allowRefreshToken','useUserInfo'],
      32768
    );
    SELECT configuration.* INTO STRICT oidc_configuration
    FROM public.tenant_oidc_provider_configurations AS configuration
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id
    FOR UPDATE;
    configuration_changed :=
      oidc_configuration.issuer IS DISTINCT FROM oidc ->> 'issuer'
      OR oidc_configuration.client_id IS DISTINCT FROM oidc ->> 'clientId'
      OR oidc_configuration.redirect_uri IS DISTINCT FROM p_request ->> 'oidcRedirectUri'
      OR oidc_configuration.post_logout_redirect_uri IS DISTINCT FROM oidc ->> 'postLogoutRedirectUri'
      OR oidc_configuration.extra_scopes IS DISTINCT FROM
        ARRAY(SELECT jsonb_array_elements_text(oidc -> 'extraScopes'))
      OR oidc_configuration.allow_refresh_token IS DISTINCT FROM (oidc ->> 'allowRefreshToken')::boolean
      OR oidc_configuration.use_user_info IS DISTINCT FROM (oidc ->> 'useUserInfo')::boolean;
  ELSE
    PERFORM app.private_mfa_assert_json_object_v1(
      saml,
      ARRAY['expectedEntityId','redirectSignatureAlgorithm','signaturePolicy','encryptionPolicy',
        'requestedAuthnContexts','subjectSource','subjectAttributeName','subjectAttributeNameFormat',
        'clockSkewSeconds','maxAuthenticationAgeSeconds'],
      ARRAY['expectedEntityId','redirectSignatureAlgorithm','signaturePolicy','encryptionPolicy',
        'requestedAuthnContexts','subjectSource','clockSkewSeconds','maxAuthenticationAgeSeconds'],
      32768
    );
    SELECT configuration.* INTO STRICT saml_configuration
    FROM public.tenant_saml_provider_configurations AS configuration
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id
    FOR UPDATE;
    configuration_changed :=
      saml_configuration.expected_entity_id IS DISTINCT FROM saml ->> 'expectedEntityId'
      OR saml_configuration.sp_entity_id IS DISTINCT FROM (
        (p_request ->> 'samlSpMetadataBaseUrl') || '/' ||
        (SELECT tenant.slug FROM public.tenants AS tenant WHERE tenant.id = context_tenant) || '/' ||
        binding.key || '/metadata'
      )
      OR saml_configuration.acs_url IS DISTINCT FROM p_request ->> 'samlAcsUrl'
      OR saml_configuration.redirect_signature_algorithm IS DISTINCT FROM saml ->> 'redirectSignatureAlgorithm'
      OR saml_configuration.signature_policy IS DISTINCT FROM saml ->> 'signaturePolicy'
      OR saml_configuration.encryption_policy IS DISTINCT FROM saml ->> 'encryptionPolicy'
      OR saml_configuration.requested_authn_contexts IS DISTINCT FROM
        ARRAY(SELECT jsonb_array_elements_text(saml -> 'requestedAuthnContexts'))
      OR saml_configuration.subject_source IS DISTINCT FROM saml ->> 'subjectSource'
      OR saml_configuration.subject_attribute_name IS DISTINCT FROM saml ->> 'subjectAttributeName'
      OR saml_configuration.subject_attribute_name_format IS DISTINCT FROM saml ->> 'subjectAttributeNameFormat'
      OR saml_configuration.clock_skew_nanoseconds IS DISTINCT FROM
        (saml ->> 'clockSkewSeconds')::bigint * 1000000000
      OR saml_configuration.max_authentication_age_nanoseconds IS DISTINCT FROM
        (saml ->> 'maxAuthenticationAgeSeconds')::bigint * 1000000000;
  END IF;
  IF configuration_changed AND (provider.enabled OR binding.enabled) THEN
    RAISE EXCEPTION 'disable the tenant federated provider before changing protocol configuration'
      USING ERRCODE = '55000';
  END IF;
  IF configuration_changed AND provider.kind = 'saml' AND EXISTS (
    SELECT 1
    FROM public.tenant_federated_trust_rules AS rule
    WHERE rule.tenant_id = context_tenant
      AND rule.provider_id = target_provider_id
      AND rule.provider_kind = 'saml'
      AND rule.retired_at IS NULL
      AND NOT rule.exact_value = ANY(
        ARRAY(SELECT jsonb_array_elements_text(
          saml -> 'requestedAuthnContexts'
        ))
      )
  ) THEN
    RAISE EXCEPTION 'tenant SAML authentication contexts would orphan an assurance rule'
      USING ERRCODE = '22023';
  END IF;

  next_configuration_revision := policy.configuration_revision +
    CASE WHEN configuration_changed THEN 1 ELSE 0 END;
  IF configuration_changed AND provider.kind = 'oidc' THEN
    UPDATE public.tenant_oidc_client_secrets AS secret
    SET retired_at = transaction_timestamp()
    WHERE secret.tenant_id = context_tenant
      AND secret.provider_id = target_provider_id
      AND secret.retired_at IS NULL;
    UPDATE public.tenant_oidc_provider_configurations AS configuration
    SET issuer = oidc ->> 'issuer',
        client_id = oidc ->> 'clientId',
        redirect_uri = p_request ->> 'oidcRedirectUri',
        post_logout_redirect_uri = oidc ->> 'postLogoutRedirectUri',
        extra_scopes = ARRAY(SELECT jsonb_array_elements_text(oidc -> 'extraScopes')),
        allow_refresh_token = (oidc ->> 'allowRefreshToken')::boolean,
        use_user_info = (oidc ->> 'useUserInfo')::boolean,
        client_secret_revision = configuration.client_secret_revision + 1,
        discovery_revision = configuration.discovery_revision + 1,
        jwks_revision = configuration.jwks_revision + 1,
        version = next_configuration_revision,
        updated_at = transaction_timestamp()
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id;
  ELSIF configuration_changed THEN
    UPDATE public.tenant_saml_sp_keys AS key
    SET retired_at = transaction_timestamp()
    WHERE key.tenant_id = context_tenant
      AND key.provider_id = target_provider_id
      AND key.retired_at IS NULL;
    UPDATE public.tenant_saml_provider_configurations AS configuration
    SET expected_entity_id = saml ->> 'expectedEntityId',
        sp_entity_id = (p_request ->> 'samlSpMetadataBaseUrl') || '/' ||
          (SELECT tenant.slug FROM public.tenants AS tenant WHERE tenant.id = context_tenant) || '/' ||
          binding.key || '/metadata',
        acs_url = p_request ->> 'samlAcsUrl',
        redirect_signature_algorithm = saml ->> 'redirectSignatureAlgorithm',
        signature_policy = saml ->> 'signaturePolicy',
        encryption_policy = saml ->> 'encryptionPolicy',
        requested_authn_contexts = ARRAY(SELECT jsonb_array_elements_text(saml -> 'requestedAuthnContexts')),
        subject_source = saml ->> 'subjectSource',
        subject_attribute_name = saml ->> 'subjectAttributeName',
        subject_attribute_name_format = saml ->> 'subjectAttributeNameFormat',
        clock_skew_nanoseconds = (saml ->> 'clockSkewSeconds')::bigint * 1000000000,
        max_authentication_age_nanoseconds =
          (saml ->> 'maxAuthenticationAgeSeconds')::bigint * 1000000000,
        sp_key_revision = configuration.sp_key_revision + 1,
        metadata_revision = configuration.metadata_revision + 1,
        version = next_configuration_revision,
        updated_at = transaction_timestamp()
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id;
  END IF;

  IF desired_enabled AND NOT app.private_tenant_federation_configured_v1(
    context_tenant, target_provider_id, provider.kind
  ) THEN
    RAISE EXCEPTION 'tenant federated provider trust material is incomplete'
      USING ERRCODE = '55000';
  END IF;
  IF desired_enabled
     AND (p_request ->> 'jitMode') = 'create'
     AND (p_request ->> 'noMatchPolicy') = 'deny'
     AND NOT EXISTS (
       SELECT 1 FROM public.tenant_federated_mapping_rule_epochs AS epoch
       WHERE epoch.tenant_id = context_tenant
         AND epoch.provider_id = target_provider_id
         AND epoch.binding_id = binding.id
         AND epoch.mapping_revision = binding.mapping_revision
         AND epoch.enabled AND epoch.ended_at IS NULL
     ) THEN
    RAISE EXCEPTION 'JIT tenant provider requires an active exact mapping rule'
      USING ERRCODE = '55000';
  END IF;

  IF binding.enabled AND NOT desired_enabled THEN
    UPDATE public.tenant_auth_provider_bindings AS candidate
    SET enabled = false,
        current_access_epoch_id = NULL,
        auth_revision = candidate.auth_revision + 1,
        updated_by_membership_id = actor_membership,
        version = candidate.version + 1,
        updated_at = transaction_timestamp()
    WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
    PERFORM app.private_close_tenant_identity_access_epoch_v1(
      context_tenant, binding.current_access_epoch_id, actor_membership,
      'federated_provider_disabled'
    );
  ELSIF NOT binding.enabled AND desired_enabled THEN
    SELECT coalesce(max(epoch.sequence), 0) + 1 INTO next_epoch_sequence
    FROM public.tenant_identity_provider_access_epochs AS epoch
    WHERE epoch.tenant_id = context_tenant AND epoch.binding_id = binding.id;
    new_source_id := uuidv7();
    new_epoch_id := uuidv7();
    INSERT INTO public.tenant_authorization_sources (
      id, tenant_id, kind, key, authoritative, protected
    ) VALUES (
      new_source_id, context_tenant, 'identity_provider_access',
      format('identity_provider_access:%s:%s', binding.id, next_epoch_sequence),
      true, false
    );
    INSERT INTO public.tenant_identity_provider_access_epochs (
      id, tenant_id, binding_id, provider_id, source_id, sequence,
      started_by_membership_id
    ) VALUES (
      new_epoch_id, context_tenant, binding.id, target_provider_id, new_source_id,
      next_epoch_sequence, actor_membership
    );
    UPDATE public.tenant_auth_provider_bindings AS candidate
    SET enabled = true,
        current_access_epoch_id = new_epoch_id,
        auth_revision = candidate.auth_revision + 1,
        updated_by_membership_id = actor_membership,
        version = candidate.version + 1,
        updated_at = transaction_timestamp()
    WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  ELSE
    UPDATE public.tenant_auth_provider_bindings AS candidate
    SET auth_revision = candidate.auth_revision + 1,
        updated_by_membership_id = actor_membership,
        version = candidate.version + 1,
        updated_at = transaction_timestamp()
    WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  END IF;

  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = next_configuration_revision,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      jit_mode = p_request ->> 'jitMode',
      no_match_policy = p_request ->> 'noMatchPolicy',
      enabled = desired_enabled,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_providers AS candidate
  SET display_name = p_request ->> 'displayName',
      description = p_request ->> 'description',
      enabled = desired_enabled,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;

  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'federated provider configuration changed'
  );
  after_document := app.private_tenant_federation_provider_document_v1(
    context_tenant, target_provider_id
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.federated.updated', 'identity_provider',
    target_provider_id,
    before_document - 'oidc' - 'saml',
    after_document - 'oidc' - 'saml',
    jsonb_build_object(
      'reason', reason, 'configuration_changed', configuration_changed,
      'revoked_sessions', revoked_sessions
    )
  );
  RETURN after_document;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.archive_tenant_federated_auth_provider_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  reason text;
  retired_mapping_source_id uuid;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','expectedVersion','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','expectedVersion','reason','occurredAt','audit'],
    8192
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  reason := btrim(p_request ->> 'reason');
  IF expected_version < 1
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant federation archive envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind IN ('oidc','saml')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found'
      USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL OR provider.enabled THEN
    RAISE EXCEPTION 'only a disabled live tenant federated provider can be archived'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant federated provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.enabled OR binding.current_access_epoch_id IS NOT NULL THEN
    RAISE EXCEPTION 'tenant federation binding must be disabled before archive'
      USING ERRCODE = '55000';
  END IF;

  FOR retired_mapping_source_id IN
    SELECT epoch.source_id
    FROM public.tenant_federated_mapping_rule_epochs AS epoch
    WHERE epoch.tenant_id = context_tenant AND epoch.provider_id = target_provider_id
      AND epoch.ended_at IS NULL
    FOR UPDATE
  LOOP
    UPDATE public.tenant_federated_mapping_rule_epochs AS epoch
    SET enabled = false, ended_at = transaction_timestamp()
    WHERE epoch.tenant_id = context_tenant AND epoch.source_id = retired_mapping_source_id;
    UPDATE public.tenant_authorization_sources AS source
    SET retired_at = transaction_timestamp()
    WHERE source.tenant_id = context_tenant AND source.id = retired_mapping_source_id
      AND source.retired_at IS NULL;
  END LOOP;
  UPDATE public.tenant_federated_trust_rules AS rule
  SET retired_at = transaction_timestamp(), enabled = false
  WHERE rule.tenant_id = context_tenant AND rule.provider_id = target_provider_id
    AND rule.retired_at IS NULL;
  UPDATE public.tenant_oidc_client_secrets AS secret
  SET retired_at = transaction_timestamp()
  WHERE secret.tenant_id = context_tenant AND secret.provider_id = target_provider_id
    AND secret.retired_at IS NULL;
  UPDATE public.tenant_saml_sp_keys AS key
  SET retired_at = transaction_timestamp()
  WHERE key.tenant_id = context_tenant AND key.provider_id = target_provider_id
    AND key.retired_at IS NULL;
  UPDATE public.tenant_federated_provider_policies AS policy
  SET enabled = false, security_revision = policy.security_revision + 1,
      plan_revision = policy.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE policy.tenant_id = context_tenant AND policy.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET archived_at = transaction_timestamp(),
      archived_by_membership_id = actor_membership,
      archive_reason = reason,
      auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET archived_at = transaction_timestamp(),
      archived_by_membership_id = actor_membership,
      archive_reason = reason,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'federated provider archived'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.federated.archived', 'identity_provider',
    target_provider_id,
    jsonb_build_object('enabled', false, 'archived', false, 'version', provider.version),
    jsonb_build_object('enabled', false, 'archived', true, 'version', provider.version + 1),
    jsonb_build_object('reason', reason, 'revoked_sessions', revoked_sessions)
  );
  RETURN jsonb_build_object('version', provider.version + 1);
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.prepare_tenant_oidc_client_secret_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  target_binding_id uuid;
  configuration public.tenant_oidc_provider_configurations%ROWTYPE;
  existing_secret_id uuid;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['membershipId','providerId','expectedVersion'],
    ARRAY['membershipId','providerId','expectedVersion'], 1024
  );
  PERFORM app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'oidc';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant OIDC provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant OIDC provider cannot change secrets'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant OIDC provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT binding.id INTO STRICT target_binding_id
  FROM public.tenant_auth_provider_bindings AS binding
  WHERE binding.tenant_id = context_tenant AND binding.provider_id = target_provider_id;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_oidc_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  SELECT secret.id INTO existing_secret_id
  FROM public.tenant_oidc_client_secrets AS secret
  WHERE secret.tenant_id = context_tenant AND secret.provider_id = target_provider_id
    AND secret.revision = configuration.client_secret_revision
    AND secret.retired_at IS NULL;
  IF configuration.client_secret_revision >= 9007199254740991 THEN
    RAISE EXCEPTION 'tenant OIDC secret revision is exhausted' USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'tenantId', context_tenant, 'providerId', target_provider_id,
    'bindingId', target_binding_id, 'currentSecretId', existing_secret_id,
    'nextSecretRevision', configuration.client_secret_revision + 1
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.replace_tenant_oidc_client_secret_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  target_binding_id uuid;
  new_secret_id uuid;
  expected_version integer;
  expected_revision bigint;
  new_key_version integer;
  new_nonce bytea;
  new_ciphertext bytea;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_oidc_provider_configurations%ROWTYPE;
  current_secret public.tenant_oidc_client_secrets%ROWTYPE;
  reason text;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'secretId','keyVersion','nonce','ciphertext','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'secretId','keyVersion','nonce','ciphertext','reason','occurredAt','audit'], 65536
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  target_binding_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'bindingId');
  new_secret_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'secretId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  expected_revision := (p_request ->> 'expectedRevision')::bigint;
  new_key_version := (p_request ->> 'keyVersion')::integer;
  new_nonce := decode(p_request ->> 'nonce', 'base64');
  new_ciphertext := decode(p_request ->> 'ciphertext', 'base64');
  reason := btrim(p_request ->> 'reason');
  IF octet_length(new_nonce) <> 12 OR octet_length(new_ciphertext) NOT BETWEEN 17 AND 8208
     OR new_key_version NOT BETWEEN 1 AND 32767
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant OIDC client-secret envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'oidc'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant OIDC provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant OIDC provider cannot change secrets'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant OIDC provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.id <> target_binding_id THEN
    RAISE EXCEPTION 'tenant OIDC binding substitution was rejected'
      USING ERRCODE = '42501';
  END IF;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_oidc_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF expected_revision <> configuration.client_secret_revision + 1 THEN
    RAISE EXCEPTION 'tenant OIDC secret revision does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO current_secret
  FROM public.tenant_oidc_client_secrets AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
    AND candidate.revision = configuration.client_secret_revision
    AND candidate.retired_at IS NULL
  FOR UPDATE;
  IF FOUND THEN
    IF current_secret.id <> new_secret_id THEN
      RAISE EXCEPTION 'tenant OIDC secret identity substitution was rejected'
        USING ERRCODE = '42501';
    END IF;
    UPDATE public.tenant_oidc_client_secrets AS secret
    SET revision = expected_revision, key_version = new_key_version,
        nonce = new_nonce, ciphertext = new_ciphertext,
        created_at = transaction_timestamp(), retired_at = NULL
    WHERE secret.id = current_secret.id;
  ELSE
    INSERT INTO public.tenant_oidc_client_secrets (
      id, tenant_id, provider_id, revision, key_version, nonce, ciphertext
    ) VALUES (
      new_secret_id, context_tenant, target_provider_id, expected_revision,
      new_key_version, new_nonce, new_ciphertext
    );
  END IF;
  UPDATE public.tenant_oidc_provider_configurations AS candidate
  SET client_secret_revision = expected_revision,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'OIDC client secret rotated'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.oidc_secret.replaced', 'identity_provider',
    target_provider_id,
    jsonb_build_object('material_present', current_secret.id IS NOT NULL,
      'material_revision', configuration.client_secret_revision,
      'provider_version', provider.version),
    jsonb_build_object('material_present', true,
      'material_revision', expected_revision,
      'provider_version', provider.version + 1),
    jsonb_build_object('reason', reason, 'key_version', new_key_version,
      'revoked_sessions', revoked_sessions)
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id, 'providerVersion', provider.version + 1,
    'secretRevision', expected_revision
  );
END;
$function$;
