CREATE FUNCTION app.replace_tenant_federated_mapping_policy_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  claim jsonb;
  rule jsonb;
  mapping_rule_id uuid;
  new_mapping_epoch_id uuid;
  new_mapping_source_id uuid;
  target_role_ids uuid[];
  canonical_roles uuid[];
  target_operator_team_id uuid;
  target_assignment_epoch_id uuid;
  next_rule_revision bigint;
  next_mapping_revision bigint;
  sequence_number integer := 0;
  target_provider_kind public.auth_provider_kind;
  reason text;
  retired_source_id uuid;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','expectedVersion','kind','oidcClaimRules',
      'samlAttributeRules','rules','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','expectedVersion','kind','oidcClaimRules',
      'samlAttributeRules','rules',
      'reason','occurredAt','audit'], 2097152
  );
  IF p_request ->> 'kind' NOT IN ('oidc','saml')
     OR jsonb_typeof(p_request -> 'oidcClaimRules') <> 'array'
     OR jsonb_typeof(p_request -> 'samlAttributeRules') <> 'array'
     OR (p_request ->> 'kind' = 'oidc' AND (
       jsonb_array_length(p_request -> 'oidcClaimRules') NOT BETWEEN 1 AND 64
       OR jsonb_array_length(p_request -> 'samlAttributeRules') <> 0))
     OR (p_request ->> 'kind' = 'saml' AND (
       jsonb_array_length(p_request -> 'samlAttributeRules') NOT BETWEEN 1 AND 64
       OR jsonb_array_length(p_request -> 'oidcClaimRules') <> 0))
     OR jsonb_typeof(p_request -> 'rules') <> 'array'
     OR jsonb_array_length(p_request -> 'rules') NOT BETWEEN 0 AND 2000 THEN
    RAISE EXCEPTION 'tenant federation mapping policy arrays are invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_mapping.manage'
  );
  PERFORM app.private_tenant_federation_assert_actor_v1(
    p_request, 'role.grant'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  target_provider_kind := (p_request ->> 'kind')::public.auth_provider_kind;
  reason := btrim(p_request ->> 'reason');
  IF NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant federation mapping mutation envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = target_provider_kind
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant federated provider cannot change mappings'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant federated provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.mapping_revision >= 9007199254740991
     OR policy.configuration_revision >= 9007199254740991
     OR policy.security_revision >= 9007199254740991
     OR policy.plan_revision >= 9007199254740991 THEN
    RAISE EXCEPTION 'tenant federation mapping revision is exhausted'
      USING ERRCODE = '55000';
  END IF;

  IF target_provider_kind = 'oidc' THEN
    DELETE FROM public.tenant_oidc_claim_rules AS existing
    WHERE existing.tenant_id = context_tenant AND existing.provider_id = target_provider_id;
    sequence_number := 0;
    FOR claim IN SELECT value FROM jsonb_array_elements(p_request -> 'oidcClaimRules')
      WITH ORDINALITY AS item(value, ordinal) ORDER BY item.ordinal
    LOOP
      PERFORM app.private_mfa_assert_json_object_v1(
        claim,
        ARRAY['source','kind','claimName','profileField','required'],
        ARRAY['source','kind','claimName','required'], 4096
      );
      INSERT INTO public.tenant_oidc_claim_rules (
        tenant_id, provider_id, source, sequence, kind, claim_name,
        profile_field, required
      ) VALUES (
        context_tenant, target_provider_id, claim ->> 'source', sequence_number,
        claim ->> 'kind', claim ->> 'claimName', claim ->> 'profileField',
        (claim ->> 'required')::boolean
      );
      sequence_number := sequence_number + 1;
    END LOOP;
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_oidc_claim_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'profile' AND candidate.profile_field = 'username'
    ) OR NOT EXISTS (
      SELECT 1 FROM public.tenant_oidc_claim_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'amr' AND candidate.claim_name = 'amr'
        AND candidate.source = 'id_token'
    ) OR EXISTS (
      SELECT 1 FROM public.tenant_oidc_claim_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind IN ('acr','amr') AND candidate.source <> 'id_token'
    ) OR EXISTS (
      SELECT 1
      FROM public.tenant_oidc_claim_rules AS candidate
      WHERE candidate.tenant_id = context_tenant
        AND candidate.provider_id = target_provider_id
      GROUP BY candidate.source,candidate.kind
      HAVING (candidate.kind = 'scalar' AND count(*) > 16)
        OR (candidate.kind = 'profile' AND count(*) > 8)
        OR (candidate.kind = 'groups' AND count(*) > 1)
        OR (candidate.kind IN ('acr','amr') AND count(*) > 1)
    ) OR (
      SELECT configuration.use_user_info
      FROM public.tenant_oidc_provider_configurations AS configuration
      WHERE configuration.tenant_id = context_tenant
        AND configuration.provider_id = target_provider_id
    ) IS DISTINCT FROM EXISTS (
      SELECT 1
      FROM public.tenant_oidc_claim_rules AS candidate
      WHERE candidate.tenant_id = context_tenant
        AND candidate.provider_id = target_provider_id
        AND candidate.source = 'userinfo'
    ) THEN
      RAISE EXCEPTION 'tenant OIDC claim extraction is not canonical'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    DELETE FROM public.tenant_saml_attribute_rules AS existing
    WHERE existing.tenant_id = context_tenant AND existing.provider_id = target_provider_id;
    sequence_number := 0;
    FOR claim IN SELECT value FROM jsonb_array_elements(p_request -> 'samlAttributeRules')
      WITH ORDINALITY AS item(value, ordinal) ORDER BY item.ordinal
    LOOP
      PERFORM app.private_mfa_assert_json_object_v1(
        claim,
        ARRAY['kind','attributeName','attributeNameFormat','profileField','required'],
        ARRAY['kind','attributeName','attributeNameFormat','required'], 4096
      );
      INSERT INTO public.tenant_saml_attribute_rules (
        tenant_id, provider_id, sequence, kind, attribute_name,
        attribute_name_format, profile_field, required
      ) VALUES (
        context_tenant, target_provider_id, sequence_number, claim ->> 'kind',
        claim ->> 'attributeName', claim ->> 'attributeNameFormat',
        claim ->> 'profileField', (claim ->> 'required')::boolean
      );
      sequence_number := sequence_number + 1;
    END LOOP;
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_saml_attribute_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'profile' AND candidate.profile_field = 'username'
    ) OR EXISTS (
      SELECT 1 FROM public.tenant_saml_attribute_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'groups'
      OFFSET 1
    ) OR EXISTS (
      SELECT candidate.attribute_name
      FROM public.tenant_saml_attribute_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'scalar'
      GROUP BY candidate.attribute_name HAVING count(*) > 1
    ) OR EXISTS (
      SELECT candidate.profile_field
      FROM public.tenant_saml_attribute_rules AS candidate
      WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
        AND candidate.kind = 'profile'
      GROUP BY candidate.profile_field HAVING count(*) > 1
    ) OR EXISTS (
      SELECT 1
      FROM public.tenant_saml_attribute_rules AS candidate
      WHERE candidate.tenant_id = context_tenant
        AND candidate.provider_id = target_provider_id
      GROUP BY candidate.kind
      HAVING (candidate.kind = 'scalar' AND count(*) > 32)
        OR (candidate.kind = 'profile' AND count(*) > 16)
        OR (candidate.kind = 'groups' AND count(*) > 1)
    ) THEN
      RAISE EXCEPTION 'tenant SAML attributes require an unambiguous username mapping'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  FOR retired_source_id IN
    SELECT epoch.source_id
    FROM public.tenant_federated_mapping_rule_epochs AS epoch
    WHERE epoch.tenant_id = context_tenant AND epoch.provider_id = target_provider_id
      AND epoch.ended_at IS NULL
    FOR UPDATE
  LOOP
    UPDATE public.tenant_federated_mapping_rule_epochs AS epoch
    SET enabled = false, ended_at = transaction_timestamp()
    WHERE epoch.tenant_id = context_tenant AND epoch.source_id = retired_source_id;
    UPDATE public.tenant_authorization_sources AS source
    SET retired_at = transaction_timestamp()
    WHERE source.tenant_id = context_tenant AND source.id = retired_source_id
      AND source.retired_at IS NULL;
  END LOOP;
  next_mapping_revision := binding.mapping_revision + 1;
  sequence_number := 1;
  FOR rule IN SELECT value FROM jsonb_array_elements(p_request -> 'rules')
    WITH ORDINALITY AS item(value, ordinal) ORDER BY item.ordinal
  LOOP
    PERFORM app.private_mfa_assert_json_object_v1(
      rule,
      ARRAY['ruleId','priority','matcherKind','claimName','matcherValue',
        'reconciliationMode','tenantSecurityGroupId','roleIds','operatorTeamId',
        'operatorTeamAssignmentEpochId','enabled'],
      ARRAY['ruleId','priority','matcherKind','matcherValue','reconciliationMode',
        'tenantSecurityGroupId','roleIds','enabled'], 65536
    );
    IF jsonb_typeof(rule -> 'roleIds') <> 'array'
       OR jsonb_array_length(rule -> 'roleIds') NOT BETWEEN 1 AND 32 THEN
      RAISE EXCEPTION 'tenant federation mapping role targets are invalid'
        USING ERRCODE = '22023';
    END IF;
    mapping_rule_id := app.private_mfa_require_uuidv7_v1(rule ->> 'ruleId');
    target_role_ids := ARRAY(
      SELECT app.private_mfa_require_uuidv7_v1(value)
      FROM jsonb_array_elements_text(rule -> 'roleIds') AS role(value)
    );
    target_operator_team_id := CASE WHEN rule -> 'operatorTeamId' IS NULL
      OR rule -> 'operatorTeamId' = 'null'::jsonb THEN NULL
      ELSE app.private_mfa_require_uuidv7_v1(rule ->> 'operatorTeamId') END;
    target_assignment_epoch_id := CASE WHEN rule -> 'operatorTeamAssignmentEpochId' IS NULL
      OR rule -> 'operatorTeamAssignmentEpochId' = 'null'::jsonb THEN NULL
      ELSE app.private_mfa_require_uuidv7_v1(rule ->> 'operatorTeamAssignmentEpochId') END;
    canonical_roles := app.private_validate_tenant_ldap_mapping_targets_v1(
      context_tenant,
      app.private_mfa_require_uuidv7_v1(rule ->> 'tenantSecurityGroupId'),
      target_role_ids, target_operator_team_id, target_assignment_epoch_id
    );
    IF rule ->> 'matcherKind' = 'group_equals' THEN
      IF rule -> 'claimName' IS NOT NULL AND rule -> 'claimName' <> 'null'::jsonb
         OR NOT EXISTS (
           SELECT 1
           FROM (
             SELECT candidate.kind
             FROM public.tenant_oidc_claim_rules AS candidate
             WHERE target_provider_kind = 'oidc' AND candidate.tenant_id = context_tenant
               AND candidate.provider_id = target_provider_id AND candidate.kind = 'groups'
             UNION ALL
             SELECT candidate.kind
             FROM public.tenant_saml_attribute_rules AS candidate
             WHERE target_provider_kind = 'saml' AND candidate.tenant_id = context_tenant
               AND candidate.provider_id = target_provider_id AND candidate.kind = 'groups'
           ) AS extraction
         ) THEN
        RAISE EXCEPTION 'group mapping requires a configured group extraction'
          USING ERRCODE = '22023';
      END IF;
    ELSIF rule ->> 'matcherKind' = 'scalar_equals' THEN
      IF NOT EXISTS (
        SELECT 1
        FROM (
          SELECT candidate.claim_name AS name
          FROM public.tenant_oidc_claim_rules AS candidate
          WHERE target_provider_kind = 'oidc' AND candidate.tenant_id = context_tenant
            AND candidate.provider_id = target_provider_id AND candidate.kind = 'scalar'
          UNION ALL
          SELECT candidate.attribute_name AS name
          FROM public.tenant_saml_attribute_rules AS candidate
          WHERE target_provider_kind = 'saml' AND candidate.tenant_id = context_tenant
            AND candidate.provider_id = target_provider_id AND candidate.kind = 'scalar'
        ) AS extraction
        WHERE extraction.name = rule ->> 'claimName'
      ) THEN
        RAISE EXCEPTION 'scalar mapping source is not configured'
          USING ERRCODE = '22023';
      END IF;
    ELSE
      RAISE EXCEPTION 'tenant federation mapping matcher is invalid'
        USING ERRCODE = '22023';
    END IF;
    SELECT coalesce(max(epoch.revision), 0) + 1 INTO next_rule_revision
    FROM public.tenant_federated_mapping_rule_epochs AS epoch
    WHERE epoch.tenant_id = context_tenant AND epoch.rule_id = mapping_rule_id;
    new_mapping_epoch_id := uuidv7();
    new_mapping_source_id := uuidv7();
    INSERT INTO public.tenant_authorization_sources (
      id, tenant_id, kind, key, authoritative, protected
    ) VALUES (
      new_mapping_source_id, context_tenant, 'identity_mapping',
      format('identity_mapping:%s:%s', mapping_rule_id, next_rule_revision),
      (rule ->> 'reconciliationMode') = 'authoritative', false
    );
    INSERT INTO public.tenant_federated_mapping_rule_epochs (
      id, tenant_id, rule_id, provider_id, binding_id, provider_kind,
      source_id, sequence, revision, mapping_revision, priority, matcher_kind,
      claim_name, matcher_value, reconciliation_mode, tenant_security_group_id,
      operator_team_id, operator_team_assignment_epoch_id, enabled
    ) VALUES (
      new_mapping_epoch_id, context_tenant, mapping_rule_id, target_provider_id, binding.id, target_provider_kind,
      new_mapping_source_id, sequence_number, next_rule_revision, next_mapping_revision,
      (rule ->> 'priority')::integer, rule ->> 'matcherKind', rule ->> 'claimName',
      rule ->> 'matcherValue', rule ->> 'reconciliationMode',
      app.private_mfa_require_uuidv7_v1(rule ->> 'tenantSecurityGroupId'),
      target_operator_team_id, target_assignment_epoch_id, (rule ->> 'enabled')::boolean
    );
    INSERT INTO public.tenant_federated_mapping_rule_role_targets (
      tenant_id, rule_epoch_id, role_id, role_principal_kind
    ) SELECT context_tenant, new_mapping_epoch_id, role_id, 'human'
      FROM unnest(canonical_roles) AS role(role_id);
    sequence_number := sequence_number + 1;
  END LOOP;

  IF target_provider_kind = 'oidc' THEN
    UPDATE public.tenant_oidc_provider_configurations AS configuration
    SET version = configuration.version + 1,
        updated_at = transaction_timestamp()
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id;
  ELSE
    UPDATE public.tenant_saml_provider_configurations AS configuration
    SET version = configuration.version + 1,
        updated_at = transaction_timestamp()
    WHERE configuration.tenant_id = context_tenant
      AND configuration.provider_id = target_provider_id;
  END IF;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET mapping_revision = next_mapping_revision,
      auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'federated mapping policy changed'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_mapping.federated.replaced', 'identity_provider',
    target_provider_id,
    jsonb_build_object('mapping_revision', binding.mapping_revision),
    jsonb_build_object('mapping_revision', next_mapping_revision,
      'provider_kind', target_provider_kind,
      'extraction_rule_count', CASE WHEN target_provider_kind = 'oidc'
        THEN jsonb_array_length(p_request -> 'oidcClaimRules')
        ELSE jsonb_array_length(p_request -> 'samlAttributeRules') END,
      'mapping_rule_count', jsonb_array_length(p_request -> 'rules')),
    jsonb_build_object('reason', reason, 'revoked_sessions', revoked_sessions)
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id, 'providerVersion', provider.version + 1,
    'mappingRevision', next_mapping_revision
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.replace_tenant_federated_assurance_policy_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  rule jsonb;
  assurance_rule_id uuid;
  asserted_exact_value text;
  asserted_required_values text[];
  next_rule_revision bigint;
  next_policy_revision bigint;
  target_provider_kind public.auth_provider_kind;
  reason text;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','expectedVersion','kind','rules','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','expectedVersion','kind','rules','reason','occurredAt','audit'],
    524288
  );
  IF p_request ->> 'kind' NOT IN ('oidc','saml')
     OR jsonb_typeof(p_request -> 'rules') <> 'array'
     OR jsonb_array_length(p_request -> 'rules') NOT BETWEEN 0 AND
       (CASE WHEN p_request ->> 'kind' = 'saml' THEN 64 ELSE 128 END) THEN
    RAISE EXCEPTION 'tenant federation assurance rule array is invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_policy.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  target_provider_kind := (p_request ->> 'kind')::public.auth_provider_kind;
  reason := btrim(p_request ->> 'reason');
  IF NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant federation assurance mutation envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = target_provider_kind
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant federated provider cannot change assurance policy'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant federated provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  next_policy_revision := policy.assurance_policy_revision + 1;
  IF next_policy_revision > 9007199254740991 THEN
    RAISE EXCEPTION 'tenant federation assurance revision is exhausted'
      USING ERRCODE = '55000';
  END IF;
  UPDATE public.tenant_federated_trust_rules AS existing
  SET retired_at = transaction_timestamp(), enabled = false
  WHERE existing.tenant_id = context_tenant AND existing.provider_id = target_provider_id
    AND existing.retired_at IS NULL;
  FOR rule IN SELECT value FROM jsonb_array_elements(p_request -> 'rules')
    WITH ORDINALITY AS item(value, ordinal) ORDER BY item.ordinal
  LOOP
    PERFORM app.private_mfa_assert_json_object_v1(
      rule,
      ARRAY['ruleId','enabled','level','exactValue','requiredValues',
        'maximumAuthenticationAgeSeconds'],
      ARRAY['ruleId','enabled','level','requiredValues','maximumAuthenticationAgeSeconds'],
      32768
    );
    IF jsonb_typeof(rule -> 'requiredValues') <> 'array'
       OR jsonb_array_length(rule -> 'requiredValues') > 128 THEN
      RAISE EXCEPTION 'tenant federation assurance values are invalid'
        USING ERRCODE = '22023';
    END IF;
    assurance_rule_id := app.private_mfa_require_uuidv7_v1(rule ->> 'ruleId');
    asserted_exact_value := CASE WHEN rule -> 'exactValue' IS NULL
      OR rule -> 'exactValue' = 'null'::jsonb THEN NULL ELSE rule ->> 'exactValue' END;
    asserted_required_values := ARRAY(
      SELECT value FROM jsonb_array_elements_text(rule -> 'requiredValues') AS entry(value)
      ORDER BY value
    );
    IF array_position(asserted_required_values, NULL) IS NOT NULL
       OR cardinality(asserted_required_values) <> (
         SELECT count(DISTINCT value)::integer
         FROM unnest(asserted_required_values) AS entry(value)
       ) OR EXISTS (
         SELECT 1 FROM unnest(asserted_required_values) AS entry(value)
         WHERE NOT app.private_federation_evidence_text_valid_v1(
           value,1,4096
         )
       ) OR (asserted_exact_value IS NOT NULL AND
         NOT app.private_federation_evidence_text_valid_v1(
           asserted_exact_value,1,4096
         )) THEN
      RAISE EXCEPTION 'tenant federation assurance evidence matcher is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF target_provider_kind = 'oidc' AND asserted_exact_value IS NULL AND cardinality(asserted_required_values) = 0
       OR target_provider_kind = 'saml' AND (asserted_exact_value IS NULL OR cardinality(asserted_required_values) <> 0)
       OR target_provider_kind = 'saml' AND NOT EXISTS (
         SELECT 1 FROM public.tenant_saml_provider_configurations AS configuration
         WHERE configuration.tenant_id = context_tenant
            AND configuration.provider_id = target_provider_id
            AND asserted_exact_value = ANY(configuration.requested_authn_contexts)
       ) THEN
      RAISE EXCEPTION 'tenant federation assurance matcher does not match provider kind'
        USING ERRCODE = '22023';
    END IF;
    SELECT coalesce(max(existing.revision), 0) + 1 INTO next_rule_revision
    FROM public.tenant_federated_trust_rules AS existing
    WHERE existing.tenant_id = context_tenant AND existing.id = assurance_rule_id;
    IF next_rule_revision > 9007199254740991 THEN
      RAISE EXCEPTION 'tenant federation assurance rule revision is exhausted'
        USING ERRCODE = '55000';
    END IF;
    INSERT INTO public.tenant_federated_trust_rules (
      id, tenant_id, provider_id, binding_id, provider_kind, revision,
      enabled, level, exact_value, required_values,
      maximum_authentication_age_seconds
    ) VALUES (
      assurance_rule_id, context_tenant, target_provider_id, binding.id, target_provider_kind,
      next_rule_revision, (rule ->> 'enabled')::boolean, rule ->> 'level',
      asserted_exact_value, asserted_required_values,
      (rule ->> 'maximumAuthenticationAgeSeconds')::integer
    );
  END LOOP;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET assurance_policy_revision = next_policy_revision,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'federated assurance policy changed'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_policy.federated.replaced', 'identity_provider',
    target_provider_id,
    jsonb_build_object('assurance_policy_revision', policy.assurance_policy_revision),
    jsonb_build_object('assurance_policy_revision', next_policy_revision,
      'provider_kind', target_provider_kind,
      'rule_count', jsonb_array_length(p_request -> 'rules')),
    jsonb_build_object('reason', reason, 'revoked_sessions', revoked_sessions)
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id, 'providerVersion', provider.version + 1,
    'assurancePolicyRevision', next_policy_revision
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.prepare_tenant_oidc_trust_documents_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  configuration public.tenant_oidc_provider_configurations%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['membershipId','providerId','expectedVersion'],
    ARRAY['membershipId','providerId','expectedVersion'], 1024
  );
  PERFORM app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'oidc';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant OIDC provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant OIDC provider cannot refresh trust documents'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant OIDC provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_oidc_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  IF greatest(configuration.discovery_revision, configuration.jwks_revision) >= 9007199254740991 THEN
    RAISE EXCEPTION 'tenant OIDC trust document revision is exhausted'
      USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'tenantId', context_tenant, 'providerId', target_provider_id,
    'issuer', configuration.issuer,
    'nextDiscoveryRevision', configuration.discovery_revision + 1,
    'nextJwksRevision', configuration.jwks_revision + 1
  );
END;
$function$;
