CREATE FUNCTION app.commit_tenant_oidc_trust_documents_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  expected_version integer;
  new_discovery_revision bigint;
  new_jwks_revision bigint;
  fetched_discovery_document bytea;
  fetched_jwks_document bytea;
  fetched_discovery_digest bytea;
  fetched_jwks_digest bytea;
  discovery_retrieved_at timestamptz;
  discovery_fresh_until timestamptz;
  jwks_retrieved_at timestamptz;
  jwks_fresh_until timestamptz;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_oidc_provider_configurations%ROWTYPE;
  pinned_signing_algorithms text[];
  reason text;
  validated_key_count integer;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','expectedVersion','issuer','discoveryRevision',
      'jwksRevision','discoveryDocument','discoveryDigest','discoveryCache',
      'jwksDocument','jwksDigest','jwksCache','clientAuthentication',
      'signingAlgorithms','keyCount','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','expectedVersion','issuer','discoveryRevision',
      'jwksRevision','discoveryDocument','discoveryDigest','discoveryCache',
      'jwksDocument','jwksDigest','jwksCache','clientAuthentication',
      'signingAlgorithms','keyCount','reason','occurredAt','audit'], 2097152
  );
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request -> 'discoveryCache',
    ARRAY['retrievedAt','freshUntil','cacheable','mustRevalidate'],
    ARRAY['retrievedAt','freshUntil','cacheable','mustRevalidate'], 2048
  );
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request -> 'jwksCache',
    ARRAY['retrievedAt','freshUntil','cacheable','mustRevalidate'],
    ARRAY['retrievedAt','freshUntil','cacheable','mustRevalidate'], 2048
  );
  IF jsonb_typeof(p_request -> 'signingAlgorithms') <> 'array'
     OR jsonb_array_length(p_request -> 'signingAlgorithms') NOT BETWEEN 1 AND 16 THEN
    RAISE EXCEPTION 'tenant OIDC signing algorithm policy is invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  new_discovery_revision := (p_request ->> 'discoveryRevision')::bigint;
  new_jwks_revision := (p_request ->> 'jwksRevision')::bigint;
  fetched_discovery_document := decode(p_request ->> 'discoveryDocument', 'base64');
  fetched_jwks_document := decode(p_request ->> 'jwksDocument', 'base64');
  fetched_discovery_digest := decode(p_request ->> 'discoveryDigest', 'base64');
  fetched_jwks_digest := decode(p_request ->> 'jwksDigest', 'base64');
  discovery_retrieved_at := (p_request -> 'discoveryCache' ->> 'retrievedAt')::timestamptz;
  discovery_fresh_until := (p_request -> 'discoveryCache' ->> 'freshUntil')::timestamptz;
  jwks_retrieved_at := (p_request -> 'jwksCache' ->> 'retrievedAt')::timestamptz;
  jwks_fresh_until := (p_request -> 'jwksCache' ->> 'freshUntil')::timestamptz;
  pinned_signing_algorithms := ARRAY(
    SELECT value FROM jsonb_array_elements_text(p_request -> 'signingAlgorithms') AS algorithm(value)
    ORDER BY value
  );
  validated_key_count := (p_request ->> 'keyCount')::integer;
  reason := btrim(p_request ->> 'reason');
  IF octet_length(fetched_discovery_document) NOT BETWEEN 2 AND 1048576
     OR octet_length(fetched_jwks_document) NOT BETWEEN 2 AND 1048576
     OR octet_length(fetched_discovery_digest) <> 32 OR fetched_discovery_digest <> sha256(fetched_discovery_document)
     OR octet_length(fetched_jwks_digest) <> 32 OR fetched_jwks_digest <> sha256(fetched_jwks_document)
     OR validated_key_count NOT BETWEEN 1 AND 32
     OR cardinality(pinned_signing_algorithms) <> (
       SELECT count(DISTINCT value)::integer FROM unnest(pinned_signing_algorithms) AS item(value)
     ) OR NOT isfinite(discovery_retrieved_at)
     OR NOT isfinite(discovery_fresh_until)
     OR discovery_retrieved_at > statement_timestamp()
     OR discovery_fresh_until <= statement_timestamp()
     OR discovery_fresh_until < discovery_retrieved_at
     OR discovery_fresh_until > discovery_retrieved_at + interval '7 days'
     OR NOT isfinite(jwks_retrieved_at)
     OR NOT isfinite(jwks_fresh_until)
     OR jwks_retrieved_at > statement_timestamp()
     OR jwks_fresh_until <= statement_timestamp()
     OR jwks_fresh_until < jwks_retrieved_at
     OR jwks_fresh_until > jwks_retrieved_at + interval '7 days'
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant OIDC trust document envelope is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'oidc'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant OIDC provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant OIDC provider cannot refresh trust documents'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant OIDC provider changed during trust document fetch'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_oidc_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF configuration.issuer IS DISTINCT FROM p_request ->> 'issuer'
     OR new_discovery_revision <> configuration.discovery_revision + 1
     OR new_jwks_revision <> configuration.jwks_revision + 1 THEN
    RAISE EXCEPTION 'tenant OIDC trust document revision does not match'
      USING ERRCODE = '40001';
  END IF;
  INSERT INTO public.tenant_oidc_discovery_snapshots (
    tenant_id, provider_id, revision, issuer, document, document_digest,
    retrieved_at, fresh_until, cacheable, must_revalidate,
    client_authentication, signing_algorithms
  ) VALUES (
    context_tenant, target_provider_id, new_discovery_revision, p_request ->> 'issuer',
    fetched_discovery_document, fetched_discovery_digest,
    discovery_retrieved_at, discovery_fresh_until,
    (p_request -> 'discoveryCache' ->> 'cacheable')::boolean,
    (p_request -> 'discoveryCache' ->> 'mustRevalidate')::boolean,
    p_request ->> 'clientAuthentication', pinned_signing_algorithms
  );
  INSERT INTO public.tenant_oidc_jwks_snapshots (
    tenant_id, provider_id, revision, document, document_digest,
    retrieved_at, fresh_until, cacheable, must_revalidate
  ) VALUES (
    context_tenant, target_provider_id, new_jwks_revision, fetched_jwks_document, fetched_jwks_digest,
    jwks_retrieved_at, jwks_fresh_until,
    (p_request -> 'jwksCache' ->> 'cacheable')::boolean,
    (p_request -> 'jwksCache' ->> 'mustRevalidate')::boolean
  );
  UPDATE public.tenant_oidc_provider_configurations AS candidate
  SET discovery_revision = new_discovery_revision,
      jwks_revision = new_jwks_revision,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'OIDC trust documents refreshed'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.oidc_trust.refreshed', 'identity_provider',
    target_provider_id,
    jsonb_build_object('discovery_revision', configuration.discovery_revision,
      'jwks_revision', configuration.jwks_revision, 'provider_version', provider.version),
    jsonb_build_object('discovery_revision', new_discovery_revision,
      'jwks_revision', new_jwks_revision, 'provider_version', provider.version + 1,
      'key_count', validated_key_count),
    jsonb_build_object('reason', reason, 'revoked_sessions', revoked_sessions)
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id, 'providerVersion', provider.version + 1,
    'discoveryRevision', new_discovery_revision, 'jwksRevision', new_jwks_revision,
    'keyCount', validated_key_count
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.get_tenant_federated_mapping_policy_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  oidc_rules jsonb := '[]'::jsonb;
  saml_rules jsonb := '[]'::jsonb;
  mapping_rules jsonb := '[]'::jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['providerId'], ARRAY['providerId'], 256
  );
  PERFORM app.current_tenant_membership_id();
  IF NOT app.current_tenant_human_has_exact_permission_v3(
    'identity_mapping.read', 'tenant'
  ) THEN
    RAISE EXCEPTION 'identity_mapping.read tenant scope is required'
      USING ERRCODE = '42501';
  END IF;
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id
    AND candidate.kind IN ('oidc','saml');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found'
      USING ERRCODE = 'P0002';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;

  IF provider.kind = 'oidc' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'source', rule.source,
      'kind', rule.kind,
      'claimName', rule.claim_name,
      'profileField', rule.profile_field,
      'required', rule.required
    ) ORDER BY rule.source, rule.sequence), '[]'::jsonb)
    INTO oidc_rules
    FROM public.tenant_oidc_claim_rules AS rule
    WHERE rule.tenant_id = context_tenant AND rule.provider_id = target_provider_id;
  ELSE
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'kind', rule.kind,
      'attributeName', rule.attribute_name,
      'attributeNameFormat', rule.attribute_name_format,
      'profileField', rule.profile_field,
      'required', rule.required
    ) ORDER BY rule.sequence), '[]'::jsonb)
    INTO saml_rules
    FROM public.tenant_saml_attribute_rules AS rule
    WHERE rule.tenant_id = context_tenant AND rule.provider_id = target_provider_id;
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'ruleId', epoch.rule_id,
    'priority', epoch.priority,
    'matcherKind', epoch.matcher_kind,
    'claimName', epoch.claim_name,
    'matcherValue', epoch.matcher_value,
    'reconciliationMode', epoch.reconciliation_mode,
    'tenantSecurityGroupId', epoch.tenant_security_group_id,
    'roleIds', (
      SELECT coalesce(jsonb_agg(target.role_id ORDER BY target.role_id), '[]'::jsonb)
      FROM public.tenant_federated_mapping_rule_role_targets AS target
      WHERE target.tenant_id = context_tenant AND target.rule_epoch_id = epoch.id
        AND target.role_principal_kind = 'human'
    ),
    'operatorTeamId', epoch.operator_team_id,
    'operatorTeamAssignmentEpochId', epoch.operator_team_assignment_epoch_id,
    'enabled', epoch.enabled
  ) ORDER BY epoch.sequence), '[]'::jsonb)
  INTO mapping_rules
  FROM public.tenant_federated_mapping_rule_epochs AS epoch
  WHERE epoch.tenant_id = context_tenant AND epoch.provider_id = target_provider_id
    AND epoch.binding_id = binding.id AND epoch.provider_kind = provider.kind
    AND epoch.mapping_revision = binding.mapping_revision AND epoch.ended_at IS NULL;

  RETURN jsonb_build_object(
    'tenantId', context_tenant,
    'providerId', target_provider_id,
    'kind', provider.kind,
    'providerVersion', provider.version,
    'mappingRevision', binding.mapping_revision,
    'oidcClaimRules', oidc_rules,
    'samlAttributeRules', saml_rules,
    'rules', mapping_rules
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.get_tenant_federated_assurance_policy_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  provider public.tenant_auth_providers%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  rules jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['providerId'], ARRAY['providerId'], 256
  );
  PERFORM app.current_tenant_membership_id();
  IF NOT app.current_tenant_human_has_exact_permission_v3(
    'identity_policy.read', 'tenant'
  ) THEN
    RAISE EXCEPTION 'identity_policy.read tenant scope is required'
      USING ERRCODE = '42501';
  END IF;
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id
    AND candidate.kind IN ('oidc','saml');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant federated provider was not found'
      USING ERRCODE = 'P0002';
  END IF;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.provider_kind = provider.kind;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'ruleId', rule.id,
    'enabled', rule.enabled,
    'level', rule.level,
    'exactValue', rule.exact_value,
    'requiredValues', to_jsonb(rule.required_values),
    'maximumAuthenticationAgeSeconds', rule.maximum_authentication_age_seconds
  ) ORDER BY rule.id, rule.revision), '[]'::jsonb)
  INTO rules
  FROM public.tenant_federated_trust_rules AS rule
  WHERE rule.tenant_id = context_tenant AND rule.provider_id = target_provider_id
    AND rule.binding_id = policy.binding_id
    AND rule.provider_kind = provider.kind AND rule.retired_at IS NULL;
  RETURN jsonb_build_object(
    'tenantId', context_tenant,
    'providerId', target_provider_id,
    'kind', provider.kind,
    'providerVersion', provider.version,
    'assurancePolicyRevision', policy.assurance_policy_revision,
    'rules', rules
  );
END;
$function$;
--> statement-breakpoint

DO $tenant_federation_administration_acl_v1$
DECLARE
  private_signature text;
  public_signature text;
BEGIN
  FOREACH private_signature IN ARRAY ARRAY[
    'app.private_tenant_federation_assert_actor_v1(jsonb,text)',
    'app.private_tenant_federation_configured_v1(uuid,uuid,public.auth_provider_kind)',
    'app.private_tenant_saml_single_logout_configured_v1(bytea)',
    'app.private_tenant_federation_provider_document_v1(uuid,uuid)',
    'app.private_revoke_tenant_federated_provider_sessions_v1(uuid,uuid,text)',
    'app.private_tenant_federation_append_audit_v1(jsonb,text,text,uuid,jsonb,jsonb,jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator', private_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', private_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM periapsis_api, periapsis_worker, periapsis_notifier, periapsis_auditor', private_signature);
  END LOOP;
  FOREACH public_signature IN ARRAY ARRAY[
    'app.list_tenant_federated_auth_providers_v1(jsonb)',
    'app.get_tenant_federated_auth_provider_v1(jsonb)',
    'app.create_tenant_federated_auth_provider_v1(jsonb)',
    'app.update_tenant_federated_auth_provider_v1(jsonb)',
    'app.archive_tenant_federated_auth_provider_v1(jsonb)',
    'app.prepare_tenant_oidc_client_secret_v1(jsonb)',
    'app.replace_tenant_oidc_client_secret_v1(jsonb)',
    'app.clear_tenant_oidc_client_secret_v1(jsonb)',
    'app.get_tenant_federated_mapping_policy_v1(jsonb)',
    'app.replace_tenant_federated_mapping_policy_v1(jsonb)',
    'app.get_tenant_federated_assurance_policy_v1(jsonb)',
    'app.replace_tenant_federated_assurance_policy_v1(jsonb)',
    'app.prepare_tenant_oidc_trust_documents_v1(jsonb)',
    'app.commit_tenant_oidc_trust_documents_v1(jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator', public_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', public_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM periapsis_worker, periapsis_notifier, periapsis_auditor', public_signature);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO periapsis_api', public_signature);
  END LOOP;
END;
$tenant_federation_administration_acl_v1$;
--> statement-breakpoint

-- SAML_ADMINISTRATION_APPEND_BOUNDARY: the coordinated tenant-SAML task owns
-- append-only definitions below this marker and must use distinct function
-- names. The OIDC/provider/mapping/assurance section above is frozen for it.

CREATE FUNCTION app.prepare_tenant_saml_metadata_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_saml_provider_configurations%ROWTYPE;
  metadata public.tenant_saml_metadata_snapshots%ROWTYPE;
  current_document jsonb := NULL;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['membershipId','providerId','expectedVersion'],
    ARRAY['membershipId','providerId','expectedVersion'], 1024
  );
  PERFORM app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  IF expected_version NOT BETWEEN 1 AND 2147483646 THEN
    RAISE EXCEPTION 'tenant SAML provider version is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'saml';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant SAML provider cannot change metadata'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant SAML provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_saml_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  IF configuration.metadata_revision NOT BETWEEN 1 AND 2147483646 THEN
    RAISE EXCEPTION 'tenant SAML metadata revision is exhausted'
      USING ERRCODE = '55000';
  END IF;
  IF configuration.metadata_revision > 1 THEN
    SELECT candidate.* INTO metadata
    FROM public.tenant_saml_metadata_snapshots AS candidate
    WHERE candidate.tenant_id = context_tenant
      AND candidate.provider_id = target_provider_id
      AND candidate.revision = configuration.metadata_revision;
    IF NOT FOUND OR octet_length(metadata.document) NOT BETWEEN 1 AND 524288
       OR octet_length(metadata.document_digest) <> 32
       OR sha256(metadata.document) <> metadata.document_digest
       OR metadata.maximum_valid_until <= metadata.retrieved_at
       OR metadata.maximum_valid_until > metadata.retrieved_at + interval '31 days' THEN
      RAISE EXCEPTION 'tenant SAML metadata projection is unavailable'
        USING ERRCODE = '55000';
    END IF;
    current_document := jsonb_build_object(
      'revision', metadata.revision,
      'document', replace(encode(metadata.document, 'base64'), E'\n', ''),
      'digest', replace(encode(metadata.document_digest, 'base64'), E'\n', ''),
      'retrievedAt', metadata.retrieved_at,
      'maximumValidUntil', metadata.maximum_valid_until
    );
  END IF;
  RETURN jsonb_build_object(
    'tenantId', context_tenant,
    'providerId', target_provider_id,
    'bindingId', binding.id,
    'providerVersion', provider.version,
    'expectedEntityId', configuration.expected_entity_id,
    'currentMetadataRevision', configuration.metadata_revision,
    'current', current_document
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML metadata preparation'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.replace_tenant_saml_metadata_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  target_binding_id uuid;
  expected_version integer;
  expected_revision bigint;
  document bytea;
  document_digest bytea;
  retrieved_at timestamptz;
  maximum_valid_until timestamptz;
  protected_approval boolean;
  reason text;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_saml_provider_configurations%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'document','digest','retrievedAt','maximumValidUntil','protectedApproval',
      'reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'document','digest','retrievedAt','maximumValidUntil','protectedApproval',
      'reason','occurredAt','audit'], 1048576
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  target_binding_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'bindingId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  expected_revision := (p_request ->> 'expectedRevision')::bigint;
  document := decode(p_request ->> 'document', 'base64');
  document_digest := decode(p_request ->> 'digest', 'base64');
  retrieved_at := (p_request ->> 'retrievedAt')::timestamptz;
  maximum_valid_until := (p_request ->> 'maximumValidUntil')::timestamptz;
  protected_approval := (p_request ->> 'protectedApproval')::boolean;
  reason := btrim(p_request ->> 'reason');
  IF expected_version NOT BETWEEN 1 AND 2147483646
     OR expected_revision NOT BETWEEN 2 AND 2147483647
     OR octet_length(document) NOT BETWEEN 1 AND 524288
     OR replace(encode(document, 'base64'), E'\n', '') <> p_request ->> 'document'
     OR octet_length(document_digest) <> 32
     OR replace(encode(document_digest, 'base64'), E'\n', '') <> p_request ->> 'digest'
     OR sha256(document) <> document_digest
     OR maximum_valid_until <= retrieved_at
     OR maximum_valid_until <= statement_timestamp()
     OR maximum_valid_until > retrieved_at + interval '31 days'
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant SAML metadata mutation is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'saml'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant SAML provider cannot change metadata'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant SAML provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.id <> target_binding_id THEN
    RAISE EXCEPTION 'tenant SAML binding substitution was rejected'
      USING ERRCODE = '42501';
  END IF;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_saml_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.binding_id = binding.id
    AND candidate.provider_kind = 'saml'
  FOR UPDATE;
  IF expected_revision <> configuration.metadata_revision + 1
     OR policy.configuration_revision <> configuration.version THEN
    RAISE EXCEPTION 'tenant SAML metadata revision does not match'
      USING ERRCODE = '40001';
  END IF;
  INSERT INTO public.tenant_saml_metadata_snapshots (
    tenant_id, provider_id, revision, document, document_digest,
    retrieved_at, maximum_valid_until
  ) VALUES (
    context_tenant, target_provider_id, expected_revision, document,
    document_digest, retrieved_at, maximum_valid_until
  );
  UPDATE public.tenant_saml_provider_configurations AS candidate
  SET metadata_revision = expected_revision,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'SAML metadata trust changed'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.saml_metadata.replaced',
    'identity_provider', target_provider_id,
    jsonb_build_object(
      'metadata_revision', configuration.metadata_revision,
      'provider_version', provider.version
    ),
    jsonb_build_object(
      'metadata_revision', expected_revision,
      'provider_version', provider.version + 1,
      'metadata_digest_sha256', encode(document_digest, 'hex')
    ),
    jsonb_build_object(
      'reason', reason,
      'protected_trust_reset', protected_approval,
      'revoked_sessions', revoked_sessions
    )
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id,
    'providerVersion', provider.version + 1,
    'materialRevision', expected_revision
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR invalid_parameter_value OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML metadata mutation'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.prepare_tenant_saml_sp_credential_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target_provider_id uuid;
  expected_version integer;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_saml_provider_configurations%ROWTYPE;
  current_key public.tenant_saml_sp_keys%ROWTYPE;
  certificate_count integer := 0;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['membershipId','providerId','expectedVersion'],
    ARRAY['membershipId','providerId','expectedVersion'], 1024
  );
  PERFORM app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  IF expected_version NOT BETWEEN 1 AND 2147483646 THEN
    RAISE EXCEPTION 'tenant SAML provider version is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'saml';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant SAML provider cannot change credentials'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant SAML provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_saml_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  IF configuration.sp_key_revision NOT BETWEEN 1 AND 2147483646 THEN
    RAISE EXCEPTION 'tenant SAML credential revision is exhausted'
      USING ERRCODE = '55000';
  END IF;
  SELECT candidate.* INTO current_key
  FROM public.tenant_saml_sp_keys AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.revision = configuration.sp_key_revision
    AND candidate.retired_at IS NULL;
  IF FOUND THEN
    SELECT count(*)::integer INTO certificate_count
    FROM public.tenant_saml_sp_certificates AS certificate
    WHERE certificate.tenant_id = context_tenant
      AND certificate.key_id = current_key.id;
    IF certificate_count NOT BETWEEN 1 AND 8 THEN
      RAISE EXCEPTION 'tenant SAML credential projection is unavailable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'tenantId', context_tenant,
    'providerId', target_provider_id,
    'bindingId', binding.id,
    'providerVersion', provider.version,
    'currentCredentialRevision', configuration.sp_key_revision,
    'credentialPresent', current_key.id IS NOT NULL,
    'providerEnabled', provider.enabled,
    'bindingEnabled', binding.enabled,
    'spEntityId', configuration.sp_entity_id,
    'redirectSignatureAlgorithm', configuration.redirect_signature_algorithm
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML credential preparation'
    USING ERRCODE = '22023';
END;
$function$;
