CREATE FUNCTION app.replace_tenant_saml_sp_credential_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  target_binding_id uuid;
  new_key_id uuid;
  expected_version integer;
  expected_revision bigint;
  new_key_version integer;
  envelope_ciphertext bytea;
  certificate_values jsonb;
  certificate_validity jsonb;
  reason text;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_saml_provider_configurations%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  current_key public.tenant_saml_sp_keys%ROWTYPE;
  certificate_count integer;
  certificate_digests jsonb;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'keyId','keyVersion','envelopeCiphertext','certificateDer','certificateValidity','reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'keyId','keyVersion','envelopeCiphertext','certificateDer','certificateValidity','reason','occurredAt','audit'],
    2097152
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  target_binding_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'bindingId');
  new_key_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'keyId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  expected_revision := (p_request ->> 'expectedRevision')::bigint;
  new_key_version := (p_request ->> 'keyVersion')::integer;
  envelope_ciphertext := decode(p_request ->> 'envelopeCiphertext', 'base64');
  certificate_values := p_request -> 'certificateDer';
  certificate_validity := p_request -> 'certificateValidity';
  reason := btrim(p_request ->> 'reason');
  IF expected_version NOT BETWEEN 1 AND 2147483646
     OR expected_revision NOT BETWEEN 2 AND 2147483647
     OR new_key_version NOT BETWEEN 1 AND 32767
     OR octet_length(envelope_ciphertext) NOT BETWEEN 29 AND 131072
     OR replace(encode(envelope_ciphertext, 'base64'), E'\n', '')
       <> p_request ->> 'envelopeCiphertext'
     OR jsonb_typeof(certificate_values) <> 'array'
     OR jsonb_array_length(certificate_values) NOT BETWEEN 1 AND 8
     OR jsonb_typeof(certificate_validity) <> 'array'
     OR jsonb_array_length(certificate_validity)
       <> jsonb_array_length(certificate_values)
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(certificate_values) AS item(value)
       WHERE jsonb_typeof(item.value) <> 'string'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(certificate_values) AS item(value)
       WHERE octet_length(decode(item.value, 'base64')) NOT BETWEEN 1 AND 65536
          OR replace(encode(decode(item.value, 'base64'), 'base64'), E'\n', '') <> item.value
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(certificate_values) WITH ORDINALITY AS left_item(value, sequence)
       JOIN jsonb_array_elements_text(certificate_values) WITH ORDINALITY AS right_item(value, sequence)
         ON left_item.sequence < right_item.sequence
         AND decode(left_item.value, 'base64') = decode(right_item.value, 'base64')
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(certificate_validity) AS item(value)
       CROSS JOIN LATERAL (
         SELECT (item.value ->> 'notBefore')::timestamptz AS not_before,
           (item.value ->> 'notAfter')::timestamptz AS not_after
       ) AS instant
       WHERE jsonb_typeof(item.value) <> 'object'
          OR item.value <> jsonb_build_object(
            'notBefore', item.value -> 'notBefore',
            'notAfter', item.value -> 'notAfter'
          )
          OR jsonb_typeof(item.value -> 'notBefore') <> 'string'
          OR jsonb_typeof(item.value -> 'notAfter') <> 'string'
          OR date_trunc('microseconds', instant.not_before) <> instant.not_before
          OR date_trunc('microseconds', instant.not_after) <> instant.not_after
          OR instant.not_before > statement_timestamp()
          OR instant.not_after <= statement_timestamp()
          OR instant.not_before >= instant.not_after
     )
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant SAML credential mutation is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'saml'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived tenant SAML provider cannot change credentials'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant SAML provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.id <> target_binding_id THEN
    RAISE EXCEPTION 'tenant SAML binding substitution was rejected'
      USING ERRCODE = '42501';
  END IF;
  IF provider.enabled OR binding.enabled THEN
    RAISE EXCEPTION 'disable the tenant SAML provider and binding before replacing its credential'
      USING ERRCODE = '55000';
  END IF;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_saml_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.binding_id = binding.id
    AND candidate.provider_kind = 'saml'
  FOR UPDATE;
  IF expected_revision <> configuration.sp_key_revision + 1
     OR policy.configuration_revision <> configuration.version THEN
    RAISE EXCEPTION 'tenant SAML credential revision does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO current_key
  FROM public.tenant_saml_sp_keys AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.revision = configuration.sp_key_revision
    AND candidate.retired_at IS NULL
  FOR UPDATE;
  IF FOUND THEN
    UPDATE public.tenant_saml_sp_keys AS candidate
    SET retired_at = transaction_timestamp()
    WHERE candidate.tenant_id = context_tenant AND candidate.id = current_key.id;
  END IF;
  INSERT INTO public.tenant_saml_sp_keys (
    id, tenant_id, provider_id, revision, key_version, ciphertext
  ) VALUES (
    new_key_id, context_tenant, target_provider_id, expected_revision,
    new_key_version, envelope_ciphertext
  );
  INSERT INTO public.tenant_saml_sp_certificates (
    tenant_id, key_id, sequence, certificate_der, not_before, not_after
  )
  SELECT context_tenant, new_key_id, item.sequence::integer - 1,
    decode(item.value, 'base64'),
    (validity.value ->> 'notBefore')::timestamptz,
    (validity.value ->> 'notAfter')::timestamptz
  FROM jsonb_array_elements_text(certificate_values)
    WITH ORDINALITY AS item(value, sequence)
  JOIN jsonb_array_elements(certificate_validity)
    WITH ORDINALITY AS validity(value, sequence)
    USING (sequence)
  ORDER BY item.sequence;
  certificate_count := jsonb_array_length(certificate_values);
  SELECT jsonb_agg(encode(sha256(decode(item.value, 'base64')), 'hex') ORDER BY item.sequence)
  INTO certificate_digests
  FROM jsonb_array_elements_text(certificate_values)
    WITH ORDINALITY AS item(value, sequence);
  UPDATE public.tenant_saml_provider_configurations AS candidate
  SET sp_key_revision = expected_revision,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'SAML SP credential changed'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.saml_sp_credential.replaced',
    'identity_provider', target_provider_id,
    jsonb_build_object(
      'material_present', current_key.id IS NOT NULL,
      'sp_key_revision', configuration.sp_key_revision,
      'provider_version', provider.version
    ),
    jsonb_build_object(
      'material_present', true,
      'sp_key_revision', expected_revision,
      'provider_version', provider.version + 1,
      'certificate_count', certificate_count,
      'certificate_digests_sha256', certificate_digests
    ),
    jsonb_build_object(
      'reason', reason,
      'key_version', new_key_version,
      'revoked_sessions', revoked_sessions
    )
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id,
    'providerVersion', provider.version + 1,
    'materialRevision', expected_revision
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR invalid_parameter_value OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML credential mutation'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.clear_tenant_saml_sp_credential_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid;
  target_provider_id uuid;
  target_binding_id uuid;
  expected_version integer;
  expected_revision bigint;
  reason text;
  provider public.tenant_auth_providers%ROWTYPE;
  binding public.tenant_auth_provider_bindings%ROWTYPE;
  configuration public.tenant_saml_provider_configurations%ROWTYPE;
  policy public.tenant_federated_provider_policies%ROWTYPE;
  current_key public.tenant_saml_sp_keys%ROWTYPE;
  certificate_count integer;
  certificate_digests jsonb;
  revoked_sessions integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'reason','occurredAt','audit'],
    ARRAY['membershipId','providerId','bindingId','expectedVersion','expectedRevision',
      'reason','occurredAt','audit'], 8192
  );
  PERFORM app.lock_current_tenant_authorization_state();
  actor_membership := app.private_tenant_federation_assert_actor_v1(
    p_request, 'identity_provider.manage'
  );
  target_provider_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'providerId');
  target_binding_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'bindingId');
  expected_version := (p_request ->> 'expectedVersion')::integer;
  expected_revision := (p_request ->> 'expectedRevision')::bigint;
  reason := btrim(p_request ->> 'reason');
  IF expected_version NOT BETWEEN 1 AND 2147483646
     OR expected_revision NOT BETWEEN 2 AND 2147483647
     OR NOT app.private_tenant_federation_audit_reason_valid_v1(reason)
     OR (p_request ->> 'occurredAt')::timestamptz IS NULL THEN
    RAISE EXCEPTION 'tenant SAML credential retirement is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT candidate.* INTO provider
  FROM public.tenant_auth_providers AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.id = target_provider_id AND candidate.kind = 'saml'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML provider was not found' USING ERRCODE = 'P0002';
  END IF;
  IF provider.archived_at IS NOT NULL OR provider.enabled THEN
    RAISE EXCEPTION 'disable the tenant SAML provider before clearing its credential'
      USING ERRCODE = '55000';
  END IF;
  IF provider.version <> expected_version THEN
    RAISE EXCEPTION 'tenant SAML provider version does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO STRICT binding
  FROM public.tenant_auth_provider_bindings AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  IF binding.id <> target_binding_id OR binding.enabled THEN
    RAISE EXCEPTION 'tenant SAML binding cannot clear its credential'
      USING ERRCODE = '55000';
  END IF;
  SELECT candidate.* INTO STRICT configuration
  FROM public.tenant_saml_provider_configurations AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
  FOR UPDATE;
  SELECT candidate.* INTO STRICT policy
  FROM public.tenant_federated_provider_policies AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.binding_id = binding.id
    AND candidate.provider_kind = 'saml'
  FOR UPDATE;
  IF expected_revision <> configuration.sp_key_revision + 1
     OR policy.configuration_revision <> configuration.version
     OR configuration.encryption_policy <> 'disabled'
     OR cardinality(configuration.decryption_key_versions) <> 0 THEN
    RAISE EXCEPTION 'tenant SAML credential revision or policy does not match'
      USING ERRCODE = '40001';
  END IF;
  SELECT candidate.* INTO current_key
  FROM public.tenant_saml_sp_keys AS candidate
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id
    AND candidate.revision = configuration.sp_key_revision
    AND candidate.retired_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant SAML SP credential is not configured'
      USING ERRCODE = '55000';
  END IF;
  SELECT count(*)::integer,
    jsonb_agg(encode(sha256(certificate.certificate_der), 'hex') ORDER BY certificate.sequence)
  INTO certificate_count, certificate_digests
  FROM public.tenant_saml_sp_certificates AS certificate
  WHERE certificate.tenant_id = context_tenant
    AND certificate.key_id = current_key.id;
  IF certificate_count NOT BETWEEN 1 AND 8 THEN
    RAISE EXCEPTION 'tenant SAML credential projection is unavailable'
      USING ERRCODE = '55000';
  END IF;
  UPDATE public.tenant_saml_sp_keys AS candidate
  SET retired_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = current_key.id;
  UPDATE public.tenant_saml_provider_configurations AS candidate
  SET sp_key_revision = expected_revision,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_federated_provider_policies AS candidate
  SET configuration_revision = candidate.configuration_revision + 1,
      security_revision = candidate.security_revision + 1,
      plan_revision = candidate.plan_revision + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant
    AND candidate.provider_id = target_provider_id;
  UPDATE public.tenant_auth_provider_bindings AS candidate
  SET auth_revision = candidate.auth_revision + 1,
      updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = binding.id;
  UPDATE public.tenant_auth_providers AS candidate
  SET updated_by_membership_id = actor_membership,
      version = candidate.version + 1,
      updated_at = transaction_timestamp()
  WHERE candidate.tenant_id = context_tenant AND candidate.id = target_provider_id;
  revoked_sessions := app.private_revoke_tenant_federated_provider_sessions_v1(
    context_tenant, target_provider_id, 'SAML SP credential cleared'
  );
  PERFORM app.private_tenant_federation_append_audit_v1(
    p_request, 'tenant.identity_provider.saml_sp_credential.cleared',
    'identity_provider', target_provider_id,
    jsonb_build_object(
      'material_present', true,
      'sp_key_revision', configuration.sp_key_revision,
      'provider_version', provider.version,
      'certificate_count', certificate_count,
      'certificate_digests_sha256', certificate_digests
    ),
    jsonb_build_object(
      'material_present', false,
      'sp_key_revision', expected_revision,
      'provider_version', provider.version + 1
    ),
    jsonb_build_object(
      'reason', reason,
      'revoked_sessions', revoked_sessions
    )
  );
  RETURN jsonb_build_object(
    'providerId', target_provider_id,
    'providerVersion', provider.version + 1,
    'materialRevision', expected_revision
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML credential retirement'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.get_tenant_saml_sp_metadata_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  tenant_slug text;
  login_key text;
  result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request, ARRAY['tenantSlug','loginKey'], ARRAY['tenantSlug','loginKey'], 512
  );
  tenant_slug := p_request ->> 'tenantSlug';
  login_key := p_request ->> 'loginKey';
  IF tenant_slug !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'
     OR login_key !~ '^[a-z][a-z0-9_-]{2,63}$' THEN
    RAISE EXCEPTION 'invalid tenant SAML SP metadata locator'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'tenantSlug', tenant.slug,
    'loginKey', binding.key,
    'tenantId', tenant.id,
    'providerId', provider.id,
    'bindingId', binding.id,
    'providerVersion', provider.version,
    'bindingVersion', binding.version,
    'configurationRevision', policy.configuration_revision,
    'securityRevision', policy.security_revision,
    'planRevision', policy.plan_revision,
    'authorizationRevision', binding.auth_revision,
    'spEntityId', configuration.sp_entity_id,
    'acsUrl', configuration.acs_url,
    'spKeyRevision', configuration.sp_key_revision,
    'redirectSignatureAlgorithm', configuration.redirect_signature_algorithm,
    'signaturePolicy', configuration.signature_policy,
    'encryptionPolicy', configuration.encryption_policy,
    'subjectSource', configuration.subject_source,
    'tenantActive', tenant.status = 'active',
    'providerEnabled', provider.enabled,
    'bindingEnabled', binding.enabled,
    'policyEnabled', policy.enabled,
    'providerArchived', provider.archived_at IS NOT NULL,
    'bindingArchived', binding.archived_at IS NOT NULL,
    'accessEpochLive', access_epoch.ended_at IS NULL,
    'observedAt', transaction_timestamp(),
    'certificates', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'tenantId', certificate.tenant_id,
        'providerId', provider.id,
        'bindingId', binding.id,
        'keyId', certificate.key_id,
        'keyRevision', sp_key.revision,
        'certificateSequence', certificate.sequence,
        'certificateDer', replace(encode(certificate.certificate_der, 'base64'), E'\n', '')
      ) ORDER BY certificate.sequence)
      FROM public.tenant_saml_sp_certificates AS certificate
      WHERE certificate.tenant_id = sp_key.tenant_id
        AND certificate.key_id = sp_key.id
    ), '[]'::jsonb)
  )
  INTO result
  FROM public.tenants AS tenant
  JOIN public.tenant_auth_provider_bindings AS binding
    ON binding.tenant_id = tenant.id
   AND binding.key = login_key
   AND binding.enabled
   AND binding.archived_at IS NULL
   AND binding.current_access_epoch_id IS NOT NULL
  JOIN public.tenant_auth_providers AS provider
    ON provider.tenant_id = binding.tenant_id
   AND provider.id = binding.provider_id
   AND provider.kind = 'saml'
   AND provider.enabled
   AND provider.archived_at IS NULL
  JOIN public.tenant_federated_provider_policies AS policy
    ON policy.tenant_id = provider.tenant_id
   AND policy.provider_id = provider.id
   AND policy.binding_id = binding.id
   AND policy.provider_kind = 'saml'
   AND policy.enabled
  JOIN public.tenant_saml_provider_configurations AS configuration
    ON configuration.tenant_id = provider.tenant_id
   AND configuration.provider_id = provider.id
   AND configuration.version = policy.configuration_revision
  JOIN public.tenant_saml_metadata_snapshots AS metadata
    ON metadata.tenant_id = configuration.tenant_id
   AND metadata.provider_id = configuration.provider_id
   AND metadata.revision = configuration.metadata_revision
   AND metadata.maximum_valid_until > statement_timestamp()
  JOIN public.tenant_saml_sp_keys AS sp_key
    ON sp_key.tenant_id = configuration.tenant_id
   AND sp_key.provider_id = configuration.provider_id
   AND sp_key.revision = configuration.sp_key_revision
   AND sp_key.retired_at IS NULL
  JOIN public.identity_keyring_versions AS keyring
    ON keyring.key_version = sp_key.key_version
   AND keyring.retired_at IS NULL
  JOIN public.tenant_identity_provider_access_epochs AS access_epoch
    ON access_epoch.tenant_id = binding.tenant_id
   AND access_epoch.id = binding.current_access_epoch_id
   AND access_epoch.binding_id = binding.id
   AND access_epoch.provider_id = provider.id
   AND access_epoch.ended_at IS NULL
  WHERE tenant.slug = tenant_slug
    AND tenant.status = 'active'
    AND app.private_tenant_federation_configured_v1(tenant.id, provider.id, 'saml');

  IF result IS NULL THEN
    RETURN jsonb_build_object('found', false);
  END IF;
  RETURN jsonb_build_object('found', true, 'projection', result);
EXCEPTION WHEN invalid_text_representation OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML SP metadata locator'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

DO $tenant_saml_administration_acl_v1$
DECLARE
  public_signature text;
BEGIN
  FOREACH public_signature IN ARRAY ARRAY[
    'app.prepare_tenant_saml_metadata_v1(jsonb)',
    'app.replace_tenant_saml_metadata_v1(jsonb)',
    'app.prepare_tenant_saml_sp_credential_v1(jsonb)',
    'app.replace_tenant_saml_sp_credential_v1(jsonb)',
    'app.clear_tenant_saml_sp_credential_v1(jsonb)',
    'app.get_tenant_saml_sp_metadata_v1(jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator', public_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', public_signature);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM periapsis_worker, periapsis_notifier, periapsis_auditor', public_signature);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO periapsis_api', public_signature);
  END LOOP;
END;
$tenant_saml_administration_acl_v1$;
--> statement-breakpoint

-- OIDC session lifecycle closeout. The immutable material id is the login
-- transaction operation_run_id. ID and optional refresh token envelopes are
-- kept only in this protected relation; an access token has no schema slot.
CREATE TABLE public.tenant_oidc_session_materials (
  id uuid PRIMARY KEY NOT NULL,
  tenant_id uuid NOT NULL,
  session_id uuid,
  continuation_id uuid,
  rotation_family_id uuid,
  user_id uuid NOT NULL,
  provider_id uuid NOT NULL,
  binding_id uuid NOT NULL,
  provider_kind public.auth_provider_kind DEFAULT 'oidc' NOT NULL,
  external_identity_id uuid NOT NULL,
  aad_version integer NOT NULL,
  id_token_key_version integer,
  id_token_ciphertext bytea,
  refresh_token_key_version integer,
  refresh_token_ciphertext bytea,
  refresh_token_digest bytea,
  refresh_generation bigint DEFAULT 0 NOT NULL,
  refresh_state text DEFAULT 'unavailable' NOT NULL,
  refresh_claimed_at timestamptz,
  refresh_claim_expires_at timestamptz,
  refresh_version bigint DEFAULT 1 NOT NULL,
  access_expires_at timestamptz,
  client_secret_revision bigint NOT NULL,
  client_authentication text NOT NULL,
  client_id text NOT NULL,
  token_endpoint text NOT NULL,
  revocation_endpoint text,
  end_session_endpoint text,
  post_logout_redirect_uri text NOT NULL,
  logout_disposition text DEFAULT 'available' NOT NULL,
  logout_operation_run_id uuid,
  logout_claimed_at timestamptz,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  CONSTRAINT tenant_oidc_session_materials_tenant_id_key UNIQUE (tenant_id,id),
  CONSTRAINT tenant_oidc_session_materials_transaction_fk
    FOREIGN KEY (tenant_id,id)
    REFERENCES public.tenant_federated_authentication_transactions
      (tenant_id,operation_run_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT tenant_oidc_session_materials_policy_fk
    FOREIGN KEY (tenant_id,binding_id,provider_id,provider_kind)
    REFERENCES public.tenant_federated_provider_policies
      (tenant_id,binding_id,provider_id,provider_kind)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT tenant_oidc_session_materials_client_secret_fk
    FOREIGN KEY (tenant_id,provider_id,client_secret_revision)
    REFERENCES public.tenant_oidc_client_secrets
      (tenant_id,provider_id,revision)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT tenant_oidc_session_materials_id_token_keyring_fk
    FOREIGN KEY (id_token_key_version)
    REFERENCES public.identity_keyring_versions(key_version)
