    AND provider_kind = 'oidc'
    AND ((session_id IS NULL AND rotation_family_id IS NULL)
      OR (session_id IS NOT NULL
        AND (uuid_extract_version(rotation_family_id) = 7) IS TRUE
        AND rotation_family_id <> session_id
        AND rotation_family_id <> id))
  ),
  CONSTRAINT tenant_oidc_session_materials_token_check CHECK (
    aad_version = 1
    AND (id_token_key_version IS NULL) = (id_token_ciphertext IS NULL)
    AND (id_token_key_version IS NULL OR (
      id_token_key_version BETWEEN 1 AND 32767
      AND octet_length(id_token_ciphertext) BETWEEN 29 AND 262172))
    AND refresh_version BETWEEN 1 AND 8999999999999999
    AND ((refresh_state = 'unavailable'
        AND refresh_generation = 0
        AND refresh_claimed_at IS NULL
        AND refresh_token_key_version IS NULL
        AND refresh_token_ciphertext IS NULL
        AND refresh_token_digest IS NULL
        AND access_expires_at IS NULL)
