        AND refresh_generation > 0
        AND refresh_token_key_version BETWEEN 1 AND 32767
        AND octet_length(refresh_token_ciphertext) BETWEEN 29 AND 262172
        AND octet_length(refresh_token_digest) = 32
        AND access_expires_at > created_at
        AND ((refresh_state = 'ready' AND refresh_claimed_at IS NULL)
