    client_secret_revision > 0
    AND client_authentication IN ('client_secret_basic','client_secret_post')
    AND octet_length(convert_to(client_id,'UTF8')) BETWEEN 1 AND 512
    AND client_id !~ '[[:cntrl:]]'
    AND char_length(token_endpoint) BETWEEN 9 AND 4096
    AND token_endpoint ~ '^https://[^[:space:]#]+$'
    AND (revocation_endpoint IS NULL OR (
      char_length(revocation_endpoint) BETWEEN 9 AND 4096
      AND revocation_endpoint ~ '^https://[^[:space:]#]+$'))
    AND (end_session_endpoint IS NULL OR (
