      AND end_session_endpoint ~ '^https://[^[:space:]#]+$'))
    AND (end_session_endpoint IS NULL) = (id_token_key_version IS NULL)
    AND char_length(post_logout_redirect_uri) BETWEEN 9 AND 4096
    AND post_logout_redirect_uri ~ '^https://[^[:space:]#]+$'
  ),
