        AND logout_operation_run_id <> id
        AND logout_claimed_at >= created_at))
    AND ((end_session_endpoint IS NULL)
      = (logout_disposition = 'not_configured')
      OR logout_disposition IN ('claimed','skipped'))
    AND updated_at >= created_at
  )
