    (uuid_extract_version(id) = 7) IS TRUE
    AND (uuid_extract_version(session_family_id) = 7) IS TRUE
    AND id <> operation_run_id AND id <> material_id
    AND id <> session_family_id
  ),
  CONSTRAINT tenant_oidc_logout_retry_jobs_state_check CHECK (
    state IN ('pending','claimed','complete','dead_letter')
    AND attempt BETWEEN 0 AND maximum_attempts
    AND maximum_attempts BETWEEN 1 AND 16
    AND version BETWEEN 1 AND 8999999999999999
    AND not_before >= created_at
    AND ((state = 'pending' AND claimed_at IS NULL
        AND claim_expires_at IS NULL AND completed_at IS NULL)
      OR (state = 'claimed' AND attempt > 0 AND claimed_at IS NOT NULL
        AND claim_expires_at > claimed_at AND completed_at IS NULL)
      OR (state IN ('complete','dead_letter') AND attempt > 0
        AND claimed_at IS NOT NULL AND claim_expires_at IS NOT NULL
        AND completed_at >= claimed_at))
    AND updated_at >= created_at
  )
);
