CREATE OR REPLACE FUNCTION app.guard_oidc_session_material_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_owner_valid boolean := false;
  v_source_valid boolean := false;
  v_scrub_allowed boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.authority = 'tenant_provider' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.tenant_federated_authentication_transactions AS transaction
        JOIN public.tenant_federated_authentication_applications AS application
          ON application.tenant_id = transaction.tenant_id
         AND application.transaction_id = transaction.transaction_id
         AND application.protocol = 'oidc' AND application.category = 'success'
        WHERE transaction.tenant_id = NEW.tenant_id
          AND transaction.operation_run_id = NEW.id
          AND transaction.provider_id = NEW.provider_id
          AND transaction.binding_id = NEW.binding_id
          AND transaction.provider_kind = 'oidc'
          AND transaction.state = 'completed'
          AND application.user_id = NEW.user_id
          AND application.session_id IS NOT DISTINCT FROM NEW.session_id
          AND application.continuation_id IS NOT DISTINCT FROM NEW.continuation_id
          AND (application.request_snapshot #>>
            '{authentication,validUntil}')::timestamptz >= NEW.expires_at
      ) INTO v_source_valid;
    ELSIF NEW.authority = 'tenant_platform_provider' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.tenant_platform_oidc_authentication_transactions AS transaction
        JOIN public.tenant_platform_oidc_authentication_applications AS application
          ON application.tenant_id = transaction.tenant_id
         AND application.transaction_id = transaction.transaction_id
         AND application.category = 'success'
        WHERE transaction.tenant_id = NEW.tenant_id
          AND transaction.operation_run_id = NEW.id
          AND transaction.platform_provider_id = NEW.provider_id
          AND transaction.binding_id = NEW.binding_id
          AND transaction.provider_kind = 'oidc'
          AND transaction.state = 'completed'
          AND application.user_id = NEW.user_id
          AND application.external_identity_id = NEW.external_identity_id
          AND application.session_id IS NOT DISTINCT FROM NEW.session_id
          AND application.continuation_id IS NOT DISTINCT FROM NEW.continuation_id
          AND (application.request_snapshot #>>
            '{authentication,validUntil}')::timestamptz >= NEW.expires_at
      ) INTO v_source_valid;
    ELSIF NEW.authority = 'platform_provider' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.platform_oidc_authentication_transactions AS transaction
        JOIN public.platform_oidc_authentication_applications AS application
          ON application.transaction_id = transaction.transaction_id
         AND application.category = 'success'
        WHERE transaction.operation_run_id = NEW.id
          AND transaction.platform_provider_id = NEW.provider_id
          AND transaction.provider_kind = 'oidc'
          AND transaction.state = 'completed'
          AND application.user_id = NEW.user_id
          AND application.external_identity_id = NEW.external_identity_id
          AND application.session_id IS NOT DISTINCT FROM NEW.session_id
          AND application.continuation_id IS NOT DISTINCT FROM NEW.continuation_id
      ) INTO v_source_valid;
    END IF;
    IF NOT coalesce(v_source_valid,false) THEN
      RAISE EXCEPTION 'OIDC material source authority is unavailable'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.authority IS DISTINCT FROM OLD.authority
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.binding_id IS DISTINCT FROM OLD.binding_id
       OR NEW.provider_kind IS DISTINCT FROM OLD.provider_kind
       OR NEW.external_identity_id IS DISTINCT FROM OLD.external_identity_id
       OR NEW.aad_version IS DISTINCT FROM OLD.aad_version
       OR (NEW.id_token_digest IS DISTINCT FROM OLD.id_token_digest
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.id_token_key_version IS DISTINCT FROM OLD.id_token_key_version
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.id_token_ciphertext IS DISTINCT FROM OLD.id_token_ciphertext
          AND NEW.scrubbed_at IS NULL)
       OR NEW.expires_at > OLD.expires_at
       OR (NEW.client_secret_revision IS DISTINCT FROM OLD.client_secret_revision
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.client_authentication IS DISTINCT FROM OLD.client_authentication
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.client_id IS DISTINCT FROM OLD.client_id
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.token_endpoint IS DISTINCT FROM OLD.token_endpoint
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.revocation_endpoint IS DISTINCT FROM OLD.revocation_endpoint
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.end_session_endpoint IS DISTINCT FROM OLD.end_session_endpoint
          AND NEW.scrubbed_at IS NULL)
       OR (NEW.post_logout_redirect_uri IS DISTINCT FROM OLD.post_logout_redirect_uri
          AND NEW.scrubbed_at IS NULL)
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR OLD.scrubbed_at IS NOT NULL AND (
         NEW.scrubbed_at IS DISTINCT FROM OLD.scrubbed_at
         OR NEW.scrub_operation_run_id IS DISTINCT FROM OLD.scrub_operation_run_id
       ) THEN
      RAISE EXCEPTION 'OIDC material immutable identity or pins changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF NEW.session_id IS NOT NULL THEN
    IF NEW.authority = 'tenant_provider' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.auth_sessions AS session
        JOIN public.auth_session_federated_provenance AS provenance
          ON provenance.tenant_id = NEW.tenant_id
         AND provenance.session_id = session.id
         AND provenance.user_id = session.user_id
        WHERE session.id = NEW.session_id AND session.user_id = NEW.user_id
          AND session.active_tenant_id = NEW.tenant_id
          AND session.authentication_method = 'oidc'
          AND session.rotation_family_id = NEW.rotation_family_id
          AND session.absolute_expires_at >= NEW.expires_at
          AND provenance.provider_id = NEW.provider_id
          AND provenance.binding_id = NEW.binding_id
          AND provenance.external_identity_id = NEW.external_identity_id
          AND provenance.provider_kind = 'oidc'
      ) INTO v_owner_valid;
    ELSIF NEW.authority = 'tenant_platform_provider' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.auth_sessions AS session
        JOIN public.auth_session_tenant_platform_federated_provenance AS provenance
          ON provenance.tenant_id = NEW.tenant_id
         AND provenance.session_id = session.id
         AND provenance.user_id = session.user_id
        WHERE session.id = NEW.session_id AND session.user_id = NEW.user_id
          AND session.active_tenant_id = NEW.tenant_id
          AND session.authentication_method = 'oidc'
          AND session.rotation_family_id = NEW.rotation_family_id
          AND session.absolute_expires_at >= NEW.expires_at
          AND provenance.platform_provider_id = NEW.provider_id
          AND provenance.binding_id = NEW.binding_id
          AND provenance.external_identity_id = NEW.external_identity_id
      ) INTO v_owner_valid;
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.auth_sessions AS session
        JOIN public.auth_session_platform_oidc_states AS state
          ON state.session_id = session.id AND state.user_id = session.user_id
        JOIN public.auth_session_platform_oidc_provenance AS provenance
          ON provenance.session_id = session.id
         AND provenance.user_id = session.user_id
        WHERE session.id = NEW.session_id AND session.user_id = NEW.user_id
          AND session.active_tenant_id IS NULL
          AND session.authentication_method = 'oidc'
          AND session.rotation_family_id = NEW.rotation_family_id
          AND session.absolute_expires_at >= NEW.expires_at
          AND provenance.platform_provider_id = NEW.provider_id
          AND provenance.external_identity_id = NEW.external_identity_id
      ) INTO v_owner_valid;
    END IF;
  ELSIF NEW.authority = 'tenant_provider' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tenant_post_primary_continuations AS continuation
      WHERE continuation.tenant_id = NEW.tenant_id
        AND continuation.id = NEW.continuation_id
        AND continuation.user_id = NEW.user_id
        AND continuation.primary_kind = 'tenant_provider'
        AND continuation.provider_id = NEW.provider_id
        AND continuation.binding_id = NEW.binding_id
        AND continuation.provider_kind = 'oidc'
        AND continuation.external_identity_id = NEW.external_identity_id
        AND continuation.expires_at >= NEW.expires_at
    ) INTO v_owner_valid;
  ELSIF NEW.authority = 'tenant_platform_provider' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tenant_post_primary_continuations AS continuation
      WHERE continuation.tenant_id = NEW.tenant_id
        AND continuation.id = NEW.continuation_id
        AND continuation.user_id = NEW.user_id
        AND continuation.primary_kind = 'tenant_platform_provider'
        AND continuation.platform_provider_id = NEW.provider_id
        AND continuation.binding_id = NEW.binding_id
        AND continuation.external_identity_id = NEW.external_identity_id
        AND continuation.expires_at >= NEW.expires_at
    ) INTO v_owner_valid;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.platform_post_primary_continuations AS continuation
      WHERE continuation.id = NEW.continuation_id
        AND continuation.user_id = NEW.user_id
        AND continuation.platform_provider_id = NEW.provider_id
        AND continuation.external_identity_id = NEW.external_identity_id
        AND continuation.expires_at >= NEW.expires_at
    ) INTO v_owner_valid;
  END IF;
  IF NOT coalesce(v_owner_valid,false) THEN
    RAISE EXCEPTION 'OIDC material owner authority is unavailable'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.scrubbed_at IS NULL
     AND NEW.scrubbed_at IS NOT NULL THEN
    IF NEW.scrub_operation_run_id IS NULL
       OR date_trunc('microseconds',NEW.scrubbed_at) <> NEW.scrubbed_at
       OR abs(extract(epoch FROM
         (transaction_timestamp() - NEW.scrubbed_at))) > 300 THEN
      RAISE EXCEPTION 'OIDC material scrub marker is invalid'
        USING ERRCODE = '22023';
    END IF;
    SELECT NEW.expires_at <= NEW.scrubbed_at OR EXISTS (
      SELECT 1 FROM public.auth_sessions AS session
      WHERE session.id = NEW.session_id AND session.user_id = NEW.user_id
        AND session.rotation_family_id = NEW.rotation_family_id
        AND (session.revoked_at IS NOT NULL
          OR session.absolute_expires_at <= NEW.scrubbed_at)
    ) OR (
      NEW.logout_disposition IN ('claimed','skipped') AND NOT EXISTS (
        SELECT 1 FROM public.tenant_oidc_logout_retry_jobs AS job
        WHERE job.material_id = NEW.id AND job.state IN ('pending','claimed')
      )
    ) INTO v_scrub_allowed;
    IF NOT coalesce(v_scrub_allowed,false) THEN
      RAISE EXCEPTION 'OIDC material is not terminal'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_apply_tenant_platform_oidc_material_v1(
  p_command jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_apply jsonb := p_command -> 'apply';
  v_auth jsonb := p_command -> 'apply' -> 'authentication';
  v_oidc jsonb := p_command -> 'apply' -> 'authentication' -> 'oidc';
  v_material jsonb := p_command -> 'apply' -> 'oidcSession';
  v_id jsonb;
  v_refresh jsonb;
  v_legacy jsonb;
  v_result jsonb;
  v_transaction_id bytea;
  v_tenant_id uuid;
  v_material_id uuid;
  v_expires_at timestamptz;
  v_applied_at timestamptz;
  v_id_key integer;
  v_id_cipher bytea;
  v_id_digest bytea;
  v_refresh_key integer;
  v_refresh_cipher bytea;
  v_refresh_digest bytea;
  v_refresh_generation bigint := 0;
  v_access_expires_at timestamptz;
  v_client_secret_revision bigint;
  v_transaction record;
  v_application public.tenant_platform_oidc_authentication_applications%ROWTYPE;
  v_owner_session_id uuid;
  v_owner_continuation_id uuid;
  v_family_id uuid;
  v_owner_expires_at timestamptz;
  v_existing public.tenant_oidc_session_materials%ROWTYPE;
  v_has_material boolean;
  v_has_id boolean;
  v_has_refresh boolean;
BEGIN
  v_has_material := v_material IS NOT NULL AND v_material <> 'null'::jsonb;
  PERFORM app.private_mfa_assert_json_object_v1(
    v_oidc,
    ARRAY['transactionId','expectedVersion','pins','completedAt','returnPath','materialId'],
    ARRAY['transactionId','expectedVersion','pins','completedAt','returnPath','materialId'],
    262144
  );
  BEGIN
    v_transaction_id := app.private_mfa_decode_base64_v1(
      v_oidc ->> 'transactionId',32,32
    );
    v_tenant_id := app.private_mfa_require_uuidv7_v1(v_auth ->> 'tenantId');
    v_material_id := app.private_mfa_require_uuidv7_v1(v_oidc ->> 'materialId');
    v_applied_at := (v_apply ->> 'appliedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid tenant-platform OIDC material identity'
      USING ERRCODE = '22023';
  END;

  IF v_has_material THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_material,
      ARRAY['materialId','expiresAt','idToken','refreshToken',
        'clientSecretRevision','clientAuthentication','clientId','tokenEndpoint',
        'revocationEndpoint','endSessionEndpoint','postLogoutRedirectUri'],
      ARRAY['materialId','expiresAt','clientId','postLogoutRedirectUri'],1048576
    );
    BEGIN
      IF app.private_mfa_require_uuidv7_v1(v_material ->> 'materialId')
           IS DISTINCT FROM v_material_id THEN
        RAISE EXCEPTION 'material mismatch';
      END IF;
      v_expires_at := (v_material ->> 'expiresAt')::timestamptz;
      v_client_secret_revision := nullif(
        v_material ->> 'clientSecretRevision',''
      )::bigint;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid tenant-platform OIDC material'
        USING ERRCODE = '22023';
    END;
    v_id := v_material -> 'idToken';
    v_refresh := v_material -> 'refreshToken';
  END IF;
  v_has_id := v_id IS NOT NULL AND v_id <> 'null'::jsonb;
  v_has_refresh := v_refresh IS NOT NULL AND v_refresh <> 'null'::jsonb;
  IF v_has_id THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_id,ARRAY['keyVersion','ciphertext','digest'],
      ARRAY['keyVersion','ciphertext','digest'],524288
    );
    v_id_key := (v_id ->> 'keyVersion')::integer;
    v_id_cipher := app.private_mfa_decode_base64_v1(
      v_id ->> 'ciphertext',29,262172
    );
    v_id_digest := app.private_mfa_decode_base64_v1(v_id ->> 'digest',32,32);
  END IF;
  IF v_has_refresh THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_refresh,
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      524288
    );
    v_refresh_key := (v_refresh ->> 'keyVersion')::integer;
    v_refresh_cipher := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'ciphertext',29,262172
    );
    v_refresh_digest := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'digest',32,32
    );
    v_refresh_generation := (v_refresh ->> 'generation')::bigint;
    v_access_expires_at := (v_refresh ->> 'accessExpiresAt')::timestamptz;
  END IF;
  IF v_has_material AND (
       v_expires_at <= v_applied_at
       OR v_expires_at > (v_auth ->> 'validUntil')::timestamptz
       OR date_trunc('microseconds',v_expires_at) <> v_expires_at
     ) OR v_has_id AND (
       v_id_key NOT BETWEEN 1 AND 32767
       OR encode(v_id_digest,'hex') = repeat('00',32)
     ) OR v_has_refresh AND (
       v_refresh_key NOT BETWEEN 1 AND 32767
       OR v_refresh_generation <> 1
       OR encode(v_refresh_digest,'hex') = repeat('00',32)
       OR v_access_expires_at <= v_applied_at
       OR v_access_expires_at > v_expires_at
       OR date_trunc('microseconds',v_access_expires_at) <> v_access_expires_at
     ) OR EXISTS (
       SELECT 1 FROM unnest(ARRAY[v_id_key,v_refresh_key]) AS requested(key_version)
       LEFT JOIN public.identity_keyring_versions AS keyring
         ON keyring.key_version = requested.key_version
        AND keyring.is_active AND keyring.retired_at IS NULL
       WHERE requested.key_version IS NOT NULL AND keyring.key_version IS NULL
     ) THEN
    RAISE EXCEPTION 'tenant-platform OIDC material is stale'
      USING ERRCODE = '40001';
  END IF;

  SELECT transaction.operation_run_id,transaction.state,
         transaction.platform_provider_id AS provider_id,
         transaction.binding_id,transaction.client_secret_revision,
         transaction.client_id,transaction.post_logout_redirect_uri,
         transaction.allow_refresh_token,discovery.client_authentication,
         convert_from(discovery.document,'UTF8')::jsonb AS discovery_document
    INTO v_transaction
  FROM public.tenant_platform_oidc_authentication_transactions AS transaction
  JOIN public.platform_oidc_discovery_snapshots AS discovery
    ON discovery.provider_id = transaction.platform_provider_id
   AND discovery.revision = transaction.discovery_revision
   AND discovery.document_digest = transaction.discovery_digest
  WHERE transaction.tenant_id = v_tenant_id
    AND transaction.transaction_id = v_transaction_id
    AND transaction.operation_run_id = v_material_id
    AND transaction.provider_kind = 'oidc'
  FOR UPDATE OF transaction;
  IF NOT FOUND OR v_transaction.state NOT IN ('claimed','completed') THEN
    RETURN NULL;
  END IF;
  IF v_has_material IS DISTINCT FROM (
       v_transaction.allow_refresh_token OR nullif(
         v_transaction.discovery_document ->> 'end_session_endpoint',''
       ) IS NOT NULL
     )
     OR v_has_id IS DISTINCT FROM (nullif(
       v_transaction.discovery_document ->> 'end_session_endpoint',''
     ) IS NOT NULL)
     OR v_has_refresh IS DISTINCT FROM v_transaction.allow_refresh_token
     OR v_has_material AND (
       v_material ->> 'clientId' IS DISTINCT FROM v_transaction.client_id
       OR v_material ->> 'postLogoutRedirectUri' IS DISTINCT FROM
          v_transaction.post_logout_redirect_uri
       OR nullif(v_material ->> 'endSessionEndpoint','') IS DISTINCT FROM
          nullif(v_transaction.discovery_document ->> 'end_session_endpoint','')
       OR v_has_refresh AND (
         v_client_secret_revision IS DISTINCT FROM
           v_transaction.client_secret_revision
         OR v_material ->> 'clientAuthentication' IS DISTINCT FROM
           v_transaction.client_authentication
         OR v_material ->> 'tokenEndpoint' IS DISTINCT FROM
           v_transaction.discovery_document ->> 'token_endpoint'
         OR nullif(v_material ->> 'revocationEndpoint','') IS DISTINCT FROM
           nullif(v_transaction.discovery_document ->> 'revocation_endpoint','')
       )
     ) THEN
    RAISE EXCEPTION 'tenant-platform OIDC material pins are stale'
      USING ERRCODE = '40001';
  END IF;

  v_legacy := jsonb_set(
    p_command - 'unused','{apply}',
    jsonb_set(
      v_apply - 'oidcSession','{authentication,oidc}',
      v_oidc - 'materialId',true
    ),true
  );
  v_result := app.apply_tenant_platform_oidc_authentication_v1(v_legacy);
  IF v_result ->> 'category' <> 'success' OR NOT v_has_material THEN
    RETURN v_result;
  END IF;
  SELECT application.* INTO STRICT v_application
  FROM public.tenant_platform_oidc_authentication_applications AS application
  WHERE application.tenant_id = v_tenant_id
    AND application.transaction_id = v_transaction_id
    AND application.category = 'success';
  v_owner_session_id := v_application.session_id;
  v_owner_continuation_id := v_application.continuation_id;
  IF v_owner_session_id IS NOT NULL THEN
    SELECT session.rotation_family_id,session.absolute_expires_at
      INTO STRICT v_family_id,v_owner_expires_at
    FROM public.auth_sessions AS session
    JOIN public.auth_session_tenant_platform_federated_provenance AS provenance
      ON provenance.tenant_id = v_tenant_id
     AND provenance.session_id = session.id
     AND provenance.user_id = session.user_id
    WHERE session.id = v_owner_session_id
      AND session.user_id = v_application.user_id
      AND session.active_tenant_id = v_tenant_id
      AND session.authentication_method = 'oidc'
      AND provenance.platform_provider_id = v_transaction.provider_id
      AND provenance.binding_id = v_transaction.binding_id
      AND provenance.external_identity_id = v_application.external_identity_id;
  ELSE
    SELECT continuation.expires_at INTO STRICT v_owner_expires_at
    FROM public.tenant_post_primary_continuations AS continuation
    WHERE continuation.tenant_id = v_tenant_id
      AND continuation.id = v_owner_continuation_id
      AND continuation.user_id = v_application.user_id
      AND continuation.primary_kind = 'tenant_platform_provider'
      AND continuation.platform_provider_id = v_transaction.provider_id
      AND continuation.binding_id = v_transaction.binding_id
      AND continuation.external_identity_id = v_application.external_identity_id;
  END IF;
  IF v_expires_at > v_owner_expires_at THEN
    RAISE EXCEPTION 'tenant-platform OIDC material exceeds owner expiry'
      USING ERRCODE = '40001';
  END IF;
  SELECT material.* INTO v_existing
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.id = v_material_id;
  IF FOUND THEN
    IF v_existing.authority <> 'tenant_platform_provider'
       OR v_existing.tenant_id IS DISTINCT FROM v_tenant_id
       OR v_existing.provider_id IS DISTINCT FROM v_transaction.provider_id
       OR v_existing.binding_id IS DISTINCT FROM v_transaction.binding_id
       OR v_existing.user_id IS DISTINCT FROM v_application.user_id
       OR v_existing.external_identity_id IS DISTINCT FROM
          v_application.external_identity_id
       OR v_existing.session_id IS DISTINCT FROM v_owner_session_id
       OR v_existing.continuation_id IS DISTINCT FROM v_owner_continuation_id
       OR v_existing.rotation_family_id IS DISTINCT FROM v_family_id
       OR v_existing.expires_at IS DISTINCT FROM v_expires_at
       OR v_existing.id_token_digest IS DISTINCT FROM v_id_digest
       OR v_existing.refresh_token_digest IS DISTINCT FROM v_refresh_digest
       OR (v_existing.refresh_state <> 'unavailable') IS DISTINCT FROM
          v_has_refresh THEN
      RETURN NULL;
    END IF;
    RETURN v_result;
  END IF;
  INSERT INTO public.tenant_oidc_session_materials (
    id,tenant_id,authority,session_id,continuation_id,rotation_family_id,
    user_id,provider_id,binding_id,provider_kind,external_identity_id,
    aad_version,id_token_key_version,id_token_ciphertext,id_token_digest,
    refresh_token_key_version,refresh_token_ciphertext,refresh_token_digest,
    refresh_generation,refresh_state,refresh_version,access_expires_at,
    expires_at,client_secret_revision,client_authentication,client_id,
    token_endpoint,revocation_endpoint,end_session_endpoint,
    post_logout_redirect_uri,logout_disposition,created_at,updated_at
  ) VALUES (
    v_material_id,v_tenant_id,'tenant_platform_provider',v_owner_session_id,
    v_owner_continuation_id,v_family_id,v_application.user_id,
    v_transaction.provider_id,v_transaction.binding_id,'oidc',
    v_application.external_identity_id,1,v_id_key,v_id_cipher,v_id_digest,
    v_refresh_key,v_refresh_cipher,v_refresh_digest,v_refresh_generation,
    CASE WHEN v_has_refresh THEN 'ready' ELSE 'unavailable' END,1,
    v_access_expires_at,v_expires_at,v_client_secret_revision,
    v_material ->> 'clientAuthentication',v_material ->> 'clientId',
    v_material ->> 'tokenEndpoint',
    nullif(v_material ->> 'revocationEndpoint',''),
    nullif(v_material ->> 'endSessionEndpoint',''),
    v_material ->> 'postLogoutRedirectUri',
    CASE WHEN nullif(v_material ->> 'endSessionEndpoint','') IS NULL
      THEN 'not_configured' ELSE 'available' END,v_applied_at,v_applied_at
  );
  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RAISE EXCEPTION 'tenant-platform OIDC material authority is unavailable'
    USING ERRCODE = '40001';
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant-platform OIDC material'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.private_apply_tenant_platform_oidc_material_v1(jsonb)
  OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION
  app.private_apply_tenant_platform_oidc_material_v1(jsonb)
FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
  periapsis_auditor;
--> statement-breakpoint

-- Wrap the existing SAML-aware federated apply ABI. The predecessor still
-- performs every JIT, policy, one-time-transaction, session and audit check;
-- this wrapper validates the OIDC material against that exact pinned login and
-- stores it only after a successful authority result in the same transaction.
ALTER FUNCTION app.apply_federated_authentication_v1(jsonb)
  RENAME TO private_apply_federated_authentication_v31;
--> statement-breakpoint
DROP FUNCTION IF EXISTS app.apply_federated_authentication_v1(jsonb);
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.private_apply_federated_authentication_v31(jsonb)
  FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
       periapsis_auditor, periapsis_audit_reader_owner,
       periapsis_notification_dispatch_owner, periapsis_sla_api_owner,
       periapsis_sla_worker_owner, periapsis_sla_readiness_owner;
--> statement-breakpoint

CREATE FUNCTION app.apply_federated_authentication_v1(p_command jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_apply jsonb;
  v_auth jsonb;
  v_protocol jsonb;
  v_material jsonb;
  v_id_token jsonb;
  v_refresh jsonb;
  v_legacy_apply jsonb;
  v_legacy_command jsonb;
  v_result jsonb;
  v_operation_digest bytea;
  v_transaction_id bytea;
  v_tenant_id uuid;
  v_material_id uuid;
  v_id_key_version integer;
  v_id_ciphertext bytea;
  v_id_digest bytea;
  v_refresh_key_version integer;
  v_refresh_ciphertext bytea;
  v_refresh_digest bytea;
  v_refresh_generation bigint := 0;
  v_access_expires_at timestamptz;
  v_material_expires_at timestamptz;
  v_client_secret_revision bigint;
  v_client_authentication text;
  v_client_id text;
  v_token_endpoint text;
  v_revocation_endpoint text;
  v_end_session_endpoint text;
  v_post_logout_redirect_uri text;
  v_applied_at timestamptz;
  v_owner_session_id uuid;
  v_owner_continuation_id uuid;
  v_rotation_family_id uuid;
  v_absolute_expires_at timestamptz;
  v_external_identity_id uuid;
  v_transaction record;
  v_application public.tenant_federated_authentication_applications%ROWTYPE;
  v_existing public.tenant_oidc_session_materials%ROWTYPE;
  v_has_material boolean;
  v_has_id_token boolean;
  v_has_refresh boolean;
BEGIN
  IF jsonb_typeof(p_command) <> 'object'
     OR p_command -> 'apply' -> 'authentication' ->> 'protocol' <> 'oidc' THEN
    RETURN app.private_apply_federated_authentication_v31(p_command);
  END IF;
  IF p_command #>> '{apply,authentication,oidc,pins,provider,scope}'
       = 'platform' THEN
    RETURN app.private_apply_tenant_platform_oidc_material_v1(p_command);
  END IF;

  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,ARRAY['operationDigest','apply'],ARRAY['operationDigest','apply'],2097152
  );
  v_apply := p_command -> 'apply';
  v_auth := v_apply -> 'authentication';
  v_protocol := v_auth -> 'oidc';
  v_material := v_apply -> 'oidcSession';
  v_has_material := v_material IS NOT NULL AND v_material <> 'null'::jsonb;
  PERFORM app.private_mfa_assert_json_object_v1(
    v_protocol,
    ARRAY['transactionId','expectedVersion','pins','completedAt','returnPath','materialId'],
    ARRAY['transactionId','expectedVersion','pins','completedAt','returnPath','materialId'],
    262144
  );
  IF v_has_material THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_material,
      ARRAY['materialId','expiresAt','idToken','refreshToken','clientSecretRevision',
        'clientAuthentication','clientId','tokenEndpoint','revocationEndpoint',
        'endSessionEndpoint','postLogoutRedirectUri'],
      ARRAY['materialId','expiresAt','clientId','postLogoutRedirectUri'],
      1048576
    );
    v_id_token := v_material -> 'idToken';
    v_has_id_token := v_id_token IS NOT NULL AND v_id_token <> 'null'::jsonb;
    IF v_has_id_token THEN
      PERFORM app.private_mfa_assert_json_object_v1(
        v_id_token,ARRAY['keyVersion','ciphertext','digest'],
        ARRAY['keyVersion','ciphertext','digest'],524288
      );
    END IF;
  ELSE
    v_has_id_token := false;
  END IF;

  BEGIN
    v_operation_digest := app.private_mfa_decode_base64_v1(
      p_command ->> 'operationDigest',32,32
    );
    v_transaction_id := app.private_mfa_decode_base64_v1(
      v_protocol ->> 'transactionId',32,32
    );
    v_tenant_id := app.private_mfa_require_uuidv7_v1(v_auth ->> 'tenantId');
    v_material_id := app.private_mfa_require_uuidv7_v1(
      v_protocol ->> 'materialId'
    );
    IF v_has_material AND app.private_mfa_require_uuidv7_v1(
         v_material ->> 'materialId'
       ) IS DISTINCT FROM v_material_id THEN
      RAISE EXCEPTION 'OIDC material identity is inconsistent';
    END IF;
    IF v_has_id_token THEN
      v_id_key_version := (v_id_token ->> 'keyVersion')::integer;
    END IF;
    IF v_has_material THEN
      v_client_secret_revision := nullif(
        v_material ->> 'clientSecretRevision',''
      )::bigint;
      v_material_expires_at := (v_material ->> 'expiresAt')::timestamptz;
    END IF;
    v_applied_at := (v_apply ->> 'appliedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'OIDC material identity is invalid'
      USING ERRCODE = '22023';
  END;
  IF v_has_id_token THEN
    v_id_ciphertext := app.private_mfa_decode_base64_v1(
      v_id_token ->> 'ciphertext',29,262172
    );
    v_id_digest := app.private_mfa_decode_base64_v1(
      v_id_token ->> 'digest',32,32
    );
  END IF;
  IF v_has_material THEN
    v_client_authentication := v_material ->> 'clientAuthentication';
    v_client_id := v_material ->> 'clientId';
    v_token_endpoint := v_material ->> 'tokenEndpoint';
    v_revocation_endpoint := nullif(v_material ->> 'revocationEndpoint','');
    v_end_session_endpoint := nullif(v_material ->> 'endSessionEndpoint','');
    v_post_logout_redirect_uri := v_material ->> 'postLogoutRedirectUri';
  END IF;

  IF v_has_id_token AND (v_id_key_version NOT BETWEEN 1 AND 32767
     OR encode(v_id_digest,'hex') = repeat('00',32)
     OR NOT EXISTS (
       SELECT 1 FROM public.identity_keyring_versions AS keyring
       WHERE keyring.key_version = v_id_key_version
         AND keyring.is_active AND keyring.retired_at IS NULL
     )) THEN
    RAISE EXCEPTION 'OIDC ID token key is unavailable'
      USING ERRCODE = '40001';
  END IF;

  IF v_has_material THEN
    v_refresh := v_material -> 'refreshToken';
  END IF;
  v_has_refresh := v_refresh IS NOT NULL AND v_refresh <> 'null'::jsonb;
  IF v_has_refresh THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_refresh,
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      524288
    );
    BEGIN
      v_refresh_key_version := (v_refresh ->> 'keyVersion')::integer;
      v_refresh_generation := (v_refresh ->> 'generation')::bigint;
      v_access_expires_at := (v_refresh ->> 'accessExpiresAt')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'OIDC refresh material is invalid'
        USING ERRCODE = '22023';
    END;
    v_refresh_ciphertext := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'ciphertext',29,262172
    );
    v_refresh_digest := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'digest',32,32
    );
    IF v_refresh_generation <> 1
       OR encode(v_refresh_digest,'hex') = repeat('00',32)
       OR v_access_expires_at <= v_applied_at
       OR v_access_expires_at > v_material_expires_at
       OR date_trunc('microseconds',v_access_expires_at) <> v_access_expires_at
       OR v_refresh_key_version NOT BETWEEN 1 AND 32767
       OR NOT EXISTS (
         SELECT 1 FROM public.identity_keyring_versions AS keyring
         WHERE keyring.key_version = v_refresh_key_version
           AND keyring.is_active AND keyring.retired_at IS NULL
       ) THEN
      RAISE EXCEPTION 'OIDC refresh material is stale'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  IF v_has_material AND (
       v_material_expires_at <= v_applied_at
       OR v_material_expires_at > (v_auth ->> 'validUntil')::timestamptz
       OR date_trunc('microseconds',v_material_expires_at)
            <> v_material_expires_at
     ) THEN
    RAISE EXCEPTION 'OIDC material expiry is stale'
      USING ERRCODE = '40001';
  END IF;

  SELECT transaction.operation_run_id,transaction.state,
         transaction.provider_id,transaction.binding_id,
         transaction.client_secret_revision,transaction.client_id,
         transaction.post_logout_redirect_uri,transaction.allow_refresh_token,
         discovery.client_authentication,
         convert_from(discovery.document,'UTF8')::jsonb AS discovery_document
    INTO v_transaction
  FROM public.tenant_federated_authentication_transactions AS transaction
  JOIN public.tenant_oidc_discovery_snapshots AS discovery
    ON discovery.tenant_id = transaction.tenant_id
   AND discovery.provider_id = transaction.provider_id
   AND discovery.revision = transaction.discovery_revision
   AND discovery.document_digest = transaction.discovery_digest
  WHERE transaction.tenant_id = v_tenant_id
    AND transaction.protocol = 'oidc'
    AND transaction.transaction_id = v_transaction_id
    AND transaction.operation_run_id = v_material_id
    AND transaction.provider_kind = 'oidc'
  FOR UPDATE OF transaction;
  IF NOT FOUND OR v_transaction.state NOT IN ('claimed','completed') THEN
    RETURN app.private_federated_apply_response_v1(
      v_operation_digest,'oidc',v_tenant_id,v_apply ->> 'disposition','denied'
    );
  END IF;
  IF v_has_material IS DISTINCT FROM (
       v_transaction.allow_refresh_token
       OR nullif(v_transaction.discovery_document ->> 'end_session_endpoint','')
          IS NOT NULL
     )
     OR v_has_id_token IS DISTINCT FROM (
       nullif(v_transaction.discovery_document ->> 'end_session_endpoint','')
       IS NOT NULL
     )
     OR v_has_refresh IS DISTINCT FROM v_transaction.allow_refresh_token
     OR (v_has_material AND (
       v_client_id IS DISTINCT FROM v_transaction.client_id
       OR (v_has_refresh AND (
         v_client_secret_revision IS DISTINCT FROM v_transaction.client_secret_revision
         OR v_client_authentication IS DISTINCT FROM v_transaction.client_authentication
         OR v_token_endpoint IS DISTINCT FROM
            v_transaction.discovery_document ->> 'token_endpoint'
         OR v_revocation_endpoint IS DISTINCT FROM nullif(
            v_transaction.discovery_document ->> 'revocation_endpoint',''
         )
       ))
       OR v_end_session_endpoint IS DISTINCT FROM nullif(
          v_transaction.discovery_document ->> 'end_session_endpoint',''
       )
       OR v_post_logout_redirect_uri IS DISTINCT FROM
          v_transaction.post_logout_redirect_uri
     )) THEN
    RAISE EXCEPTION 'OIDC material pins are stale'
      USING ERRCODE = '40001';
  END IF;

  v_legacy_apply := v_apply - 'oidcSession';
  v_legacy_apply := jsonb_set(
    v_legacy_apply,'{authentication,oidc}',v_protocol - 'materialId',true
  );
  v_legacy_command := jsonb_set(p_command,'{apply}',v_legacy_apply,true);
  v_result := app.private_apply_federated_authentication_v31(v_legacy_command);
  IF v_result ->> 'category' <> 'success' THEN
    RETURN v_result;
  END IF;
  IF NOT v_has_material THEN
    RETURN v_result;
  END IF;

  SELECT application.* INTO STRICT v_application
  FROM public.tenant_federated_authentication_applications AS application
  WHERE application.tenant_id = v_tenant_id
    AND application.protocol = 'oidc'
    AND application.transaction_id = v_transaction_id
    AND application.category = 'success';
  v_owner_session_id := v_application.session_id;
  v_owner_continuation_id := v_application.continuation_id;
  IF v_owner_session_id IS NOT NULL THEN
    SELECT provenance.external_identity_id,session.rotation_family_id,
           session.absolute_expires_at
      INTO STRICT v_external_identity_id,v_rotation_family_id,
        v_absolute_expires_at
    FROM public.auth_session_federated_provenance AS provenance
    JOIN public.auth_sessions AS session
      ON session.id = provenance.session_id
     AND session.user_id = provenance.user_id
     AND session.active_tenant_id = provenance.tenant_id
    WHERE provenance.tenant_id = v_tenant_id
      AND provenance.session_id = v_owner_session_id
      AND provenance.user_id = v_application.user_id
      AND provenance.provider_id = v_transaction.provider_id
      AND provenance.binding_id = v_transaction.binding_id
      AND provenance.provider_kind = 'oidc';
    IF v_access_expires_at IS NOT NULL
       AND v_access_expires_at > v_absolute_expires_at THEN
      RAISE EXCEPTION 'OIDC refresh exceeds absolute session expiry'
        USING ERRCODE = '40001';
    END IF;
    IF v_material_expires_at > v_absolute_expires_at THEN
      RAISE EXCEPTION 'OIDC material exceeds absolute session expiry'
        USING ERRCODE = '40001';
    END IF;
  ELSE
    SELECT continuation.external_identity_id,continuation.expires_at
      INTO STRICT v_external_identity_id,v_absolute_expires_at
    FROM public.tenant_post_primary_continuations AS continuation
    WHERE continuation.tenant_id = v_tenant_id
      AND continuation.id = v_owner_continuation_id
      AND continuation.user_id = v_application.user_id
      AND continuation.provider_id = v_transaction.provider_id
      AND continuation.binding_id = v_transaction.binding_id
      AND continuation.provider_kind = 'oidc';
    IF v_material_expires_at > v_absolute_expires_at THEN
      RAISE EXCEPTION 'OIDC material exceeds continuation expiry'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  SELECT material.* INTO v_existing
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_tenant_id AND material.id = v_material_id;
  IF FOUND THEN
    IF v_existing.user_id IS DISTINCT FROM v_application.user_id
       OR v_existing.provider_id IS DISTINCT FROM v_transaction.provider_id
       OR v_existing.binding_id IS DISTINCT FROM v_transaction.binding_id
       OR v_existing.external_identity_id IS DISTINCT FROM v_external_identity_id
       OR v_existing.authority IS DISTINCT FROM 'tenant_provider'
       OR v_existing.expires_at IS DISTINCT FROM v_material_expires_at
       OR v_existing.id_token_digest IS DISTINCT FROM v_id_digest
       OR v_existing.refresh_token_digest IS DISTINCT FROM v_refresh_digest
       OR v_existing.session_id IS DISTINCT FROM v_owner_session_id
       OR v_existing.continuation_id IS DISTINCT FROM v_owner_continuation_id
       OR v_existing.rotation_family_id IS DISTINCT FROM v_rotation_family_id
       OR v_existing.client_secret_revision IS DISTINCT FROM v_client_secret_revision
       OR v_existing.client_authentication IS DISTINCT FROM v_client_authentication
       OR v_existing.client_id IS DISTINCT FROM v_client_id
       OR v_existing.token_endpoint IS DISTINCT FROM v_token_endpoint
       OR v_existing.revocation_endpoint IS DISTINCT FROM v_revocation_endpoint
       OR v_existing.end_session_endpoint IS DISTINCT FROM v_end_session_endpoint
       OR v_existing.post_logout_redirect_uri IS DISTINCT FROM
          v_post_logout_redirect_uri
       OR (v_existing.refresh_state <> 'unavailable') IS DISTINCT FROM
          v_has_refresh THEN
      RETURN app.private_federated_apply_response_v1(
        v_operation_digest,'oidc',v_tenant_id,v_apply ->> 'disposition','replay'
      );
    END IF;
    RETURN v_result;
  END IF;

  INSERT INTO public.tenant_oidc_session_materials (
    id,tenant_id,authority,session_id,continuation_id,rotation_family_id,user_id,
    provider_id,binding_id,provider_kind,external_identity_id,aad_version,
    id_token_key_version,id_token_ciphertext,id_token_digest,
    refresh_token_key_version,
    refresh_token_ciphertext,refresh_token_digest,refresh_generation,
    refresh_state,refresh_version,access_expires_at,expires_at,
    client_secret_revision,
    client_authentication,client_id,token_endpoint,revocation_endpoint,
    end_session_endpoint,post_logout_redirect_uri,logout_disposition,
    created_at,updated_at
  ) VALUES (
    v_material_id,v_tenant_id,'tenant_provider',v_owner_session_id,
    v_owner_continuation_id,
    v_rotation_family_id,v_application.user_id,v_transaction.provider_id,
    v_transaction.binding_id,'oidc',v_external_identity_id,1,
    v_id_key_version,v_id_ciphertext,v_id_digest,v_refresh_key_version,
    v_refresh_ciphertext,v_refresh_digest,v_refresh_generation,
    CASE WHEN NOT v_has_refresh
      THEN 'unavailable' ELSE 'ready' END,
    1,v_access_expires_at,v_material_expires_at,v_client_secret_revision,
    v_client_authentication,
    v_client_id,v_token_endpoint,v_revocation_endpoint,v_end_session_endpoint,
    v_post_logout_redirect_uri,
    CASE WHEN v_end_session_endpoint IS NULL
      THEN 'not_configured' ELSE 'available' END,
    v_applied_at,v_applied_at
  );
  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RAISE EXCEPTION 'OIDC material authority is unavailable'
    USING ERRCODE = '40001';
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC federated apply command'
    USING ERRCODE = '22023';
END;
