-- Preserve the single immutable OIDC material row across every authority
-- owner transition. Migration 0165 preserved the full tenant-provider
-- implementation under its private v34 name and installed a family dispatcher;
-- migration 0210 then wrapped that dispatcher with LDAP routing. Patch only the
-- private v34 body so both public dispatch layers remain intact. Each replacement
-- is anchored to the already-hardened SAML v2 definition and aborts the migration
-- if that predecessor drifted.
DO $oidc_step_up_material_transfer_v1$
DECLARE
  v_definition text;
  v_old text := $old$
    UPDATE public.tenant_saml_session_materials AS material
    SET session_id = NULL, continuation_id = v_continuation_id
    WHERE material.tenant_id = v_tenant_id
      AND material.session_id = v_session_id
      AND material.aad_version = 2;
    IF v_provenance.provider_kind = 'saml' AND NOT FOUND THEN
      RAISE EXCEPTION 'SAML session material ownership is stale'
        USING ERRCODE = '40001';
    END IF;$old$;
  v_new text := $new$
    UPDATE public.tenant_saml_session_materials AS material
    SET session_id = NULL, continuation_id = v_continuation_id
    WHERE material.tenant_id = v_tenant_id
      AND material.session_id = v_session_id
      AND material.aad_version = 2;
    IF v_provenance.provider_kind = 'saml' AND NOT FOUND THEN
      RAISE EXCEPTION 'SAML session material ownership is stale'
        USING ERRCODE = '40001';
    END IF;
    UPDATE public.tenant_oidc_session_materials AS material
    SET session_id = NULL, continuation_id = v_continuation_id,
        rotation_family_id = NULL, updated_at = v_observed_at
    WHERE material.tenant_id = v_tenant_id
      AND material.session_id = v_session_id
      AND material.provider_kind = 'oidc';
    IF v_provenance.provider_kind = 'oidc' AND NOT FOUND
       AND NOT app.private_tenant_provider_oidc_material_absence_attested_v1(
         v_tenant_id,v_session_id,NULL
       ) THEN
      RAISE EXCEPTION 'OIDC session material ownership is stale'
        USING ERRCODE = '40001';
    END IF;$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.private_v34_apply_federated_session_revalidation_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
     OR strpos(substr(v_definition,strpos(v_definition,v_old) + length(v_old)),v_old) > 0 THEN
    RAISE EXCEPTION 'unexpected OIDC step-up predecessor definition';
  END IF;
  EXECUTE replace(v_definition,v_old,v_new);
END;
$oidc_step_up_material_transfer_v1$;
