       ) THEN
      RAISE EXCEPTION 'OIDC session material ownership is stale'
        USING ERRCODE = '40001';
    END IF;$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.private_v34_apply_federated_session_revalidation_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
     OR strpos(substr(v_definition,strpos(v_definition,v_old) + length(v_old)),v_old) > 0 THEN
    RAISE EXCEPTION 'unexpected OIDC revalidation predecessor definition';
