-- The reservation method describes the MFA factor, while the persisted
-- session method describes the immutable primary provenance. Normalize the
-- successor before moving protocol material so its owner guard never sees the
-- transient factor method.
DO $oidc_mfa_primary_method_order_v1$
DECLARE
  v_definition text;
  v_old text := $old$
  IF v_anchor.flow = 'session' THEN
    UPDATE public.tenant_saml_session_materials AS material
$old$;
  v_new text := $new$
  UPDATE ONLY public.auth_sessions AS session
  SET authentication_method = v_provider_authentication_method
  WHERE session.id = v_new_session_id
    AND session.user_id = v_user_id
    AND session.active_tenant_id = v_tenant_id
    AND session.authentication_method = v_authentication_method;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'federated MFA successor primary method is unavailable'
      USING ERRCODE = '23514';
  END IF;
  IF v_anchor.flow = 'session' THEN
    UPDATE public.tenant_saml_session_materials AS material
$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.private_mfa_apply_federated_session_v1(jsonb,uuid,text,uuid,bigint,timestamp with time zone)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
