CREATE FUNCTION app.claim_tenant_oidc_refresh_rotation_v1(p_command jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_tenant_id uuid;
  v_user_id uuid;
  v_family_id uuid;
  v_expected_generation bigint;
  v_expected_digest bytea;
  v_requested_claimed_at timestamptz;
  v_claimed_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_session public.auth_sessions%ROWTYPE;
  v_category text;
  v_version bigint;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['sessionFamilyId','expectedGeneration','expectedDigest','claimedAt'],
    ARRAY['sessionFamilyId','expectedGeneration','expectedDigest','claimedAt'],
    8192
  );
  BEGIN
    v_tenant_id := current_setting('app.tenant_id',true)::uuid;
    v_user_id := current_setting('app.user_id',true)::uuid;
    v_family_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'sessionFamilyId'
    );
    v_expected_generation := (p_command ->> 'expectedGeneration')::bigint;
    v_claimed_at := (p_command ->> 'claimedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid OIDC refresh claim'
      USING ERRCODE = '22023';
  END;
  v_expected_digest := app.private_mfa_decode_base64_v1(
    p_command ->> 'expectedDigest',32,32
  );
  IF v_tenant_id IS NULL OR v_user_id IS NULL
     OR (uuid_extract_version(v_tenant_id) = 7) IS DISTINCT FROM true
     OR (uuid_extract_version(v_user_id) = 7) IS DISTINCT FROM true
     OR v_expected_generation < 1
     OR encode(v_expected_digest,'hex') = repeat('00',32)
     OR v_claimed_at IS NULL
     OR date_trunc('microseconds',v_claimed_at) <> v_claimed_at
     OR abs(extract(epoch FROM (transaction_timestamp() - v_claimed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC refresh claim'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_tenant_id
    AND material.rotation_family_id = v_family_id
    AND material.user_id = v_user_id
    AND material.session_id IS NOT NULL
    AND material.continuation_id IS NULL
    AND material.refresh_state IN ('ready','claimed')
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;
  SELECT session.* INTO v_session
  FROM public.auth_sessions AS session
  WHERE session.id = v_material.session_id
    AND session.user_id = v_material.user_id
    AND session.rotation_family_id = v_family_id
    AND session.active_tenant_id = v_tenant_id
    AND session.authentication_method = 'oidc'
  FOR UPDATE;
  IF NOT FOUND OR v_session.revoked_at IS NOT NULL
     OR v_session.absolute_expires_at <= v_claimed_at THEN
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_state = 'revoked',refresh_version = material.refresh_version + 1,
        updated_at = v_claimed_at
    WHERE material.tenant_id = v_tenant_id AND material.id = v_material.id;
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;

  IF v_material.refresh_generation IS DISTINCT FROM v_expected_generation
     OR v_material.refresh_token_digest IS DISTINCT FROM v_expected_digest THEN
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;
  IF v_material.refresh_state = 'claimed' THEN
    UPDATE public.auth_sessions AS family
    SET revoked_at = v_claimed_at,revoke_reason = 'oidc_refresh_reuse'
    WHERE family.user_id = v_material.user_id
      AND family.rotation_family_id = v_family_id
      AND family.revoked_at IS NULL;
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_state = 'revoked',refresh_version = material.refresh_version + 1,
        updated_at = v_claimed_at
    WHERE material.tenant_id = v_tenant_id AND material.id = v_material.id;
    INSERT INTO public.audit_events (
      id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
      resource_type,resource_id,authentication_method,outcome,metadata
    ) VALUES (
      uuidv7(),v_tenant_id,0,v_claimed_at,'user',v_material.user_id,
      'tenant.identity.oidc_refresh_reuse','auth_session',v_material.session_id,
      'oidc','success',jsonb_build_object(
        'session_family_id',v_family_id::text,
        'material_id',v_material.id::text,'material_disclosed',false
      )
    );
    RETURN jsonb_build_object(
      'category','reuse','sessionFamilyId',v_family_id::text,
      'tenantId',v_tenant_id::text,'materialId',v_material.id::text
    );
  END IF;

  UPDATE public.tenant_oidc_session_materials AS material
  SET refresh_state = 'claimed',refresh_claimed_at = v_claimed_at,
      refresh_version = material.refresh_version + 1,updated_at = v_claimed_at
  WHERE material.tenant_id = v_tenant_id AND material.id = v_material.id
    AND material.refresh_state = 'ready'
  RETURNING material.refresh_version INTO v_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OIDC refresh claim lost CAS'
      USING ERRCODE = '40001';
  END IF;
  v_category := 'claimed';
  RETURN jsonb_build_object(
    'category',v_category,
    'tenantId',v_tenant_id::text,
    'materialId',v_material.id::text,
    'sessionFamilyId',v_family_id::text,
    'generation',v_material.refresh_generation,
    'version',v_version,
    'provider',jsonb_build_object(
      'scope','tenant','tenantId',v_tenant_id::text,
      'providerId',v_material.provider_id::text,
      'bindingId',v_material.binding_id::text
    ),
    'bindingId',v_material.binding_id::text,
    'clientSecretRevision',v_material.client_secret_revision,
    'endpoint',v_material.token_endpoint,
    'clientAuthentication',v_material.client_authentication,
    'clientId',v_material.client_id,
    'token',jsonb_build_object(
      'keyVersion',v_material.refresh_token_key_version,
      'ciphertext',replace(encode(v_material.refresh_token_ciphertext,'base64'),E'\n','')
    ),
    'tokenDigest',replace(encode(v_material.refresh_token_digest,'base64'),E'\n',''),
    'absoluteSessionExpiry',to_jsonb(v_session.absolute_expires_at)
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC refresh claim'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.complete_tenant_oidc_refresh_rotation_v1(p_command jsonb)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_context_tenant uuid;
  v_context_user uuid;
  v_tenant_id uuid;
  v_material_id uuid;
  v_family_id uuid;
  v_expected_version bigint;
  v_expected_generation bigint;
  v_successor_generation bigint;
  v_successor_digest bytea;
  v_successor_key_version integer;
  v_successor_ciphertext bytea;
  v_access_expires_at timestamptz;
  v_completed_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_absolute_expires_at timestamptz;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['tenantId','materialId','sessionFamilyId','expectedVersion',
      'expectedGeneration','successorGeneration','successorDigest',
      'successorToken','accessExpiresAt','completedAt'],
    ARRAY['tenantId','materialId','sessionFamilyId','expectedVersion',
      'expectedGeneration','successorGeneration','successorDigest',
      'successorToken','accessExpiresAt','completedAt'],
    524288
  );
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command -> 'successorToken',ARRAY['keyVersion','ciphertext'],
    ARRAY['keyVersion','ciphertext'],524288
  );
  BEGIN
    v_context_tenant := current_setting('app.tenant_id',true)::uuid;
    v_context_user := current_setting('app.user_id',true)::uuid;
    v_tenant_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'tenantId');
    v_material_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'materialId');
    v_family_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'sessionFamilyId');
    v_expected_version := (p_command ->> 'expectedVersion')::bigint;
    v_expected_generation := (p_command ->> 'expectedGeneration')::bigint;
    v_successor_generation := (p_command ->> 'successorGeneration')::bigint;
    v_successor_key_version := (
      p_command -> 'successorToken' ->> 'keyVersion'
    )::integer;
    v_access_expires_at := (p_command ->> 'accessExpiresAt')::timestamptz;
    v_completed_at := (p_command ->> 'completedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid OIDC refresh completion'
      USING ERRCODE = '22023';
  END;
  v_successor_digest := app.private_mfa_decode_base64_v1(
    p_command ->> 'successorDigest',32,32
  );
  v_successor_ciphertext := app.private_mfa_decode_base64_v1(
    p_command -> 'successorToken' ->> 'ciphertext',17,262144
  );
  IF v_context_tenant IS DISTINCT FROM v_tenant_id
     OR v_context_user IS NULL
     OR (uuid_extract_version(v_context_user) = 7) IS DISTINCT FROM true
     OR v_expected_version < 1 OR v_expected_generation < 1
     OR v_successor_generation <> v_expected_generation + 1
     OR encode(v_successor_digest,'hex') = repeat('00',32)
     OR v_successor_key_version NOT BETWEEN 1 AND 32767
     OR v_completed_at IS NULL
     OR date_trunc('microseconds',v_completed_at) <> v_completed_at
     OR abs(extract(epoch FROM (transaction_timestamp() - v_completed_at))) > 300
     OR v_access_expires_at <= v_completed_at
     OR date_trunc('microseconds',v_access_expires_at) <> v_access_expires_at
     OR NOT EXISTS (
       SELECT 1 FROM public.identity_keyring_versions AS keyring
       WHERE keyring.key_version = v_successor_key_version
         AND keyring.is_active AND keyring.retired_at IS NULL
     ) THEN
    RAISE EXCEPTION 'invalid OIDC refresh completion'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_tenant_id
    AND material.id = v_material_id
    AND material.rotation_family_id = v_family_id
    AND material.user_id = v_context_user
    AND material.session_id IS NOT NULL
    AND material.refresh_state = 'claimed'
    AND material.refresh_version = v_expected_version
    AND material.refresh_generation = v_expected_generation
  FOR UPDATE;
  IF NOT FOUND OR v_material.refresh_token_digest = v_successor_digest THEN
    RETURN false;
  END IF;
  SELECT session.absolute_expires_at INTO v_absolute_expires_at
  FROM public.auth_sessions AS session
  WHERE session.id = v_material.session_id
    AND session.user_id = v_material.user_id
    AND session.rotation_family_id = v_family_id
    AND session.active_tenant_id = v_tenant_id
    AND session.authentication_method = 'oidc'
    AND session.revoked_at IS NULL
    AND session.absolute_expires_at > v_completed_at
  FOR UPDATE;
  IF NOT FOUND OR v_access_expires_at > v_absolute_expires_at THEN
    RETURN false;
  END IF;
  UPDATE public.tenant_oidc_session_materials AS material
  SET refresh_token_key_version = v_successor_key_version,
      refresh_token_ciphertext = v_successor_ciphertext,
      refresh_token_digest = v_successor_digest,
      refresh_generation = v_successor_generation,
      refresh_state = 'ready',refresh_claimed_at = NULL,
      access_expires_at = v_access_expires_at,
      refresh_version = material.refresh_version + 1,
      updated_at = v_completed_at
  WHERE material.tenant_id = v_tenant_id AND material.id = v_material_id
    AND material.refresh_state = 'claimed'
    AND material.refresh_version = v_expected_version
    AND material.refresh_generation = v_expected_generation;
  RETURN FOUND;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC refresh completion'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.claim_tenant_oidc_logout_retry_v1(
  p_request jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_job_id uuid;
  v_candidate_family_id uuid;
  v_requested_observed_at timestamptz;
  v_observed_at timestamptz;
  v_deadline timestamptz;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_material_lookup record;
  v_material_found boolean;
  v_provider jsonb;
  v_admission jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['jobId','observedAt'],ARRAY['jobId','observedAt'],2048
  );
  v_job_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'jobId');
  v_requested_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF date_trunc('microseconds',v_requested_observed_at)
       <> v_requested_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC logout retry claim'
      USING ERRCODE = '22023';
  END IF;
  v_observed_at := date_trunc('microseconds',transaction_timestamp());
  -- Resolve the immutable family without a row lock, then enter the same
  -- family critical section used by logout, refresh, and retention pruning.
  -- Re-read and lock the job only after the advisory fence so no job ->
  -- session/material edge can invert the pruner's family -> session -> job
  -- order.
  SELECT job.session_family_id INTO v_candidate_family_id
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_candidate_family_id::text,90174213
  ));
  SELECT job.* INTO v_job
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id
    AND job.session_family_id = v_candidate_family_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state IN ('complete','dead_letter')
     OR v_job.not_before > v_observed_at
     OR (v_job.state = 'claimed' AND v_job.claim_expires_at > v_observed_at) THEN
    RETURN NULL;
  END IF;
  -- Reserve one version for this claim and one for its completion.  A
  -- saturated retry is failed closed without overflowing the canonical
  -- JavaScript-safe counter boundary.
  IF v_job.version >= 8999999999999998 THEN
    UPDATE public.tenant_oidc_logout_retry_jobs AS job
    SET state = 'dead_letter',attempt = greatest(job.attempt,1),
        claimed_at = coalesce(job.claimed_at,v_observed_at),
        claim_expires_at = coalesce(job.claim_expires_at,v_observed_at),
        completed_at = v_observed_at,updated_at = v_observed_at
    WHERE job.id = v_job_id;
    RETURN NULL;
  END IF;
  IF v_job.attempt >= v_job.maximum_attempts THEN
    UPDATE public.tenant_oidc_logout_retry_jobs AS job
    SET state = 'dead_letter',attempt = greatest(job.attempt,1),
        claimed_at = coalesce(job.claimed_at,v_observed_at),
        claim_expires_at = coalesce(job.claim_expires_at,v_observed_at),
        completed_at = v_observed_at,version = job.version + 1,
        updated_at = v_observed_at
    WHERE job.id = v_job_id;
    RETURN NULL;
  END IF;
  SELECT material AS material,
         least(material.expires_at,session.absolute_expires_at) AS deadline
    INTO v_material_lookup
  FROM public.tenant_oidc_session_materials AS material
  JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
    AS effective ON true
  JOIN public.auth_sessions AS session
    ON session.id = effective.session_id
   AND session.user_id = material.user_id
   AND session.rotation_family_id = material.rotation_family_id
  WHERE material.id = v_job.material_id
    AND material.tenant_id IS NOT DISTINCT FROM v_job.tenant_id
    AND material.authority = v_job.authority
    AND material.rotation_family_id = v_job.session_family_id
  FOR SHARE;
  v_material_found := FOUND;
  IF v_material_found THEN
    v_material := v_material_lookup.material;
    v_deadline := v_material_lookup.deadline;
  END IF;
  IF NOT v_material_found OR v_material.scrubbed_at IS NOT NULL
     OR v_deadline <= v_observed_at
     OR v_material.refresh_state <> 'revoked'
     OR v_material.refresh_token_key_version IS NULL
     OR v_material.refresh_token_ciphertext IS NULL
     OR v_material.refresh_token_digest IS NULL
     OR v_material.revocation_endpoint IS NULL THEN
    UPDATE public.tenant_oidc_logout_retry_jobs AS job
    SET state = 'dead_letter',attempt = greatest(job.attempt,1),
        claimed_at = coalesce(job.claimed_at,v_observed_at),
        claim_expires_at = coalesce(job.claim_expires_at,v_observed_at),
        completed_at = v_observed_at,version = job.version + 1,
        updated_at = v_observed_at
    WHERE job.id = v_job_id;
    RETURN NULL;
  END IF;
  UPDATE public.tenant_oidc_logout_retry_jobs AS job
  SET state = 'claimed',attempt = job.attempt + 1,
      claimed_at = v_observed_at,
      claim_expires_at = least(
        v_observed_at + interval '2 minutes',v_deadline
      ),
      completed_at = NULL,version = job.version + 1,
      updated_at = v_observed_at
  WHERE job.id = v_job_id
  RETURNING job.* INTO STRICT v_job;
  v_provider := CASE v_material.authority
    WHEN 'tenant_provider' THEN jsonb_build_object(
      'scope','tenant','tenantId',v_material.tenant_id::text,
      'providerId',v_material.provider_id::text,
      'bindingId',v_material.binding_id::text
    ) ELSE jsonb_build_object(
      'scope','platform','providerId',v_material.provider_id::text
    ) END;
  v_admission := CASE WHEN v_material.authority = 'tenant_platform_provider'
    THEN jsonb_build_object(
      'tenantId',v_material.tenant_id::text,
      'bindingId',v_material.binding_id::text
    ) END;
  RETURN jsonb_build_object(
    'jobId',v_job.id::text,'observedAt',to_jsonb(v_observed_at),
    'tenantId',to_jsonb(v_job.tenant_id),
    'materialId',v_job.material_id::text,
    'sessionFamilyId',v_job.session_family_id::text,
    'attempt',v_job.attempt,'maximumAttempts',v_job.maximum_attempts,
    'claimVersion',v_job.version,
    'leaseExpiresAt',to_jsonb(v_job.claim_expires_at),
    'notBefore',to_jsonb(v_job.not_before),'provider',v_provider,
    'clientSecretRevision',v_material.client_secret_revision,
    'clientAuthentication',v_material.client_authentication,
    'clientId',v_material.client_id,'endpoint',v_material.revocation_endpoint,
    'refreshGeneration',v_material.refresh_generation,
    'tokenDigest',replace(encode(
      v_material.refresh_token_digest,'base64'
    ),E'\n',''),
    'materialExpiresAt',to_jsonb(v_material.expires_at),
    'opaqueReference',jsonb_build_object(
      'keyVersion',v_material.refresh_token_key_version,
      'ciphertext',replace(encode(
        v_material.refresh_token_ciphertext,'base64'
      ),E'\n','')
    )
  ) || CASE WHEN v_admission IS NULL THEN '{}'::jsonb
    ELSE jsonb_build_object('admission',v_admission) END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC logout retry claim'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.complete_tenant_oidc_logout_retry_v1(
  p_request jsonb
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_job_id uuid;
  v_candidate_family_id uuid;
  v_attempt integer;
  v_expected_version bigint;
  v_outcome text;
  v_requested_completed_at timestamptz;
  v_completed_at timestamptz;
  v_requested_next_try_at timestamptz;
  v_next_try_at timestamptz;
  v_retry_base interval;
  v_retry_delay interval;
  v_jitter numeric;
  v_deadline timestamptz;
  v_effective_session_id uuid;
  v_effective_tenant_id uuid;
  v_effective_authority text;
  v_effective_binding_id uuid;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_material_lookup record;
  v_material_found boolean;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,
    ARRAY['jobId','attempt','expectedVersion','outcome','completedAt','nextTryAt'],
    ARRAY['jobId','attempt','expectedVersion','outcome','completedAt'],4096
  );
  v_job_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'jobId');
  v_attempt := (p_request ->> 'attempt')::integer;
  v_expected_version := (p_request ->> 'expectedVersion')::bigint;
  v_outcome := p_request ->> 'outcome';
  v_requested_completed_at := (p_request ->> 'completedAt')::timestamptz;
  v_requested_next_try_at := nullif(p_request ->> 'nextTryAt','')::timestamptz;
  IF v_attempt < 1 OR v_expected_version < 1
     OR v_expected_version >= 8999999999999999
     OR v_outcome NOT IN (
       'succeeded','safe_to_retry','local_dependency_unavailable',
       'ambiguous','rejected'
     )
     OR date_trunc('microseconds',v_requested_completed_at)
          <> v_requested_completed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_completed_at))) > 300
     OR (v_outcome = 'safe_to_retry') IS DISTINCT FROM
       (v_requested_next_try_at IS NOT NULL)
     OR (v_requested_next_try_at IS NOT NULL AND (
       v_requested_next_try_at <= v_requested_completed_at
       OR v_requested_next_try_at
            > v_requested_completed_at + interval '15 minutes'
       OR date_trunc('microseconds',v_requested_next_try_at)
            <> v_requested_next_try_at
     )) THEN
    RAISE EXCEPTION 'invalid OIDC logout retry completion'
      USING ERRCODE = '22023';
  END IF;
  v_completed_at := date_trunc('microseconds',transaction_timestamp());
  SELECT job.session_family_id INTO v_candidate_family_id
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_candidate_family_id::text,90174213
  ));
  SELECT job.* INTO v_job
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id
    AND job.session_family_id = v_candidate_family_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'claimed'
     OR v_job.attempt <> v_attempt OR v_job.version <> v_expected_version
     OR v_completed_at < v_job.claimed_at
     OR (v_outcome IN (
         'succeeded','safe_to_retry','local_dependency_unavailable'
       )
       AND v_completed_at >= v_job.claim_expires_at) THEN
    RETURN false;
  END IF;

  SELECT material AS material,
         least(material.expires_at,session.absolute_expires_at) AS deadline,
         effective.session_id AS effective_session_id,
         effective.tenant_id AS effective_tenant_id,
         effective.authority AS effective_authority,
         effective.binding_id AS effective_binding_id
    INTO v_material_lookup
  FROM public.tenant_oidc_session_materials AS material
  JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
    AS effective ON true
  JOIN public.auth_sessions AS session
    ON session.id = effective.session_id
   AND session.user_id = material.user_id
   AND session.rotation_family_id = material.rotation_family_id
  WHERE material.id = v_job.material_id
    AND material.tenant_id IS NOT DISTINCT FROM v_job.tenant_id
    AND material.authority = v_job.authority
    AND material.rotation_family_id = v_job.session_family_id
    AND material.scrubbed_at IS NULL
    AND (
      (material.authority = 'tenant_provider'
        AND effective.authority = 'tenant_provider'
        AND effective.tenant_id = material.tenant_id
        AND effective.binding_id = material.binding_id)
      OR (material.authority = 'tenant_platform_provider'
        AND effective.authority = 'tenant_platform_provider'
        AND effective.tenant_id = material.tenant_id
        AND effective.binding_id = material.binding_id)
      OR (material.authority = 'platform_provider'
        AND material.tenant_id IS NULL AND material.binding_id IS NULL
        AND ((effective.authority = 'platform_provider'
              AND effective.tenant_id IS NULL
              AND effective.binding_id IS NULL)
          OR (effective.authority = 'tenant_platform_provider'
              AND effective.tenant_id IS NOT NULL
              AND effective.binding_id IS NOT NULL)))
    )
  FOR UPDATE OF material,session;
  v_material_found := FOUND;
  IF v_material_found THEN
    v_material := v_material_lookup.material;
    v_deadline := v_material_lookup.deadline;
    v_effective_session_id := v_material_lookup.effective_session_id;
    v_effective_tenant_id := v_material_lookup.effective_tenant_id;
    v_effective_authority := v_material_lookup.effective_authority;
    v_effective_binding_id := v_material_lookup.effective_binding_id;
  END IF;
  IF NOT v_material_found OR v_deadline <= v_completed_at
     OR (v_outcome = 'safe_to_retry'
       AND v_attempt >= v_job.maximum_attempts) THEN
    v_outcome := 'rejected';
  END IF;

  IF v_outcome IN ('safe_to_retry','local_dependency_unavailable') THEN
    v_retry_base := CASE WHEN v_outcome = 'safe_to_retry'
      THEN v_requested_next_try_at - v_requested_completed_at
      ELSE interval '30 seconds' END;
    v_jitter := 750 + mod(abs(hashtextextended(
      v_job.id::text || ':' || v_job.attempt::text || ':logout',88419037
    )::numeric),501);
    v_retry_delay := make_interval(secs => least(
      900::numeric,
      extract(epoch FROM v_retry_base)::numeric * v_jitter / 1000
    )::double precision);
    v_next_try_at := date_trunc(
      'microseconds',v_completed_at + v_retry_delay
    );
    IF v_next_try_at >= v_deadline THEN
      v_outcome := 'rejected';
    ELSE
      UPDATE public.tenant_oidc_logout_retry_jobs AS job
      SET state = 'pending',not_before = v_next_try_at,
          attempt = CASE WHEN v_outcome = 'local_dependency_unavailable'
            THEN greatest(job.attempt - 1,0) ELSE job.attempt END,
          claimed_at = NULL,claim_expires_at = NULL,completed_at = NULL,
          version = job.version + 1,updated_at = v_completed_at
      WHERE job.id = v_job_id AND job.state = 'claimed'
        AND job.attempt = v_attempt AND job.version = v_expected_version;
      RETURN FOUND;
    END IF;
  END IF;
  UPDATE public.tenant_oidc_logout_retry_jobs AS job
  SET state = CASE WHEN v_outcome = 'succeeded'
        THEN 'complete' ELSE 'dead_letter' END,
      completed_at = v_completed_at,version = job.version + 1,
      updated_at = v_completed_at
  WHERE job.id = v_job_id AND job.state = 'claimed'
    AND job.attempt = v_attempt AND job.version = v_expected_version;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_outcome IN ('ambiguous','rejected') THEN
    IF v_material.id IS NOT NULL THEN
      UPDATE public.auth_sessions AS family
      SET revoked_at = coalesce(family.revoked_at,v_completed_at),
          revoke_reason = coalesce(family.revoke_reason,
            'oidc_logout_retry_' || v_outcome)
      WHERE family.user_id = v_material.user_id
        AND family.rotation_family_id = v_job.session_family_id;
      IF v_material.scrubbed_at IS NULL THEN
        UPDATE public.tenant_oidc_session_materials AS material
        SET refresh_state = CASE WHEN material.refresh_state = 'unavailable'
              THEN 'unavailable' ELSE 'revoked' END,
            refresh_retry_attempt = 0,
            refresh_claimed_at = NULL,refresh_claim_expires_at = NULL,
            refresh_version = CASE
              WHEN material.refresh_version < 8999999999999999
                THEN material.refresh_version + 1
              ELSE material.refresh_version END,
            updated_at = v_completed_at
        WHERE material.id = v_material.id;
      END IF;
      IF v_effective_tenant_id IS NOT NULL THEN
        INSERT INTO public.audit_events (
          id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
          resource_type,resource_id,authentication_method,outcome,metadata
        ) VALUES (
          uuidv7(),v_effective_tenant_id,0,v_completed_at,'system',NULL,
          'tenant.identity.oidc_logout_retry_terminal','auth_session',
          v_effective_session_id,'oidc','failure',jsonb_build_object(
            'outcome',v_outcome,'job_id',v_job.id::text,
            'material_id',v_material.id::text,
            'effective_authority',v_effective_authority,
            'effective_binding_id',v_effective_binding_id,
            'material_disclosed',false
          )
        );
      ELSE
        PERFORM app.append_platform_audit_event(
          uuidv7(),'system',NULL,
          'platform.identity.oidc_logout_retry_terminal','auth_session',
          v_effective_session_id,uuidv7(),uuidv7(),NULL,NULL,'oidc','failure',
          NULL,jsonb_build_object(
            'outcome',v_outcome,'job_id',v_job.id::text,
            'material_id',v_material.id::text,'material_disclosed',false
          )
        );
      END IF;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC logout retry completion'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.revoke_tenant_oidc_session_family_v1(p_command jsonb)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_tenant_id uuid;
  v_user_id uuid;
  v_family_id uuid;
  v_reason text;
  v_revoked_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,ARRAY['sessionFamilyId','reason','revokedAt'],
    ARRAY['sessionFamilyId','reason','revokedAt'],4096
  );
  BEGIN
    v_tenant_id := current_setting('app.tenant_id',true)::uuid;
    v_user_id := current_setting('app.user_id',true)::uuid;
    v_family_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'sessionFamilyId'
    );
    v_revoked_at := (p_command ->> 'revokedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid OIDC session family revocation'
      USING ERRCODE = '22023';
  END;
  v_reason := p_command ->> 'reason';
  IF v_tenant_id IS NULL OR v_user_id IS NULL
     OR v_reason NOT IN (
       'refresh_reuse','refresh_failure','refresh_key_failure','session_drift'
     )
     OR v_revoked_at IS NULL
     OR date_trunc('microseconds',v_revoked_at) <> v_revoked_at
     OR abs(extract(epoch FROM (transaction_timestamp() - v_revoked_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC session family revocation'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_tenant_id
    AND material.rotation_family_id = v_family_id
    AND material.user_id = v_user_id
    AND material.session_id IS NOT NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  UPDATE public.auth_sessions AS family
  SET revoked_at = v_revoked_at,
      revoke_reason = left('oidc_' || v_reason,500)
  WHERE family.user_id = v_user_id
    AND family.rotation_family_id = v_family_id
    AND family.revoked_at IS NULL;
  UPDATE public.tenant_oidc_session_materials AS material
  SET refresh_state = CASE WHEN material.refresh_state = 'unavailable'
        THEN 'unavailable' ELSE 'revoked' END,
      refresh_version = CASE
        WHEN material.refresh_version < 8999999999999999
          THEN material.refresh_version + 1
        ELSE material.refresh_version END,
      updated_at = v_revoked_at
  WHERE material.tenant_id = v_tenant_id AND material.id = v_material.id;
  INSERT INTO public.audit_events (
    id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
    resource_type,resource_id,authentication_method,outcome,metadata
  ) VALUES (
    uuidv7(),v_tenant_id,0,v_revoked_at,'user',v_user_id,
    'tenant.identity.oidc_session_family_revoked','auth_session',
    v_material.session_id,'oidc','success',jsonb_build_object(
      'reason',v_reason,'session_family_id',v_family_id::text,
      'material_id',v_material.id::text,'material_disclosed',false
    )
  );
  RETURN true;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.revoke_local_oidc_session_v1(
  p_user_id uuid,
  p_command jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_operation_run_id uuid;
  v_tenant_id uuid;
  v_authenticated_user_id uuid;
  v_session_id uuid;
  v_expected_version bigint;
  v_request_upstream boolean;
  v_request_digest bytea;
  v_request_snapshot jsonb;
  v_result jsonb;
  v_revoked_at timestamptz := transaction_timestamp();
  v_session public.auth_sessions%ROWTYPE;
  v_state public.auth_session_mfa_states%ROWTYPE;
  v_provenance public.auth_session_federated_provenance%ROWTYPE;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_existing public.tenant_oidc_logout_commands%ROWTYPE;
  v_membership_id uuid;
  v_retry_job_id uuid;
  v_has_material boolean := false;
  v_claim_end_session boolean := false;
  v_schedule_revocation boolean := false;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['operationRunId','tenantId','authenticatedUserId','sessionId',
      'expectedVersion','requestUpstream','requestDigest'],
    ARRAY['operationRunId','tenantId','authenticatedUserId','sessionId',
      'expectedVersion','requestUpstream','requestDigest'],
    16384
  );
  BEGIN
    v_operation_run_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'operationRunId'
    );
    v_tenant_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'tenantId');
    v_authenticated_user_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'authenticatedUserId'
    );
    v_session_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'sessionId'
    );
    v_expected_version := (p_command ->> 'expectedVersion')::bigint;
    v_request_upstream := (p_command ->> 'requestUpstream')::boolean;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid local OIDC logout command'
      USING ERRCODE = '22023';
  END;
  v_request_digest := app.private_mfa_decode_base64_v1(
    p_command ->> 'requestDigest',32,32
  );
  v_request_snapshot := p_command - 'requestDigest';
  IF p_user_id IS NULL
     OR (uuid_extract_version(p_user_id) = 7) IS DISTINCT FROM true
     OR p_user_id IS DISTINCT FROM v_authenticated_user_id
     OR v_expected_version < 1
     OR v_operation_run_id IN (v_session_id,v_authenticated_user_id)
     OR v_tenant_id = v_authenticated_user_id
     OR v_session_id = v_authenticated_user_id
     OR encode(v_request_digest,'hex') = repeat('00',32)
     OR jsonb_typeof(p_command -> 'requestUpstream') <> 'boolean'
     OR pg_column_size(v_request_snapshot) NOT BETWEEN 2 AND 16384 THEN
    RAISE EXCEPTION 'invalid local OIDC logout command'
      USING ERRCODE = '22023';
  END IF;
  IF current_setting('app.tenant_id',true) IS DISTINCT FROM v_tenant_id::text
     OR current_setting('app.user_id',true) IS DISTINCT FROM p_user_id::text THEN
    RAISE EXCEPTION 'local OIDC logout authority rejected'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_operation_run_id::text,73419022
  ));
  SELECT membership.id INTO v_membership_id
  FROM public.tenant_memberships AS membership
  WHERE membership.tenant_id = v_tenant_id
    AND membership.user_id = p_user_id
    AND membership.status = 'active'
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT command.* INTO v_existing
  FROM public.tenant_oidc_logout_commands AS command
  WHERE command.operation_run_id = v_operation_run_id;
  IF FOUND THEN
    IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id
       OR v_existing.session_id IS DISTINCT FROM v_session_id
       OR v_existing.expected_version IS DISTINCT FROM v_expected_version
       OR v_existing.request_upstream IS DISTINCT FROM v_request_upstream
       OR v_existing.request_digest IS DISTINCT FROM v_request_digest
       OR v_existing.request_snapshot IS DISTINCT FROM v_request_snapshot THEN
      RETURN NULL;
    END IF;
    PERFORM 1
    FROM public.auth_sessions AS session
    JOIN public.auth_session_federated_provenance AS provenance
      ON provenance.tenant_id = v_tenant_id
     AND provenance.session_id = session.id
     AND provenance.user_id = session.user_id
     AND provenance.primary_kind = 'tenant_provider'
     AND provenance.authentication_method = 'oidc'
     AND provenance.provider_kind = 'oidc'
    LEFT JOIN public.tenant_oidc_session_materials AS material
      ON material.tenant_id = v_tenant_id
     AND material.id = v_existing.material_id
     AND material.session_id = session.id
     AND material.continuation_id IS NULL
     AND material.rotation_family_id = session.rotation_family_id
     AND material.user_id = session.user_id
     AND material.provider_id = provenance.provider_id
     AND material.binding_id = provenance.binding_id
     AND material.external_identity_id = provenance.external_identity_id
    WHERE session.id = v_session_id
      AND session.active_tenant_id = v_tenant_id
      AND session.user_id = p_user_id
      AND session.authentication_method = 'oidc'
      AND ((v_existing.material_id IS NULL AND material.id IS NULL)
        OR material.id = v_existing.material_id)
    FOR SHARE OF session;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    RETURN v_existing.result_snapshot;
  END IF;

  SELECT session.* INTO STRICT v_session
  FROM public.auth_sessions AS session
  WHERE session.id = v_session_id
    AND session.active_tenant_id = v_tenant_id
    AND session.user_id = p_user_id
    AND session.authentication_method = 'oidc'
    AND session.revoked_at IS NULL
  FOR UPDATE;
  SELECT state.* INTO STRICT v_state
  FROM public.auth_session_mfa_states AS state
  WHERE state.tenant_id = v_tenant_id
    AND state.session_id = v_session_id
    AND state.user_id = v_session.user_id
    AND state.primary_kind = 'tenant_provider'
    AND state.session_version = v_expected_version
  FOR UPDATE;
  SELECT provenance.* INTO STRICT v_provenance
  FROM public.auth_session_federated_provenance AS provenance
  WHERE provenance.tenant_id = v_tenant_id
    AND provenance.session_id = v_session_id
    AND provenance.user_id = v_session.user_id
    AND provenance.primary_kind = 'tenant_provider'
    AND provenance.authentication_method = 'oidc'
    AND provenance.provider_kind = 'oidc';
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_tenant_id
    AND material.session_id = v_session_id
    AND material.continuation_id IS NULL
    AND material.rotation_family_id = v_session.rotation_family_id
    AND material.user_id = v_session.user_id
    AND material.provider_id = v_provenance.provider_id
    AND material.binding_id = v_provenance.binding_id
    AND material.provider_kind = 'oidc'
    AND material.external_identity_id = v_provenance.external_identity_id
  FOR UPDATE;
  v_has_material := FOUND;
  IF v_has_material AND v_operation_run_id = v_material.id THEN
    RETURN NULL;
  END IF;

  UPDATE public.auth_sessions AS family
  SET revoked_at = v_revoked_at,revoke_reason = 'oidc_local_logout'
  WHERE family.user_id = v_session.user_id
    AND family.rotation_family_id = v_session.rotation_family_id
    AND family.revoked_at IS NULL;
  UPDATE public.auth_session_mfa_states AS state
  SET session_version = state.session_version + 1
  WHERE state.tenant_id = v_tenant_id
    AND state.session_id = v_session_id
    AND state.session_version = v_expected_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'local OIDC logout lost CAS'
      USING ERRCODE = '40001';
  END IF;

  IF v_has_material THEN
    v_claim_end_session := v_request_upstream
      AND v_material.end_session_endpoint IS NOT NULL
      AND v_material.id_token_key_version IS NOT NULL;
    v_schedule_revocation := v_request_upstream
      AND v_material.refresh_state <> 'unavailable'
      AND v_material.revocation_endpoint IS NOT NULL;
    IF v_schedule_revocation THEN
      v_retry_job_id := uuidv7();
    END IF;
    UPDATE public.tenant_oidc_session_materials AS material
    SET logout_disposition = CASE WHEN v_claim_end_session
          THEN 'claimed' ELSE 'skipped' END,
        logout_operation_run_id = v_operation_run_id,
        logout_claimed_at = v_revoked_at,
        refresh_state = CASE WHEN material.refresh_state = 'unavailable'
          THEN 'unavailable' ELSE 'revoked' END,
        refresh_version = CASE
          WHEN material.refresh_version < 8999999999999999
            THEN material.refresh_version + 1
          ELSE material.refresh_version END,
        updated_at = v_revoked_at
    WHERE material.tenant_id = v_tenant_id AND material.id = v_material.id
      AND material.logout_operation_run_id IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'OIDC logout material disposition lost CAS'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  v_result := jsonb_strip_nulls(jsonb_build_object(
    'operationRunId',v_operation_run_id::text,
    'tenantId',v_tenant_id::text,
    'authenticatedUserId',p_user_id::text,
    'sessionId',v_session_id::text,
    'sessionFamilyId',v_session.rotation_family_id::text,
    'previousVersion',v_expected_version,
    'provider',jsonb_build_object(
      'scope','tenant','tenantId',v_tenant_id::text,
      'providerId',v_provenance.provider_id::text,
      'bindingId',v_provenance.binding_id::text
    ),
    'bindingId',v_provenance.binding_id::text,
    'materialId',CASE WHEN v_has_material THEN v_material.id::text END,
    'endSession',CASE WHEN v_claim_end_session THEN jsonb_build_object(
      'endpoint',v_material.end_session_endpoint,
      'clientId',v_material.client_id,
      'postLogoutRedirectUri',v_material.post_logout_redirect_uri
    ) END,
    'protectedIdToken',CASE WHEN v_claim_end_session THEN jsonb_build_object(
      'keyVersion',v_material.id_token_key_version,
      'ciphertext',replace(encode(v_material.id_token_ciphertext,'base64'),E'\n','')
    ) END,
    'logoutRetryJobId',v_retry_job_id::text,
    'revokedAt',to_jsonb(v_revoked_at)
  ));
  IF pg_column_size(v_result) NOT BETWEEN 2 AND 1048576 THEN
    RAISE EXCEPTION 'local OIDC logout snapshot exceeds bound'
      USING ERRCODE = '54000';
  END IF;
  INSERT INTO public.tenant_oidc_logout_commands (
    tenant_id,operation_run_id,session_id,expected_version,request_upstream,
    material_id,request_digest,request_snapshot,result_snapshot,applied_at
  ) VALUES (
    v_tenant_id,v_operation_run_id,v_session_id,v_expected_version,
    v_request_upstream,CASE WHEN v_has_material THEN v_material.id END,
    v_request_digest,v_request_snapshot,v_result,v_revoked_at
  );
  IF v_schedule_revocation THEN
    INSERT INTO public.tenant_oidc_logout_retry_jobs (
      id,tenant_id,operation_run_id,material_id,session_family_id,state,
      attempt,maximum_attempts,not_before,version,created_at,updated_at
    ) VALUES (
      v_retry_job_id,v_tenant_id,v_operation_run_id,v_material.id,
      v_session.rotation_family_id,'pending',0,8,v_revoked_at,1,
      v_revoked_at,v_revoked_at
    );
  END IF;
  INSERT INTO public.audit_events (
    id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
    resource_type,resource_id,authentication_method,outcome,metadata
  ) VALUES (
    uuidv7(),v_tenant_id,0,v_revoked_at,'user',v_session.user_id,
    'tenant.identity.oidc_local_logout','auth_session',v_session_id,
    'oidc','success',jsonb_build_object(
      'upstream_requested',v_request_upstream,
      'end_session_claimed',v_claim_end_session,
      'revocation_scheduled',v_schedule_revocation,
      'material_present',v_has_material,
      'material_disclosed',false
    )
  );
  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RETURN NULL;
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid local OIDC logout command'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_legacy_claim_tenant_oidc_logout_retry_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_job_id uuid;
  v_observed_at timestamptz;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['jobId','observedAt'],ARRAY['jobId','observedAt'],2048
  );
  BEGIN
    v_job_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'jobId');
    v_observed_at := (p_request ->> 'observedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid OIDC logout retry claim'
      USING ERRCODE = '22023';
  END;
  IF v_observed_at IS NULL
     OR date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR abs(extract(epoch FROM (transaction_timestamp() - v_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC logout retry claim'
      USING ERRCODE = '22023';
  END IF;
  SELECT job.* INTO v_job
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_job.state IN ('complete','dead_letter')
     OR v_job.not_before > v_observed_at
     OR (v_job.state = 'claimed' AND v_job.claim_expires_at > v_observed_at)
     OR v_job.attempt >= v_job.maximum_attempts THEN
    RETURN NULL;
  END IF;
  SELECT material.* INTO STRICT v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.tenant_id = v_job.tenant_id
    AND material.id = v_job.material_id
    AND material.rotation_family_id = v_job.session_family_id
    AND material.refresh_state = 'revoked'
    AND material.refresh_token_key_version IS NOT NULL
    AND material.refresh_token_ciphertext IS NOT NULL
    AND material.revocation_endpoint IS NOT NULL
  FOR SHARE;
  UPDATE public.tenant_oidc_logout_retry_jobs AS job
  SET state = 'claimed',attempt = job.attempt + 1,
      claimed_at = v_observed_at,
      claim_expires_at = v_observed_at + interval '2 minutes',
      completed_at = NULL,version = job.version + 1,
      updated_at = v_observed_at
  WHERE job.id = v_job_id
  RETURNING job.* INTO STRICT v_job;
  RETURN jsonb_build_object(
    'jobId',v_job.id::text,
    'tenantId',v_job.tenant_id::text,
    'materialId',v_job.material_id::text,
    'sessionFamilyId',v_job.session_family_id::text,
    'attempt',v_job.attempt,
    'maximumAttempts',v_job.maximum_attempts,
    'notBefore',to_jsonb(v_job.not_before),
    'provider',jsonb_build_object(
      'scope','tenant','tenantId',v_material.tenant_id::text,
      'providerId',v_material.provider_id::text,
      'bindingId',v_material.binding_id::text
    ),
    'bindingId',v_material.binding_id::text,
    'clientSecretRevision',v_material.client_secret_revision,
    'clientAuthentication',v_material.client_authentication,
    'clientId',v_material.client_id,
    'endpoint',v_material.revocation_endpoint,
    'refreshGeneration',v_material.refresh_generation,
    'opaqueReference',jsonb_build_object(
      'keyVersion',v_material.refresh_token_key_version,
      'ciphertext',replace(encode(v_material.refresh_token_ciphertext,'base64'),E'\n','')
    )
  );
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RETURN NULL;
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC logout retry claim'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_legacy_complete_tenant_oidc_logout_retry_v1(p_request jsonb)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_job_id uuid;
  v_attempt integer;
  v_observed_at timestamptz;
  v_next_try_at timestamptz;
  v_disposition text;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['jobId','attempt','observedAt','nextTryAt','disposition'],
    ARRAY['jobId','attempt','observedAt','disposition'],4096
  );
  BEGIN
    v_job_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'jobId');
    v_attempt := (p_request ->> 'attempt')::integer;
    v_observed_at := (p_request ->> 'observedAt')::timestamptz;
    v_next_try_at := nullif(p_request ->> 'nextTryAt','')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid OIDC logout retry completion'
      USING ERRCODE = '22023';
  END;
  v_disposition := p_request ->> 'disposition';
  IF v_attempt < 1
     OR v_disposition NOT IN ('complete','reschedule','dead_letter')
     OR v_observed_at IS NULL
     OR date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR abs(extract(epoch FROM (transaction_timestamp() - v_observed_at))) > 300
     OR (v_disposition = 'reschedule') <> (v_next_try_at IS NOT NULL)
     OR (v_next_try_at IS NOT NULL AND (
       v_next_try_at <= v_observed_at
       OR v_next_try_at > v_observed_at + interval '15 minutes'
       OR date_trunc('microseconds',v_next_try_at) <> v_next_try_at
     )) THEN
    RAISE EXCEPTION 'invalid OIDC logout retry completion'
      USING ERRCODE = '22023';
  END IF;
  SELECT job.* INTO v_job
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'claimed'
     OR v_job.attempt <> v_attempt
     OR v_observed_at < v_job.claimed_at
     OR v_observed_at > v_job.claim_expires_at
     OR (v_disposition = 'reschedule' AND v_attempt >= v_job.maximum_attempts)
     OR (v_disposition = 'dead_letter' AND v_attempt < v_job.maximum_attempts) THEN
    RETURN false;
  END IF;
  UPDATE public.tenant_oidc_logout_retry_jobs AS job
  SET state = CASE v_disposition
        WHEN 'reschedule' THEN 'pending'
        ELSE v_disposition
      END,
      not_before = coalesce(v_next_try_at,job.not_before),
      claimed_at = CASE WHEN v_disposition = 'reschedule'
        THEN NULL ELSE job.claimed_at END,
      claim_expires_at = CASE WHEN v_disposition = 'reschedule'
        THEN NULL ELSE job.claim_expires_at END,
      completed_at = CASE WHEN v_disposition = 'reschedule'
        THEN NULL ELSE v_observed_at END,
      version = job.version + 1,updated_at = v_observed_at
  WHERE job.id = v_job_id AND job.state = 'claimed'
    AND job.attempt = v_attempt;
  RETURN FOUND;
END;
$function$;
--> statement-breakpoint

-- Reinstall v3 after the new relation exists so retained OIDC ID/refresh
-- envelopes participate in the same deadlock-safe process key inventory.
CREATE OR REPLACE FUNCTION app.verify_identity_keyring_v3(
  p_versions integer[],
  p_verifiers bytea[],
  p_active_version integer
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  BEGIN
    LOCK TABLE public.tenant_ldap_directory_operation_runs,
      public.tenant_ldap_provider_secrets,
      public.tenant_ldap_external_identities,
      public.tenant_ldap_external_identity_subject_aliases,
      public.tenant_oidc_client_secrets,
      public.tenant_saml_sp_keys,
      public.tenant_federated_external_identities,
      public.tenant_federated_external_identity_aliases,
      public.tenant_federated_authentication_transactions,
      public.tenant_saml_session_materials,
      public.tenant_oidc_session_materials,
      public.auth_sessions,
      public.tenant_post_primary_continuations,
      public.platform_saml_post_primary_continuations,
      public.platform_saml_session_materials,
      public.platform_saml_tenant_switch_commands,
      public.auth_session_tenant_platform_federated_provenance,
      public.session_logout_continuations,
      public.platform_oidc_client_secrets,
      public.platform_saml_sp_keys,
      public.platform_federated_external_identities,
      public.platform_federated_external_identity_aliases,
      public.tenant_platform_oidc_authentication_transactions
      IN SHARE MODE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RETURN false;
  END;
  LOCK TABLE public.identity_keyring_versions IN EXCLUSIVE MODE;

  IF EXISTS (
    SELECT 1
    FROM public.tenant_ldap_directory_operation_runs AS operation
    LEFT JOIN public.identity_keyring_versions AS keyring
      ON keyring.key_version = operation.bind_secret_key_version
    WHERE operation.status = 'started'
      AND operation.expires_at > transaction_timestamp()
      AND (
        keyring.key_version IS NULL
        OR keyring.retired_at IS NOT NULL
        OR NOT operation.bind_secret_key_version = ANY(p_versions)
      )
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_oidc_client_secrets AS secret
    WHERE secret.retired_at IS NULL
      AND NOT secret.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_saml_sp_keys AS sp_key
    WHERE sp_key.retired_at IS NULL
      AND NOT sp_key.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_federated_external_identities AS identity
    WHERE identity.retired_at IS NULL
      AND NOT identity.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_federated_external_identities AS identity
    WHERE NOT EXISTS (
      SELECT 1
      FROM ONLY public.tenant_federated_external_identity_aliases AS alias
      WHERE alias.tenant_id = identity.tenant_id
        AND alias.provider_id = identity.provider_id
        AND alias.external_identity_id = identity.id
        AND alias.key_version = ANY(p_versions)
        AND (identity.retired_at IS NOT NULL OR alias.retired_at IS NULL)
    )
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_federated_authentication_transactions AS transaction
    WHERE transaction.state IN ('pending','claimed')
      AND transaction.expires_at > transaction_timestamp()
      AND transaction.verifier_key_version IS NOT NULL
      AND NOT transaction.verifier_key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_saml_session_materials AS material
    WHERE material.key_version IS NOT NULL
      AND app.private_tenant_saml_material_live_v1(
        material.id,transaction_timestamp()
      )
      AND NOT material.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_saml_session_materials AS material
    LEFT JOIN ONLY public.tenant_saml_sp_keys AS sp_key
      ON sp_key.tenant_id = material.tenant_id
     AND sp_key.provider_id = material.provider_id
     AND sp_key.revision = (
       material.logout_configuration #>> '{authentication,spKeyRevision}'
     )::bigint
    WHERE material.logout_configuration IS NOT NULL
      AND app.private_tenant_saml_material_live_v1(
        material.id,transaction_timestamp()
      )
      AND (sp_key.id IS NULL OR NOT sp_key.key_version = ANY(p_versions))
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_oidc_session_materials AS material
    WHERE material.id_token_key_version IS NOT NULL
      AND NOT material.id_token_key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.tenant_oidc_session_materials AS material
    WHERE material.refresh_token_key_version IS NOT NULL
      AND NOT material.refresh_token_key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_oidc_session_materials AS material
    LEFT JOIN ONLY public.tenant_oidc_client_secrets AS tenant_secret
      ON material.authority = 'tenant_provider'
     AND tenant_secret.tenant_id = material.tenant_id
     AND tenant_secret.provider_id = material.provider_id
     AND tenant_secret.revision = material.client_secret_revision
    LEFT JOIN ONLY public.platform_oidc_client_secrets AS platform_secret
      ON material.authority IN ('tenant_platform_provider','platform_provider')
     AND platform_secret.provider_id = material.provider_id
     AND platform_secret.revision = material.client_secret_revision
    WHERE material.scrubbed_at IS NULL
      AND material.expires_at > transaction_timestamp()
      AND material.client_secret_revision IS NOT NULL
      AND ((material.authority = 'tenant_provider' AND (
          tenant_secret.id IS NULL
          OR NOT tenant_secret.key_version = ANY(p_versions)
        )) OR (material.authority IN (
          'tenant_platform_provider','platform_provider'
        ) AND (
          platform_secret.id IS NULL
          OR NOT platform_secret.key_version = ANY(p_versions)
        )))
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.platform_saml_session_materials AS material
    WHERE material.key_version IS NOT NULL
      AND app.private_platform_saml_material_live_v1(
        material.id,transaction_timestamp()
      )
      AND NOT material.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_saml_session_materials AS material
    LEFT JOIN ONLY public.platform_saml_sp_keys AS sp_key
      ON sp_key.provider_id = material.platform_provider_id
     AND sp_key.revision = (
       material.logout_configuration #>> '{authentication,spKeyRevision}'
     )::bigint
    WHERE material.logout_configuration IS NOT NULL
      AND app.private_platform_saml_material_live_v1(
        material.id,transaction_timestamp()
      )
      AND (sp_key.id IS NULL OR NOT sp_key.key_version = ANY(p_versions))
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.platform_oidc_client_secrets AS secret
    WHERE secret.retired_at IS NULL
      AND NOT secret.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.platform_saml_sp_keys AS sp_key
    WHERE sp_key.retired_at IS NULL
      AND NOT sp_key.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1 FROM ONLY public.platform_federated_external_identities AS identity
    WHERE identity.retired_at IS NULL
      AND NOT identity.key_version = ANY(p_versions)
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.platform_federated_external_identities AS identity
    WHERE NOT EXISTS (
      SELECT 1
      FROM ONLY public.platform_federated_external_identity_aliases AS alias
      WHERE alias.platform_provider_id = identity.platform_provider_id
        AND alias.external_identity_id = identity.id
        AND alias.key_version = ANY(p_versions)
        AND (identity.retired_at IS NOT NULL OR alias.retired_at IS NULL)
    )
  ) OR EXISTS (
    SELECT 1
    FROM ONLY public.tenant_platform_oidc_authentication_transactions AS transaction
    WHERE transaction.state IN ('pending','claimed')
      AND transaction.expires_at > transaction_timestamp()
      AND NOT transaction.verifier_key_version = ANY(p_versions)
  ) THEN
    RETURN false;
  END IF;

  RETURN app.verify_identity_keyring_v2(
    p_versions,p_verifiers,p_active_version
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.tenant_oidc_session_lifecycle_schema_readiness_v1()
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  relation_name text;
  relation_oid regclass;
  runtime_role text;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY[
    'tenant_oidc_session_materials',
    'tenant_oidc_logout_commands',
    'tenant_oidc_logout_retry_jobs'
  ] LOOP
    relation_oid := ('public.' || relation_name)::regclass;
    IF NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_class AS relation
      WHERE relation.oid = relation_oid
        AND relation.relowner = 'periapsis_migrator'::regrole
        AND relation.relrowsecurity AND relation.relforcerowsecurity
    ) OR EXISTS (
      SELECT 1 FROM pg_catalog.pg_policy AS policy
      WHERE policy.polrelid = relation_oid
    ) THEN
      RETURN false;
    END IF;
    FOREACH runtime_role IN ARRAY ARRAY[
      'periapsis_api','periapsis_worker','periapsis_notifier','periapsis_auditor'
    ] LOOP
      IF has_any_column_privilege(runtime_role,relation_oid,'SELECT,INSERT,UPDATE,REFERENCES')
         OR has_table_privilege(runtime_role,relation_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER,REFERENCES') THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_trigger AS trigger
    WHERE trigger.tgname = 'tenant_oidc_session_materials_guard_v1'
      AND trigger.tgrelid = 'public.tenant_oidc_session_materials'::regclass
      AND trigger.tgfoid = 'app.guard_oidc_session_material_v1()'::regprocedure
      AND trigger.tgenabled = 'O' AND NOT trigger.tgisinternal
  ) OR NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_trigger AS trigger
    WHERE trigger.tgname = 'tenant_oidc_logout_commands_immutable_v1'
      AND trigger.tgrelid = 'public.tenant_oidc_logout_commands'::regclass
      AND trigger.tgfoid =
        'app.guard_federated_immutable_ledger_v1()'::regprocedure
      AND trigger.tgenabled = 'O' AND NOT trigger.tgisinternal
  ) OR EXISTS (
    SELECT 1 FROM public.tenant_oidc_session_materials AS material
    LEFT JOIN public.identity_keyring_versions AS id_key
      ON id_key.key_version = material.id_token_key_version
    LEFT JOIN public.identity_keyring_versions AS refresh_key
      ON refresh_key.key_version = material.refresh_token_key_version
    WHERE (material.id_token_key_version IS NOT NULL
        AND (id_key.key_version IS NULL OR id_key.retired_at IS NOT NULL))
       OR (material.refresh_token_key_version IS NOT NULL
        AND (refresh_key.key_version IS NULL OR refresh_key.retired_at IS NOT NULL))
  ) THEN
    RETURN false;
  END IF;

  RETURN has_function_privilege(
      'periapsis_api','app.apply_federated_authentication_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.claim_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.complete_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.revoke_tenant_oidc_session_family_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.revoke_local_oidc_session_v1(uuid,jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.claim_tenant_oidc_logout_retry_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.complete_tenant_oidc_logout_retry_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.claim_tenant_oidc_logout_retry_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_worker','app.revoke_local_oidc_session_v1(uuid,jsonb)','EXECUTE'
    );
END;
$function$;
--> statement-breakpoint

DO $tenant_oidc_lifecycle_function_acl_v1$
DECLARE
  signature text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'app.claim_tenant_oidc_refresh_rotation_v1(jsonb)',
    'app.complete_tenant_oidc_refresh_rotation_v1(jsonb)',
    'app.revoke_tenant_oidc_session_family_v1(jsonb)',
    'app.revoke_local_oidc_session_v1(uuid,jsonb)',
    'app.claim_tenant_oidc_logout_retry_v1(jsonb)',
    'app.complete_tenant_oidc_logout_retry_v1(jsonb)',
    'app.tenant_oidc_session_lifecycle_schema_readiness_v1()'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator',signature);
    EXECUTE format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier, periapsis_auditor, periapsis_audit_reader_owner, periapsis_notification_dispatch_owner, periapsis_sla_api_owner, periapsis_sla_worker_owner, periapsis_sla_readiness_owner',
      signature
    );
  END LOOP;
END;
$tenant_oidc_lifecycle_function_acl_v1$;
