-- Direct platform login has a distinct authority graph and uses no tenant or
-- binding identifier. The wrapper strips the new material fields before
-- invoking the existing CAS apply and persists only after its success.
ALTER FUNCTION app.apply_platform_oidc_authentication_v1(jsonb)
  RENAME TO private_apply_platform_oidc_authentication_v31;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.private_apply_platform_oidc_authentication_v31(jsonb)
  FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
