--> statement-breakpoint
CREATE FUNCTION app.apply_platform_oidc_authentication_v1(p_command jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_material_id uuid;
  v_transaction_id bytea;
  v_material jsonb := p_command -> 'oidcSession';
  v_id jsonb;
  v_refresh jsonb;
  v_result jsonb;
  v_transaction record;
  v_application public.platform_oidc_authentication_applications%ROWTYPE;
  v_existing public.tenant_oidc_session_materials%ROWTYPE;
  v_has_material boolean;
  v_has_id boolean;
  v_has_refresh boolean;
  v_expires_at timestamptz;
  v_observed_at timestamptz;
  v_valid_until timestamptz;
  v_owner_expires_at timestamptz;
  v_family_id uuid;
  v_id_key integer;
  v_id_cipher bytea;
  v_id_digest bytea;
  v_refresh_key integer;
  v_refresh_cipher bytea;
  v_refresh_digest bytea;
  v_refresh_generation bigint := 0;
  v_access_expires_at timestamptz;
  v_client_secret_revision bigint;
BEGIN
  PERFORM app.private_platform_oidc_direct_json_v1(
    p_command,
    ARRAY['transactionId','claimAttemptId','expectedVersion','operationDigest',
      'browserCapabilityDigest','returnPath','subject','observation',
      'assurance','disposition','session','continuation','observedAt','audit',
      'materialId','oidcSession','validUntil'],
    ARRAY['transactionId','claimAttemptId','expectedVersion','operationDigest',
      'browserCapabilityDigest','returnPath','subject','observation',
      'assurance','disposition','observedAt','audit','materialId','validUntil'],2162688
  );
  BEGIN
    v_material_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'materialId'
    );
    v_transaction_id := app.private_mfa_decode_base64_v1(
      p_command ->> 'transactionId',32,32
    );
    v_observed_at := (p_command ->> 'observedAt')::timestamptz;
    v_valid_until := (p_command ->> 'validUntil')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid direct platform OIDC material identity'
      USING ERRCODE = '22023';
  END;
  v_has_material := v_material IS NOT NULL AND v_material <> 'null'::jsonb;
  IF v_has_material THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_material,
      ARRAY['materialId','expiresAt','idToken','refreshToken',
        'clientSecretRevision','clientAuthentication','clientId','tokenEndpoint',
        'revocationEndpoint','endSessionEndpoint','postLogoutRedirectUri'],
      ARRAY['materialId','expiresAt','clientId','postLogoutRedirectUri'],1048576
    );
    IF app.private_mfa_require_uuidv7_v1(v_material ->> 'materialId')
         IS DISTINCT FROM v_material_id THEN
      RAISE EXCEPTION 'direct platform OIDC material identity mismatch'
        USING ERRCODE = '22023';
    END IF;
    v_expires_at := (v_material ->> 'expiresAt')::timestamptz;
    v_client_secret_revision := nullif(
      v_material ->> 'clientSecretRevision',''
    )::bigint;
    v_id := v_material -> 'idToken';
    v_refresh := v_material -> 'refreshToken';
  END IF;
  v_has_id := v_id IS NOT NULL AND v_id <> 'null'::jsonb;
  v_has_refresh := v_refresh IS NOT NULL AND v_refresh <> 'null'::jsonb;
  IF v_has_id THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_id,ARRAY['keyVersion','ciphertext','digest'],
      ARRAY['keyVersion','ciphertext','digest'],524288
    );
    v_id_key := (v_id ->> 'keyVersion')::integer;
    v_id_cipher := app.private_mfa_decode_base64_v1(
      v_id ->> 'ciphertext',29,262172
    );
    v_id_digest := app.private_mfa_decode_base64_v1(v_id ->> 'digest',32,32);
  END IF;
  IF v_has_refresh THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      v_refresh,
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      ARRAY['keyVersion','ciphertext','digest','generation','accessExpiresAt'],
      524288
    );
    v_refresh_key := (v_refresh ->> 'keyVersion')::integer;
    v_refresh_cipher := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'ciphertext',29,262172
    );
    v_refresh_digest := app.private_mfa_decode_base64_v1(
      v_refresh ->> 'digest',32,32
    );
    v_refresh_generation := (v_refresh ->> 'generation')::bigint;
    v_access_expires_at := (v_refresh ->> 'accessExpiresAt')::timestamptz;
  END IF;
  IF v_valid_until IS NULL
     OR date_trunc('microseconds',v_valid_until) <> v_valid_until
     OR v_valid_until <= v_observed_at
     OR v_has_material AND (v_expires_at <= v_observed_at
       OR v_expires_at > v_valid_until
       OR date_trunc('microseconds',v_expires_at) <> v_expires_at)
     OR v_has_id AND (v_id_key NOT BETWEEN 1 AND 32767
       OR encode(v_id_digest,'hex') = repeat('00',32))
     OR v_has_refresh AND (v_refresh_key NOT BETWEEN 1 AND 32767
       OR v_refresh_generation <> 1
       OR encode(v_refresh_digest,'hex') = repeat('00',32)
       OR v_access_expires_at <= v_observed_at
       OR v_access_expires_at > v_expires_at
       OR date_trunc('microseconds',v_access_expires_at) <> v_access_expires_at)
     OR EXISTS (
       SELECT 1 FROM unnest(ARRAY[v_id_key,v_refresh_key]) AS requested(key_version)
       LEFT JOIN public.identity_keyring_versions AS keyring
         ON keyring.key_version = requested.key_version
        AND keyring.is_active AND keyring.retired_at IS NULL
       WHERE requested.key_version IS NOT NULL AND keyring.key_version IS NULL
     ) THEN
    RAISE EXCEPTION 'direct platform OIDC material is stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT transaction.operation_run_id,transaction.state,
         transaction.platform_provider_id AS provider_id,
         transaction.allow_refresh_token,transaction.client_secret_revision,
         transaction.client_id,transaction.post_logout_redirect_uri,
         discovery.client_authentication,
         convert_from(discovery.document,'UTF8')::jsonb AS discovery_document
    INTO v_transaction
  FROM public.platform_oidc_authentication_transactions AS transaction
  JOIN public.platform_oidc_discovery_snapshots AS discovery
    ON discovery.provider_id = transaction.platform_provider_id
   AND discovery.revision = transaction.discovery_revision
   AND discovery.document_digest = transaction.discovery_digest
  WHERE transaction.transaction_id = v_transaction_id
    AND transaction.operation_run_id = v_material_id
    AND transaction.provider_kind = 'oidc'
  FOR UPDATE OF transaction;
  IF NOT FOUND OR v_transaction.state NOT IN ('claimed','completed') THEN
    RETURN NULL;
  END IF;
  IF v_has_material IS DISTINCT FROM (
       v_transaction.allow_refresh_token OR nullif(
         v_transaction.discovery_document ->> 'end_session_endpoint',''
       ) IS NOT NULL)
     OR v_has_id IS DISTINCT FROM (nullif(
       v_transaction.discovery_document ->> 'end_session_endpoint',''
     ) IS NOT NULL)
     OR v_has_refresh IS DISTINCT FROM v_transaction.allow_refresh_token
     OR v_has_material AND (
       (v_material ->> 'clientId') IS DISTINCT FROM v_transaction.client_id
       OR (v_material ->> 'postLogoutRedirectUri') IS DISTINCT FROM
          v_transaction.post_logout_redirect_uri
       OR nullif(v_material ->> 'endSessionEndpoint','') IS DISTINCT FROM
          nullif(v_transaction.discovery_document ->> 'end_session_endpoint','')
       OR v_has_refresh AND (
         v_client_secret_revision IS DISTINCT FROM
           v_transaction.client_secret_revision
         OR (v_material ->> 'clientAuthentication') IS DISTINCT FROM
           v_transaction.client_authentication
         OR (v_material ->> 'tokenEndpoint') IS DISTINCT FROM
           v_transaction.discovery_document ->> 'token_endpoint'
         OR nullif(v_material ->> 'revocationEndpoint','') IS DISTINCT FROM
           nullif(v_transaction.discovery_document ->> 'revocation_endpoint','')
       )) THEN
    RAISE EXCEPTION 'direct platform OIDC material pins are stale'
      USING ERRCODE = '40001';
  END IF;
  v_result := app.private_apply_platform_oidc_authentication_v31(
    p_command - 'materialId' - 'oidcSession' - 'validUntil'
  );
  IF v_result ->> 'category' <> 'success' OR NOT v_has_material THEN
    RETURN v_result;
  END IF;
  SELECT application.* INTO STRICT v_application
  FROM public.platform_oidc_authentication_applications AS application
  WHERE application.transaction_id = v_transaction_id
    AND application.category = 'success';
  IF v_application.session_id IS NOT NULL THEN
    SELECT session.rotation_family_id,session.absolute_expires_at
      INTO STRICT v_family_id,v_owner_expires_at
    FROM public.auth_sessions AS session
    JOIN public.auth_session_platform_oidc_states AS state
      ON state.session_id = session.id AND state.user_id = session.user_id
    JOIN public.auth_session_platform_oidc_provenance AS provenance
      ON provenance.session_id = session.id
     AND provenance.user_id = session.user_id
    WHERE session.id = v_application.session_id
      AND session.user_id = v_application.user_id
      AND session.active_tenant_id IS NULL
      AND session.authentication_method = 'oidc'
      AND provenance.platform_provider_id = v_transaction.provider_id
      AND provenance.external_identity_id = v_application.external_identity_id;
  ELSE
    SELECT continuation.expires_at INTO STRICT v_owner_expires_at
    FROM public.platform_post_primary_continuations AS continuation
    WHERE continuation.id = v_application.continuation_id
      AND continuation.user_id = v_application.user_id
      AND continuation.platform_provider_id = v_transaction.provider_id
      AND continuation.external_identity_id = v_application.external_identity_id;
  END IF;
  IF v_expires_at > v_owner_expires_at THEN
    RAISE EXCEPTION 'direct platform OIDC material exceeds owner expiry'
      USING ERRCODE = '40001';
  END IF;
  SELECT material.* INTO v_existing
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.id = v_material_id;
  IF FOUND THEN
    IF v_existing.authority <> 'platform_provider'
       OR v_existing.tenant_id IS NOT NULL OR v_existing.binding_id IS NOT NULL
       OR v_existing.provider_id IS DISTINCT FROM v_transaction.provider_id
       OR v_existing.user_id IS DISTINCT FROM v_application.user_id
       OR v_existing.external_identity_id IS DISTINCT FROM
          v_application.external_identity_id
       OR v_existing.session_id IS DISTINCT FROM v_application.session_id
       OR v_existing.continuation_id IS DISTINCT FROM v_application.continuation_id
       OR v_existing.rotation_family_id IS DISTINCT FROM v_family_id
       OR v_existing.expires_at IS DISTINCT FROM v_expires_at
       OR v_existing.id_token_digest IS DISTINCT FROM v_id_digest
       OR v_existing.refresh_token_digest IS DISTINCT FROM v_refresh_digest
       OR (v_existing.refresh_state <> 'unavailable') IS DISTINCT FROM
          v_has_refresh THEN
      RETURN NULL;
    END IF;
    RETURN v_result;
  END IF;
  INSERT INTO public.tenant_oidc_session_materials (
    id,tenant_id,authority,session_id,continuation_id,rotation_family_id,
    user_id,provider_id,binding_id,provider_kind,external_identity_id,
    aad_version,id_token_key_version,id_token_ciphertext,id_token_digest,
    refresh_token_key_version,refresh_token_ciphertext,refresh_token_digest,
    refresh_generation,refresh_state,refresh_version,access_expires_at,
    expires_at,client_secret_revision,client_authentication,client_id,
    token_endpoint,revocation_endpoint,end_session_endpoint,
    post_logout_redirect_uri,logout_disposition,created_at,updated_at
  ) VALUES (
    v_material_id,NULL,'platform_provider',v_application.session_id,
    v_application.continuation_id,v_family_id,v_application.user_id,
    v_transaction.provider_id,NULL,'oidc',v_application.external_identity_id,
    1,v_id_key,v_id_cipher,v_id_digest,v_refresh_key,v_refresh_cipher,
    v_refresh_digest,v_refresh_generation,
    CASE WHEN v_has_refresh THEN 'ready' ELSE 'unavailable' END,1,
    v_access_expires_at,v_expires_at,v_client_secret_revision,
    v_material ->> 'clientAuthentication',v_material ->> 'clientId',
    v_material ->> 'tokenEndpoint',
    nullif(v_material ->> 'revocationEndpoint',''),
    nullif(v_material ->> 'endSessionEndpoint',''),
    v_material ->> 'postLogoutRedirectUri',
    CASE WHEN nullif(v_material ->> 'endSessionEndpoint','') IS NULL
      THEN 'not_configured' ELSE 'available' END,v_observed_at,v_observed_at
  );
  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
  RAISE EXCEPTION 'direct platform OIDC material authority is unavailable'
    USING ERRCODE = '40001';
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid direct platform OIDC material'
    USING ERRCODE = '22023';
END;
$function$;
