ALTER TABLE public.platform_oidc_authentication_transactions
  DROP CONSTRAINT platform_oidc_auth_transactions_refresh_check;
--> statement-breakpoint
DO $platform_oidc_direct_refresh_admission_v1$
DECLARE
  v_definition text;
  v_old text := E'     AND NOT configuration.allow_refresh_token\n';
BEGIN
  SELECT pg_get_functiondef(
    'app.private_platform_oidc_direct_configuration_v1(uuid,jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0
     OR strpos(substr(v_definition,strpos(v_definition,v_old) + length(v_old)),v_old) > 0 THEN
    RAISE EXCEPTION 'unexpected direct platform OIDC configuration predecessor';
  END IF;
  EXECUTE replace(v_definition,v_old,'');
END;
$platform_oidc_direct_refresh_admission_v1$;
