-- Historical SAML material is retained only for the bounded owner/session or
-- logout-continuation lifetime.  These predicates deliberately ignore current
-- provider policy: local-first logout must survive provider disable/rotation.
CREATE FUNCTION app.private_tenant_saml_material_live_v1(
  p_material_id uuid,
  p_observed_at timestamptz
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM public.tenant_saml_session_materials AS material
    WHERE material.id = p_material_id
      AND material.scrubbed_at IS NULL
      AND material.key_version IS NOT NULL
      AND material.ciphertext IS NOT NULL
      AND (
        EXISTS (
          SELECT 1 FROM public.auth_sessions AS session
          WHERE session.id = material.session_id
            AND session.user_id = material.user_id
            AND session.absolute_expires_at > p_observed_at
        )
        OR EXISTS (
          SELECT 1
          FROM public.tenant_post_primary_continuations AS continuation
          WHERE continuation.tenant_id = material.tenant_id
            AND continuation.id = material.continuation_id
            AND continuation.user_id = material.user_id
            AND continuation.expires_at > p_observed_at
        )
        OR EXISTS (
          SELECT 1 FROM public.session_logout_continuations AS continuation
          WHERE continuation.tenant_saml_material_id = material.id
            AND continuation.expires_at > p_observed_at
        )
      )
  );
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_platform_saml_material_live_v1(
  p_material_id uuid,
  p_observed_at timestamptz
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1
    FROM public.platform_saml_session_materials AS material
    WHERE material.id = p_material_id
      AND material.scrubbed_at IS NULL
      AND material.key_version IS NOT NULL
      AND material.nonce IS NOT NULL
      AND material.ciphertext IS NOT NULL
      AND (
        EXISTS (
          SELECT 1 FROM public.auth_sessions AS session
          WHERE session.id = material.session_id
            AND session.user_id = material.user_id
            AND session.absolute_expires_at > p_observed_at
        )
        OR EXISTS (
          SELECT 1
          FROM app.private_platform_saml_material_effective_session_v1(
            material.id
          ) AS effective
          JOIN public.auth_sessions AS target
            ON target.id = effective.session_id
           AND target.user_id = material.user_id
           AND target.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
           AND target.authentication_method = 'saml'
           AND target.absolute_expires_at > p_observed_at
          WHERE effective.authority = 'tenant_platform_provider'
        )
        OR EXISTS (
          SELECT 1
          FROM public.platform_saml_post_primary_continuations AS continuation
          WHERE continuation.id = material.continuation_id
            AND continuation.user_id = material.user_id
            AND continuation.expires_at > p_observed_at
        )
        OR EXISTS (
          SELECT 1 FROM public.session_logout_continuations AS continuation
          WHERE continuation.platform_saml_material_id = material.id
            AND continuation.expires_at > p_observed_at
        )
      )
  );
END;
$function$;
