-- Purpose-separated historical tenant key loader.  The response intentionally
-- preserves the interactive loader shape so the secret-opening boundary can
-- stay shared; the exact request echo includes the material attestation.
CREATE FUNCTION app.load_tenant_saml_logout_sp_key_envelope_v1(p_lookup jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_tenant_id uuid;
  v_provider_id uuid;
  v_binding_id uuid;
  v_material_id uuid;
  v_revision bigint;
  v_result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_lookup,ARRAY['provider','revision','materialId'],
    ARRAY['provider','revision','materialId'],16384
  );
  PERFORM app.private_mfa_assert_json_object_v1(
    p_lookup -> 'provider',ARRAY['scope','tenantId','providerId','bindingId'],
    ARRAY['scope','tenantId','providerId','bindingId'],8192
  );
  IF p_lookup #>> '{provider,scope}' <> 'tenant' THEN
    RAISE EXCEPTION 'invalid tenant SAML logout SP-key lookup'
      USING ERRCODE = '22023';
  END IF;
  v_tenant_id := app.private_mfa_require_uuidv7_v1(
    p_lookup #>> '{provider,tenantId}'
  );
  v_provider_id := app.private_mfa_require_uuidv7_v1(
    p_lookup #>> '{provider,providerId}'
  );
  v_binding_id := app.private_mfa_require_uuidv7_v1(
    p_lookup #>> '{provider,bindingId}'
  );
  v_material_id := app.private_mfa_require_uuidv7_v1(
    p_lookup ->> 'materialId'
  );
  v_revision := (p_lookup ->> 'revision')::bigint;
  IF v_revision NOT BETWEEN 1 AND 4294967295 THEN
    RAISE EXCEPTION 'invalid tenant SAML logout SP-key lookup'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'lookup',p_lookup,'keyId',sp_key.id::text,
    'envelopeKeyVersion',sp_key.key_version,
    'envelopeCiphertext',replace(encode(sp_key.ciphertext,'base64'),E'\n',''),
    'certificateDer',coalesce((
      SELECT jsonb_agg(
        replace(encode(certificate.certificate_der,'base64'),E'\n','')
        ORDER BY certificate.sequence
      )
      FROM public.tenant_saml_sp_certificates AS certificate
      WHERE certificate.tenant_id = sp_key.tenant_id
        AND certificate.key_id = sp_key.id
    ),'[]'::jsonb)
  ) INTO v_result
  FROM public.tenant_saml_session_materials AS material
  JOIN public.tenant_saml_sp_keys AS sp_key
    ON sp_key.tenant_id = material.tenant_id
   AND sp_key.provider_id = material.provider_id
   AND sp_key.revision = v_revision
  JOIN public.identity_keyring_versions AS keyring
    ON keyring.key_version = sp_key.key_version
   AND keyring.retired_at IS NULL
  WHERE material.id = v_material_id
    AND material.tenant_id = v_tenant_id
    AND material.provider_id = v_provider_id
    AND material.binding_id = v_binding_id
    AND material.logout_configuration #>> '{authentication,provider,scope}'
          = 'tenant'
    AND material.logout_configuration #>> '{authentication,provider,tenantId}'
          = v_tenant_id::text
    AND material.logout_configuration #>> '{authentication,provider,providerId}'
          = v_provider_id::text
    AND material.logout_configuration #>> '{authentication,provider,bindingId}'
          = v_binding_id::text
    AND (material.logout_configuration #>> '{authentication,spKeyRevision}')::bigint
          = v_revision
    AND app.private_tenant_saml_material_live_v1(
      material.id,statement_timestamp()
    )
    AND (
      SELECT count(*) BETWEEN 1 AND 8
      FROM public.tenant_saml_sp_certificates AS certificate
      WHERE certificate.tenant_id = sp_key.tenant_id
        AND certificate.key_id = sp_key.id
    );
  RETURN v_result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid tenant SAML logout SP-key lookup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

-- Purpose-separated platform loader, likewise attested by the material row.
-- Retired keys and expired certificates remain usable only while that row is
-- live; the root KEK itself must still be retained by readiness.
CREATE FUNCTION app.load_platform_saml_logout_sp_key_envelope_v1(p_lookup jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_provider_id uuid;
  v_material_id uuid;
  v_login_revision bigint;
  v_key_revision bigint;
  v_result jsonb;
BEGIN
  PERFORM app.private_platform_saml_direct_json_v1(
    p_lookup,
    ARRAY['provider','platformLoginRevision','keyRevision','materialId'],
    ARRAY['provider','platformLoginRevision','keyRevision','materialId'],8192
  );
  PERFORM app.private_platform_saml_direct_json_v1(
    p_lookup -> 'provider',ARRAY['scope','providerId'],
    ARRAY['scope','providerId'],4096
  );
  IF p_lookup #>> '{provider,scope}' <> 'platform' THEN
    RAISE EXCEPTION 'invalid platform SAML logout SP-key scope'
      USING ERRCODE = '22023';
  END IF;
  v_provider_id := app.private_mfa_require_uuidv7_v1(
    p_lookup #>> '{provider,providerId}'
  );
  v_material_id := app.private_mfa_require_uuidv7_v1(
    p_lookup ->> 'materialId'
  );
  v_login_revision := (p_lookup ->> 'platformLoginRevision')::bigint;
  v_key_revision := (p_lookup ->> 'keyRevision')::bigint;
  IF v_login_revision NOT BETWEEN 1 AND 9007199254740991
     OR v_key_revision NOT BETWEEN 1 AND 9007199254740991 THEN
    RAISE EXCEPTION 'invalid platform SAML logout SP-key lookup'
      USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'request',p_lookup,'platformLoginRevision',material.login_policy_revision,
    'context',jsonb_build_object(
      'provider',p_lookup -> 'provider','keyId',sp_key.id::text,
      'keyRevision',sp_key.revision
    ),
    'envelope',jsonb_build_object(
      'keyVersion',sp_key.key_version,
      'nonce',replace(encode(sp_key.nonce,'base64'),E'\n',''),
      'ciphertext',replace(encode(sp_key.ciphertext,'base64'),E'\n','')
    ),
    'certificateDer',(
      SELECT coalesce(jsonb_agg(
        replace(encode(certificate.certificate_der,'base64'),E'\n','')
        ORDER BY certificate.sequence
      ),'[]'::jsonb)
      FROM public.platform_saml_sp_certificates AS certificate
      WHERE certificate.key_id = sp_key.id
    ),'live',true
  ) INTO v_result
  FROM public.platform_saml_session_materials AS material
  JOIN public.platform_saml_sp_keys AS sp_key
    ON sp_key.provider_id = material.platform_provider_id
   AND sp_key.revision = v_key_revision
  JOIN public.identity_keyring_versions AS keyring
    ON keyring.key_version = sp_key.key_version
   AND keyring.retired_at IS NULL
  WHERE material.id = v_material_id
    AND material.platform_provider_id = v_provider_id
    AND material.login_policy_revision = v_login_revision
    AND material.logout_configuration #>> '{authentication,provider,scope}'
          = 'platform'
    AND material.logout_configuration #>> '{authentication,provider,providerId}'
          = v_provider_id::text
    AND (material.logout_configuration #>> '{authentication,platformLoginRevision}')::bigint
          = v_login_revision
    AND (material.logout_configuration #>> '{authentication,spKeyRevision}')::bigint
          = v_key_revision
    AND app.private_platform_saml_material_live_v1(
      material.id,statement_timestamp()
    )
    AND (
      SELECT count(*) BETWEEN 1 AND 8
      FROM public.platform_saml_sp_certificates AS certificate
      WHERE certificate.key_id = sp_key.id
    );
  RETURN v_result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid platform SAML logout SP-key lookup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

DO $saml_logout_key_loader_acl_v1$
DECLARE
  signature text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'app.load_tenant_saml_logout_sp_key_envelope_v1(jsonb)',
    'app.load_platform_saml_logout_sp_key_envelope_v1(jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator',signature);
    EXECUTE format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, periapsis_worker, periapsis_notifier, periapsis_auditor',
      signature
    );
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO periapsis_api',signature);
  END LOOP;
END;
$saml_logout_key_loader_acl_v1$;
