-- Remove encrypted SAML material only after every owner and logout proof has
-- reached its bounded expiry.  One row per scope per maintenance tick keeps the
-- cleanup transaction bounded while guaranteeing eventual key release.
CREATE FUNCTION app.private_cleanup_expired_saml_materials_v1(
  p_observed_at timestamptz
)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_material_id uuid;
  v_scrub_operation uuid;
  v_effective_observed_at timestamptz;
  v_count integer := 0;
BEGIN
  IF p_observed_at IS NULL
     OR date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
    RAISE EXCEPTION 'invalid SAML material cleanup instant'
      USING ERRCODE = '22023';
  END IF;
  -- A worker clock may lead the database clock by at most the dispatcher
  -- tolerance.  Destructive retention nevertheless uses the authoritative
  -- database boundary so a +299s caller cannot scrub a still-live session.
  v_effective_observed_at := least(p_observed_at,transaction_timestamp());
  PERFORM set_config('app.saml_material_scrub_v1','on',true);

  SELECT material.id INTO v_material_id
  FROM public.tenant_saml_session_materials AS material
  WHERE material.scrubbed_at IS NULL
    AND NOT app.private_tenant_saml_material_live_v1(
      material.id,v_effective_observed_at
    )
  ORDER BY material.created_at,material.id
  FOR UPDATE SKIP LOCKED LIMIT 1;
  IF FOUND THEN
    v_scrub_operation := uuidv7();
    UPDATE public.tenant_saml_session_materials AS material
    SET key_version = NULL,ciphertext = NULL,session_index_digest = NULL,
        logout_configuration = NULL,
        scrubbed_at = greatest(material.created_at,v_effective_observed_at),
        scrub_operation_run_id = v_scrub_operation
    WHERE material.id = v_material_id AND material.scrubbed_at IS NULL;
    v_count := v_count + 1;
  END IF;

  v_material_id := NULL;
  SELECT material.id INTO v_material_id
  FROM public.platform_saml_session_materials AS material
  WHERE material.scrubbed_at IS NULL
    AND NOT app.private_platform_saml_material_live_v1(
      material.id,v_effective_observed_at
    )
  ORDER BY material.created_at,material.id
  FOR UPDATE SKIP LOCKED LIMIT 1;
  IF FOUND THEN
    v_scrub_operation := uuidv7();
    PERFORM set_config('app.platform_saml_direct_runtime_write_v1','on',true);
    UPDATE public.platform_saml_session_materials AS material
    SET key_version = NULL,nonce = NULL,ciphertext = NULL,
        session_index_digest = NULL,logout_configuration = NULL,
        scrubbed_at = greatest(material.created_at,v_effective_observed_at),
        scrub_operation_run_id = v_scrub_operation
    WHERE material.id = v_material_id AND material.scrubbed_at IS NULL;
    v_count := v_count + 1;
  END IF;
  RETURN v_count;
END;
$function$;
