CREATE FUNCTION app.load_federated_session_revalidation_v1(p_lookup jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_session_id uuid;
  v_observed_at timestamptz;
  v_authentication_method text;
  v_result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_lookup,
    ARRAY['sessionId','tenantId','audience','authenticationMethod','observedAt'],
    ARRAY['sessionId','tenantId','audience','authenticationMethod','observedAt'],
    8192
  );
  v_session_id := app.private_mfa_require_uuidv7_v1(
    p_lookup ->> 'sessionId'
  );
  v_authentication_method := p_lookup ->> 'authenticationMethod';
  v_observed_at := (p_lookup ->> 'observedAt')::timestamptz;
  IF v_authentication_method NOT IN ('oidc','saml','passkey','ldap')
     OR date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR v_observed_at NOT BETWEEN statement_timestamp() - interval '5 minutes'
                                 AND statement_timestamp() + interval '30 seconds' THEN
    RAISE EXCEPTION 'invalid federated session revalidation lookup'
      USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.auth_sessions AS session
    WHERE session.id = v_session_id
      AND session.active_tenant_id = (p_lookup ->> 'tenantId')::uuid
      AND session.authentication_method = v_authentication_method
  ) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.tenant_oidc_session_materials AS material
    JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
      AS effective ON effective.session_id = v_session_id
        AND effective.tenant_id = (p_lookup ->> 'tenantId')::uuid
    WHERE material.session_id IS NOT NULL
      AND (material.scrubbed_at IS NOT NULL
        OR material.expires_at <= v_observed_at
        OR material.refresh_state IN ('claimed','revoked','scrubbed')
        OR (material.refresh_state = 'ready'
          AND material.access_expires_at <= v_observed_at))
  ) THEN
    RETURN NULL;
  END IF;
  v_result := app.private_load_federated_session_revalidation_v31(
    p_lookup - ARRAY['observedAt','authenticationMethod']
  );
  IF v_result IS NULL THEN RETURN NULL; END IF;
  RETURN v_result || jsonb_build_object('lookup',p_lookup);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid federated session revalidation lookup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint
