-- F-AUD-38 closes logout over an opaque, same-origin, one-time continuation.
-- The DELETE response never contains an IdP endpoint or protected material.
ALTER TABLE public.tenant_oidc_session_materials
  DROP CONSTRAINT tenant_oidc_session_materials_protocol_check,
  ALTER COLUMN client_id DROP NOT NULL,
  ALTER COLUMN post_logout_redirect_uri DROP NOT NULL,
  ADD CONSTRAINT tenant_oidc_session_materials_protocol_check CHECK (
    ((refresh_state = 'scrubbed'
        AND client_secret_revision IS NULL
        AND client_authentication IS NULL
        AND client_id IS NULL AND token_endpoint IS NULL
        AND revocation_endpoint IS NULL AND end_session_endpoint IS NULL
        AND post_logout_redirect_uri IS NULL)
      OR (refresh_state <> 'scrubbed'
        AND client_id IS NOT NULL AND post_logout_redirect_uri IS NOT NULL
        AND ((refresh_state IN ('ready','claimed','revoked'))
          = (client_secret_revision IS NOT NULL
            AND client_authentication IS NOT NULL
            AND token_endpoint IS NOT NULL))))
    AND (client_secret_revision IS NULL OR client_secret_revision > 0)
    AND (client_authentication IS NULL OR
      client_authentication IN ('client_secret_basic','client_secret_post'))
    AND (client_id IS NULL OR (
      octet_length(convert_to(client_id,'UTF8')) BETWEEN 1 AND 512
      AND client_id !~ '[[:cntrl:]]'))
    AND (token_endpoint IS NULL OR (
      char_length(token_endpoint) BETWEEN 9 AND 4096
      AND token_endpoint ~ '^https://[^[:space:]#]+$'))
    AND (revocation_endpoint IS NULL OR (
      char_length(revocation_endpoint) BETWEEN 9 AND 4096
      AND revocation_endpoint ~ '^https://[^[:space:]#]+$'))
    AND (end_session_endpoint IS NULL OR (
      char_length(end_session_endpoint) BETWEEN 9 AND 4096
      AND end_session_endpoint ~ '^https://[^[:space:]#]+$'))
    AND (scrubbed_at IS NOT NULL
      OR (end_session_endpoint IS NULL) = (id_token_key_version IS NULL))
    AND (post_logout_redirect_uri IS NULL OR (
      char_length(post_logout_redirect_uri) BETWEEN 9 AND 4096
      AND post_logout_redirect_uri ~ '^https://[^[:space:]#]+$'))
    AND expires_at > created_at
    AND date_trunc('microseconds',expires_at) = expires_at
  );
