  tenant_id uuid,
  authority text NOT NULL,
  protocol text NOT NULL,
  oidc_material_id uuid,
  tenant_saml_material_id uuid,
  platform_saml_material_id uuid,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  CONSTRAINT session_logout_continuations_token_key UNIQUE (token_digest),
  CONSTRAINT session_logout_continuations_operation_key UNIQUE (operation_run_id),
  CONSTRAINT session_logout_continuations_tenant_fk
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE RESTRICT,
  CONSTRAINT session_logout_continuations_command_fk
    FOREIGN KEY (operation_run_id)
    REFERENCES public.tenant_oidc_logout_commands(operation_run_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT session_logout_continuations_oidc_material_fk
    FOREIGN KEY (oidc_material_id)
    REFERENCES public.tenant_oidc_session_materials(id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT session_logout_continuations_tenant_saml_material_fk
    FOREIGN KEY (tenant_id,tenant_saml_material_id)
    REFERENCES public.tenant_saml_session_materials(tenant_id,id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT session_logout_continuations_platform_saml_material_fk
    FOREIGN KEY (platform_saml_material_id)
    REFERENCES public.platform_saml_session_materials(id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT session_logout_continuations_identity_check CHECK (
    (uuid_extract_version(id) = 7) IS TRUE
    AND id <> operation_run_id AND id <> session_id AND id <> user_id
    AND octet_length(token_digest) = 32
    AND encode(token_digest,'hex') <> repeat('00',32)
    AND ((protocol = 'oidc' AND oidc_material_id IS NOT NULL
        AND tenant_saml_material_id IS NULL
        AND platform_saml_material_id IS NULL
        AND ((authority IN ('tenant_provider','tenant_platform_provider')
            AND tenant_id IS NOT NULL)
          OR (authority = 'platform_provider' AND tenant_id IS NULL)))
      OR (protocol = 'saml' AND oidc_material_id IS NULL
        AND ((authority = 'tenant_provider' AND tenant_id IS NOT NULL
            AND tenant_saml_material_id IS NOT NULL
            AND platform_saml_material_id IS NULL)
          OR (authority = 'platform_provider' AND tenant_id IS NULL
            AND tenant_saml_material_id IS NULL
            AND platform_saml_material_id IS NOT NULL)
          OR (authority = 'tenant_platform_provider' AND tenant_id IS NOT NULL
            AND tenant_saml_material_id IS NULL
            AND platform_saml_material_id IS NOT NULL))))
  ),
  CONSTRAINT session_logout_continuations_lifecycle_check CHECK (
    date_trunc('microseconds',created_at) = created_at
    AND date_trunc('microseconds',expires_at) = expires_at
    AND expires_at > created_at
    AND expires_at <= created_at + interval '2 minutes'
    AND (consumed_at IS NULL OR (
      date_trunc('microseconds',consumed_at) = consumed_at
      AND consumed_at >= created_at AND consumed_at < expires_at))
  )
);
