CREATE FUNCTION app.guard_session_logout_continuation_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.expires_at <= transaction_timestamp() THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'live logout continuation is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.token_digest IS DISTINCT FROM OLD.token_digest
     OR NEW.operation_run_id IS DISTINCT FROM OLD.operation_run_id
     OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.authority IS DISTINCT FROM OLD.authority
     OR NEW.protocol IS DISTINCT FROM OLD.protocol
     OR NEW.oidc_material_id IS DISTINCT FROM OLD.oidc_material_id
     OR NEW.tenant_saml_material_id IS DISTINCT FROM OLD.tenant_saml_material_id
     OR NEW.platform_saml_material_id IS DISTINCT FROM OLD.platform_saml_material_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
     OR OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL THEN
    RAISE EXCEPTION 'logout continuation immutable identity changed'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.guard_session_logout_continuation_v1()
  OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.guard_session_logout_continuation_v1()
  FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
       periapsis_auditor;
