CREATE OR REPLACE FUNCTION app.resolve_session_for_logout_v1(
  p_token_digest bytea
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  SELECT jsonb_build_object(
    'sessionId',session.id::text,
    'userId',session.user_id::text,
    'tenantId',to_jsonb(session.active_tenant_id),
    'tokenDigest',replace(encode(session.token_digest,'base64'),E'\n',''),
    'csrfDigest',replace(encode(session.csrf_secret_digest,'base64'),E'\n','')
  )
