CREATE FUNCTION app.revoke_local_session_for_logout_v1(p_command jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_operation_run_id uuid;
  v_session_id uuid;
  v_user_id uuid;
  v_tenant_id uuid;
  v_family_id uuid;
  v_token_digest bytea;
  v_request_digest bytea;
  v_request_upstream boolean;
  v_requested_at timestamptz;
  v_database_now timestamptz;
  v_continuation_id uuid;
  v_continuation_digest bytea;
  v_continuation_expires_at timestamptz;
  v_request_id uuid;
  v_correlation_id uuid;
  v_remote_address inet;
  v_user_agent text;
  v_request_snapshot jsonb;
  v_base_result jsonb;
  v_result jsonb;
  v_command_authority text;
  v_previous_version bigint;
  v_revoked_at timestamptz;
  v_protocol text;
  v_continuation_created boolean := false;
  v_oidc_found boolean := false;
  v_tenant_saml_found boolean := false;
  v_platform_saml_found boolean := false;
  v_schedule_retry boolean := false;
  v_retry_job_id uuid;
  v_session public.auth_sessions%ROWTYPE;
  v_oidc public.tenant_oidc_session_materials%ROWTYPE;
  v_oidc_effective_authority text;
  v_tenant_saml public.tenant_saml_session_materials%ROWTYPE;
  v_platform_saml public.platform_saml_session_materials%ROWTYPE;
  v_platform_saml_effective record;
  v_existing public.tenant_oidc_logout_commands%ROWTYPE;
  v_existing_continuation public.session_logout_continuations%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['operationRunId','sessionId','userId','tenantId','tokenDigest',
      'requestDigest','requestUpstream','requestedAt','continuationId',
      'continuationDigest','continuationExpiresAt','audit'],
    ARRAY['operationRunId','sessionId','userId','tenantId','tokenDigest',
      'requestDigest','requestUpstream','requestedAt','continuationId',
      'continuationDigest','continuationExpiresAt','audit'],32768
  );
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command -> 'audit',
    ARRAY['requestId','correlationId','remoteAddress','userAgent'],
    ARRAY['requestId','correlationId','remoteAddress','userAgent'],4096
  );
  BEGIN
    v_operation_run_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'operationRunId'
    );
    v_session_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'sessionId'
    );
    v_user_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'userId');
    IF jsonb_typeof(p_command -> 'tenantId') = 'null' THEN
      v_tenant_id := NULL;
    ELSE
      v_tenant_id := app.private_mfa_require_uuidv7_v1(
        p_command ->> 'tenantId'
      );
    END IF;
    v_token_digest := app.private_mfa_decode_base64_v1(
      p_command ->> 'tokenDigest',32,32
    );
    v_request_digest := app.private_mfa_decode_base64_v1(
      p_command ->> 'requestDigest',32,32
    );
    v_request_upstream := (p_command ->> 'requestUpstream')::boolean;
    v_requested_at := (p_command ->> 'requestedAt')::timestamptz;
    v_continuation_id := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'continuationId'
    );
    v_continuation_digest := app.private_mfa_decode_base64_v1(
      p_command ->> 'continuationDigest',32,32
    );
    v_continuation_expires_at := (
      p_command ->> 'continuationExpiresAt'
    )::timestamptz;
    v_request_id := app.private_mfa_require_uuidv7_v1(
      p_command #>> '{audit,requestId}'
    );
    v_correlation_id := app.private_mfa_require_uuidv7_v1(
      p_command #>> '{audit,correlationId}'
    );
    v_remote_address := (p_command #>> '{audit,remoteAddress}')::inet;
    v_user_agent := p_command #>> '{audit,userAgent}';
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid local session logout command'
      USING ERRCODE = '22023';
  END;
  IF jsonb_typeof(p_command -> 'requestUpstream') <> 'boolean'
     OR v_operation_run_id IN (v_session_id,v_user_id,v_continuation_id)
     OR v_session_id IN (v_user_id,v_continuation_id)
     OR v_user_id = v_continuation_id
     OR (v_tenant_id IS NOT NULL AND v_tenant_id IN (
       v_operation_run_id,v_session_id,v_user_id,v_continuation_id
     ))
     OR encode(v_token_digest,'hex') = repeat('00',32)
     OR encode(v_request_digest,'hex') = repeat('00',32)
     OR encode(v_continuation_digest,'hex') = repeat('00',32)
     OR date_trunc('microseconds',v_requested_at) <> v_requested_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_at))) > 300
     OR date_trunc('microseconds',v_continuation_expires_at)
          <> v_continuation_expires_at
     OR v_continuation_expires_at <= v_requested_at
     OR v_continuation_expires_at > v_requested_at + interval '2 minutes'
     OR v_user_agent IS NULL OR char_length(v_user_agent) NOT BETWEEN 1 AND 512
     OR v_user_agent ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'invalid local session logout command'
      USING ERRCODE = '22023';
  END IF;

  v_request_snapshot := jsonb_build_object(
    'operationRunId',v_operation_run_id::text,
    'sessionId',v_session_id::text,'userId',v_user_id::text,
    'tenantId',to_jsonb(v_tenant_id),
    'requestUpstream',v_request_upstream,
    'requestedAt',to_jsonb(v_requested_at),
    'continuationId',v_continuation_id::text,
    'continuationExpiresAt',to_jsonb(v_continuation_expires_at)
  );
  PERFORM pg_advisory_xact_lock(hashtextextended(
    v_operation_run_id::text,73419022
  ));

  -- Refresh claim/completion serialize on the rotation family before taking
  -- material or session row locks. Discover the immutable family without a
  -- row lock, take that same advisory lock, then re-read and attest the exact
  -- credential under lock. This prevents session->material versus
  -- material->session deadlocks without trusting the optimistic read.
  SELECT session.rotation_family_id INTO v_family_id
  FROM public.auth_sessions AS session
  WHERE session.id = v_session_id AND session.user_id = v_user_id
    AND session.active_tenant_id IS NOT DISTINCT FROM v_tenant_id
    AND session.token_digest = v_token_digest;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));

  SELECT session.* INTO v_session
  FROM public.auth_sessions AS session
  WHERE session.id = v_session_id AND session.user_id = v_user_id
    AND session.active_tenant_id IS NOT DISTINCT FROM v_tenant_id
    AND session.token_digest = v_token_digest
    AND session.rotation_family_id = v_family_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT command.* INTO v_existing
  FROM public.tenant_oidc_logout_commands AS command
  WHERE command.operation_run_id = v_operation_run_id;
  IF FOUND THEN
    IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id
       OR v_existing.session_id IS DISTINCT FROM v_session_id
       OR v_existing.request_upstream IS DISTINCT FROM v_request_upstream
       OR v_existing.request_digest IS DISTINCT FROM v_request_digest
       OR v_existing.request_snapshot IS DISTINCT FROM v_request_snapshot THEN
      RETURN NULL;
    END IF;
    SELECT continuation.* INTO v_existing_continuation
    FROM public.session_logout_continuations AS continuation
    WHERE continuation.operation_run_id = v_operation_run_id
      AND continuation.id = v_continuation_id
      AND continuation.token_digest = v_continuation_digest
      AND continuation.consumed_at IS NULL
      AND transaction_timestamp() < continuation.expires_at;
    IF FOUND THEN
      RETURN v_existing.result_snapshot || jsonb_build_object(
        'category','logout_continuation',
        'continuationId',v_existing_continuation.id::text,
        'continuationExpiresAt',to_jsonb(v_existing_continuation.expires_at)
      );
    END IF;
    RETURN v_existing.result_snapshot;
  END IF;

  -- The caller timestamp participates only in the immutable request digest.
  -- Security-relevant creation, expiry, revocation, and audit time comes from
  -- PostgreSQL so a valid +/- five-minute client skew cannot extend or
  -- prematurely consume the one-time continuation.
  v_database_now := date_trunc('microseconds',transaction_timestamp());
  v_continuation_expires_at := v_database_now
    + (v_continuation_expires_at - v_requested_at);
  v_requested_at := v_database_now;

  v_protocol := v_session.authentication_method;
  IF v_tenant_id IS NOT NULL THEN
    v_protocol := coalesce(
      (
        SELECT provenance.authentication_method
        FROM public.auth_session_tenant_platform_federated_provenance
          AS provenance
        WHERE provenance.tenant_id = v_tenant_id
          AND provenance.session_id = v_session_id
          AND provenance.user_id = v_user_id
          AND provenance.primary_kind = 'tenant_platform_provider'
      ),
      (
        SELECT provenance.authentication_method
        FROM public.auth_session_federated_provenance AS provenance
        WHERE provenance.tenant_id = v_tenant_id
          AND provenance.session_id = v_session_id
          AND provenance.user_id = v_user_id
          AND provenance.primary_kind = 'tenant_provider'
      ),
      v_protocol
    );
  END IF;
  IF v_tenant_id IS NOT NULL THEN
    SELECT state.session_version INTO v_previous_version
    FROM public.auth_session_mfa_states AS state
    WHERE state.tenant_id = v_tenant_id AND state.session_id = v_session_id
      AND state.user_id = v_user_id
    FOR UPDATE;
  ELSIF v_protocol = 'oidc' THEN
    SELECT state.session_version INTO v_previous_version
    FROM public.auth_session_platform_oidc_states AS state
    WHERE state.session_id = v_session_id AND state.user_id = v_user_id
    FOR UPDATE;
  ELSIF v_protocol = 'saml' THEN
    SELECT state.session_version INTO v_previous_version
    FROM public.auth_session_platform_saml_states AS state
    WHERE state.session_id = v_session_id AND state.user_id = v_user_id
    FOR UPDATE;
  END IF;
  v_previous_version := coalesce(v_previous_version,1);
  v_revoked_at := coalesce(v_session.revoked_at,v_requested_at);

  -- The auth-session row is the durable deduplication fence even after its
  -- original command ledger has been pruned. A fresh browser logout request
  -- still receives a valid local-only receipt so the transport can clear its
  -- cookie, but it must not mint another command, audit event, continuation,
  -- retry job, or upstream signing opportunity for an already-revoked session.
  IF v_session.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'category','revoked_local_only',
      'operationRunId',v_operation_run_id::text,
      'sessionId',v_session_id::text,'userId',v_user_id::text,
      'tenantId',to_jsonb(v_tenant_id),
      'requestedAt',v_request_snapshot -> 'requestedAt',
      'observedAt',to_jsonb(v_requested_at),
      'previousVersion',v_previous_version,
      'revokedAt',to_jsonb(v_revoked_at)
    );
  END IF;

  IF v_protocol = 'oidc' THEN
    SELECT material.* INTO v_oidc
    FROM public.tenant_oidc_session_materials AS material
    WHERE material.continuation_id IS NULL
      AND material.user_id = v_user_id
      AND EXISTS (
        SELECT 1
        FROM app.private_oidc_material_effective_session_v1(material.id)
          AS effective
        WHERE effective.session_id = v_session_id
          AND effective.tenant_id IS NOT DISTINCT FROM v_tenant_id
      )
    FOR UPDATE;
    v_oidc_found := FOUND;
    IF v_oidc_found THEN
      SELECT effective.authority INTO STRICT v_oidc_effective_authority
      FROM app.private_oidc_material_effective_session_v1(v_oidc.id)
        AS effective
      WHERE effective.session_id = v_session_id
        AND effective.tenant_id IS NOT DISTINCT FROM v_tenant_id;
      v_command_authority := v_oidc_effective_authority;
    END IF;
  ELSIF v_protocol = 'saml' AND v_tenant_id IS NOT NULL THEN
    SELECT material.* INTO v_tenant_saml
    FROM public.tenant_saml_session_materials AS material
    WHERE material.tenant_id = v_tenant_id
      AND material.session_id = v_session_id
      AND material.continuation_id IS NULL
      AND material.user_id = v_user_id
    FOR SHARE;
    v_tenant_saml_found := FOUND;
    IF NOT v_tenant_saml_found THEN
      SELECT material.* INTO v_platform_saml
      FROM public.platform_saml_session_materials AS material
      JOIN LATERAL app.private_platform_saml_material_effective_session_v1(
        material.id
      ) AS effective
        ON effective.session_id = v_session_id
       AND effective.tenant_id = v_tenant_id
       AND effective.authority = 'tenant_platform_provider'
      WHERE material.continuation_id IS NULL
        AND material.user_id = v_user_id
      FOR SHARE OF material;
      v_platform_saml_found := FOUND;
      IF v_platform_saml_found THEN
        SELECT effective.* INTO STRICT v_platform_saml_effective
        FROM app.private_platform_saml_material_effective_session_v1(
          v_platform_saml.id
        ) AS effective
        WHERE effective.session_id = v_session_id
          AND effective.tenant_id = v_tenant_id
          AND effective.authority = 'tenant_platform_provider';
        v_command_authority := v_platform_saml_effective.authority;
      END IF;
    END IF;
  ELSIF v_protocol = 'saml' THEN
    SELECT material.* INTO v_platform_saml
    FROM public.platform_saml_session_materials AS material
    JOIN LATERAL app.private_platform_saml_material_effective_session_v1(
      material.id
    ) AS effective
      ON effective.session_id = v_session_id
     AND effective.tenant_id IS NULL
     AND effective.authority = 'platform_provider'
    WHERE material.session_id = v_session_id
      AND material.continuation_id IS NULL
      AND material.user_id = v_user_id
    FOR SHARE;
    v_platform_saml_found := FOUND;
    IF v_platform_saml_found THEN
      SELECT effective.* INTO STRICT v_platform_saml_effective
      FROM app.private_platform_saml_material_effective_session_v1(
        v_platform_saml.id
      ) AS effective
      WHERE effective.session_id = v_session_id
        AND effective.tenant_id IS NULL
        AND effective.authority = 'platform_provider';
      v_command_authority := v_platform_saml_effective.authority;
    END IF;
  END IF;
  v_command_authority := coalesce(
    v_command_authority,
    CASE WHEN v_tenant_id IS NULL THEN 'platform_session'
      ELSE 'tenant_session' END
  );

  UPDATE public.auth_sessions AS family
  SET revoked_at = v_requested_at,
      revoke_reason = left(coalesce(v_protocol,'session') || '_local_logout',500)
  WHERE family.user_id = v_user_id
    AND family.rotation_family_id = v_session.rotation_family_id
    AND family.revoked_at IS NULL;
  IF v_tenant_id IS NOT NULL THEN
    UPDATE public.auth_session_mfa_states AS state
    SET session_version = CASE
          WHEN state.session_version < 9000000000000000
            THEN state.session_version + 1
          ELSE state.session_version END
    WHERE state.tenant_id = v_tenant_id AND state.session_id = v_session_id
      AND state.user_id = v_user_id
      AND state.session_version = v_previous_version;
  ELSIF v_protocol = 'oidc' THEN
    UPDATE public.auth_session_platform_oidc_states AS state
    SET session_version = CASE
          WHEN state.session_version < 2147483647
            THEN state.session_version + 1
          ELSE state.session_version END
    WHERE state.session_id = v_session_id AND state.user_id = v_user_id
      AND state.session_version = v_previous_version;
  ELSIF v_protocol = 'saml' THEN
    UPDATE public.auth_session_platform_saml_states AS state
    SET session_version = CASE
          WHEN state.session_version < 2147483647
            THEN state.session_version + 1
          ELSE state.session_version END
    WHERE state.session_id = v_session_id AND state.user_id = v_user_id
      AND state.session_version = v_previous_version;
  END IF;

  IF v_oidc_found AND v_oidc.scrubbed_at IS NULL
     AND v_oidc.logout_operation_run_id IS NULL THEN
    v_continuation_created := v_request_upstream
      AND v_session.absolute_expires_at > v_requested_at
      AND v_oidc.expires_at > v_requested_at
      AND v_continuation_expires_at <= v_session.absolute_expires_at
      AND v_continuation_expires_at <= v_oidc.expires_at
      AND v_oidc.end_session_endpoint IS NOT NULL
      AND v_oidc.id_token_key_version IS NOT NULL
      AND v_oidc.id_token_ciphertext IS NOT NULL
      AND v_oidc.id_token_digest IS NOT NULL;
    v_schedule_retry := v_request_upstream
      AND v_session.absolute_expires_at > v_requested_at
      AND v_oidc.expires_at > v_requested_at
      AND v_oidc.refresh_state IN ('ready','claimed')
      AND v_oidc.refresh_token_key_version IS NOT NULL
      AND v_oidc.refresh_token_ciphertext IS NOT NULL
      AND v_oidc.revocation_endpoint IS NOT NULL;
    IF v_schedule_retry THEN v_retry_job_id := uuidv7(); END IF;
    UPDATE public.tenant_oidc_session_materials AS material
    SET logout_disposition = CASE WHEN v_continuation_created
          THEN 'claimed' ELSE 'skipped' END,
        logout_operation_run_id = v_operation_run_id,
        logout_claimed_at = v_requested_at,
        refresh_state = CASE WHEN material.refresh_state = 'unavailable'
          THEN 'unavailable' ELSE 'revoked' END,
        refresh_claimed_at = NULL,refresh_claim_expires_at = NULL,
        refresh_version = CASE
          WHEN material.refresh_version < 8999999999999999
            THEN material.refresh_version + 1
          ELSE material.refresh_version END,
        updated_at = v_requested_at
    WHERE material.id = v_oidc.id
      AND material.logout_operation_run_id IS NULL;
    IF NOT FOUND THEN
      v_continuation_created := false;
      v_schedule_retry := false;
      v_retry_job_id := NULL;
    END IF;
  ELSIF v_tenant_saml_found
      AND v_tenant_saml.logout_operation_run_id IS NULL THEN
    v_continuation_created := v_request_upstream
      AND v_session.absolute_expires_at > v_requested_at
      AND v_continuation_expires_at <= v_session.absolute_expires_at
      AND v_tenant_saml.aad_version = 2
      AND v_tenant_saml.key_version IS NOT NULL
      AND v_tenant_saml.ciphertext IS NOT NULL
      AND v_tenant_saml.logout_configuration IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.session_logout_continuations AS continuation
        WHERE continuation.tenant_id = v_tenant_id
          AND continuation.tenant_saml_material_id = v_tenant_saml.id
      );
    PERFORM set_config('app.saml_logout_claim_v1','on',true);
    UPDATE public.tenant_saml_session_materials AS material
    SET logout_disposition = CASE WHEN v_continuation_created
          THEN 'claimed' ELSE 'skipped' END,
        logout_operation_run_id = v_operation_run_id,
        logout_claimed_at = v_requested_at
    WHERE material.id = v_tenant_saml.id
      AND material.tenant_id = v_tenant_saml.tenant_id
      AND material.logout_operation_run_id IS NULL;
    IF NOT FOUND THEN v_continuation_created := false; END IF;
  ELSIF v_platform_saml_found
      AND v_platform_saml.logout_operation_run_id IS NULL THEN
    v_continuation_created := v_request_upstream
      AND v_session.absolute_expires_at > v_requested_at
      AND v_continuation_expires_at <= v_session.absolute_expires_at
      AND v_platform_saml.key_version IS NOT NULL
      AND v_platform_saml.nonce IS NOT NULL
      AND v_platform_saml.ciphertext IS NOT NULL
      AND v_platform_saml.logout_configuration IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.session_logout_continuations AS continuation
        WHERE continuation.platform_saml_material_id = v_platform_saml.id
      );
    PERFORM set_config('app.saml_logout_claim_v1','on',true);
    PERFORM set_config('app.platform_saml_direct_runtime_write_v1','on',true);
    UPDATE public.platform_saml_session_materials AS material
    SET logout_disposition = CASE WHEN v_continuation_created
          THEN 'claimed' ELSE 'skipped' END,
        logout_operation_run_id = v_operation_run_id,
        logout_claimed_at = v_requested_at
    WHERE material.id = v_platform_saml.id
      AND material.logout_operation_run_id IS NULL;
    IF NOT FOUND THEN v_continuation_created := false; END IF;
  END IF;

  v_base_result := jsonb_build_object(
    'category','revoked_local_only',
    'operationRunId',v_operation_run_id::text,
    'sessionId',v_session_id::text,'userId',v_user_id::text,
    'tenantId',to_jsonb(v_tenant_id),
    'requestedAt',v_request_snapshot -> 'requestedAt',
    'observedAt',to_jsonb(v_requested_at),
    'previousVersion',v_previous_version,'revokedAt',to_jsonb(v_revoked_at)
  );
  INSERT INTO public.tenant_oidc_logout_commands (
    tenant_id,authority,operation_run_id,session_id,expected_version,
    request_upstream,material_id,request_digest,request_snapshot,
    result_snapshot,applied_at
  ) VALUES (
    v_tenant_id,v_command_authority,v_operation_run_id,v_session_id,
    v_previous_version,v_request_upstream,
    CASE WHEN v_oidc_found THEN v_oidc.id END,
    v_request_digest,v_request_snapshot,v_base_result,v_requested_at
  );
  IF v_schedule_retry THEN
    INSERT INTO public.tenant_oidc_logout_retry_jobs (
      id,tenant_id,authority,operation_run_id,material_id,session_family_id,
      state,attempt,maximum_attempts,not_before,version,created_at,updated_at
    ) VALUES (
      v_retry_job_id,v_oidc.tenant_id,v_oidc.authority,v_operation_run_id,
      v_oidc.id,v_session.rotation_family_id,'pending',0,8,v_requested_at,1,
      v_requested_at,v_requested_at
    );
  END IF;
  IF v_continuation_created THEN
    INSERT INTO public.session_logout_continuations (
      id,token_digest,operation_run_id,session_id,user_id,tenant_id,
      authority,protocol,oidc_material_id,tenant_saml_material_id,
      platform_saml_material_id,created_at,expires_at
    ) VALUES (
      v_continuation_id,v_continuation_digest,v_operation_run_id,v_session_id,
      v_user_id,v_tenant_id,
      CASE WHEN v_oidc_found THEN v_oidc_effective_authority
        WHEN v_tenant_saml_found THEN 'tenant_provider'
        WHEN v_tenant_id IS NOT NULL THEN 'tenant_platform_provider'
        ELSE 'platform_provider' END,
      v_protocol,CASE WHEN v_oidc_found THEN v_oidc.id END,
      CASE WHEN v_tenant_saml_found THEN v_tenant_saml.id END,
      CASE WHEN v_platform_saml_found THEN v_platform_saml.id END,
      v_requested_at,v_continuation_expires_at
    );
  END IF;

  IF v_tenant_id IS NOT NULL THEN
    INSERT INTO public.audit_events (
      id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
      resource_type,resource_id,request_id,correlation_id,ip_address,
      user_agent,authentication_method,outcome,metadata
    ) VALUES (
      uuidv7(),v_tenant_id,0,v_requested_at,'user',v_user_id,
      'tenant.identity.session_local_logout','auth_session',v_session_id,
      v_request_id,v_correlation_id,v_remote_address,v_user_agent,
      v_protocol,'success',jsonb_build_object(
        'upstream_requested',v_request_upstream,
        'continuation_created',v_continuation_created,
        'material_present',v_oidc_found OR v_tenant_saml_found
          OR v_platform_saml_found,
        'material_disclosed',false
      )
    );
  ELSE
    PERFORM app.append_platform_audit_event(
      uuidv7(),'user',v_user_id,'platform.identity.session_local_logout',
      'auth_session',v_session_id,v_request_id,v_correlation_id,
      v_remote_address,v_user_agent,v_protocol,'success',NULL,
      jsonb_build_object(
        'upstream_requested',v_request_upstream,
        'continuation_created',v_continuation_created,
        'material_present',v_oidc_found OR v_platform_saml_found,
        'material_disclosed',false
      )
    );
  END IF;
  IF v_continuation_created THEN
    v_result := v_base_result || jsonb_build_object(
      'category','logout_continuation',
      'continuationId',v_continuation_id::text,
      'continuationExpiresAt',to_jsonb(v_continuation_expires_at)
    );
    RETURN v_result;
  END IF;
  RETURN v_base_result;
EXCEPTION WHEN unique_violation THEN
  -- A digest or material collision never reassigns a live browser proof.
  RETURN NULL;
WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid local session logout command'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.claim_session_logout_continuation_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_id uuid;
  v_digest bytea;
  v_claimed_at timestamptz;
  v_requested_claimed_at timestamptz;
  v_continuation public.session_logout_continuations%ROWTYPE;
  v_command public.tenant_oidc_logout_commands%ROWTYPE;
  v_oidc public.tenant_oidc_session_materials%ROWTYPE;
  v_tenant_saml public.tenant_saml_session_materials%ROWTYPE;
  v_platform_saml public.platform_saml_session_materials%ROWTYPE;
  v_platform_saml_effective record;
  v_configuration jsonb;
  v_provider jsonb;
  v_admission jsonb;
  v_retry_id uuid;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['continuationId','tokenDigest','claimedAt'],
    ARRAY['continuationId','tokenDigest','claimedAt'],4096
  );
  BEGIN
    v_id := app.private_mfa_require_uuidv7_v1(
      p_request ->> 'continuationId'
    );
    v_digest := app.private_mfa_decode_base64_v1(
      p_request ->> 'tokenDigest',32,32
    );
    v_requested_claimed_at := (p_request ->> 'claimedAt')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  IF encode(v_digest,'hex') = repeat('00',32)
     OR date_trunc('microseconds',v_requested_claimed_at)
          <> v_requested_claimed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_claimed_at))) > 300 THEN
    RETURN NULL;
  END IF;
  v_claimed_at := date_trunc('microseconds',transaction_timestamp());
  PERFORM pg_advisory_xact_lock(hashtextextended(v_id::text,73419023));
  SELECT continuation.* INTO v_continuation
  FROM public.session_logout_continuations AS continuation
  WHERE continuation.id = v_id
  FOR UPDATE;
  IF NOT FOUND OR v_continuation.token_digest IS DISTINCT FROM v_digest
     OR v_continuation.consumed_at IS NOT NULL
     OR v_claimed_at < v_continuation.created_at
     OR v_claimed_at >= v_continuation.expires_at THEN
    RETURN NULL;
  END IF;
  SELECT command.* INTO v_command
  FROM public.tenant_oidc_logout_commands AS command
  WHERE command.operation_run_id = v_continuation.operation_run_id
    AND command.session_id = v_continuation.session_id
    AND command.tenant_id IS NOT DISTINCT FROM v_continuation.tenant_id
    AND command.request_upstream
  FOR SHARE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- Consume before any protected protocol material is projected. A later
  -- lookup failure is intentionally terminal and cannot resurrect the proof.
  UPDATE public.session_logout_continuations AS continuation
  SET consumed_at = v_claimed_at
  WHERE continuation.id = v_id AND continuation.consumed_at IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;

  BEGIN
  IF v_continuation.protocol = 'oidc' THEN
    SELECT material.* INTO v_oidc
    FROM public.tenant_oidc_session_materials AS material
    WHERE material.id = v_continuation.oidc_material_id
      AND material.user_id = v_continuation.user_id
      AND EXISTS (
        SELECT 1
        FROM app.private_oidc_material_effective_session_v1(material.id)
          AS effective
        WHERE effective.session_id = v_continuation.session_id
          AND effective.tenant_id IS NOT DISTINCT FROM v_continuation.tenant_id
          AND effective.authority = v_continuation.authority
      )
      AND material.scrubbed_at IS NULL
      AND material.expires_at > v_claimed_at
      AND material.logout_disposition = 'claimed'
      AND material.logout_operation_run_id = v_continuation.operation_run_id
      AND material.id_token_key_version IS NOT NULL
      AND material.id_token_ciphertext IS NOT NULL
      AND material.id_token_digest IS NOT NULL
      AND material.end_session_endpoint IS NOT NULL
      AND material.post_logout_redirect_uri IS NOT NULL
    FOR SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    v_provider := CASE v_oidc.authority
      WHEN 'tenant_provider' THEN jsonb_build_object(
        'scope','tenant','tenantId',v_oidc.tenant_id::text,
        'providerId',v_oidc.provider_id::text,
        'bindingId',v_oidc.binding_id::text
      ) ELSE jsonb_build_object(
        'scope','platform','providerId',v_oidc.provider_id::text
      ) END;
    v_admission := CASE WHEN v_oidc.authority = 'tenant_platform_provider'
      THEN jsonb_build_object(
        'tenantId',v_oidc.tenant_id::text,
        'bindingId',v_oidc.binding_id::text
      ) END;
    SELECT job.id INTO v_retry_id
    FROM public.tenant_oidc_logout_retry_jobs AS job
    WHERE job.operation_run_id = v_continuation.operation_run_id
      AND job.material_id = v_oidc.id;
    RETURN jsonb_build_object(
      'category','oidc_end_session',
      'requestedClaimedAt',to_jsonb(v_requested_claimed_at),
      'observedAt',to_jsonb(v_claimed_at),
      'continuationId',v_continuation.id::text,
      'operationRunId',v_continuation.operation_run_id::text,
      'sessionId',v_continuation.session_id::text,
      'userId',v_continuation.user_id::text,
      'tenantId',to_jsonb(v_continuation.tenant_id),
      'previousVersion',v_command.expected_version,
      'provider',v_provider,
      'materialId',v_oidc.id::text,
      'endSessionEndpoint',v_oidc.end_session_endpoint,
      'postLogoutRedirectUri',v_oidc.post_logout_redirect_uri,
      'protectedIdToken',jsonb_build_object(
        'keyVersion',v_oidc.id_token_key_version,
        'ciphertext',replace(encode(
          v_oidc.id_token_ciphertext,'base64'
        ),E'\n','')
      ),
      'idTokenDigest',replace(encode(v_oidc.id_token_digest,'base64'),E'\n',''),
      'materialExpiresAt',to_jsonb(v_oidc.expires_at),
      'revokedAt',to_jsonb(v_command.applied_at),
      'expiresAt',to_jsonb(v_continuation.expires_at)
    ) || CASE WHEN v_admission IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('admission',v_admission) END
      || CASE WHEN v_retry_id IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('logoutRetryJobId',v_retry_id::text) END;
  ELSIF v_continuation.tenant_saml_material_id IS NOT NULL THEN
    SELECT material.* INTO v_tenant_saml
    FROM public.tenant_saml_session_materials AS material
    WHERE material.tenant_id = v_continuation.tenant_id
      AND material.id = v_continuation.tenant_saml_material_id
      AND material.session_id = v_continuation.session_id
      AND material.user_id = v_continuation.user_id
      AND material.aad_version = 2
      AND material.key_version IS NOT NULL
      AND material.ciphertext IS NOT NULL
    FOR SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    v_configuration := v_tenant_saml.logout_configuration;
    IF v_configuration IS NULL THEN RETURN NULL; END IF;
    RETURN jsonb_build_object(
      'category','saml_logout',
      'requestedClaimedAt',to_jsonb(v_requested_claimed_at),
      'observedAt',to_jsonb(v_claimed_at),
      'continuationId',v_continuation.id::text,
      'operationRunId',v_continuation.operation_run_id::text,
      'sessionId',v_continuation.session_id::text,
      'userId',v_continuation.user_id::text,
      'tenantId',v_continuation.tenant_id::text,
      'previousVersion',v_command.expected_version,
      'provider',jsonb_build_object(
        'scope','tenant','tenantId',v_tenant_saml.tenant_id::text,
        'providerId',v_tenant_saml.provider_id::text,
        'bindingId',v_tenant_saml.binding_id::text
      ),
      'bindingId',v_tenant_saml.binding_id::text,
      'materialId',v_tenant_saml.id::text,
      'configuration',v_configuration,
      'protectedMaterial',jsonb_build_object(
        'keyVersion',v_tenant_saml.key_version,
        'ciphertext',replace(encode(v_tenant_saml.ciphertext,'base64'),E'\n','')
      ),
      'revokedAt',to_jsonb(v_command.applied_at),
      'expiresAt',to_jsonb(v_continuation.expires_at)
    );
  ELSE
    SELECT material.* INTO v_platform_saml
    FROM public.platform_saml_session_materials AS material
    JOIN LATERAL app.private_platform_saml_material_effective_session_v1(
      material.id
    ) AS effective
      ON effective.session_id = v_continuation.session_id
     AND effective.tenant_id IS NOT DISTINCT FROM v_continuation.tenant_id
     AND effective.authority = v_continuation.authority
    WHERE material.id = v_continuation.platform_saml_material_id
      AND material.user_id = v_continuation.user_id
      AND material.key_version IS NOT NULL
      AND material.nonce IS NOT NULL AND material.ciphertext IS NOT NULL
      AND material.logout_configuration IS NOT NULL
    FOR SHARE OF material;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT effective.* INTO STRICT v_platform_saml_effective
    FROM app.private_platform_saml_material_effective_session_v1(
      v_platform_saml.id
    ) AS effective
    WHERE effective.session_id = v_continuation.session_id
      AND effective.tenant_id IS NOT DISTINCT FROM v_continuation.tenant_id
      AND effective.authority = v_continuation.authority;
    v_configuration := v_platform_saml.logout_configuration;
    IF v_configuration IS NULL THEN RETURN NULL; END IF;
    IF v_continuation.authority = 'tenant_platform_provider' THEN
      v_admission := jsonb_build_object(
        'tenantId',v_continuation.tenant_id::text,
        'bindingId',v_platform_saml_effective.binding_id::text
      );
    ELSE
      v_admission := NULL;
    END IF;
    RETURN jsonb_build_object(
      'category','saml_logout',
      'requestedClaimedAt',to_jsonb(v_requested_claimed_at),
      'observedAt',to_jsonb(v_claimed_at),
      'continuationId',v_continuation.id::text,
      'operationRunId',v_continuation.operation_run_id::text,
      'sessionId',v_continuation.session_id::text,
      'userId',v_continuation.user_id::text,
      'tenantId',to_jsonb(v_continuation.tenant_id),
      'previousVersion',v_command.expected_version,
      'provider',jsonb_build_object(
        'scope','platform','providerId',v_platform_saml.platform_provider_id::text
      ),
      'bindingId',NULL,
      'materialId',v_platform_saml.id::text,
      'configuration',v_configuration,
      'protectedMaterial',jsonb_build_object(
        'keyVersion',v_platform_saml.key_version,
        'ciphertext',replace(encode(
          v_platform_saml.nonce || v_platform_saml.ciphertext,'base64'
        ),E'\n','')
      ),
      'revokedAt',to_jsonb(v_command.applied_at),
      'expiresAt',to_jsonb(v_continuation.expires_at)
    ) || CASE WHEN v_admission IS NULL THEN '{}'::jsonb
      ELSE jsonb_build_object('admission',v_admission) END;
  END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RETURN NULL;
END;
$function$;
--> statement-breakpoint

-- Keep the still-supported tenant-only logout ABI local-first after membership
-- suspension and bind its optional upstream projection to the login material.
-- Legacy rows without a stored projection deliberately degrade to local-only.
DO $tenant_saml_historical_logout_v1$
DECLARE
  v_definition text;
  v_membership_old text := $old$
  SELECT membership.id INTO v_membership_id
  FROM public.tenant_memberships AS membership
  WHERE membership.tenant_id = v_tenant_id
    AND membership.user_id = p_user_id
    AND membership.status = 'active'
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;$old$;
  v_membership_new text := $new$
  SELECT membership.id INTO v_membership_id
  FROM public.tenant_memberships AS membership
  WHERE membership.tenant_id = v_tenant_id
    AND membership.user_id = p_user_id
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;$new$;
  v_configuration_old text := $old$
      v_configuration := app.private_saml_logout_configuration_record_v1(
        v_tenant_id, v_provenance.provider_id, v_provenance.binding_id
      );$old$;
  v_configuration_new text := $new$
      v_configuration := v_material.logout_configuration;$new$;
  v_material_old text := $old$
      WHEN NOT v_request_upstream OR v_material.key_version IS NULL THEN NULL$old$;
  v_material_new text := $new$
      WHEN NOT v_request_upstream OR v_material.key_version IS NULL
        OR v_configuration IS NULL THEN NULL$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.revoke_local_saml_session_v1(uuid,jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_membership_old) = 0
     OR strpos(v_definition,v_configuration_old) = 0
     OR strpos(v_definition,v_material_old) = 0 THEN
    RAISE EXCEPTION 'unexpected tenant SAML logout predecessor';
  END IF;
  EXECUTE replace(replace(replace(
    v_definition,v_membership_old,v_membership_new
  ),v_configuration_old,v_configuration_new),v_material_old,v_material_new);
END;
$tenant_saml_historical_logout_v1$;
--> statement-breakpoint

CREATE FUNCTION app.cleanup_session_logout_continuations_v1(p_request jsonb)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_observed_at timestamptz;
  v_removed integer;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['observedAt'],ARRAY['observedAt'],1024
  );
  v_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid logout continuation cleanup'
      USING ERRCODE = '22023';
  END IF;
  WITH expired AS (
    SELECT continuation.id
    FROM public.session_logout_continuations AS continuation
    WHERE continuation.expires_at <= least(
      v_observed_at,transaction_timestamp()
    )
    ORDER BY continuation.expires_at,continuation.id
    FOR UPDATE SKIP LOCKED
    LIMIT 100
  ), removed AS (
    DELETE FROM public.session_logout_continuations AS continuation
    USING expired
    WHERE continuation.id = expired.id
    RETURNING continuation.id
  ) SELECT count(*)::integer INTO v_removed FROM removed;
  RETURN v_removed;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.scrub_oidc_session_material_v1(p_request jsonb)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_material_id uuid;
  v_operation_run_id uuid;
  v_observed_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['materialId','operationRunId','observedAt'],
    ARRAY['materialId','operationRunId','observedAt'],2048
  );
  v_material_id := app.private_mfa_require_uuidv7_v1(
    p_request ->> 'materialId'
  );
  v_operation_run_id := app.private_mfa_require_uuidv7_v1(
    p_request ->> 'operationRunId'
  );
  v_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF v_material_id = v_operation_run_id
     OR date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC material scrub command'
      USING ERRCODE = '22023';
  END IF;
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.id = v_material_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_material.scrubbed_at IS NOT NULL THEN
    RETURN v_material.scrub_operation_run_id = v_operation_run_id;
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.session_logout_continuations AS continuation
       WHERE continuation.oidc_material_id = v_material_id
         AND continuation.consumed_at IS NULL
         AND continuation.expires_at > v_observed_at
     ) OR EXISTS (
       SELECT 1 FROM public.tenant_oidc_logout_retry_jobs AS job
       WHERE job.material_id = v_material_id
         AND job.state IN ('pending','claimed')
     ) OR NOT (
       v_material.expires_at <= v_observed_at OR EXISTS (
          SELECT 1
          FROM app.private_oidc_material_effective_session_v1(v_material.id)
            AS effective
          JOIN public.auth_sessions AS session
            ON session.id = effective.session_id
          WHERE session.id = effective.session_id
            AND session.user_id = v_material.user_id
            AND session.rotation_family_id = v_material.rotation_family_id
           AND (session.revoked_at IS NOT NULL
             OR session.absolute_expires_at <= v_observed_at)
       )
     ) THEN
    RETURN false;
  END IF;
  UPDATE public.tenant_oidc_session_materials AS material
  SET id_token_key_version = NULL,id_token_ciphertext = NULL,
      id_token_digest = NULL,refresh_token_key_version = NULL,
      refresh_token_ciphertext = NULL,refresh_token_digest = NULL,
      refresh_state = 'scrubbed',refresh_claimed_at = NULL,
      refresh_claim_expires_at = NULL,
      refresh_retry_attempt = 0,
      access_expires_at = NULL,
      client_secret_revision = NULL,client_authentication = NULL,
      client_id = NULL,token_endpoint = NULL,revocation_endpoint = NULL,
      end_session_endpoint = NULL,post_logout_redirect_uri = NULL,
      logout_disposition = CASE
        WHEN material.logout_disposition IN ('available','not_configured')
          THEN 'skipped' ELSE material.logout_disposition END,
      logout_operation_run_id = CASE
        WHEN material.logout_operation_run_id IS NULL
          THEN v_operation_run_id ELSE material.logout_operation_run_id END,
      logout_claimed_at = CASE WHEN material.logout_claimed_at IS NULL
          THEN v_observed_at ELSE material.logout_claimed_at END,
      scrubbed_at = v_observed_at,
      scrub_operation_run_id = v_operation_run_id,
      refresh_version = CASE
        WHEN material.refresh_version < 8999999999999999
          THEN material.refresh_version + 1
        ELSE material.refresh_version END,
      updated_at = v_observed_at
  WHERE material.id = v_material_id AND material.scrubbed_at IS NULL;
  RETURN FOUND;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC material scrub command'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.private_legacy_claim_tenant_oidc_logout_retry_v2(
  p_request jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_job_id uuid;
  v_observed_at timestamptz;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_provider jsonb;
  v_admission jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['jobId','observedAt'],ARRAY['jobId','observedAt'],2048
  );
  v_job_id := app.private_mfa_require_uuidv7_v1(p_request ->> 'jobId');
  v_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF date_trunc('microseconds',v_observed_at) <> v_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC logout retry claim'
      USING ERRCODE = '22023';
  END IF;
  SELECT job.* INTO v_job
  FROM public.tenant_oidc_logout_retry_jobs AS job
  WHERE job.id = v_job_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state IN ('complete','dead_letter')
     OR v_job.not_before > v_observed_at
     OR (v_job.state = 'claimed' AND v_job.claim_expires_at > v_observed_at)
     OR v_job.attempt >= v_job.maximum_attempts THEN
    RETURN NULL;
  END IF;
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.id = v_job.material_id
    AND material.tenant_id IS NOT DISTINCT FROM v_job.tenant_id
    AND material.authority = v_job.authority
    AND material.rotation_family_id = v_job.session_family_id
  FOR SHARE;
  IF NOT FOUND OR v_material.scrubbed_at IS NOT NULL
     OR v_material.expires_at <= v_observed_at
     OR v_material.refresh_state <> 'revoked'
     OR v_material.refresh_token_key_version IS NULL
     OR v_material.refresh_token_ciphertext IS NULL
     OR v_material.revocation_endpoint IS NULL THEN
    UPDATE public.tenant_oidc_logout_retry_jobs AS job
    SET state = 'dead_letter',attempt = greatest(job.attempt,1),
        claimed_at = coalesce(job.claimed_at,v_observed_at),
        claim_expires_at = coalesce(job.claim_expires_at,v_observed_at),
        completed_at = v_observed_at,version = job.version + 1,
        updated_at = v_observed_at
    WHERE job.id = v_job_id;
    RETURN NULL;
  END IF;
  UPDATE public.tenant_oidc_logout_retry_jobs AS job
  SET state = 'claimed',attempt = job.attempt + 1,
      claimed_at = v_observed_at,
      claim_expires_at = v_observed_at + interval '2 minutes',
      completed_at = NULL,version = job.version + 1,
      updated_at = v_observed_at
  WHERE job.id = v_job_id
  RETURNING job.* INTO STRICT v_job;
  v_provider := CASE v_material.authority
    WHEN 'tenant_provider' THEN jsonb_build_object(
      'scope','tenant','tenantId',v_material.tenant_id::text,
      'providerId',v_material.provider_id::text,
      'bindingId',v_material.binding_id::text
    ) ELSE jsonb_build_object(
      'scope','platform','providerId',v_material.provider_id::text
    ) END;
  v_admission := CASE WHEN v_material.authority = 'tenant_platform_provider'
    THEN jsonb_build_object(
      'tenantId',v_material.tenant_id::text,
      'bindingId',v_material.binding_id::text
    ) END;
  RETURN jsonb_build_object(
    'jobId',v_job.id::text,'tenantId',to_jsonb(v_job.tenant_id),
    'materialId',v_job.material_id::text,
    'sessionFamilyId',v_job.session_family_id::text,
    'attempt',v_job.attempt,'maximumAttempts',v_job.maximum_attempts,
    'notBefore',to_jsonb(v_job.not_before),'provider',v_provider,
    'clientSecretRevision',v_material.client_secret_revision,
    'clientAuthentication',v_material.client_authentication,
    'clientId',v_material.client_id,'endpoint',v_material.revocation_endpoint,
    'refreshGeneration',v_material.refresh_generation,
    'materialExpiresAt',to_jsonb(v_material.expires_at),
    'opaqueReference',jsonb_build_object(
      'keyVersion',v_material.refresh_token_key_version,
      'ciphertext',replace(encode(
        v_material.refresh_token_ciphertext,'base64'
      ),E'\n','')
    )
  ) || CASE WHEN v_admission IS NULL THEN '{}'::jsonb
    ELSE jsonb_build_object('admission',v_admission) END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC logout retry claim'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

-- Retention is deliberately split by dependency class and executed in a
-- separate worker autocommit from work claim. One invocation can lock only a
-- continuation, consumed-token, or SAML-material class and never acquires an
-- OIDC family/session lock afterwards. No cross-class lock can therefore
-- invert the auth-state pruner.
CREATE FUNCTION app.cleanup_federated_maintenance_retention_v1(
  p_request jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_kind text;
  v_requested_observed_at timestamptz;
  v_observed_at timestamptz;
  v_removed integer := 0;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['kind','observedAt'],ARRAY['kind','observedAt'],1024
  );
  v_kind := p_request ->> 'kind';
  v_requested_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF v_kind NOT IN ('logout_continuation','consumed_refresh','saml_material')
     OR date_trunc('microseconds',v_requested_observed_at)
       <> v_requested_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid federated maintenance cleanup'
      USING ERRCODE = '22023';
  END IF;
  v_observed_at := date_trunc('microseconds',transaction_timestamp());

  IF v_kind = 'logout_continuation' THEN
    v_removed := app.cleanup_session_logout_continuations_v1(
      jsonb_build_object('observedAt',to_jsonb(v_observed_at))
    );
  ELSIF v_kind = 'consumed_refresh' THEN
    WITH expired AS (
      SELECT consumed.id
      FROM public.tenant_oidc_consumed_refresh_tokens AS consumed
      WHERE consumed.retain_until <= v_observed_at
      ORDER BY consumed.retain_until,consumed.id
      FOR UPDATE SKIP LOCKED LIMIT 100
    ), removed AS (
      DELETE FROM public.tenant_oidc_consumed_refresh_tokens AS consumed
      USING expired
      WHERE consumed.id = expired.id
      RETURNING consumed.id
    ) SELECT count(*)::integer INTO v_removed FROM removed;
  ELSE
    v_removed := app.private_cleanup_expired_saml_materials_v1(v_observed_at);
  END IF;

  RETURN jsonb_build_object(
    'kind',v_kind,
    'observedAt',to_jsonb(v_observed_at),
    'removed',v_removed
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid federated maintenance cleanup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

-- Access expiry is an authentication boundary, not merely a scheduling hint.
-- Process at most one immutable OIDC family in its own worker autocommit so a
-- subsequent work claim cannot hold or roll back locks from another family.
CREATE FUNCTION app.expire_oidc_access_lease_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_kind text;
  v_requested_observed_at timestamptz;
  v_observed_at timestamptz;
  v_candidate_material_id uuid;
  v_candidate_family_id uuid;
  v_effective_session_id uuid;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_expired boolean := false;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['kind','observedAt'],ARRAY['kind','observedAt'],1024
  );
  v_kind := p_request ->> 'kind';
  v_requested_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF v_kind <> 'access_expiry'
     OR date_trunc('microseconds',v_requested_observed_at)
          <> v_requested_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC access expiry'
      USING ERRCODE = '22023';
  END IF;
  v_observed_at := date_trunc('microseconds',transaction_timestamp());

  -- Discover without taking a row lock, then serialize on the same immutable
  -- family advisory used by refresh and local logout. Under that fence, lock
  -- the effective session first, the material second, and re-attest every due
  -- predicate. This common order prevents a session/material deadlock while a
  -- concurrent logout is revoking the same family.
  SELECT material.id,material.rotation_family_id
    INTO v_candidate_material_id,v_candidate_family_id
  FROM public.tenant_oidc_session_materials AS material
  JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
    AS effective ON true
  JOIN public.auth_sessions AS session
    ON session.id = effective.session_id
   AND session.user_id = material.user_id
   AND session.rotation_family_id = material.rotation_family_id
  WHERE (material.refresh_state = 'ready'
      OR (material.refresh_state = 'claimed'
        AND material.refresh_claim_expires_at <= v_observed_at))
    AND material.scrubbed_at IS NULL
    AND material.access_expires_at <= v_observed_at
    AND session.revoked_at IS NULL
  ORDER BY material.access_expires_at,material.id
  LIMIT 1;
  IF FOUND THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      v_candidate_family_id::text,90174213
    ));
    SELECT session.id INTO v_effective_session_id
    FROM public.tenant_oidc_session_materials AS material
    JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
      AS effective ON true
    JOIN public.auth_sessions AS session
      ON session.id = effective.session_id
     AND session.user_id = material.user_id
     AND session.rotation_family_id = material.rotation_family_id
     AND session.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
    WHERE material.id = v_candidate_material_id
      AND material.rotation_family_id = v_candidate_family_id
    FOR UPDATE OF session;
    IF FOUND THEN
      SELECT material.* INTO v_material
      FROM public.tenant_oidc_session_materials AS material
      JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
        AS effective ON true
      JOIN public.auth_sessions AS session
        ON session.id = effective.session_id
       AND session.id = v_effective_session_id
       AND session.user_id = material.user_id
       AND session.rotation_family_id = material.rotation_family_id
       AND session.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
      WHERE material.id = v_candidate_material_id
        AND material.rotation_family_id = v_candidate_family_id
        AND (material.refresh_state = 'ready'
          OR (material.refresh_state = 'claimed'
            AND material.refresh_claim_expires_at <= v_observed_at))
        AND material.scrubbed_at IS NULL
        AND material.access_expires_at <= v_observed_at
        AND session.revoked_at IS NULL
      FOR UPDATE OF material;
      IF FOUND THEN
        UPDATE public.auth_sessions AS family
        SET revoked_at = v_observed_at,
            revoke_reason = 'oidc_access_lease_expired'
        WHERE family.user_id = v_material.user_id
          AND family.rotation_family_id = v_material.rotation_family_id
          AND family.revoked_at IS NULL;
        UPDATE public.tenant_oidc_session_materials AS material
        SET refresh_state = 'revoked',refresh_claimed_at = NULL,
            refresh_claim_expires_at = NULL,
            refresh_version = CASE
              WHEN material.refresh_version < 8999999999999999
                THEN material.refresh_version + 1
              ELSE material.refresh_version END,
            updated_at = v_observed_at
        WHERE material.id = v_material.id
          AND material.refresh_state IN ('ready','claimed');
        v_expired := true;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'kind',v_kind,
    'observedAt',to_jsonb(v_observed_at),
    'expired',v_expired
  );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC access expiry'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.claim_due_oidc_maintenance_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_kind text;
  v_requested_observed_at timestamptz;
  v_observed_at timestamptz;
  v_job_id uuid;
  v_candidate_material_id uuid;
  v_candidate_family_id uuid;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_effective_tenant_id uuid;
  v_refresh_lookup record;
  v_refresh_found boolean;
  v_claim jsonb;
  v_scrub_operation uuid;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_request,ARRAY['kind','observedAt'],ARRAY['kind','observedAt'],1024
  );
  v_kind := p_request ->> 'kind';
  v_requested_observed_at := (p_request ->> 'observedAt')::timestamptz;
  IF v_kind NOT IN ('logout_retry','refresh','scrub')
     OR date_trunc('microseconds',v_requested_observed_at)
          <> v_requested_observed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_observed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC maintenance claim'
      USING ERRCODE = '22023';
  END IF;
  v_observed_at := date_trunc('microseconds',transaction_timestamp());

  -- Each claim transaction is scoped to one immutable OIDC family (or one
  -- scrub candidate). Access expiry and generic retention are separate worker
  -- autocommits, so their locks and rollback cannot couple unrelated claims.

  IF v_kind = 'logout_retry' THEN
    SELECT job.id INTO v_job_id
    FROM public.tenant_oidc_logout_retry_jobs AS job
    JOIN public.tenant_oidc_session_materials AS material
      ON material.id = job.material_id
     AND material.scrubbed_at IS NULL
    WHERE ((job.state = 'pending' AND job.not_before <= v_observed_at)
        OR (job.state = 'claimed'
          AND job.claim_expires_at <= v_observed_at))
    ORDER BY CASE WHEN job.state = 'claimed'
        THEN job.claim_expires_at ELSE job.not_before END,job.id
    LIMIT 1;
    IF FOUND THEN
      v_claim := app.claim_tenant_oidc_logout_retry_v1(
        jsonb_build_object(
          'jobId',v_job_id::text,'observedAt',to_jsonb(v_observed_at)
        )
      );
      IF v_claim IS NOT NULL THEN
        RETURN jsonb_build_object(
          'kind','logout_retry','observedAt',to_jsonb(v_observed_at)
        ) || v_claim;
      END IF;
    END IF;
    RETURN NULL;
  END IF;

  IF v_kind = 'refresh' THEN
    v_candidate_material_id := NULL;
    v_candidate_family_id := NULL;
    SELECT material.id,material.rotation_family_id
      INTO v_candidate_material_id,v_candidate_family_id
    FROM public.tenant_oidc_session_materials AS material
    JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
      AS effective ON true
    JOIN public.auth_sessions AS session
      ON session.id = effective.session_id
     AND session.user_id = material.user_id
     AND session.rotation_family_id = material.rotation_family_id
     AND session.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
    WHERE ((material.refresh_state = 'ready'
          AND material.access_expires_at <= v_observed_at + interval '5 minutes')
        OR (material.refresh_state = 'claimed'
          AND material.refresh_claim_expires_at <= v_observed_at))
      AND material.scrubbed_at IS NULL
      AND material.expires_at > v_observed_at
      AND material.access_expires_at > v_observed_at
      AND session.revoked_at IS NULL
      AND session.absolute_expires_at > v_observed_at
    ORDER BY CASE WHEN material.refresh_state = 'claimed'
        THEN material.refresh_claim_expires_at ELSE material.access_expires_at END,
      material.id
    LIMIT 1;
    IF FOUND THEN
      -- The dispatcher must never lock material before the family advisory:
      -- local logout takes advisory -> session -> material. Re-read eligibility
      -- under that same fence, then let the claim ABI take its own canonical
      -- material/session locks and CAS the generation plus digest.
      PERFORM pg_advisory_xact_lock(hashtextextended(
        v_candidate_family_id::text,90174213
      ));
      SELECT material AS material,
             effective.tenant_id AS effective_tenant_id
        INTO v_refresh_lookup
      FROM public.tenant_oidc_session_materials AS material
      JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
        AS effective ON true
      JOIN public.auth_sessions AS session
        ON session.id = effective.session_id
       AND session.user_id = material.user_id
       AND session.rotation_family_id = material.rotation_family_id
       AND session.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
      WHERE material.id = v_candidate_material_id
        AND material.rotation_family_id = v_candidate_family_id
        AND ((material.refresh_state = 'ready'
            AND material.access_expires_at <= v_observed_at + interval '5 minutes')
          OR (material.refresh_state = 'claimed'
            AND material.refresh_claim_expires_at <= v_observed_at))
        AND material.scrubbed_at IS NULL
        AND material.expires_at > v_observed_at
        AND material.access_expires_at > v_observed_at
        AND session.revoked_at IS NULL
        AND session.absolute_expires_at > v_observed_at;
      v_refresh_found := FOUND;
      IF v_refresh_found THEN
        v_material := v_refresh_lookup.material;
        v_effective_tenant_id := v_refresh_lookup.effective_tenant_id;
        PERFORM set_config(
          'app.tenant_id',coalesce(v_effective_tenant_id::text,''),true
        );
        PERFORM set_config('app.user_id',v_material.user_id::text,true);
        v_claim := app.claim_tenant_oidc_refresh_rotation_v1(
          jsonb_build_object(
            'sessionFamilyId',v_material.rotation_family_id::text,
            'expectedGeneration',v_material.refresh_generation,
            'expectedDigest',replace(encode(
              v_material.refresh_token_digest,'base64'
            ),E'\n',''),
            'claimedAt',to_jsonb(v_observed_at)
          )
        );
        IF v_claim ->> 'category' = 'claimed' THEN
          RETURN jsonb_build_object(
            'kind','refresh','observedAt',to_jsonb(v_observed_at)
          ) || v_claim;
        END IF;
      END IF;
    END IF;
    RETURN NULL;
  END IF;

  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  LEFT JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
    AS effective ON true
  LEFT JOIN public.auth_sessions AS session
    ON session.id = effective.session_id
   AND session.user_id = material.user_id
   AND session.rotation_family_id = material.rotation_family_id
  WHERE material.scrubbed_at IS NULL
    AND (material.expires_at <= v_observed_at
      OR session.revoked_at IS NOT NULL
      OR session.absolute_expires_at <= v_observed_at)
    AND NOT EXISTS (
      SELECT 1 FROM public.session_logout_continuations AS continuation
      WHERE continuation.oidc_material_id = material.id
        AND continuation.consumed_at IS NULL
        AND continuation.expires_at > v_observed_at
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.tenant_oidc_logout_retry_jobs AS job
      WHERE job.material_id = material.id
        AND job.state IN ('pending','claimed')
    )
  ORDER BY material.expires_at,material.id
  FOR UPDATE OF material SKIP LOCKED LIMIT 1;
  IF FOUND THEN
    v_scrub_operation := uuidv7();
    IF app.scrub_oidc_session_material_v1(jsonb_build_object(
      'materialId',v_material.id::text,
      'operationRunId',v_scrub_operation::text,
      'observedAt',to_jsonb(v_observed_at)
    )) THEN
      RETURN jsonb_build_object(
        'kind','scrub','materialId',v_material.id::text,
        'operationRunId',v_scrub_operation::text,
        'observedAt',to_jsonb(v_observed_at),
        'completedAt',to_jsonb(v_observed_at)
      );
    END IF;
  END IF;
  RETURN NULL;
END;
$function$;
