-- Authoritative, identifier-free maintenance liveness. Queue time and age are
-- always measured by PostgreSQL; callers cannot move due work across a clock
-- boundary. `oldestDueAt` is null exactly when the corresponding due count is
-- zero, while deadLetterCount describes only operator-visible logout DLQ rows.
CREATE FUNCTION app.get_oidc_maintenance_queue_snapshot_v1(p_request jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_observed_at timestamptz := date_trunc(
    'microseconds',transaction_timestamp()
  );
  v_logout_due bigint;
  v_logout_reclaimable bigint;
  v_logout_dead_letter bigint;
  v_logout_oldest timestamptz;
  v_refresh_due bigint;
  v_refresh_reclaimable bigint;
  v_refresh_oldest timestamptz;
  v_scrub_due bigint;
  v_scrub_oldest timestamptz;
BEGIN
  IF jsonb_typeof(p_request) IS DISTINCT FROM 'object'
     OR p_request <> '{}'::jsonb
     OR pg_column_size(p_request) > 32 THEN
    RAISE EXCEPTION 'invalid OIDC maintenance snapshot request'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*) FILTER (WHERE due),
         count(*) FILTER (WHERE reclaimable),
         count(*) FILTER (WHERE state = 'dead_letter'),
         min(due_at) FILTER (WHERE due)
    INTO v_logout_due,v_logout_reclaimable,v_logout_dead_letter,
         v_logout_oldest
  FROM (
    SELECT job.state,
      ((job.state = 'pending' AND job.not_before <= v_observed_at)
        OR (job.state = 'claimed'
          AND job.claim_expires_at <= v_observed_at)) AS due,
      (job.state = 'claimed'
        AND job.claim_expires_at <= v_observed_at) AS reclaimable,
      CASE WHEN job.state = 'claimed' THEN job.claim_expires_at
        ELSE job.not_before END AS due_at
    FROM public.tenant_oidc_logout_retry_jobs AS job
  ) AS logout_queue;

  SELECT count(*),count(*) FILTER (WHERE reclaimable),min(due_at)
    INTO v_refresh_due,v_refresh_reclaimable,v_refresh_oldest
  FROM (
    SELECT material.refresh_state = 'claimed' AS reclaimable,
      CASE WHEN material.refresh_state = 'claimed'
        THEN material.refresh_claim_expires_at
        ELSE material.access_expires_at - interval '5 minutes' END AS due_at
    FROM public.tenant_oidc_session_materials AS material
    JOIN LATERAL app.private_oidc_material_effective_session_v1(material.id)
      AS effective ON true
    JOIN public.auth_sessions AS session
      ON session.id = effective.session_id
     AND session.user_id = material.user_id
     AND session.rotation_family_id = material.rotation_family_id
     AND session.active_tenant_id IS NOT DISTINCT FROM effective.tenant_id
    WHERE ((material.refresh_state = 'ready'
          AND material.access_expires_at <= v_observed_at + interval '5 minutes')
        OR (material.refresh_state = 'claimed'
          AND material.refresh_claim_expires_at <= v_observed_at))
      AND material.scrubbed_at IS NULL
      AND material.expires_at > v_observed_at
      AND material.access_expires_at > v_observed_at
      AND session.revoked_at IS NULL
      AND session.absolute_expires_at > v_observed_at
  ) AS refresh_queue;

  SELECT count(*),min(due_at)
    INTO v_scrub_due,v_scrub_oldest
  FROM (
    SELECT least(
      material.expires_at,
      coalesce(session.revoked_at,session.absolute_expires_at,
        material.expires_at)
    ) AS due_at
    FROM public.tenant_oidc_session_materials AS material
    LEFT JOIN LATERAL app.private_oidc_material_effective_session_v1(
      material.id
    ) AS effective ON true
    LEFT JOIN public.auth_sessions AS session
      ON session.id = effective.session_id
     AND session.user_id = material.user_id
     AND session.rotation_family_id = material.rotation_family_id
    WHERE material.scrubbed_at IS NULL
      AND (material.expires_at <= v_observed_at
        OR session.revoked_at IS NOT NULL
        OR session.absolute_expires_at <= v_observed_at)
      AND NOT EXISTS (
        SELECT 1 FROM public.session_logout_continuations AS continuation
        WHERE continuation.oidc_material_id = material.id
          AND continuation.consumed_at IS NULL
          AND continuation.expires_at > v_observed_at
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.tenant_oidc_logout_retry_jobs AS job
        WHERE job.material_id = material.id
          AND job.state IN ('pending','claimed')
      )
  ) AS scrub_queue;

  IF greatest(v_logout_due,v_logout_reclaimable,v_logout_dead_letter,
       v_refresh_due,v_refresh_reclaimable,v_scrub_due) > 9000000000000000
     OR (v_logout_due = 0) IS DISTINCT FROM (v_logout_oldest IS NULL)
     OR (v_refresh_due = 0) IS DISTINCT FROM (v_refresh_oldest IS NULL)
     OR (v_scrub_due = 0) IS DISTINCT FROM (v_scrub_oldest IS NULL)
     OR v_logout_oldest > v_observed_at
     OR v_refresh_oldest > v_observed_at
     OR v_scrub_oldest > v_observed_at THEN
    RAISE EXCEPTION 'invalid OIDC maintenance queue state'
      USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object(
    'observedAt',to_jsonb(v_observed_at),
    'categories',jsonb_build_object(
      'logout_retry',jsonb_build_object(
        'dueCount',v_logout_due,
        'reclaimableCount',v_logout_reclaimable,
        'deadLetterCount',v_logout_dead_letter,
        'oldestDueAt',to_jsonb(v_logout_oldest)
      ),
      'refresh',jsonb_build_object(
        'dueCount',v_refresh_due,
        'reclaimableCount',v_refresh_reclaimable,
        'oldestDueAt',to_jsonb(v_refresh_oldest)
      ),
      'scrub',jsonb_build_object(
        'dueCount',v_scrub_due,
        'oldestDueAt',to_jsonb(v_scrub_oldest)
      )
    )
  );
END;
$function$;
--> statement-breakpoint

DO $session_logout_oidc_lifecycle_acl_v2$
DECLARE
  signature text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'app.revoke_local_session_for_logout_v1(jsonb)',
    'app.claim_session_logout_continuation_v1(jsonb)',
    'app.cleanup_session_logout_continuations_v1(jsonb)',
    'app.cleanup_federated_maintenance_retention_v1(jsonb)',
    'app.expire_oidc_access_lease_v1(jsonb)',
    'app.scrub_oidc_session_material_v1(jsonb)',
    'app.claim_due_oidc_maintenance_v1(jsonb)',
    'app.get_oidc_maintenance_queue_snapshot_v1(jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator',signature);
    EXECUTE format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier, periapsis_auditor, periapsis_audit_reader_owner, periapsis_notification_dispatch_owner, periapsis_sla_api_owner, periapsis_sla_worker_owner, periapsis_sla_readiness_owner',
      signature
    );
  END LOOP;
END;
$session_logout_oidc_lifecycle_acl_v2$;
