CREATE OR REPLACE FUNCTION app.tenant_oidc_session_lifecycle_schema_readiness_v1()
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  relation_name text;
  relation_oid regclass;
  runtime_role text;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY[
    'tenant_oidc_session_materials',
    'tenant_oidc_consumed_refresh_tokens',
    'tenant_oidc_logout_commands',
    'tenant_oidc_logout_retry_jobs',
    'session_logout_continuations'
  ] LOOP
    relation_oid := ('public.' || relation_name)::regclass;
    IF NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_class AS relation
      WHERE relation.oid = relation_oid
        AND relation.relowner = 'periapsis_migrator'::regrole
        AND relation.relrowsecurity AND relation.relforcerowsecurity
    ) OR EXISTS (
      SELECT 1 FROM pg_catalog.pg_policy AS policy
      WHERE policy.polrelid = relation_oid
    ) THEN
      RETURN false;
    END IF;
    FOREACH runtime_role IN ARRAY ARRAY[
      'periapsis_api','periapsis_worker','periapsis_notifier','periapsis_auditor'
    ] LOOP
      IF has_any_column_privilege(
           runtime_role,relation_oid,'SELECT,INSERT,UPDATE,REFERENCES'
         ) OR has_table_privilege(
           runtime_role,relation_oid,
           'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER,REFERENCES'
         ) THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;
  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_trigger AS trigger
    WHERE trigger.tgname = 'tenant_oidc_session_materials_guard_v1'
      AND trigger.tgrelid = 'public.tenant_oidc_session_materials'::regclass
      AND trigger.tgfoid = 'app.guard_oidc_session_material_v1()'::regprocedure
      AND trigger.tgenabled = 'O' AND NOT trigger.tgisinternal
  ) OR NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_trigger AS trigger
    WHERE trigger.tgname = 'tenant_oidc_logout_commands_immutable_v1'
      AND trigger.tgrelid = 'public.tenant_oidc_logout_commands'::regclass
      AND trigger.tgfoid =
        'app.guard_federated_immutable_ledger_v1()'::regprocedure
      AND trigger.tgenabled = 'O' AND NOT trigger.tgisinternal
  ) OR NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_trigger AS trigger
    WHERE trigger.tgname = 'session_logout_continuations_guard_v1'
      AND trigger.tgrelid = 'public.session_logout_continuations'::regclass
      AND trigger.tgfoid =
        'app.guard_session_logout_continuation_v1()'::regprocedure
      AND trigger.tgenabled = 'O' AND NOT trigger.tgisinternal
  ) OR EXISTS (
    SELECT 1 FROM public.tenant_oidc_session_materials AS material
    LEFT JOIN public.identity_keyring_versions AS id_key
      ON id_key.key_version = material.id_token_key_version
    LEFT JOIN public.identity_keyring_versions AS refresh_key
      ON refresh_key.key_version = material.refresh_token_key_version
    WHERE (material.id_token_key_version IS NOT NULL
        AND (id_key.key_version IS NULL OR id_key.retired_at IS NOT NULL))
       OR (material.refresh_token_key_version IS NOT NULL
        AND (refresh_key.key_version IS NULL
          OR refresh_key.retired_at IS NOT NULL))
  ) THEN
    RETURN false;
  END IF;
  RETURN has_function_privilege(
      'periapsis_api','app.resolve_session_for_logout_v1(bytea)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.revoke_local_session_for_logout_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.claim_session_logout_continuation_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.claim_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.complete_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_api','app.revoke_tenant_oidc_session_family_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.claim_tenant_oidc_logout_retry_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.complete_tenant_oidc_logout_retry_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker',
      'app.cleanup_federated_maintenance_retention_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.expire_oidc_access_lease_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.cleanup_session_logout_continuations_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.scrub_oidc_session_material_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker','app.claim_due_oidc_maintenance_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker',
      'app.get_oidc_maintenance_queue_snapshot_v1(jsonb)','EXECUTE'
    ) AND has_function_privilege(
      'periapsis_worker',
      'app.load_oidc_maintenance_client_secret_envelope_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.claim_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.complete_tenant_oidc_refresh_rotation_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.revoke_local_oidc_session_v1(uuid,jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.revoke_local_saml_session_v1(uuid,jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api',
      'app.cleanup_federated_maintenance_retention_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.expire_oidc_access_lease_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api','app.claim_due_oidc_maintenance_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api',
      'app.get_oidc_maintenance_queue_snapshot_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_api',
      'app.load_oidc_maintenance_client_secret_envelope_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_worker','app.revoke_local_session_for_logout_v1(jsonb)','EXECUTE'
    ) AND NOT has_function_privilege(
      'periapsis_worker','app.claim_session_logout_continuation_v1(jsonb)','EXECUTE'
    );
END;
$function$;
