-- F-AUD-41/F-AUD-42: keep protocol configuration and worker leases pinned to
-- the immutable login material. A claimed refresh lease is bounded and cannot
-- survive a worker crash indefinitely.
ALTER TABLE public.tenant_oidc_session_materials
  DROP CONSTRAINT tenant_oidc_session_materials_token_check,
  ADD CONSTRAINT tenant_oidc_session_materials_token_check CHECK (
    aad_version = 1
    AND refresh_version BETWEEN 1 AND 8999999999999999
    AND ((scrubbed_at IS NULL
        AND (id_token_key_version IS NULL) = (id_token_ciphertext IS NULL)
        AND (id_token_key_version IS NULL) = (id_token_digest IS NULL)
        AND (id_token_key_version IS NULL OR (
          id_token_key_version BETWEEN 1 AND 32767
          AND octet_length(id_token_ciphertext) BETWEEN 29 AND 262172
          AND octet_length(id_token_digest) = 32
          AND encode(id_token_digest,'hex') <> repeat('00',32)))
        AND ((refresh_state = 'unavailable'
            AND refresh_generation = 0 AND refresh_claimed_at IS NULL
            AND refresh_claim_expires_at IS NULL
            AND refresh_token_key_version IS NULL
            AND refresh_token_ciphertext IS NULL
            AND refresh_token_digest IS NULL AND access_expires_at IS NULL)
          OR (refresh_state IN ('ready','claimed','revoked')
            AND refresh_generation BETWEEN 1 AND 8999999999999999
            AND refresh_token_key_version BETWEEN 1 AND 32767
            AND octet_length(refresh_token_ciphertext) BETWEEN 29 AND 262172
            AND octet_length(refresh_token_digest) = 32
            AND encode(refresh_token_digest,'hex') <> repeat('00',32)
            AND access_expires_at > created_at
            AND access_expires_at <= expires_at
            AND ((refresh_state = 'ready' AND refresh_claimed_at IS NULL
                AND refresh_claim_expires_at IS NULL)
              OR (refresh_state = 'claimed'
                AND refresh_claimed_at >= created_at
                AND refresh_claim_expires_at > refresh_claimed_at
                AND refresh_claim_expires_at <= expires_at
                AND refresh_claim_expires_at
                  <= refresh_claimed_at + interval '2 minutes')
              OR (refresh_state = 'revoked' AND refresh_claimed_at IS NULL
                AND refresh_claim_expires_at IS NULL)))))
      OR (scrubbed_at >= created_at AND refresh_state = 'scrubbed'
        AND refresh_claimed_at IS NULL AND refresh_claim_expires_at IS NULL
        AND id_token_key_version IS NULL AND id_token_ciphertext IS NULL
        AND id_token_digest IS NULL
        AND refresh_token_key_version IS NULL
        AND refresh_token_ciphertext IS NULL
        AND refresh_token_digest IS NULL AND access_expires_at IS NULL))
  );
--> statement-breakpoint

-- Snapshot the already validated, exact pinned direct-platform SAML document
-- in the same atomic apply that persists encrypted logout material.
DO $platform_saml_logout_configuration_apply_v1$
DECLARE
  v_definition text;
  v_old text := $old$
    INSERT INTO public.platform_saml_session_materials (
      id,session_id,continuation_id,user_id,platform_provider_id,external_identity_id,
      login_policy_revision,session_index_digest,key_version,nonce,ciphertext,created_at
    ) VALUES (
      material_id,session_id,continuation_id,user_id,provider_id,identity_id,
      transaction_record.login_policy_revision,session_index_digest,
      (p_command#>>'{protectedSessionMaterial,keyVersion}')::integer,
      app.private_mfa_decode_base64_v1(p_command#>>'{protectedSessionMaterial,nonce}',12,12),
      app.private_mfa_decode_base64_v1(p_command#>>'{protectedSessionMaterial,ciphertext}',17,16384),
      observed_at
    );$old$;
  v_new text := $new$
    INSERT INTO public.platform_saml_session_materials (
      id,session_id,continuation_id,user_id,platform_provider_id,external_identity_id,
      login_policy_revision,session_index_digest,key_version,nonce,ciphertext,
      logout_configuration,created_at
    ) VALUES (
      material_id,session_id,continuation_id,user_id,provider_id,identity_id,
      transaction_record.login_policy_revision,session_index_digest,
      (p_command#>>'{protectedSessionMaterial,keyVersion}')::integer,
      app.private_mfa_decode_base64_v1(p_command#>>'{protectedSessionMaterial,nonce}',12,12),
      app.private_mfa_decode_base64_v1(p_command#>>'{protectedSessionMaterial,ciphertext}',17,16384),
      app.private_platform_saml_direct_configuration_v1(provider_id,authority->'pins'),
      observed_at
    );$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.apply_platform_saml_authentication_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0 THEN
    RAISE EXCEPTION 'unexpected platform SAML material predecessor definition';
  END IF;
  EXECUTE replace(v_definition,v_old,v_new);
END;
$platform_saml_logout_configuration_apply_v1$;
--> statement-breakpoint

-- Existing live rows are upgraded best-effort from their exact application
-- pins. Rows whose old live configuration is no longer resolvable remain NULL
-- and deliberately degrade to local-only logout.
DO $platform_saml_logout_configuration_backfill_v1$
BEGIN
  PERFORM set_config('app.platform_saml_direct_runtime_write_v1','on',true);
  UPDATE public.platform_saml_session_materials AS material
  SET logout_configuration =
    app.private_platform_saml_direct_configuration_v1(
      material.platform_provider_id,
      application.request_snapshot #> '{authority,pins}'
    )
  FROM public.platform_saml_authentication_applications AS application
  WHERE material.logout_configuration IS NULL
    AND application.request_snapshot #>> '{authority,materialId}' = material.id::text
    AND application.platform_provider_id = material.platform_provider_id
    AND app.private_platform_saml_direct_configuration_v1(
      material.platform_provider_id,
      application.request_snapshot #> '{authority,pins}'
    ) IS NOT NULL;
END;
$platform_saml_logout_configuration_backfill_v1$;
