CREATE FUNCTION app.guard_platform_saml_logout_configuration_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'INSERT' AND (
    NEW.logout_configuration IS NULL
    OR NEW.logout_disposition <> 'available'
    OR NEW.logout_operation_run_id IS NOT NULL
    OR NEW.logout_claimed_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'platform SAML logout configuration is unavailable'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.scrubbed_at IS NULL
     AND NEW.scrubbed_at IS NOT NULL THEN
    IF current_setting('app.saml_material_scrub_v1',true) <> 'on'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.session_id IS DISTINCT FROM OLD.session_id
       OR NEW.continuation_id IS DISTINCT FROM OLD.continuation_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.platform_provider_id IS DISTINCT FROM OLD.platform_provider_id
       OR NEW.external_identity_id IS DISTINCT FROM OLD.external_identity_id
       OR NEW.login_policy_revision IS DISTINCT FROM OLD.login_policy_revision
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.logout_disposition IS DISTINCT FROM OLD.logout_disposition
       OR NEW.logout_operation_run_id IS DISTINCT FROM OLD.logout_operation_run_id
       OR NEW.logout_claimed_at IS DISTINCT FROM OLD.logout_claimed_at
       OR NEW.key_version IS NOT NULL OR NEW.nonce IS NOT NULL
       OR NEW.ciphertext IS NOT NULL OR NEW.session_index_digest IS NOT NULL
       OR NEW.logout_configuration IS NOT NULL THEN
      RAISE EXCEPTION 'invalid platform SAML material scrub'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.scrubbed_at IS NOT NULL
     OR (OLD.logout_configuration IS NOT NULL
       AND NEW.logout_configuration IS DISTINCT FROM OLD.logout_configuration)) THEN
    RAISE EXCEPTION 'platform SAML logout configuration is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND (
       NEW.logout_disposition IS DISTINCT FROM OLD.logout_disposition
       OR NEW.logout_operation_run_id IS DISTINCT FROM OLD.logout_operation_run_id
       OR NEW.logout_claimed_at IS DISTINCT FROM OLD.logout_claimed_at
     ) THEN
    IF current_setting('app.saml_logout_claim_v1',true) <> 'on'
       OR OLD.logout_disposition <> 'available'
       OR OLD.logout_operation_run_id IS NOT NULL
       OR OLD.logout_claimed_at IS NOT NULL
       OR NEW.logout_disposition NOT IN ('claimed','skipped')
       OR (uuid_extract_version(NEW.logout_operation_run_id) = 7) IS NOT TRUE
       OR NEW.logout_operation_run_id = NEW.id
       OR NEW.logout_claimed_at < NEW.created_at
       OR date_trunc('microseconds',NEW.logout_claimed_at)
            <> NEW.logout_claimed_at THEN
      RAISE EXCEPTION 'invalid platform SAML logout material claim'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.guard_platform_saml_logout_configuration_v1()
  OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.guard_platform_saml_logout_configuration_v1()
  FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
       periapsis_auditor;
--> statement-breakpoint
CREATE TRIGGER platform_saml_session_materials_logout_configuration_guard_v1
BEFORE INSERT OR UPDATE ON public.platform_saml_session_materials
FOR EACH ROW EXECUTE FUNCTION app.guard_platform_saml_logout_configuration_v1();
--> statement-breakpoint

-- Carry the one immutable OIDC material row across tenant-platform and direct
-- platform rotation, step-up, and MFA-promotion owner changes.
DO $tenant_platform_oidc_rotation_owner_v1$
DECLARE
  v_definition text;
  v_old text := $old$
    WHERE provenance.tenant_id = tenant_id AND provenance.session_id = session_id;
    INSERT INTO public.auth_session_mfa_policy_pins$old$;
  v_new text := $new$
    WHERE provenance.tenant_id = tenant_id AND provenance.session_id = session_id;
    IF session_record.authentication_method = 'oidc' THEN
      UPDATE public.tenant_oidc_session_materials AS material
      SET session_id = (p_mutation #>> '{session,sessionId}')::uuid,
          updated_at = observed_at
      WHERE material.authority = 'tenant_platform_provider'
        AND material.tenant_id = (p_mutation ->> 'tenantId')::uuid
        AND material.session_id = (p_mutation ->> 'sessionId')::uuid
        AND material.user_id = (p_mutation ->> 'userId')::uuid;
      IF NOT FOUND AND NOT EXISTS (
        SELECT 1
        FROM public.tenant_oidc_session_materials AS origin
        JOIN LATERAL app.private_oidc_material_effective_session_v1(origin.id)
          AS effective ON true
        WHERE origin.authority = 'platform_provider'
          AND origin.tenant_id IS NULL AND origin.binding_id IS NULL
          AND origin.user_id = (p_mutation ->> 'userId')::uuid
          AND effective.session_id = (p_mutation ->> 'sessionId')::uuid
          AND effective.tenant_id = (p_mutation ->> 'tenantId')::uuid
      ) THEN
        RAISE EXCEPTION 'tenant-platform OIDC material ownership is stale'
          USING ERRCODE = '40001';
      END IF;
    END IF;
    INSERT INTO public.auth_session_mfa_policy_pins$new$;
BEGIN
  SELECT pg_get_functiondef(
    'app.apply_tenant_platform_federated_session_revalidation_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,v_old) = 0 THEN
    RAISE EXCEPTION 'unexpected tenant-platform OIDC rotation predecessor';
  END IF;
  EXECUTE replace(v_definition,v_old,v_new);
END;
$tenant_platform_oidc_rotation_owner_v1$;
