DO $tenant_platform_oidc_step_up_owner_v1$
DECLARE
  v_definition text;
  v_old text := $old$
      session_id,session_record.rotation_family_id,expected_version + 1,
      session_record.absolute_expires_at
    );
  ELSIF decision IN ('revoke','deny') THEN$old$;
  v_new text := $new$
      session_id,session_record.rotation_family_id,expected_version + 1,
      session_record.absolute_expires_at
    );
    IF session_record.authentication_method = 'oidc' THEN
      UPDATE public.tenant_oidc_session_materials AS material
      SET session_id = NULL,
          continuation_id = (p_mutation #>> '{continuation,continuationId}')::uuid,
          rotation_family_id = NULL,
          expires_at = least(material.expires_at,continuation_expires_at),
          access_expires_at = CASE WHEN material.access_expires_at IS NULL THEN NULL
            ELSE least(material.access_expires_at,continuation_expires_at) END,
          updated_at = observed_at
      WHERE material.authority = 'tenant_platform_provider'
        AND material.tenant_id = (p_mutation ->> 'tenantId')::uuid
        AND material.session_id = (p_mutation ->> 'sessionId')::uuid
        AND material.user_id = (p_mutation ->> 'userId')::uuid;
      IF NOT FOUND AND NOT EXISTS (
        SELECT 1
        FROM public.tenant_oidc_session_materials AS origin
        JOIN LATERAL app.private_oidc_material_effective_session_v1(origin.id)
          AS effective ON true
        WHERE origin.authority = 'platform_provider'
          AND origin.tenant_id IS NULL AND origin.binding_id IS NULL
          AND origin.user_id = (p_mutation ->> 'userId')::uuid
          AND effective.session_id = (p_mutation ->> 'sessionId')::uuid
          AND effective.tenant_id = (p_mutation ->> 'tenantId')::uuid
      ) THEN
        RAISE EXCEPTION 'tenant-platform OIDC material ownership is stale'
          USING ERRCODE = '40001';
