-- OIDC material is intentionally absent when the completed authentication
-- transaction neither admitted refresh tokens nor pinned an end-session
-- endpoint.  Owner changes must prove that fact from the immutable
-- application/transaction/discovery lineage; provider/user heuristics are not
-- sufficient because two otherwise identical logins may pin different token
-- or logout requirements.
CREATE FUNCTION app.private_tenant_provider_oidc_material_absence_attested_v1(
  p_tenant_id uuid,p_session_id uuid,p_continuation_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  WITH RECURSIVE session_node AS NOT MATERIALIZED (
    SELECT session.id,session.user_id,session.rotation_family_id,
           session.rotated_from_session_id,session.created_at,
           session.absolute_expires_at,state.session_version,
           provenance.authenticated_at,
           provenance.provider_id,provenance.binding_id,
           provenance.external_identity_id,
           provenance.external_identity_revision,provenance.trust_rule_revision,
           jsonb_build_array(provenance.provider_id,provenance.binding_id,
             provenance.external_identity_id,
             provenance.external_identity_revision,
             provenance.trust_rule_revision) AS coordinates,
           coalesce((
             SELECT jsonb_agg(
               to_jsonb(evidence)-ARRAY['id','tenant_id','session_id']::text[]
               ORDER BY (to_jsonb(evidence)-
                 ARRAY['id','tenant_id','session_id']::text[])::text COLLATE "C"
             )
             FROM ONLY public.auth_session_mfa_evidence AS evidence
             WHERE evidence.tenant_id = p_tenant_id
               AND evidence.session_id = session.id
               AND evidence.provider_id IS NOT NULL
           ),'[]'::jsonb) AS provider_evidence
    FROM ONLY public.auth_sessions AS session
    JOIN ONLY public.auth_session_mfa_states AS state
      ON state.tenant_id = p_tenant_id AND state.session_id = session.id
     AND state.user_id = session.user_id AND state.primary_kind = 'tenant_provider'
    JOIN ONLY public.auth_session_federated_provenance AS provenance
      ON provenance.tenant_id = p_tenant_id AND provenance.session_id = session.id
     AND provenance.user_id = session.user_id
     AND provenance.primary_kind = 'tenant_provider'
     AND provenance.authentication_method = 'oidc'
     AND provenance.provider_kind = 'oidc'
    WHERE session.active_tenant_id = p_tenant_id
      AND session.authentication_method = 'oidc'
  ), continuation_node AS NOT MATERIALIZED (
    SELECT continuation.id,continuation.created_at,
           continuation.consumed_at,provenance.*,
           jsonb_build_array(provenance.provider_id,provenance.binding_id,
             provenance.external_identity_id,
             provenance.external_identity_revision,
             provenance.security_revision) AS coordinates,
           coalesce((
             SELECT jsonb_agg(
               to_jsonb(evidence)-ARRAY['id','tenant_id','continuation_id']::text[]
               ORDER BY (to_jsonb(evidence)-
                 ARRAY['id','tenant_id','continuation_id']::text[])::text COLLATE "C"
             )
             FROM ONLY public.tenant_post_primary_continuation_evidence AS evidence
             WHERE evidence.tenant_id = p_tenant_id
               AND evidence.continuation_id = continuation.id
               AND evidence.provider_id IS NOT NULL
           ),'[]'::jsonb) AS provider_evidence
    FROM ONLY public.tenant_post_primary_continuations AS continuation
    JOIN ONLY public.tenant_post_primary_federated_provenance AS provenance
      ON provenance.tenant_id = continuation.tenant_id
     AND provenance.continuation_id = continuation.id
     AND provenance.user_id = continuation.user_id
     AND provenance.primary_kind = 'tenant_provider'
     AND provenance.authentication_method = 'oidc'
     AND provenance.provider_kind = 'oidc'
     AND provenance.provider_id = continuation.provider_id
     AND provenance.binding_id = continuation.binding_id
     AND provenance.external_identity_id = continuation.external_identity_id
     AND provenance.external_identity_revision = continuation.primary_revision
    WHERE continuation.tenant_id = p_tenant_id
      AND continuation.primary_kind = 'tenant_provider'
      AND continuation.provider_kind = 'oidc'
      AND continuation.state = 'consumed' AND continuation.version = 2
      AND continuation.consumed_at >= continuation.created_at
      AND continuation.consumed_at < continuation.expires_at
  ), session_edge AS NOT MATERIALIZED (
    SELECT successor.id AS child_id,source.id AS parent_id
    FROM session_node AS successor
    JOIN session_node AS source ON source.id = successor.rotated_from_session_id
     AND source.user_id = successor.user_id
     AND source.rotation_family_id = successor.rotation_family_id
     AND source.absolute_expires_at = successor.absolute_expires_at
     AND source.created_at <= successor.created_at
     AND source.coordinates = successor.coordinates
     AND source.authenticated_at = successor.authenticated_at
     AND source.provider_evidence = successor.provider_evidence
    UNION ALL
    SELECT successor.id,source.id
    FROM session_node AS successor
    JOIN continuation_node AS continuation
      ON successor.rotated_from_session_id IS NULL
     AND continuation.origin = 'session_revalidation'
     AND continuation.consumed_at = successor.created_at
     AND continuation.user_id = successor.user_id
     AND continuation.coordinates = successor.coordinates
     AND continuation.source_session_family_id = successor.rotation_family_id
     AND continuation.source_absolute_expires_at = successor.absolute_expires_at
     AND continuation.created_at = successor.authenticated_at
     AND continuation.provider_evidence = successor.provider_evidence
    JOIN session_node AS source ON source.id = continuation.source_session_id
     AND source.user_id = continuation.user_id
     AND source.rotation_family_id = continuation.source_session_family_id
     AND source.absolute_expires_at = continuation.source_absolute_expires_at
     AND source.session_version = continuation.source_session_version
     AND source.coordinates = continuation.coordinates
     AND source.authenticated_at = continuation.authenticated_at
     AND source.provider_evidence = continuation.provider_evidence
  ), starting_session AS MATERIALIZED (
    SELECT session.* FROM session_node AS session
    WHERE p_session_id IS NOT NULL AND p_continuation_id IS NULL
      AND session.id = p_session_id
    UNION ALL
    SELECT session.* FROM continuation_node AS continuation
    JOIN session_node AS session ON session.id = continuation.source_session_id
     AND session.user_id = continuation.user_id
     AND session.rotation_family_id = continuation.source_session_family_id
     AND session.absolute_expires_at = continuation.source_absolute_expires_at
     AND session.session_version = continuation.source_session_version
     AND session.coordinates = continuation.coordinates
     AND session.authenticated_at = continuation.authenticated_at
     AND session.provider_evidence = continuation.provider_evidence
    WHERE p_session_id IS NULL AND p_continuation_id = continuation.id
      AND continuation.origin = 'session_revalidation'
  ), ancestry(id,depth,path) AS (
    SELECT id,0,ARRAY[id] FROM starting_session
    UNION ALL
    SELECT edge.parent_id,ancestry.depth+1,ancestry.path || edge.parent_id
    FROM ancestry
    JOIN session_edge AS edge ON edge.child_id = ancestry.id
    WHERE ancestry.depth < 1024 AND NOT edge.parent_id = ANY(ancestry.path)
      AND (SELECT count(*) FROM session_edge AS candidate
           WHERE candidate.child_id = ancestry.id) = 1
  ), initial_owner AS MATERIALIZED (
    SELECT application.*,root.provider_evidence,
           root.external_identity_id,root.external_identity_revision,
           root.trust_rule_revision AS security_revision,
           NULL::uuid AS initial_continuation_id
    FROM ancestry
    JOIN session_node AS root ON root.id = ancestry.id
    JOIN ONLY public.tenant_federated_authentication_applications AS application
      ON application.tenant_id = p_tenant_id AND application.session_id = root.id
     AND application.continuation_id IS NULL AND application.user_id = root.user_id
     AND application.provider_id = root.provider_id
     AND application.binding_id = root.binding_id
     AND application.applied_at = root.created_at
    WHERE root.rotated_from_session_id IS NULL
    UNION ALL
    SELECT application.*,root.provider_evidence,
           root.external_identity_id,root.external_identity_revision,
           root.trust_rule_revision,continuation.id
    FROM ancestry
    JOIN session_node AS root ON root.id = ancestry.id
    JOIN continuation_node AS continuation
      ON root.rotated_from_session_id IS NULL
     AND continuation.origin = 'initial_login'
     AND continuation.user_id = root.user_id
     AND continuation.coordinates = root.coordinates
     AND continuation.consumed_at = root.created_at
     AND continuation.created_at = root.authenticated_at
    JOIN ONLY public.tenant_federated_authentication_applications AS application
      ON application.tenant_id = p_tenant_id
     AND application.session_id IS NULL
     AND application.continuation_id = continuation.id
     AND application.user_id = continuation.user_id
     AND application.provider_id = continuation.provider_id
     AND application.binding_id = continuation.binding_id
     AND application.applied_at = continuation.created_at
    UNION ALL
    SELECT application.*,continuation.provider_evidence,
           continuation.external_identity_id,continuation.external_identity_revision,
           continuation.security_revision,continuation.id
    FROM continuation_node AS continuation
    JOIN ONLY public.tenant_federated_authentication_applications AS application
      ON application.tenant_id = p_tenant_id AND application.session_id IS NULL
     AND application.continuation_id = continuation.id
     AND application.user_id = continuation.user_id
     AND application.provider_id = continuation.provider_id
     AND application.binding_id = continuation.binding_id
     AND application.applied_at = continuation.created_at
    WHERE p_session_id IS NULL AND p_continuation_id = continuation.id
      AND continuation.origin = 'initial_login'
  ), attested AS MATERIALIZED (
    SELECT NOT transaction.allow_refresh_token AND nullif(
      convert_from(discovery.document,'UTF8')::jsonb ->> 'end_session_endpoint',''
    ) IS NULL AS material_optional
    FROM initial_owner AS owner
    LEFT JOIN continuation_node AS origin
      ON origin.id = owner.initial_continuation_id
    LEFT JOIN session_node AS initial_session
      ON initial_session.id = owner.session_id
    JOIN ONLY public.tenant_federated_authentication_transactions AS transaction
      ON transaction.tenant_id = owner.tenant_id
     AND transaction.protocol = 'oidc' AND transaction.provider_kind = 'oidc'
     AND transaction.transaction_id = owner.transaction_id
     AND transaction.provider_id = owner.provider_id
     AND transaction.binding_id = owner.binding_id
     AND transaction.state = 'completed' AND transaction.completed_at = owner.applied_at
     AND transaction.transaction_id = decode(
       owner.request_snapshot #>> '{authentication,oidc,transactionId}','base64'
     )
    JOIN ONLY public.tenant_oidc_discovery_snapshots AS discovery
      ON discovery.tenant_id = transaction.tenant_id
     AND discovery.provider_id = transaction.provider_id
     AND discovery.revision = transaction.discovery_revision
     AND discovery.document_digest = transaction.discovery_digest
    WHERE owner.category = 'success' AND owner.primary_kind = 'tenant_provider'
      AND owner.protocol = 'oidc' AND owner.provider_kind = 'oidc'
      AND (owner.initial_continuation_id IS NOT NULL OR
        initial_session.authenticated_at =
          (owner.request_snapshot #>> '{authentication,authenticatedAt}')::timestamptz)
      AND owner.external_identity_id =
        (owner.request_snapshot #>> '{plan,subject,externalIdentityId}')::uuid
      AND owner.external_identity_revision >= 1
      AND owner.request_snapshot #>> '{authentication,protocol}' = 'oidc'
      AND owner.request_snapshot #>> '{authentication,method}' = 'oidc'
      AND (owner.request_snapshot #>> '{authentication,tenantId}')::uuid = p_tenant_id
      AND owner.request_snapshot #>> '{authentication,oidc,pins,provider,scope}' = 'tenant'
      AND (owner.request_snapshot #>> '{authentication,oidc,pins,provider,tenantId}')::uuid = p_tenant_id
      AND (owner.request_snapshot #>> '{authentication,oidc,pins,provider,providerId}')::uuid = owner.provider_id
      AND (owner.request_snapshot #>> '{authentication,oidc,pins,provider,bindingId}')::uuid = owner.binding_id
      AND (owner.request_snapshot #>> '{plan,securityRevision}')::bigint = owner.security_revision
      AND (owner.initial_continuation_id IS NULL OR (
        origin.origin = 'initial_login'
        AND origin.authenticated_at =
          (owner.request_snapshot #>> '{authentication,authenticatedAt}')::timestamptz
        AND ROW(origin.provider_revision,origin.binding_revision,
          origin.configuration_revision,origin.security_revision,
          origin.mapping_revision,origin.authorization_revision,
          origin.assurance_policy_revision,origin.plan_revision)
          IS NOT DISTINCT FROM ROW(
          transaction.provider_revision,transaction.binding_revision,
          transaction.configuration_revision,transaction.security_revision,
          transaction.mapping_revision,transaction.authorization_revision,
          transaction.assurance_policy_revision,transaction.plan_revision)
      ))
      AND ROW(transaction.provider_revision,transaction.binding_revision,
        transaction.configuration_revision,transaction.security_revision,
        transaction.mapping_revision,transaction.authorization_revision,
        transaction.assurance_policy_revision,transaction.plan_revision,
        transaction.client_secret_revision,transaction.discovery_revision,
        transaction.jwks_revision)
        IS NOT DISTINCT FROM ROW(
        (owner.request_snapshot #>> '{plan,providerRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,bindingRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,configurationRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,securityRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,mappingRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,authorizationRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,policyRevision}')::bigint,
        (owner.request_snapshot #>> '{plan,planRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,clientSecretRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,discoveryRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,jwksRevision}')::bigint)
      AND ROW(transaction.provider_revision,transaction.binding_revision,
        transaction.configuration_revision,transaction.security_revision,
        transaction.mapping_revision,transaction.authorization_revision,
        transaction.assurance_policy_revision)
        IS NOT DISTINCT FROM ROW(
        (owner.request_snapshot #>> '{authentication,oidc,pins,providerRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,bindingRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,configurationRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,securityRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,mappingRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,authorizationRevision}')::bigint,
        (owner.request_snapshot #>> '{authentication,oidc,pins,assurancePolicyRevision}')::bigint)
      AND transaction.discovery_digest = decode(
        owner.request_snapshot #>> '{authentication,oidc,pins,discoveryDigest}','base64'
      )
      AND transaction.jwks_digest = decode(
        owner.request_snapshot #>> '{authentication,oidc,pins,jwksDigest}','base64'
      )
      AND jsonb_array_length(owner.provider_evidence) BETWEEN 1 AND 64
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(owner.request_snapshot #> '{authentication,evidence}') AS evidence(value)
        WHERE evidence.value -> 'local' IS DISTINCT FROM 'false'::jsonb
          OR evidence.value ->> 'kind' IS DISTINCT FROM 'factor'
          OR (evidence.value ->> 'providerId')::uuid IS DISTINCT FROM owner.provider_id
          OR (evidence.value ->> 'bindingId')::uuid IS DISTINCT FROM owner.binding_id
      )
      AND owner.provider_evidence = (
        SELECT jsonb_agg(proof.value ORDER BY proof.value::text COLLATE "C")
        FROM jsonb_array_elements(owner.request_snapshot #> '{authentication,evidence}') AS evidence(value)
        CROSS JOIN LATERAL (
          SELECT jsonb_build_object(
            'local_credential_id',NULL,'totp_factor_id',NULL,
            'webauthn_credential_id',NULL,'recovery_code_set_id',NULL,
            'level',evidence.value ->> 'level','kind','provider',
            'provider_id',(evidence.value ->> 'providerId')::uuid,
            'binding_id',(evidence.value ->> 'bindingId')::uuid,
            'authenticated_at',(evidence.value ->> 'authenticatedAt')::timestamptz,
            'expires_at',(evidence.value ->> 'expiresAt')::timestamptz,
            'factor_revision',(evidence.value ->> 'factorRevision')::bigint,
            'trust_rule_revision',(evidence.value ->> 'trustRuleRevision')::bigint
          ) AS value
        ) AS proof
        WHERE evidence.value -> 'local' = 'false'::jsonb
          AND (evidence.value ->> 'providerId')::uuid = owner.provider_id
          AND (evidence.value ->> 'bindingId')::uuid = owner.binding_id
      )
  )
  SELECT (p_session_id IS NULL) <> (p_continuation_id IS NULL)
    AND coalesce((SELECT count(*) = 1 AND bool_and(material_optional) FROM attested),false);
$function$;
