CREATE FUNCTION app.private_direct_platform_oidc_material_absence_attested_v1(
  p_session_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  WITH RECURSIVE current_session AS MATERIALIZED (
    SELECT session.id,session.user_id,session.rotation_family_id,
           session.rotated_from_session_id
    FROM ONLY public.auth_sessions AS session
    WHERE session.id = p_session_id
      AND session.active_tenant_id IS NULL
      AND session.authentication_method = 'oidc'
  ), ancestry (
    session_id,user_id,rotation_family_id,rotated_from_session_id,depth,path
  ) AS (
    SELECT session.id,session.user_id,session.rotation_family_id,
           session.rotated_from_session_id,0,ARRAY[session.id]
    FROM current_session AS session
    UNION ALL
    SELECT parent.id,parent.user_id,parent.rotation_family_id,
           parent.rotated_from_session_id,ancestry.depth + 1,
           ancestry.path || parent.id
    FROM ancestry
    JOIN ONLY public.auth_sessions AS parent
      ON parent.id = ancestry.rotated_from_session_id
    JOIN current_session AS current ON true
    WHERE parent.user_id = current.user_id
      AND parent.rotation_family_id = current.rotation_family_id
      AND parent.active_tenant_id IS NULL
      AND parent.authentication_method = 'oidc'
      AND ancestry.depth < 1024
      AND NOT parent.id = ANY(ancestry.path)
  ), family_root AS MATERIALIZED (
    SELECT root.id AS session_id,root.created_at
    FROM ancestry
    JOIN ONLY public.auth_sessions AS root
      ON root.id = ancestry.session_id
    WHERE ancestry.rotated_from_session_id IS NULL
  ), current_provenance AS MATERIALIZED (
    SELECT provenance.*
    FROM current_session AS session
    JOIN ONLY public.auth_session_platform_oidc_provenance AS provenance
      ON provenance.session_id = session.id
     AND provenance.user_id = session.user_id
     AND provenance.primary_kind = 'platform_provider'
  ), session_lineage AS MATERIALIZED (
    SELECT application.transaction_id,application.applied_at,
           current_provenance.*
    FROM current_session
    JOIN current_provenance ON true
    JOIN ancestry ON true
    JOIN ONLY public.auth_sessions AS origin_session
      ON origin_session.id = ancestry.session_id
    JOIN ONLY public.platform_oidc_authentication_applications AS application
      ON application.session_id = origin_session.id
     AND application.continuation_id IS NULL
     AND application.category = 'success'
     AND application.primary_kind = 'platform_provider'
     AND application.user_id = current_provenance.user_id
     AND application.platform_provider_id =
       current_provenance.platform_provider_id
     AND application.external_identity_id =
       current_provenance.external_identity_id
     AND application.applied_at = origin_session.created_at
    JOIN ONLY public.auth_session_platform_oidc_provenance AS origin_provenance
      ON origin_provenance.session_id = origin_session.id
     AND origin_provenance.user_id = current_provenance.user_id
     AND origin_provenance.primary_kind = 'platform_provider'
    WHERE ROW(origin_provenance.user_id,origin_provenance.primary_kind,
      origin_provenance.platform_provider_id,
      origin_provenance.external_identity_id,
      origin_provenance.provider_revision,
      origin_provenance.login_policy_revision,
      origin_provenance.security_revision,
      origin_provenance.user_authentication_revision,
      origin_provenance.identity_version,origin_provenance.alias_key_version,
      origin_provenance.assurance_policy_revision,
      origin_provenance.platform_floor_policy_id,
      origin_provenance.platform_floor_policy_revision,
      origin_provenance.trust_rule_id,origin_provenance.trust_rule_revision,
      origin_provenance.authenticated_at)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,current_provenance.primary_kind,
      current_provenance.platform_provider_id,
      current_provenance.external_identity_id,
      current_provenance.provider_revision,
      current_provenance.login_policy_revision,
      current_provenance.security_revision,
      current_provenance.user_authentication_revision,
      current_provenance.identity_version,current_provenance.alias_key_version,
      current_provenance.assurance_policy_revision,
      current_provenance.platform_floor_policy_id,
      current_provenance.platform_floor_policy_revision,
      current_provenance.trust_rule_id,current_provenance.trust_rule_revision,
      current_provenance.authenticated_at)
      AND (
        SELECT count(*) = 1
        FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
        WHERE evidence.session_id = current_session.id
          AND evidence.kind = 'platform_provider'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM (
          (SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = origin_session.id
             AND evidence.kind = 'platform_provider'
           EXCEPT ALL
           SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = current_session.id
             AND evidence.kind = 'platform_provider')
          UNION ALL
          (SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = current_session.id
             AND evidence.kind = 'platform_provider'
           EXCEPT ALL
           SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = origin_session.id
             AND evidence.kind = 'platform_provider')
        ) AS evidence_difference
      )
  ), continuation_lineage AS MATERIALIZED (
    SELECT application.transaction_id,application.applied_at,
           current_provenance.*
    FROM current_session
    JOIN current_provenance ON true
    JOIN family_root ON true
    JOIN ONLY public.platform_oidc_authentication_applications AS application
      ON application.session_id IS NULL
     AND application.continuation_id IS NOT NULL
     AND application.category = 'success'
     AND application.primary_kind = 'platform_provider'
     AND application.user_id = current_provenance.user_id
     AND application.platform_provider_id =
       current_provenance.platform_provider_id
     AND application.external_identity_id =
       current_provenance.external_identity_id
    JOIN ONLY public.platform_post_primary_continuations AS continuation
      ON continuation.id = application.continuation_id
     AND continuation.user_id = application.user_id
     AND continuation.platform_provider_id = application.platform_provider_id
     AND continuation.external_identity_id = application.external_identity_id
     AND continuation.origin = 'initial_login'
     AND continuation.action = 'session.create'
     AND continuation.state = 'consumed'
     AND continuation.version = 2
     AND continuation.consumed_at = family_root.created_at
     AND continuation.created_at = application.applied_at
    WHERE ROW(continuation.user_id,continuation.platform_provider_id,
      continuation.external_identity_id,continuation.provider_revision,
      continuation.login_policy_revision,continuation.security_revision,
      continuation.user_authentication_revision,continuation.identity_version,
      continuation.alias_key_version,continuation.assurance_policy_revision,
      continuation.platform_floor_policy_id,
      continuation.platform_floor_policy_revision,continuation.trust_rule_id,
      continuation.trust_rule_revision)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,
      current_provenance.platform_provider_id,
      current_provenance.external_identity_id,
      current_provenance.provider_revision,
      current_provenance.login_policy_revision,
      current_provenance.security_revision,
      current_provenance.user_authentication_revision,
      current_provenance.identity_version,current_provenance.alias_key_version,
      current_provenance.assurance_policy_revision,
      current_provenance.platform_floor_policy_id,
      current_provenance.platform_floor_policy_revision,
      current_provenance.trust_rule_id,current_provenance.trust_rule_revision)
      AND (
        SELECT count(*) = 1
        FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
        WHERE evidence.session_id = current_session.id
          AND evidence.kind = 'platform_provider'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM (
          (SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.platform_post_primary_continuation_evidence AS evidence
           WHERE evidence.continuation_id = continuation.id
             AND evidence.kind = 'platform_provider'
           EXCEPT ALL
           SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = current_session.id
             AND evidence.kind = 'platform_provider')
          UNION ALL
          (SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = current_session.id
             AND evidence.kind = 'platform_provider'
           EXCEPT ALL
           SELECT evidence.user_id,evidence.kind,evidence.level,
                  evidence.platform_provider_id,evidence.external_identity_id,
                  evidence.totp_credential_id,evidence.factor_revision,
                  evidence.trust_rule_id,evidence.trust_rule_revision,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.platform_post_primary_continuation_evidence AS evidence
           WHERE evidence.continuation_id = continuation.id
             AND evidence.kind = 'platform_provider')
        ) AS evidence_difference
      )
  ), lineage AS MATERIALIZED (
    SELECT * FROM session_lineage
    UNION ALL
    SELECT * FROM continuation_lineage
  ), candidates AS MATERIALIZED (
    SELECT transaction.allow_refresh_token OR nullif(
             convert_from(discovery.document,'UTF8')::jsonb
               ->> 'end_session_endpoint',''
           ) IS NOT NULL AS material_required
    FROM lineage
    JOIN ONLY public.platform_oidc_authentication_transactions AS transaction
      ON transaction.transaction_id = lineage.transaction_id
     AND transaction.platform_provider_id = lineage.platform_provider_id
     AND transaction.provider_kind = 'oidc'
     AND transaction.protocol = 'oidc'
     AND transaction.state = 'completed'
     AND transaction.completed_at = lineage.applied_at
     AND transaction.provider_revision = lineage.provider_revision
     AND transaction.login_policy_revision = lineage.login_policy_revision
     AND transaction.security_revision = lineage.security_revision
     AND transaction.assurance_policy_revision =
       lineage.assurance_policy_revision
     AND transaction.platform_floor_policy_id =
       lineage.platform_floor_policy_id
     AND transaction.platform_floor_policy_revision =
       lineage.platform_floor_policy_revision
    JOIN ONLY public.platform_oidc_discovery_snapshots AS discovery
      ON discovery.provider_id = transaction.platform_provider_id
     AND discovery.revision = transaction.discovery_revision
     AND discovery.document_digest = transaction.discovery_digest
  )
  SELECT coalesce((
    SELECT count(*) >= 1 AND bool_and(NOT candidates.material_required)
    FROM candidates
  ),false)
  AND EXISTS (
    SELECT 1 FROM family_root
  );
$function$;
