CREATE FUNCTION app.private_tenant_platform_oidc_material_absence_attested_v1(
  p_tenant_id uuid,
  p_session_id uuid,
  p_initial_continuation_id uuid
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
  WITH RECURSIVE current_session AS MATERIALIZED (
    SELECT session.id,session.user_id,session.rotation_family_id,
           session.rotated_from_session_id
    FROM ONLY public.auth_sessions AS session
    WHERE p_initial_continuation_id IS NULL
      AND session.id = p_session_id
      AND session.active_tenant_id = p_tenant_id
      AND session.authentication_method = 'oidc'
  ), ancestry (
    session_id,user_id,rotation_family_id,rotated_from_session_id,depth,path
  ) AS (
    SELECT session.id,session.user_id,session.rotation_family_id,
           session.rotated_from_session_id,0,ARRAY[session.id]
    FROM current_session AS session
    UNION ALL
    SELECT parent.id,parent.user_id,parent.rotation_family_id,
           parent.rotated_from_session_id,ancestry.depth + 1,
           ancestry.path || parent.id
    FROM ancestry
    JOIN ONLY public.auth_sessions AS parent
      ON parent.id = ancestry.rotated_from_session_id
    JOIN current_session AS current ON true
    WHERE parent.user_id = current.user_id
      AND parent.rotation_family_id = current.rotation_family_id
      AND parent.active_tenant_id = p_tenant_id
      AND parent.authentication_method = 'oidc'
      AND ancestry.depth < 1024
      AND NOT parent.id = ANY(ancestry.path)
  ), family_root AS MATERIALIZED (
    SELECT root.id AS session_id,root.created_at
    FROM ancestry
    JOIN ONLY public.auth_sessions AS root
      ON root.id = ancestry.session_id
    WHERE ancestry.rotated_from_session_id IS NULL
  ), current_provenance AS MATERIALIZED (
    SELECT provenance.*
    FROM current_session AS session
    JOIN ONLY public.auth_session_tenant_platform_federated_provenance
      AS provenance
      ON provenance.tenant_id = p_tenant_id
     AND provenance.session_id = session.id
     AND provenance.user_id = session.user_id
     AND provenance.primary_kind = 'tenant_platform_provider'
     AND provenance.authentication_method = 'oidc'
  ), session_application_lineage AS MATERIALIZED (
    SELECT application.transaction_id,application.applied_at,
           current_provenance.tenant_id,current_provenance.user_id,
           current_provenance.platform_provider_id,
           current_provenance.binding_id,current_provenance.access_epoch_id,
           current_provenance.access_source_id,
           current_provenance.access_grant_id,current_provenance.membership_id,
           current_provenance.external_identity_id,
           current_provenance.external_identity_revision,
           current_provenance.provider_revision,
           current_provenance.binding_revision,
           current_provenance.security_revision,
           current_provenance.mapping_revision,
           current_provenance.authorization_revision,
           current_provenance.subject_alias_key_version,
           current_provenance.trust_rule_revision,
           current_provenance.authenticated_at
    FROM current_session
    JOIN current_provenance ON true
    JOIN ancestry ON true
    JOIN ONLY public.auth_sessions AS origin_session
      ON origin_session.id = ancestry.session_id
    JOIN ONLY public.tenant_platform_oidc_authentication_applications
      AS application
      ON application.tenant_id = p_tenant_id
     AND application.session_id = origin_session.id
     AND application.continuation_id IS NULL
     AND application.category = 'success'
     AND application.primary_kind = 'tenant_platform_provider'
     AND application.user_id = current_provenance.user_id
     AND application.platform_provider_id =
       current_provenance.platform_provider_id
     AND application.binding_id = current_provenance.binding_id
     AND application.external_identity_id =
       current_provenance.external_identity_id
     AND application.applied_at = origin_session.created_at
    JOIN ONLY public.auth_session_tenant_platform_federated_provenance
      AS origin_provenance
      ON origin_provenance.tenant_id = p_tenant_id
     AND origin_provenance.session_id = origin_session.id
     AND origin_provenance.user_id = current_provenance.user_id
    WHERE ROW(origin_provenance.user_id,origin_provenance.primary_kind,
      origin_provenance.authentication_method,
      origin_provenance.platform_provider_id,origin_provenance.binding_id,
      origin_provenance.access_epoch_id,origin_provenance.access_source_id,
      origin_provenance.access_grant_id,origin_provenance.membership_id,
      origin_provenance.external_identity_id,
      origin_provenance.external_identity_revision,
      origin_provenance.provider_revision,origin_provenance.binding_revision,
      origin_provenance.security_revision,origin_provenance.mapping_revision,
      origin_provenance.authorization_revision,
      origin_provenance.subject_alias_key_version,
      origin_provenance.trust_rule_revision,
      origin_provenance.authenticated_at)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,current_provenance.primary_kind,
      current_provenance.authentication_method,
      current_provenance.platform_provider_id,current_provenance.binding_id,
      current_provenance.access_epoch_id,current_provenance.access_source_id,
      current_provenance.access_grant_id,current_provenance.membership_id,
      current_provenance.external_identity_id,
      current_provenance.external_identity_revision,
      current_provenance.provider_revision,current_provenance.binding_revision,
      current_provenance.security_revision,current_provenance.mapping_revision,
      current_provenance.authorization_revision,
      current_provenance.subject_alias_key_version,
      current_provenance.trust_rule_revision,
      current_provenance.authenticated_at)
      AND EXISTS (
        SELECT 1
        FROM ONLY public.auth_session_tenant_platform_federated_evidence
          AS evidence
        WHERE evidence.tenant_id = p_tenant_id
          AND evidence.session_id = current_session.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM (
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = origin_session.id
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id)
          UNION ALL
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = origin_session.id)
        ) AS evidence_difference
      )
  ), session_continuation_lineage AS MATERIALIZED (
    SELECT application.transaction_id,application.applied_at,
           current_provenance.tenant_id,current_provenance.user_id,
           current_provenance.platform_provider_id,
           current_provenance.binding_id,current_provenance.access_epoch_id,
           current_provenance.access_source_id,
           current_provenance.access_grant_id,current_provenance.membership_id,
           current_provenance.external_identity_id,
           current_provenance.external_identity_revision,
           current_provenance.provider_revision,
           current_provenance.binding_revision,
           current_provenance.security_revision,
           current_provenance.mapping_revision,
           current_provenance.authorization_revision,
           current_provenance.subject_alias_key_version,
           current_provenance.trust_rule_revision,
           current_provenance.authenticated_at
    FROM current_session
    JOIN current_provenance ON true
    JOIN family_root ON true
    JOIN ONLY public.auth_session_tenant_platform_federated_provenance
      AS root_provenance
      ON root_provenance.tenant_id = p_tenant_id
     AND root_provenance.session_id = family_root.session_id
     AND root_provenance.user_id = current_session.user_id
     AND root_provenance.primary_kind = 'tenant_platform_provider'
     AND root_provenance.authentication_method = 'oidc'
    JOIN ONLY public.tenant_platform_oidc_authentication_applications
      AS application
      ON application.tenant_id = p_tenant_id
     AND application.session_id IS NULL
     AND application.continuation_id IS NOT NULL
     AND application.category = 'success'
     AND application.primary_kind = 'tenant_platform_provider'
     AND application.user_id = current_provenance.user_id
     AND application.platform_provider_id =
       current_provenance.platform_provider_id
     AND application.binding_id = current_provenance.binding_id
     AND application.external_identity_id =
       current_provenance.external_identity_id
    JOIN ONLY public.tenant_post_primary_platform_federated_provenance
      AS continuation
      ON continuation.tenant_id = p_tenant_id
     AND continuation.continuation_id = application.continuation_id
     AND continuation.user_id = application.user_id
     AND continuation.origin = 'initial_login'
    JOIN ONLY public.tenant_post_primary_continuations AS continuation_owner
      ON continuation_owner.tenant_id = continuation.tenant_id
     AND continuation_owner.id = continuation.continuation_id
     AND continuation_owner.user_id = continuation.user_id
     AND continuation_owner.primary_kind = 'tenant_platform_provider'
     AND continuation_owner.provider_kind = 'oidc'
     AND continuation_owner.platform_provider_id =
       continuation.platform_provider_id
     AND continuation_owner.binding_id = continuation.binding_id
     AND continuation_owner.external_identity_id =
       continuation.external_identity_id
     AND continuation_owner.state = 'consumed'
     AND continuation_owner.version = 2
     AND continuation_owner.consumed_at = family_root.created_at
     AND continuation_owner.created_at = application.applied_at
    WHERE ROW(root_provenance.user_id,root_provenance.platform_provider_id,
      root_provenance.binding_id,root_provenance.access_epoch_id,
      root_provenance.access_source_id,root_provenance.access_grant_id,
      root_provenance.membership_id,root_provenance.external_identity_id,
      root_provenance.external_identity_revision,root_provenance.provider_revision,
      root_provenance.binding_revision,root_provenance.security_revision,
      root_provenance.mapping_revision,root_provenance.authorization_revision,
      root_provenance.subject_alias_key_version,root_provenance.trust_rule_revision,
      root_provenance.authenticated_at)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,current_provenance.platform_provider_id,
      current_provenance.binding_id,current_provenance.access_epoch_id,
      current_provenance.access_source_id,current_provenance.access_grant_id,
      current_provenance.membership_id,current_provenance.external_identity_id,
      current_provenance.external_identity_revision,current_provenance.provider_revision,
      current_provenance.binding_revision,current_provenance.security_revision,
      current_provenance.mapping_revision,current_provenance.authorization_revision,
      current_provenance.subject_alias_key_version,current_provenance.trust_rule_revision,
      current_provenance.authenticated_at)
      AND ROW(continuation.user_id,continuation.platform_provider_id,
      continuation.binding_id,continuation.access_epoch_id,
      continuation.access_source_id,continuation.access_grant_id,
      continuation.membership_id,continuation.external_identity_id,
      continuation.external_identity_revision,continuation.provider_revision,
      continuation.binding_revision,continuation.security_revision,
      continuation.mapping_revision,continuation.authorization_revision,
      continuation.subject_alias_key_version,continuation.trust_rule_revision,
      continuation.authenticated_at)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,
      current_provenance.platform_provider_id,current_provenance.binding_id,
      current_provenance.access_epoch_id,current_provenance.access_source_id,
      current_provenance.access_grant_id,current_provenance.membership_id,
      current_provenance.external_identity_id,
      current_provenance.external_identity_revision,
      current_provenance.provider_revision,current_provenance.binding_revision,
      current_provenance.security_revision,current_provenance.mapping_revision,
      current_provenance.authorization_revision,
      current_provenance.subject_alias_key_version,
      current_provenance.trust_rule_revision,
      current_provenance.authenticated_at)
      AND EXISTS (
        SELECT 1
        FROM ONLY public.auth_session_tenant_platform_federated_evidence
          AS evidence
        WHERE evidence.tenant_id = p_tenant_id
          AND evidence.session_id = current_session.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM (
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = family_root.session_id
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id)
          UNION ALL
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.binding_id,evidence.external_identity_id,
                  evidence.level,evidence.authenticated_at,evidence.expires_at,
                  evidence.trust_rule_revision
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = family_root.session_id)
        ) AS evidence_difference
      )
  ), explicit_continuation_lineage AS MATERIALIZED (
    SELECT application.transaction_id,application.applied_at,
           continuation.tenant_id,continuation.user_id,
           continuation.platform_provider_id,continuation.binding_id,
           continuation.access_epoch_id,continuation.access_source_id,
           continuation.access_grant_id,continuation.membership_id,
           continuation.external_identity_id,
           continuation.external_identity_revision,
           continuation.provider_revision,continuation.binding_revision,
           continuation.security_revision,continuation.mapping_revision,
           continuation.authorization_revision,
           continuation.subject_alias_key_version,
           continuation.trust_rule_revision,continuation.authenticated_at
    FROM ONLY public.tenant_platform_oidc_authentication_applications
      AS application
    JOIN ONLY public.tenant_post_primary_platform_federated_provenance
      AS continuation
      ON continuation.tenant_id = application.tenant_id
     AND continuation.continuation_id = application.continuation_id
     AND continuation.user_id = application.user_id
     AND continuation.origin = 'initial_login'
    JOIN ONLY public.tenant_post_primary_continuations AS continuation_owner
      ON continuation_owner.tenant_id = continuation.tenant_id
     AND continuation_owner.id = continuation.continuation_id
     AND continuation_owner.user_id = continuation.user_id
     AND continuation_owner.primary_kind = 'tenant_platform_provider'
     AND continuation_owner.provider_kind = 'oidc'
     AND continuation_owner.platform_provider_id =
       continuation.platform_provider_id
     AND continuation_owner.binding_id = continuation.binding_id
     AND continuation_owner.external_identity_id =
       continuation.external_identity_id
     AND continuation_owner.state = 'consumed'
     AND continuation_owner.version = 2
     AND continuation_owner.created_at = application.applied_at
    JOIN ONLY public.auth_sessions AS successor
      ON successor.id = p_session_id
     AND successor.user_id = continuation.user_id
     AND successor.active_tenant_id = p_tenant_id
     AND successor.authentication_method = 'oidc'
     AND successor.rotated_from_session_id IS NULL
     AND successor.created_at = continuation_owner.consumed_at
    JOIN ONLY public.auth_session_tenant_platform_federated_provenance
      AS successor_provenance
      ON successor_provenance.tenant_id = p_tenant_id
     AND successor_provenance.session_id = successor.id
     AND successor_provenance.user_id = successor.user_id
     AND successor_provenance.primary_kind = 'tenant_platform_provider'
     AND successor_provenance.authentication_method = 'oidc'
    WHERE p_session_id IS NOT NULL
      AND p_initial_continuation_id IS NOT NULL
      AND application.tenant_id = p_tenant_id
      AND application.session_id IS NULL
      AND application.continuation_id = p_initial_continuation_id
      AND application.category = 'success'
      AND application.primary_kind = 'tenant_platform_provider'
      AND application.platform_provider_id = continuation.platform_provider_id
      AND application.binding_id = continuation.binding_id
      AND application.external_identity_id = continuation.external_identity_id
      AND ROW(successor_provenance.user_id,
        successor_provenance.platform_provider_id,
        successor_provenance.binding_id,successor_provenance.access_epoch_id,
        successor_provenance.access_source_id,
        successor_provenance.access_grant_id,successor_provenance.membership_id,
        successor_provenance.external_identity_id,
        successor_provenance.external_identity_revision,
        successor_provenance.provider_revision,
        successor_provenance.binding_revision,
        successor_provenance.security_revision,
        successor_provenance.mapping_revision,
        successor_provenance.authorization_revision,
        successor_provenance.subject_alias_key_version,
        successor_provenance.trust_rule_revision,
        successor_provenance.authenticated_at)
        IS NOT DISTINCT FROM
        ROW(continuation.user_id,continuation.platform_provider_id,
        continuation.binding_id,continuation.access_epoch_id,
        continuation.access_source_id,continuation.access_grant_id,
        continuation.membership_id,continuation.external_identity_id,
        continuation.external_identity_revision,continuation.provider_revision,
        continuation.binding_revision,continuation.security_revision,
        continuation.mapping_revision,continuation.authorization_revision,
        continuation.subject_alias_key_version,
        continuation.trust_rule_revision,continuation.authenticated_at)
      AND EXISTS (
        SELECT 1
        FROM ONLY public.tenant_post_primary_platform_federated_evidence
          AS evidence
        WHERE evidence.tenant_id = p_tenant_id
          AND evidence.continuation_id = continuation.continuation_id
          AND evidence.user_id = continuation.user_id
          AND evidence.platform_provider_id = continuation.platform_provider_id
          AND evidence.binding_id = continuation.binding_id
          AND evidence.external_identity_id = continuation.external_identity_id
      )
  ), tenant_lineage AS MATERIALIZED (
    SELECT * FROM session_application_lineage
    UNION ALL
    SELECT * FROM session_continuation_lineage
    UNION ALL
    SELECT * FROM explicit_continuation_lineage
  ), tenant_candidates AS MATERIALIZED (
    SELECT transaction.allow_refresh_token OR nullif(
             convert_from(discovery.document,'UTF8')::jsonb
               ->> 'end_session_endpoint',''
           ) IS NOT NULL AS material_required
    FROM tenant_lineage
    JOIN ONLY public.tenant_platform_oidc_authentication_transactions
      AS transaction
      ON transaction.tenant_id = tenant_lineage.tenant_id
     AND transaction.transaction_id = tenant_lineage.transaction_id
     AND transaction.platform_provider_id =
       tenant_lineage.platform_provider_id
     AND transaction.binding_id = tenant_lineage.binding_id
     AND transaction.provider_kind = 'oidc'
     AND transaction.protocol = 'oidc'
     AND transaction.state = 'completed'
     AND transaction.completed_at = tenant_lineage.applied_at
     AND transaction.access_epoch_id = tenant_lineage.access_epoch_id
     AND transaction.access_source_id = tenant_lineage.access_source_id
     AND transaction.provider_revision = tenant_lineage.provider_revision
     AND transaction.binding_revision = tenant_lineage.binding_revision
     AND transaction.security_revision = tenant_lineage.security_revision
     AND transaction.mapping_revision = tenant_lineage.mapping_revision
     AND transaction.authorization_revision =
       tenant_lineage.authorization_revision
    JOIN ONLY public.platform_oidc_discovery_snapshots AS discovery
      ON discovery.provider_id = transaction.platform_provider_id
     AND discovery.revision = transaction.discovery_revision
     AND discovery.document_digest = transaction.discovery_digest
  ), switch_candidates AS MATERIALIZED (
    SELECT app.private_direct_platform_oidc_material_absence_attested_v1(
             switch.source_session_id
           ) AS absence_attested
    FROM current_session
    JOIN current_provenance ON true
    JOIN ancestry ON true
    JOIN ONLY public.platform_oidc_tenant_switch_commands AS switch
      ON switch.rotated_session_id = ancestry.session_id
     AND switch.target_tenant_id = p_tenant_id
     AND switch.decision = 'rotated'
     AND switch.membership_id = current_provenance.membership_id
     AND switch.binding_id = current_provenance.binding_id
     AND switch.binding_version = current_provenance.binding_revision
     AND switch.mapping_revision = current_provenance.mapping_revision
     AND switch.authorization_revision =
       current_provenance.authorization_revision
     AND switch.access_epoch_id = current_provenance.access_epoch_id
     AND switch.access_source_id = current_provenance.access_source_id
     AND switch.access_grant_id = current_provenance.access_grant_id
    JOIN ONLY public.auth_sessions AS switch_target
      ON switch_target.id = switch.rotated_session_id
     AND switch_target.user_id = current_session.user_id
     AND switch_target.rotation_family_id = current_session.rotation_family_id
     AND switch_target.active_tenant_id = p_tenant_id
     AND switch_target.authentication_method = 'oidc'
     AND switch_target.rotated_from_session_id = switch.source_session_id
     AND switch_target.created_at = switch.applied_at
    JOIN ONLY public.auth_sessions AS source_session
      ON source_session.id = switch.source_session_id
     AND source_session.user_id = current_session.user_id
     AND source_session.rotation_family_id = current_session.rotation_family_id
     AND source_session.active_tenant_id IS NULL
     AND source_session.authentication_method = 'oidc'
    JOIN ONLY public.auth_session_platform_oidc_provenance AS source_provenance
      ON source_provenance.session_id = source_session.id
     AND source_provenance.user_id = source_session.user_id
     AND source_provenance.primary_kind = 'platform_provider'
    WHERE ROW(source_provenance.user_id,
      source_provenance.platform_provider_id,
      source_provenance.external_identity_id,
      source_provenance.provider_revision,source_provenance.security_revision,
      source_provenance.identity_version,source_provenance.alias_key_version,
      source_provenance.authenticated_at)
      IS NOT DISTINCT FROM
      ROW(current_provenance.user_id,
      current_provenance.platform_provider_id,
      current_provenance.external_identity_id,
      current_provenance.provider_revision,current_provenance.security_revision,
      current_provenance.external_identity_revision,
      current_provenance.subject_alias_key_version,
      current_provenance.authenticated_at)
      AND current_provenance.trust_rule_revision =
        current_provenance.security_revision
      AND NOT EXISTS (
        SELECT 1
        FROM (
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.external_identity_id,evidence.level,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = source_session.id
             AND evidence.kind = 'platform_provider'
             AND evidence.trust_rule_id IS NOT DISTINCT FROM
               source_provenance.trust_rule_id
             AND evidence.trust_rule_revision IS NOT DISTINCT FROM
               source_provenance.trust_rule_revision
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.external_identity_id,evidence.level,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id
             AND evidence.binding_id = current_provenance.binding_id
             AND evidence.trust_rule_revision =
               current_provenance.security_revision)
          UNION ALL
          (SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.external_identity_id,evidence.level,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_tenant_platform_federated_evidence
             AS evidence
           WHERE evidence.tenant_id = p_tenant_id
             AND evidence.session_id = current_session.id
             AND evidence.binding_id = current_provenance.binding_id
             AND evidence.trust_rule_revision =
               current_provenance.security_revision
           EXCEPT ALL
           SELECT evidence.user_id,evidence.platform_provider_id,
                  evidence.external_identity_id,evidence.level,
                  evidence.authenticated_at,evidence.expires_at
           FROM ONLY public.auth_session_platform_oidc_evidence AS evidence
           WHERE evidence.session_id = source_session.id
             AND evidence.kind = 'platform_provider'
             AND evidence.trust_rule_id IS NOT DISTINCT FROM
               source_provenance.trust_rule_id
             AND evidence.trust_rule_revision IS NOT DISTINCT FROM
               source_provenance.trust_rule_revision)
        ) AS evidence_difference
      )
  ), candidates AS MATERIALIZED (
    SELECT NOT tenant_candidates.material_required AS absence_attested,
           'tenant'::text AS source_kind
    FROM tenant_candidates
    UNION ALL
    SELECT switch_candidates.absence_attested,'switch'::text
    FROM switch_candidates
  )
  SELECT coalesce((
    SELECT count(*) >= 1 AND bool_and(candidates.absence_attested)
    FROM candidates
  ),false)
  AND (
    p_session_id IS NOT NULL
  )
  AND (
    p_initial_continuation_id IS NOT NULL
    OR EXISTS (SELECT 1 FROM family_root)
    OR EXISTS (SELECT 1 FROM switch_candidates)
  )
  AND NOT (
    EXISTS (SELECT 1 FROM tenant_candidates)
    AND EXISTS (SELECT 1 FROM switch_candidates)
  )
  AND (SELECT count(*) FROM switch_candidates) <= 1;
$function$;
