    'app.private_tenant_platform_session_authority_live_v1(uuid,uuid,timestamp with time zone)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,$needle$provider.kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,$needle$policy.provider_kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,$needle$session.authentication_method = 'oidc'$needle$) = 0 THEN
    RAISE EXCEPTION 'unexpected tenant-platform authority predecessor';
  END IF;
  v_definition := replace(
    v_definition,$needle$provider.kind = 'oidc'$needle$,
    'provider.kind::text = provenance.authentication_method'
  );
  v_definition := replace(
    v_definition,$needle$policy.provider_kind = 'oidc'$needle$,
    'policy.provider_kind::text = provenance.authentication_method'
  );
  v_definition := replace(
    v_definition,$needle$session.authentication_method = 'oidc'$needle$,
    'session.authentication_method = provenance.authentication_method'
  );
  EXECUTE v_definition;

  SELECT pg_get_functiondef(
    'app.load_tenant_platform_federated_session_revalidation_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,$needle$provider.kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,$needle$policy.provider_kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,$needle$rule.provider_kind = 'oidc'$needle$) = 0 THEN
    RAISE EXCEPTION 'unexpected tenant-platform revalidation loader predecessor';
  END IF;
  v_definition := replace(
    v_definition,$needle$provider.kind = 'oidc'$needle$,
    'provider.kind::text = provenance_record.authentication_method'
  );
  v_definition := replace(
    v_definition,$needle$policy.provider_kind = 'oidc'$needle$,
    'policy.provider_kind::text = provenance_record.authentication_method'
  );
  v_definition := replace(
    v_definition,$needle$rule.provider_kind = 'oidc'$needle$,
    'rule.provider_kind::text = provenance_record.authentication_method'
  );
  EXECUTE v_definition;

  SELECT pg_get_functiondef(
    'app.apply_tenant_platform_federated_session_revalidation_v1(jsonb)'::regprocedure
  ) INTO STRICT v_definition;
  IF strpos(v_definition,$needle$policy.provider_kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,$needle$rule.provider_kind = 'oidc'$needle$) = 0
     OR strpos(v_definition,
