-- F-AUD-28/F-AUD-42: refresh claims are bounded leases.  A stale lease gets a
-- fresh version before credentials can be projected again, and completion is
-- guarded by that version so an old worker cannot win an ABA race.
CREATE OR REPLACE FUNCTION app.claim_tenant_oidc_refresh_rotation_v1(
  p_command jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_tenant_id uuid := nullif(current_setting('app.tenant_id',true),'')::uuid;
  v_user_id uuid := nullif(current_setting('app.user_id',true),'')::uuid;
  v_family_id uuid;
  v_expected_generation bigint;
  v_expected_digest bytea;
  v_requested_claimed_at timestamptz;
  v_claimed_at timestamptz;
  v_lease_expires_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_session public.auth_sessions%ROWTYPE;
  v_effective_session_id uuid;
  v_effective_tenant_id uuid;
  v_session_found boolean;
  v_retry_delay interval;
  v_retry_deadline timestamptz;
  v_provider jsonb;
  v_admission jsonb;
  v_reuse boolean;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['sessionFamilyId','expectedGeneration','expectedDigest','claimedAt'],
    ARRAY['sessionFamilyId','expectedGeneration','expectedDigest','claimedAt'],8192
  );
  v_family_id := app.private_mfa_require_uuidv7_v1(
    p_command ->> 'sessionFamilyId'
  );
  v_expected_generation := (p_command ->> 'expectedGeneration')::bigint;
  v_expected_digest := app.private_mfa_decode_base64_v1(
    p_command ->> 'expectedDigest',32,32
  );
  v_requested_claimed_at := (p_command ->> 'claimedAt')::timestamptz;
  IF v_user_id IS NULL OR v_expected_generation < 1
     OR v_expected_generation >= 9000000000000000
     OR encode(v_expected_digest,'hex') = repeat('00',32)
     OR date_trunc('microseconds',v_requested_claimed_at)
          <> v_requested_claimed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_claimed_at))) > 300 THEN
    RAISE EXCEPTION 'invalid OIDC refresh claim' USING ERRCODE = '22023';
  END IF;
  v_claimed_at := date_trunc('microseconds',transaction_timestamp());
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.rotation_family_id = v_family_id
    AND material.user_id = v_user_id
    AND material.session_id IS NOT NULL
    AND material.continuation_id IS NULL
    AND EXISTS (
      SELECT 1
      FROM app.private_oidc_material_effective_session_v1(material.id)
        AS effective
      WHERE effective.tenant_id IS NOT DISTINCT FROM v_tenant_id
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;
  SELECT effective.session_id,effective.tenant_id
    INTO STRICT v_effective_session_id,v_effective_tenant_id
  FROM app.private_oidc_material_effective_session_v1(v_material.id)
    AS effective
  WHERE effective.tenant_id IS NOT DISTINCT FROM v_tenant_id;
  SELECT session.* INTO v_session
  FROM public.auth_sessions AS session
  WHERE session.id = v_effective_session_id
    AND session.user_id = v_material.user_id
    AND session.rotation_family_id = v_family_id
    AND session.active_tenant_id IS NOT DISTINCT FROM v_effective_tenant_id
    AND session.authentication_method = 'oidc'
  FOR UPDATE;
  IF NOT FOUND OR v_session.revoked_at IS NOT NULL
     OR v_session.absolute_expires_at <= v_claimed_at
     OR v_material.expires_at <= v_claimed_at
     OR v_material.scrubbed_at IS NOT NULL
     OR v_material.refresh_state IN ('unavailable','revoked','scrubbed')
     OR v_material.access_expires_at <= v_claimed_at THEN
    IF v_material.scrubbed_at IS NULL
       AND v_material.refresh_state IN ('ready','claimed') THEN
      UPDATE public.tenant_oidc_session_materials AS material
      SET refresh_state = 'revoked',refresh_claimed_at = NULL,
          refresh_claim_expires_at = NULL,
          refresh_version = CASE
            WHEN material.refresh_version < 8999999999999999
              THEN material.refresh_version + 1
            ELSE material.refresh_version END,
          updated_at = v_claimed_at
      WHERE material.id = v_material.id;
    END IF;
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;

  -- Reserve a version for both claim and completion, plus the requeue
  -- transition when an expired lease is reclaimed. Counter exhaustion is a
  -- fail-closed terminal state and never crosses the canonical 9e15 boundary.
  IF (v_material.refresh_state = 'ready'
        AND v_material.refresh_version >= 8999999999999998)
     OR (v_material.refresh_state = 'claimed'
        AND v_material.refresh_claim_expires_at <= v_claimed_at
        AND v_material.refresh_version >= 8999999999999997) THEN
    UPDATE public.auth_sessions AS family
    SET revoked_at = coalesce(family.revoked_at,v_claimed_at),
        revoke_reason = coalesce(
          family.revoke_reason,'oidc_refresh_version_exhausted'
        )
    WHERE family.user_id = v_material.user_id
      AND family.rotation_family_id = v_family_id;
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_state = 'revoked',refresh_claimed_at = NULL,
        refresh_claim_expires_at = NULL,updated_at = v_claimed_at
    WHERE material.id = v_material.id;
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;

  -- Expired claims are reclaimable, but only after their version is advanced.
  IF v_material.refresh_state = 'claimed'
     AND v_material.refresh_claim_expires_at <= v_claimed_at THEN
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_state = 'ready',refresh_claimed_at = NULL,
        refresh_claim_expires_at = NULL,
        refresh_version = CASE
          WHEN material.refresh_version < 8999999999999999
            THEN material.refresh_version + 1
          ELSE material.refresh_version END,
        updated_at = v_claimed_at
    WHERE material.id = v_material.id
      AND material.refresh_state = 'claimed'
      AND material.refresh_version = v_material.refresh_version
    RETURNING material.* INTO STRICT v_material;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.tenant_oidc_consumed_refresh_tokens AS consumed
    WHERE consumed.authority = v_material.authority
      AND consumed.material_id = v_material.id
      AND consumed.session_family_id = v_family_id
      AND (consumed.generation = v_expected_generation
        OR consumed.token_digest = v_expected_digest)
      AND consumed.retain_until > v_claimed_at
  ) INTO v_reuse;
  IF v_material.refresh_state = 'claimed'
     AND v_material.refresh_claim_expires_at > v_claimed_at
     AND v_material.refresh_generation = v_expected_generation
     AND v_material.refresh_token_digest = v_expected_digest THEN
    RETURN jsonb_build_object(
      'category','busy','sessionFamilyId',v_family_id::text
    );
  END IF;
  IF v_reuse THEN
    UPDATE public.auth_sessions AS family
    SET revoked_at = coalesce(family.revoked_at,v_claimed_at),
        revoke_reason = coalesce(family.revoke_reason,'oidc_refresh_reuse')
    WHERE family.user_id = v_material.user_id
      AND family.rotation_family_id = v_family_id;
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_state = 'revoked',refresh_claimed_at = NULL,
        refresh_claim_expires_at = NULL,
        refresh_version = CASE
          WHEN material.refresh_version < 8999999999999999
            THEN material.refresh_version + 1
          ELSE material.refresh_version END,
        updated_at = v_claimed_at
    WHERE material.id = v_material.id
      AND material.scrubbed_at IS NULL;
    IF v_effective_tenant_id IS NOT NULL THEN
      INSERT INTO public.audit_events (
        id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
        resource_type,resource_id,authentication_method,outcome,metadata
      ) VALUES (
        uuidv7(),v_effective_tenant_id,0,v_claimed_at,'system',NULL,
        'tenant.identity.oidc_refresh_reuse','auth_session',
        v_effective_session_id,'oidc','success',jsonb_build_object(
          'session_family_id',v_family_id::text,
          'material_id',v_material.id::text,'material_disclosed',false
        )
      );
    ELSE
      PERFORM app.append_platform_audit_event(
        uuidv7(),'system',NULL,'platform.identity.oidc_refresh_reuse',
        'auth_session',v_material.session_id,uuidv7(),uuidv7(),NULL,NULL,
        'oidc','success',NULL,jsonb_build_object(
          'session_family_id',v_family_id::text,
          'material_id',v_material.id::text,'material_disclosed',false
        )
      );
    END IF;
    RETURN jsonb_build_object(
      'category','reuse','sessionFamilyId',v_family_id::text,
      'tenantId',to_jsonb(v_material.tenant_id),
      'effectiveTenantId',to_jsonb(v_effective_tenant_id),
      'materialId',v_material.id::text
    );
  END IF;
  IF v_material.refresh_state <> 'ready'
     OR v_material.refresh_generation IS DISTINCT FROM v_expected_generation
     OR v_material.refresh_token_digest IS DISTINCT FROM v_expected_digest THEN
    RETURN jsonb_build_object(
      'category','stale','sessionFamilyId',v_family_id::text
    );
  END IF;
  v_lease_expires_at := least(
    v_claimed_at + interval '2 minutes',v_material.expires_at,
    v_session.absolute_expires_at
  );
  UPDATE public.tenant_oidc_session_materials AS material
  SET refresh_state = 'claimed',refresh_claimed_at = v_claimed_at,
      refresh_claim_expires_at = v_lease_expires_at,
      refresh_version = material.refresh_version + 1,updated_at = v_claimed_at
  WHERE material.id = v_material.id AND material.refresh_state = 'ready'
    AND material.refresh_version = v_material.refresh_version
  RETURNING material.* INTO STRICT v_material;
  v_provider := CASE v_material.authority
    WHEN 'tenant_provider' THEN jsonb_build_object(
      'scope','tenant','tenantId',v_material.tenant_id::text,
      'providerId',v_material.provider_id::text,
      'bindingId',v_material.binding_id::text
    ) ELSE jsonb_build_object(
      'scope','platform','providerId',v_material.provider_id::text
    ) END;
  v_admission := CASE WHEN v_material.authority = 'tenant_platform_provider'
    THEN jsonb_build_object(
      'tenantId',v_material.tenant_id::text,'bindingId',v_material.binding_id::text
    ) END;
  RETURN jsonb_build_object(
    'category','claimed','observedAt',to_jsonb(v_claimed_at),
    'tenantId',to_jsonb(v_material.tenant_id),
    'effectiveTenantId',to_jsonb(v_effective_tenant_id),
    'materialId',v_material.id::text,
    'sessionFamilyId',v_family_id::text,
    'generation',v_material.refresh_generation,
    'version',v_material.refresh_version,
    'leaseExpiresAt',to_jsonb(v_material.refresh_claim_expires_at),
    'provider',v_provider,'bindingId',to_jsonb(v_material.binding_id),
    'clientSecretRevision',v_material.client_secret_revision,
    'endpoint',v_material.token_endpoint,
    'clientAuthentication',v_material.client_authentication,
    'clientId',v_material.client_id,
    'token',jsonb_build_object(
      'keyVersion',v_material.refresh_token_key_version,
      'ciphertext',replace(encode(
        v_material.refresh_token_ciphertext,'base64'
      ),E'\n','')
    ),
    'tokenDigest',replace(encode(
      v_material.refresh_token_digest,'base64'
    ),E'\n',''),
    'materialExpiresAt',to_jsonb(v_material.expires_at),
    'absoluteSessionExpiry',to_jsonb(v_session.absolute_expires_at)
  ) || CASE WHEN v_admission IS NULL THEN '{}'::jsonb
    ELSE jsonb_build_object('admission',v_admission) END;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC refresh claim' USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.complete_tenant_oidc_refresh_rotation_v1(
  p_command jsonb
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_tenant_id uuid;
  v_effective_tenant_id_requested uuid;
  v_material_id uuid;
  v_family_id uuid;
  v_expected_version bigint;
  v_expected_generation bigint;
  v_outcome text;
  v_requested_completed_at timestamptz;
  v_completed_at timestamptz;
  v_successor_generation bigint;
  v_successor_digest bytea;
  v_successor_key_version integer;
  v_successor_ciphertext bytea;
  v_access_expires_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_session public.auth_sessions%ROWTYPE;
  v_effective_session_id uuid;
  v_effective_tenant_id uuid;
  v_session_found boolean;
  v_retry_delay interval;
  v_retry_deadline timestamptz;
  v_jitter numeric;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_command,
    ARRAY['tenantId','effectiveTenantId','materialId','sessionFamilyId','expectedVersion',
      'expectedGeneration','outcome','successorGeneration','successorDigest',
      'successorToken','accessExpiresAt','completedAt'],
    ARRAY['tenantId','effectiveTenantId','materialId','sessionFamilyId','expectedVersion',
      'expectedGeneration','outcome','completedAt'],524288
  );
  IF jsonb_typeof(p_command -> 'tenantId') = 'null' THEN
    v_tenant_id := NULL;
  ELSE
    v_tenant_id := app.private_mfa_require_uuidv7_v1(p_command ->> 'tenantId');
  END IF;
  IF jsonb_typeof(p_command -> 'effectiveTenantId') = 'null' THEN
    v_effective_tenant_id_requested := NULL;
  ELSE
    v_effective_tenant_id_requested := app.private_mfa_require_uuidv7_v1(
      p_command ->> 'effectiveTenantId'
    );
  END IF;
  v_material_id := app.private_mfa_require_uuidv7_v1(
    p_command ->> 'materialId'
  );
  v_family_id := app.private_mfa_require_uuidv7_v1(
    p_command ->> 'sessionFamilyId'
  );
  v_expected_version := (p_command ->> 'expectedVersion')::bigint;
  v_expected_generation := (p_command ->> 'expectedGeneration')::bigint;
  v_outcome := p_command ->> 'outcome';
  v_requested_completed_at := (p_command ->> 'completedAt')::timestamptz;
  IF v_expected_version < 1
     OR v_expected_version >= 8999999999999999
     OR v_expected_generation < 1
     OR v_expected_generation >= 9000000000000000
     OR v_outcome NOT IN (
       'rotated','safe_to_retry','local_dependency_unavailable',
       'ambiguous','rejected'
     )
     OR date_trunc('microseconds',v_requested_completed_at)
          <> v_requested_completed_at
     OR abs(extract(epoch FROM
       (transaction_timestamp() - v_requested_completed_at))) > 300
     OR ((v_outcome = 'rotated') IS DISTINCT FROM
       (p_command ?& ARRAY['successorGeneration','successorDigest',
         'successorToken','accessExpiresAt'])) THEN
    RAISE EXCEPTION 'invalid OIDC refresh completion'
      USING ERRCODE = '22023';
  END IF;
  v_completed_at := date_trunc('microseconds',transaction_timestamp());
  IF v_outcome = 'rotated' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      p_command -> 'successorToken',ARRAY['keyVersion','ciphertext'],
      ARRAY['keyVersion','ciphertext'],524288
    );
    v_successor_generation := (p_command ->> 'successorGeneration')::bigint;
    v_successor_digest := app.private_mfa_decode_base64_v1(
      p_command ->> 'successorDigest',32,32
    );
    v_successor_key_version :=
      (p_command #>> '{successorToken,keyVersion}')::integer;
    v_successor_ciphertext := app.private_mfa_decode_base64_v1(
      p_command #>> '{successorToken,ciphertext}',29,262172
    );
    v_access_expires_at := (p_command ->> 'accessExpiresAt')::timestamptz;
    IF v_successor_generation <> v_expected_generation + 1
       OR v_successor_generation >= 9000000000000000
       OR encode(v_successor_digest,'hex') = repeat('00',32)
       OR v_successor_key_version NOT BETWEEN 1 AND 32767
       OR date_trunc('microseconds',v_access_expires_at) <> v_access_expires_at
       OR v_access_expires_at <= v_completed_at
       OR NOT EXISTS (
         SELECT 1 FROM public.identity_keyring_versions AS keyring
         WHERE keyring.key_version = v_successor_key_version
           AND keyring.is_active AND keyring.retired_at IS NULL
       ) THEN
      RAISE EXCEPTION 'invalid OIDC refresh completion'
        USING ERRCODE = '22023';
    END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_family_id::text,90174213));
  SELECT material.* INTO v_material
  FROM public.tenant_oidc_session_materials AS material
  WHERE material.id = v_material_id
    AND material.tenant_id IS NOT DISTINCT FROM v_tenant_id
    AND material.rotation_family_id = v_family_id
    AND material.session_id IS NOT NULL
    AND material.refresh_state = 'claimed'
    AND material.refresh_version = v_expected_version
    AND material.refresh_generation = v_expected_generation
    AND (v_outcome IN ('ambiguous','rejected')
      OR material.refresh_claim_expires_at > v_completed_at)
    AND material.scrubbed_at IS NULL
    AND (v_outcome IN ('ambiguous','rejected')
      OR material.expires_at > v_completed_at)
    AND EXISTS (
      SELECT 1
      FROM app.private_oidc_material_effective_session_v1(material.id)
        AS effective
      WHERE effective.tenant_id IS NOT DISTINCT FROM
        v_effective_tenant_id_requested
    )
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT effective.session_id,effective.tenant_id
    INTO STRICT v_effective_session_id,v_effective_tenant_id
  FROM app.private_oidc_material_effective_session_v1(v_material.id)
    AS effective
  WHERE effective.tenant_id IS NOT DISTINCT FROM
    v_effective_tenant_id_requested;
  SELECT session.* INTO v_session
  FROM public.auth_sessions AS session
  WHERE session.id = v_effective_session_id
    AND session.user_id = v_material.user_id
    AND session.rotation_family_id = v_family_id
    AND session.active_tenant_id IS NOT DISTINCT FROM v_effective_tenant_id
    AND session.authentication_method = 'oidc'
  FOR UPDATE;
  v_session_found := FOUND;
  IF v_outcome = 'rotated' THEN
    IF NOT v_session_found OR v_session.revoked_at IS NOT NULL
       OR v_session.absolute_expires_at <= v_completed_at
       OR v_access_expires_at > v_session.absolute_expires_at
       OR v_access_expires_at > v_material.expires_at
       OR v_material.refresh_token_digest = v_successor_digest THEN
      RETURN false;
    END IF;
    INSERT INTO public.tenant_oidc_consumed_refresh_tokens (
      tenant_id,authority,material_id,session_family_id,generation,
      token_digest,consumed_at,retain_until
    ) VALUES (
      v_material.tenant_id,v_material.authority,v_material.id,v_family_id,
      v_material.refresh_generation,v_material.refresh_token_digest,
      v_completed_at,least(v_session.absolute_expires_at,v_material.expires_at)
    );
    UPDATE public.tenant_oidc_session_materials AS material
    SET refresh_token_key_version = v_successor_key_version,
        refresh_token_ciphertext = v_successor_ciphertext,
        refresh_token_digest = v_successor_digest,
        refresh_generation = v_successor_generation,
        refresh_retry_attempt = 0,
        refresh_state = 'ready',refresh_claimed_at = NULL,
        refresh_claim_expires_at = NULL,
        access_expires_at = v_access_expires_at,
        refresh_version = material.refresh_version + 1,
        updated_at = v_completed_at
    WHERE material.id = v_material_id AND material.refresh_state = 'claimed'
      AND material.refresh_version = v_expected_version;
    RETURN FOUND;
  ELSIF v_outcome = 'safe_to_retry' THEN
    v_jitter := 750 + mod(abs(hashtextextended(
      v_material.id::text || ':' || v_material.refresh_generation::text
        || ':' || v_material.refresh_retry_attempt::text || ':refresh',
      88419038
    )::numeric),501);
    v_retry_delay := make_interval(secs => (
      15::numeric * power(2::numeric,v_material.refresh_retry_attempt)
        * v_jitter / 1000
    )::double precision);
    v_retry_deadline := least(
      v_material.access_expires_at,v_material.expires_at,
      v_session.absolute_expires_at
    );
    IF v_session_found AND v_session.revoked_at IS NULL
       AND v_material.refresh_retry_attempt < 5
       AND v_completed_at + v_retry_delay < v_retry_deadline THEN
      UPDATE public.tenant_oidc_session_materials AS material
      SET refresh_state = 'claimed',refresh_claimed_at = v_completed_at,
          refresh_claim_expires_at = v_completed_at + v_retry_delay,
          refresh_retry_attempt = material.refresh_retry_attempt + 1,
          refresh_version = material.refresh_version + 1,
          updated_at = v_completed_at
      WHERE material.id = v_material_id AND material.refresh_state = 'claimed'
        AND material.refresh_version = v_expected_version;
      RETURN FOUND;
    END IF;
    -- Reuse the existing terminal, audited fail-closed path without exposing a
    -- new public completion outcome on the worker wire.
    v_outcome := 'retry_exhausted';
  ELSIF v_outcome = 'local_dependency_unavailable' THEN
    v_jitter := 750 + mod(abs(hashtextextended(
      v_material.id::text || ':' || v_material.refresh_generation::text
        || ':local-dependency',88419039
    )::numeric),501);
    v_retry_delay := make_interval(secs => (
      30::numeric * v_jitter / 1000
    )::double precision);
    v_retry_deadline := least(
      v_material.access_expires_at,v_material.expires_at,
      v_session.absolute_expires_at
    );
    IF v_session_found AND v_session.revoked_at IS NULL
       AND v_completed_at + v_retry_delay < v_retry_deadline THEN
      UPDATE public.tenant_oidc_session_materials AS material
      SET refresh_state = 'claimed',refresh_claimed_at = v_completed_at,
          refresh_claim_expires_at = v_completed_at + v_retry_delay,
          refresh_version = material.refresh_version + 1,
          updated_at = v_completed_at
      WHERE material.id = v_material_id AND material.refresh_state = 'claimed'
        AND material.refresh_version = v_expected_version;
      RETURN FOUND;
    END IF;
    v_outcome := 'local_dependency_expired';
  END IF;

  UPDATE public.auth_sessions AS family
  SET revoked_at = coalesce(family.revoked_at,v_completed_at),
      revoke_reason = coalesce(family.revoke_reason,
        'oidc_refresh_' || v_outcome)
  WHERE family.user_id = v_material.user_id
    AND family.rotation_family_id = v_family_id;
  UPDATE public.tenant_oidc_session_materials AS material
  SET refresh_state = 'revoked',refresh_claimed_at = NULL,
      refresh_claim_expires_at = NULL,
      refresh_retry_attempt = 0,
      refresh_version = CASE
        WHEN material.refresh_version < 8999999999999999
          THEN material.refresh_version + 1
        ELSE material.refresh_version END,
      updated_at = v_completed_at
  WHERE material.id = v_material_id AND material.refresh_state = 'claimed'
    AND material.refresh_version = v_expected_version;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_effective_tenant_id IS NOT NULL THEN
    INSERT INTO public.audit_events (
      id,tenant_id,sequence,occurred_at,actor_type,actor_user_id,action,
      resource_type,resource_id,authentication_method,outcome,metadata
    ) VALUES (
      uuidv7(),v_effective_tenant_id,0,v_completed_at,'system',NULL,
      'tenant.identity.oidc_refresh_terminal_failure','auth_session',
      v_effective_session_id,'oidc','failure',jsonb_build_object(
        'outcome',v_outcome,'session_family_id',v_family_id::text,
        'material_id',v_material.id::text,'material_disclosed',false
      )
    );
  ELSE
    PERFORM app.append_platform_audit_event(
      uuidv7(),'system',NULL,'platform.identity.oidc_refresh_terminal_failure',
      'auth_session',v_material.session_id,uuidv7(),uuidv7(),NULL,NULL,
      'oidc','failure',NULL,jsonb_build_object(
        'outcome',v_outcome,'session_family_id',v_family_id::text,
        'material_id',v_material.id::text,'material_disclosed',false
      )
    );
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC refresh completion'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint

DO $oidc_worker_lifecycle_acl_v42$
DECLARE
  v_signature text;
BEGIN
  FOREACH v_signature IN ARRAY ARRAY[
    'app.claim_tenant_oidc_refresh_rotation_v1(jsonb)',
    'app.complete_tenant_oidc_refresh_rotation_v1(jsonb)',
    'app.claim_tenant_oidc_logout_retry_v1(jsonb)',
    'app.complete_tenant_oidc_logout_retry_v1(jsonb)',
    'app.private_legacy_claim_tenant_oidc_logout_retry_v1(jsonb)',
    'app.private_legacy_complete_tenant_oidc_logout_retry_v1(jsonb)',
    'app.private_legacy_claim_tenant_oidc_logout_retry_v2(jsonb)'
  ] LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator',v_signature);
    EXECUTE format(
      'REVOKE ALL ON FUNCTION %s FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier, periapsis_auditor, periapsis_audit_reader_owner, periapsis_notification_dispatch_owner, periapsis_sla_api_owner, periapsis_sla_worker_owner, periapsis_sla_readiness_owner',
      v_signature
    );
  END LOOP;
END;
$oidc_worker_lifecycle_acl_v42$;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION
  app.claim_tenant_oidc_refresh_rotation_v1(jsonb),
  app.complete_tenant_oidc_refresh_rotation_v1(jsonb),
  app.claim_tenant_oidc_logout_retry_v1(jsonb),
  app.complete_tenant_oidc_logout_retry_v1(jsonb)
TO periapsis_worker;
--> statement-breakpoint

-- F-AUD-54: maintenance opens the exact client-secret revision pinned by the
-- material snapshot.  Provider/user/binding readiness is deliberately not
-- consulted: local revocation and upstream cleanup must survive disable or
-- archive.  Only the envelope key's retirement boundary remains authoritative.
CREATE FUNCTION app.load_oidc_maintenance_client_secret_envelope_v1(
  p_lookup jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_scope text;
  v_tenant_id uuid;
  v_provider_id uuid;
  v_binding_id uuid;
  v_revision bigint;
  v_result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_lookup,ARRAY['provider','admission','bindingId','revision'],
    ARRAY['provider','bindingId','revision'],16384
  );
  v_scope := p_lookup #>> '{provider,scope}';
  v_revision := (p_lookup ->> 'revision')::bigint;
  IF v_revision < 1 OR v_revision > 9000000000000000 THEN
    RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope = 'tenant' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      p_lookup -> 'provider',ARRAY['scope','tenantId','providerId','bindingId'],
      ARRAY['scope','tenantId','providerId','bindingId'],4096
    );
    IF p_lookup ? 'admission'
       OR jsonb_typeof(p_lookup -> 'bindingId') <> 'string' THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
    v_tenant_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,tenantId}'
    );
    v_provider_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,providerId}'
    );
    v_binding_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,bindingId}'
    );
    IF v_binding_id IS DISTINCT FROM app.private_mfa_require_uuidv7_v1(
         p_lookup ->> 'bindingId'
       ) THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
    SELECT jsonb_build_object(
      'lookup',p_lookup,'secretId',secret.id::text,
      'keyVersion',secret.key_version,
      'nonce',replace(encode(secret.nonce,'base64'),E'\n',''),
      'ciphertext',replace(encode(secret.ciphertext,'base64'),E'\n','')
    ) INTO v_result
    FROM ONLY public.tenant_oidc_client_secrets AS secret
    JOIN ONLY public.identity_keyring_versions AS keyring
      ON keyring.key_version = secret.key_version
     AND keyring.retired_at IS NULL
    WHERE secret.tenant_id = v_tenant_id
      AND secret.provider_id = v_provider_id
      AND secret.revision = v_revision
      AND EXISTS (
        SELECT 1
        FROM ONLY public.tenant_federated_provider_policies AS policy
        WHERE policy.tenant_id = v_tenant_id
          AND policy.provider_id = v_provider_id
          AND policy.binding_id = v_binding_id
          AND policy.provider_kind = 'oidc'
      );
  ELSIF v_scope = 'platform' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      p_lookup -> 'provider',ARRAY['scope','providerId'],
      ARRAY['scope','providerId'],4096
    );
    v_provider_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,providerId}'
    );
    IF p_lookup ? 'admission' THEN
      PERFORM app.private_mfa_assert_json_object_v1(
        p_lookup -> 'admission',ARRAY['tenantId','bindingId'],
        ARRAY['tenantId','bindingId'],4096
      );
      IF jsonb_typeof(p_lookup -> 'bindingId') <> 'string' THEN
        RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
          USING ERRCODE = '22023';
      END IF;
      v_tenant_id := app.private_mfa_require_uuidv7_v1(
        p_lookup #>> '{admission,tenantId}'
      );
      v_binding_id := app.private_mfa_require_uuidv7_v1(
        p_lookup #>> '{admission,bindingId}'
      );
      IF v_binding_id IS DISTINCT FROM app.private_mfa_require_uuidv7_v1(
           p_lookup ->> 'bindingId'
         ) OR NOT EXISTS (
           SELECT 1
           FROM ONLY public.tenant_platform_auth_provider_bindings AS binding
           WHERE binding.tenant_id = v_tenant_id
             AND binding.id = v_binding_id
             AND binding.platform_provider_id = v_provider_id
         ) THEN
        RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
          USING ERRCODE = '22023';
      END IF;
    ELSIF jsonb_typeof(p_lookup -> 'bindingId') <> 'null' THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
    SELECT jsonb_build_object(
      'lookup',p_lookup,'secretId',secret.id::text,
      'keyVersion',secret.key_version,
      'nonce',replace(encode(secret.nonce,'base64'),E'\n',''),
      'ciphertext',replace(encode(secret.ciphertext,'base64'),E'\n','')
    ) INTO v_result
    FROM ONLY public.platform_oidc_client_secrets AS secret
    JOIN ONLY public.identity_keyring_versions AS keyring
      ON keyring.key_version = secret.key_version
     AND keyring.retired_at IS NULL
    WHERE secret.provider_id = v_provider_id
      AND secret.revision = v_revision;
  ELSE
    RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
      USING ERRCODE = '22023';
  END IF;
  RETURN v_result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.load_oidc_maintenance_client_secret_envelope_v1(
  p_lookup jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_scope text;
  v_kind text;
  v_tenant_id uuid;
  v_provider_id uuid;
  v_binding_id uuid;
  v_material_id uuid;
  v_family_id uuid;
  v_job_id uuid;
  v_revision bigint;
  v_claim_version bigint;
  v_refresh_generation bigint;
  v_attempt integer;
  v_observed_at timestamptz;
  v_material public.tenant_oidc_session_materials%ROWTYPE;
  v_job public.tenant_oidc_logout_retry_jobs%ROWTYPE;
  v_result jsonb;
BEGIN
  PERFORM app.private_mfa_assert_json_object_v1(
    p_lookup,
    ARRAY['provider','admission','bindingId','revision','kind','materialId',
      'sessionFamilyId','claimVersion','refreshGeneration','jobId','attempt'],
    ARRAY['provider','bindingId','revision','kind','materialId',
      'sessionFamilyId','claimVersion','refreshGeneration'],16384
  );
  v_scope := p_lookup #>> '{provider,scope}';
  v_kind := p_lookup ->> 'kind';
  v_revision := (p_lookup ->> 'revision')::bigint;
  v_material_id := app.private_mfa_require_uuidv7_v1(
    p_lookup ->> 'materialId'
  );
  v_family_id := app.private_mfa_require_uuidv7_v1(
    p_lookup ->> 'sessionFamilyId'
  );
  v_claim_version := (p_lookup ->> 'claimVersion')::bigint;
  v_refresh_generation := (p_lookup ->> 'refreshGeneration')::bigint;
  IF v_revision < 1 OR v_revision > 9000000000000000
     OR v_claim_version < 1 OR v_claim_version >= 9000000000000000
     OR v_refresh_generation < 1
     OR v_refresh_generation >= 9000000000000000
     OR v_material_id = v_family_id
     OR v_kind NOT IN ('refresh','logout_retry') THEN
    RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
      USING ERRCODE = '22023';
  END IF;
  IF v_kind = 'refresh' THEN
    IF p_lookup ? 'jobId' OR p_lookup ? 'attempt' THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    IF NOT p_lookup ?& ARRAY['jobId','attempt'] THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
    v_job_id := app.private_mfa_require_uuidv7_v1(p_lookup ->> 'jobId');
    v_attempt := (p_lookup ->> 'attempt')::integer;
    IF v_job_id IN (v_material_id,v_family_id)
       OR v_attempt NOT BETWEEN 1 AND 16 THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_scope = 'tenant' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      p_lookup -> 'provider',ARRAY['scope','tenantId','providerId','bindingId'],
      ARRAY['scope','tenantId','providerId','bindingId'],4096
    );
    IF p_lookup ? 'admission'
       OR jsonb_typeof(p_lookup -> 'bindingId') <> 'string' THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
    v_tenant_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,tenantId}'
    );
    v_provider_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,providerId}'
    );
    v_binding_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,bindingId}'
    );
    IF v_binding_id IS DISTINCT FROM app.private_mfa_require_uuidv7_v1(
         p_lookup ->> 'bindingId'
       ) THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_scope = 'platform' THEN
    PERFORM app.private_mfa_assert_json_object_v1(
      p_lookup -> 'provider',ARRAY['scope','providerId'],
      ARRAY['scope','providerId'],4096
    );
    v_provider_id := app.private_mfa_require_uuidv7_v1(
      p_lookup #>> '{provider,providerId}'
    );
    IF p_lookup ? 'admission' THEN
      PERFORM app.private_mfa_assert_json_object_v1(
        p_lookup -> 'admission',ARRAY['tenantId','bindingId'],
        ARRAY['tenantId','bindingId'],4096
      );
      IF jsonb_typeof(p_lookup -> 'bindingId') <> 'string' THEN
        RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
          USING ERRCODE = '22023';
      END IF;
      v_tenant_id := app.private_mfa_require_uuidv7_v1(
        p_lookup #>> '{admission,tenantId}'
      );
      v_binding_id := app.private_mfa_require_uuidv7_v1(
        p_lookup #>> '{admission,bindingId}'
      );
      IF v_binding_id IS DISTINCT FROM app.private_mfa_require_uuidv7_v1(
           p_lookup ->> 'bindingId'
         ) THEN
        RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
          USING ERRCODE = '22023';
      END IF;
    ELSIF jsonb_typeof(p_lookup -> 'bindingId') <> 'null' THEN
      RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
      USING ERRCODE = '22023';
  END IF;

  v_observed_at := date_trunc('microseconds',transaction_timestamp());
  IF v_kind = 'logout_retry' THEN
    -- Completion locks job before material. Take the same ordered shared locks
    -- so a completed/reclaimed lease cannot race an old secret projection.
    SELECT job.* INTO v_job
    FROM ONLY public.tenant_oidc_logout_retry_jobs AS job
    WHERE job.id = v_job_id
      AND job.material_id = v_material_id
      AND job.session_family_id = v_family_id
      AND job.state = 'claimed'
      AND job.attempt = v_attempt
      AND job.version = v_claim_version
      AND job.claim_expires_at > v_observed_at
    FOR SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  SELECT material.* INTO v_material
  FROM ONLY public.tenant_oidc_session_materials AS material
  WHERE material.id = v_material_id
    AND material.rotation_family_id = v_family_id
    AND material.provider_id = v_provider_id
    AND material.client_secret_revision = v_revision
    AND material.scrubbed_at IS NULL
    AND material.expires_at > v_observed_at
    AND CASE v_scope
      WHEN 'tenant' THEN material.authority = 'tenant_provider'
        AND material.tenant_id = v_tenant_id
        AND material.binding_id = v_binding_id
      ELSE CASE WHEN v_tenant_id IS NULL
        THEN material.authority = 'platform_provider'
          AND material.tenant_id IS NULL AND material.binding_id IS NULL
        ELSE material.authority = 'tenant_platform_provider'
          AND material.tenant_id = v_tenant_id
          AND material.binding_id = v_binding_id
      END
    END
    AND CASE v_kind
      WHEN 'refresh' THEN material.refresh_state = 'claimed'
        AND material.refresh_version = v_claim_version
        AND material.refresh_generation = v_refresh_generation
        AND material.refresh_claim_expires_at > v_observed_at
      ELSE material.refresh_generation = v_refresh_generation
        AND v_job.material_id = material.id
        AND v_job.tenant_id IS NOT DISTINCT FROM material.tenant_id
        AND v_job.authority = material.authority
        AND v_job.session_family_id = material.rotation_family_id
    END
  FOR SHARE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF v_scope = 'tenant' THEN
    SELECT jsonb_build_object(
      'lookup',p_lookup,'secretId',secret.id::text,
      'keyVersion',secret.key_version,
      'nonce',replace(encode(secret.nonce,'base64'),E'\n',''),
      'ciphertext',replace(encode(secret.ciphertext,'base64'),E'\n','')
    ) INTO v_result
    FROM ONLY public.tenant_oidc_client_secrets AS secret
    JOIN ONLY public.identity_keyring_versions AS keyring
      ON keyring.key_version = secret.key_version
     AND keyring.retired_at IS NULL
    WHERE secret.tenant_id = v_material.tenant_id
      AND secret.provider_id = v_material.provider_id
      AND secret.revision = v_material.client_secret_revision;
  ELSE
    SELECT jsonb_build_object(
      'lookup',p_lookup,'secretId',secret.id::text,
      'keyVersion',secret.key_version,
      'nonce',replace(encode(secret.nonce,'base64'),E'\n',''),
      'ciphertext',replace(encode(secret.ciphertext,'base64'),E'\n','')
    ) INTO v_result
    FROM ONLY public.platform_oidc_client_secrets AS secret
    JOIN ONLY public.identity_keyring_versions AS keyring
      ON keyring.key_version = secret.key_version
     AND keyring.retired_at IS NULL
    WHERE secret.provider_id = v_material.provider_id
      AND secret.revision = v_material.client_secret_revision;
  END IF;
  RETURN v_result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
  OR data_exception THEN
  RAISE EXCEPTION 'invalid OIDC maintenance secret lookup'
    USING ERRCODE = '22023';
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.load_oidc_maintenance_client_secret_envelope_v1(jsonb)
  OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION
