-- Bounded SAML material retention must not leave a scrubbed FK sentinel that
-- permanently wedges the generic authentication-session pruner.  The three
-- append-only guards below admit DELETE only while the worker-only pruner is
-- executing; runtime roles still have no table DML and cannot reach this path
-- by setting the custom GUC themselves.
CREATE OR REPLACE FUNCTION app.guard_federated_immutable_ledger_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting('app.auth_state_prune_v2',true) = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'federated authentication replay ledgers are immutable'
    USING ERRCODE = '55000';
END;
$function$;
--> statement-breakpoint

CREATE OR REPLACE FUNCTION app.guard_platform_saml_direct_runtime_write_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting('app.auth_state_prune_v2',true) = 'on' THEN
    RETURN OLD;
  END IF;
  IF current_setting('app.platform_saml_direct_runtime_write_v1',true) <> 'on' THEN
    RAISE EXCEPTION 'direct platform SAML runtime requires a protected ABI'
