CREATE OR REPLACE FUNCTION app.guard_platform_oidc_runtime_write_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting('app.auth_state_prune_v2',true) = 'on' THEN
    RETURN OLD;
  END IF;
  IF current_setting('app.platform_oidc_runtime_write_v1',true) <> 'on' THEN
    RAISE EXCEPTION 'direct platform OIDC runtime rows require a protected ABI'
      USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'direct platform OIDC runtime rows are archival'
      USING ERRCODE = '55000';
