-- Reinstall the legacy worker ABI with an ordered, purpose-bound SAML
-- dependency teardown.  Non-SAML sessions with protected state are skipped
-- instead of aborting and starving this batch; bare legacy sessions preserve
-- the predecessor behavior. Replay ledgers are removed only after the whole
-- rotation family has crossed the existing thirty-day retention boundary.
-- The SECURITY DEFINER owner receives only the two audit-export reference
-- columns needed to prove that a session family is no longer retained by an
-- export job. The runtime worker still has no direct table access.
GRANT SELECT (requester_session_id)
  ON TABLE public.tenant_audit_export_jobs, public.platform_audit_export_jobs
  TO periapsis_migrator;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.prune_expired_auth_state(
  p_per_class_batch_size integer
)
RETURNS TABLE (
  rate_limits_deleted integer,
  challenges_deleted integer,
  sessions_deleted integer
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  v_rate_limits_deleted integer := 0;
  v_challenges_deleted integer := 0;
  v_sessions_deleted integer := 0;
  v_session_ids uuid[] := ARRAY[]::uuid[];
  v_family_ids uuid[] := ARRAY[]::uuid[];
  v_family record;
BEGIN
  IF p_per_class_batch_size IS NULL
     OR p_per_class_batch_size NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'authentication cleanup per-class batch must be between 1 and 1000'
      USING ERRCODE = '22023';
  END IF;

  WITH candidates AS (
    SELECT stale.id
    FROM public.auth_rate_limits AS stale
    WHERE stale.window_expires_at <= transaction_timestamp()
      AND (stale.blocked_until IS NULL
        OR stale.blocked_until <= transaction_timestamp())
    ORDER BY greatest(
      stale.window_expires_at,
      coalesce(stale.blocked_until,stale.window_expires_at)
    ),stale.id
    LIMIT p_per_class_batch_size
    FOR UPDATE SKIP LOCKED
  )
  DELETE FROM public.auth_rate_limits AS stale
  USING candidates
  WHERE stale.id = candidates.id;
  GET DIAGNOSTICS v_rate_limits_deleted = ROW_COUNT;

  WITH candidates AS (
    SELECT stale.id
    FROM public.auth_challenges AS stale
    WHERE (stale.consumed_at IS NOT NULL
        OR stale.expires_at <= transaction_timestamp())
      AND greatest(
        stale.expires_at,coalesce(stale.consumed_at,stale.expires_at)
      ) <= transaction_timestamp() - interval '24 hours'
    ORDER BY greatest(
      stale.expires_at,coalesce(stale.consumed_at,stale.expires_at)
    ),stale.id
    LIMIT p_per_class_batch_size
    FOR UPDATE SKIP LOCKED
  )
  DELETE FROM public.auth_challenges AS stale
  USING candidates
  WHERE stale.id = candidates.id;
  GET DIAGNOSTICS v_challenges_deleted = ROW_COUNT;

  -- Batch in rotation-family units. A family is never split merely because the
  -- worker requested batch=1: switch ledgers reference both the source and the
  -- rotated session with RESTRICT FKs, so deleting either endpoint alone can
  -- permanently starve the oldest cleanup row.
  FOR v_family IN
    SELECT family.user_id,family.rotation_family_id,
      max(greatest(
        family.absolute_expires_at,
        coalesce(family.revoked_at,family.absolute_expires_at)
      )) AS retention_ready_at
    FROM public.auth_sessions AS family
    GROUP BY family.user_id,family.rotation_family_id
    HAVING bool_and(
      family.revoked_at IS NOT NULL
      OR family.idle_expires_at <= transaction_timestamp()
      OR family.absolute_expires_at <= transaction_timestamp()
    )
      AND max(greatest(
        family.absolute_expires_at,
        coalesce(family.revoked_at,family.absolute_expires_at)
      )) <= transaction_timestamp() - interval '30 days'
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.tenant_audit_export_jobs AS job
          ON job.requester_session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.platform_audit_export_jobs AS job
          ON job.requester_session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.platform_local_account_command_receipts AS receipt
          ON receipt.actor_session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.tenant_mfa_authority_anchors AS anchor
          ON anchor.session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.platform_ldap_session_provenance AS provenance
          ON provenance.session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.auth_sessions AS member
        JOIN public.tenant_post_primary_passkey_provenance AS provenance
          ON provenance.source_session_id = member.id
        WHERE member.user_id = family.user_id
          AND member.rotation_family_id = family.rotation_family_id
      )
      -- A live logout retry owns the encrypted OIDC material and must reach a
      -- terminal state before retention can remove the family. This lock-free
      -- filter is repeated after the family advisory below to close the race.
      AND NOT EXISTS (
        SELECT 1
        FROM public.tenant_oidc_logout_retry_jobs AS job
        WHERE job.session_family_id = family.rotation_family_id
          AND job.state IN ('pending','claimed')
      )
    ORDER BY retention_ready_at,family.user_id,family.rotation_family_id
    LIMIT p_per_class_batch_size
  LOOP
    -- Serialize retention with logout and refresh before locking any session.
    -- The family UUID is immutable and is the common purpose-bound advisory
    -- key across every consumer that can lock this family's material or jobs.
    PERFORM pg_advisory_xact_lock(hashtextextended(
      v_family.rotation_family_id::text,90174213
    ));
    IF EXISTS (
      SELECT 1
      FROM public.tenant_oidc_logout_retry_jobs AS job
      WHERE job.session_family_id = v_family.rotation_family_id
        AND job.state IN ('pending','claimed')
    ) THEN
      CONTINUE;
    END IF;
    SELECT coalesce(array_agg(locked.id ORDER BY locked.created_at,locked.id),
      ARRAY[]::uuid[])
      INTO v_family_ids
    FROM (
      SELECT member.id,member.created_at
      FROM public.auth_sessions AS member
      WHERE member.user_id = v_family.user_id
        AND member.rotation_family_id = v_family.rotation_family_id
      FOR UPDATE
    ) AS locked;
    v_session_ids := v_session_ids || v_family_ids;
  END LOOP;

  IF cardinality(v_session_ids) > 0 THEN
    PERFORM set_config('app.auth_state_prune_v2','on',true);
    PERFORM set_config('app.platform_saml_direct_runtime_write_v1','on',true);
    PERFORM set_config('app.platform_oidc_runtime_write_v1','on',true);

    -- Logout continuations own the material FK and must be retired first.
    DELETE FROM public.session_logout_continuations AS continuation
    WHERE (
        continuation.session_id = ANY(v_session_ids)
        OR EXISTS (
          SELECT 1 FROM public.tenant_saml_session_materials AS material
          WHERE material.id = continuation.tenant_saml_material_id
            AND material.session_id = ANY(v_session_ids)
        )
        OR EXISTS (
          SELECT 1 FROM public.platform_saml_session_materials AS material
          WHERE material.id = continuation.platform_saml_material_id
            AND material.session_id = ANY(v_session_ids)
        )
      );

    DELETE FROM public.tenant_oidc_logout_retry_jobs AS job
    WHERE job.material_id IN (
      SELECT material.id
      FROM public.tenant_oidc_session_materials AS material
      WHERE material.session_id = ANY(v_session_ids)
        OR material.rotation_family_id IN (
          SELECT session.rotation_family_id
          FROM public.auth_sessions AS session
          WHERE session.id = ANY(v_session_ids)
        )
    );
    DELETE FROM public.tenant_oidc_consumed_refresh_tokens AS consumed
    WHERE consumed.material_id IN (
      SELECT material.id
      FROM public.tenant_oidc_session_materials AS material
      WHERE material.session_id = ANY(v_session_ids)
        OR material.rotation_family_id IN (
          SELECT session.rotation_family_id
          FROM public.auth_sessions AS session
          WHERE session.id = ANY(v_session_ids)
        )
    );
    DELETE FROM public.tenant_oidc_logout_commands AS command
    WHERE command.session_id = ANY(v_session_ids)
      OR command.material_id IN (
        SELECT material.id
        FROM public.tenant_oidc_session_materials AS material
        WHERE material.session_id = ANY(v_session_ids)
      );
    DELETE FROM public.tenant_oidc_session_materials AS material
    WHERE material.session_id = ANY(v_session_ids)
      OR material.rotation_family_id IN (
        SELECT session.rotation_family_id
        FROM public.auth_sessions AS session
        WHERE session.id = ANY(v_session_ids)
      );

    DELETE FROM public.tenant_saml_logout_commands AS command
    WHERE command.session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_federated_session_revalidation_commands AS command
    WHERE command.session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_federated_authentication_applications AS application
    WHERE application.session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_saml_session_materials AS material
    WHERE material.session_id = ANY(v_session_ids);

    DELETE FROM public.platform_saml_tenant_switch_commands AS command
    WHERE command.source_session_id = ANY(v_session_ids)
      OR command.rotated_session_id = ANY(v_session_ids);
    DELETE FROM public.platform_saml_session_revalidation_commands AS command
    WHERE command.session_id = ANY(v_session_ids);
    DELETE FROM public.platform_saml_authentication_applications AS application
    WHERE application.session_id = ANY(v_session_ids)
      OR application.continuation_id IN (
        SELECT continuation.id
        FROM public.platform_saml_post_primary_continuations AS continuation
        WHERE continuation.source_session_id = ANY(v_session_ids)
      );
    DELETE FROM public.platform_saml_session_materials AS material
    WHERE material.session_id = ANY(v_session_ids)
      OR material.continuation_id IN (
        SELECT continuation.id
        FROM public.platform_saml_post_primary_continuations AS continuation
        WHERE continuation.source_session_id = ANY(v_session_ids)
      );
    DELETE FROM public.platform_saml_post_primary_totp_challenges AS challenge
    WHERE challenge.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_saml_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_saml_post_primary_continuation_evidence AS evidence
    WHERE evidence.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_saml_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_saml_post_primary_continuation_policy_pins AS pin
    WHERE pin.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_saml_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_saml_post_primary_continuations AS continuation
    WHERE continuation.source_session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_saml_evidence AS evidence
    WHERE evidence.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_saml_policy_pins AS pin
    WHERE pin.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_saml_provenance AS provenance
    WHERE provenance.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_saml_states AS state
    WHERE state.session_id = ANY(v_session_ids);

    DELETE FROM public.platform_oidc_tenant_switch_commands AS command
    WHERE command.source_session_id = ANY(v_session_ids)
      OR command.rotated_session_id = ANY(v_session_ids);
    DELETE FROM public.platform_oidc_session_revalidation_commands AS command
    WHERE command.session_id = ANY(v_session_ids);
    DELETE FROM public.platform_oidc_authentication_applications AS application
    WHERE application.session_id = ANY(v_session_ids)
      OR application.continuation_id IN (
        SELECT continuation.id
        FROM public.platform_post_primary_continuations AS continuation
        WHERE continuation.source_session_id = ANY(v_session_ids)
      );
    DELETE FROM public.platform_post_primary_totp_challenges AS challenge
    WHERE challenge.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_post_primary_continuation_evidence AS evidence
    WHERE evidence.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_post_primary_continuation_policy_pins AS pin
    WHERE pin.continuation_id IN (
      SELECT continuation.id
      FROM public.platform_post_primary_continuations AS continuation
      WHERE continuation.source_session_id = ANY(v_session_ids)
    );
    DELETE FROM public.platform_post_primary_continuations AS continuation
    WHERE continuation.source_session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_oidc_evidence AS evidence
    WHERE evidence.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_oidc_policy_pins AS pin
    WHERE pin.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_oidc_provenance AS provenance
    WHERE provenance.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_platform_oidc_states AS state
    WHERE state.session_id = ANY(v_session_ids);

    DELETE FROM public.tenant_platform_federated_session_revalidation_commands AS command
    WHERE command.session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_platform_oidc_authentication_applications AS application
    WHERE application.session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_post_primary_platform_federated_provenance AS provenance
    WHERE provenance.source_session_id = ANY(v_session_ids);
    DELETE FROM public.tenant_post_primary_federated_provenance AS provenance
    WHERE provenance.source_session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_tenant_platform_federated_evidence AS evidence
    WHERE evidence.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_tenant_platform_federated_provenance AS provenance
    WHERE provenance.session_id = ANY(v_session_ids);

    DELETE FROM public.auth_session_mfa_evidence AS evidence
    WHERE evidence.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_mfa_policy_pins AS pin
    WHERE pin.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_federated_provenance AS provenance
    WHERE provenance.session_id = ANY(v_session_ids);
    DELETE FROM public.auth_session_mfa_states AS state
    WHERE state.session_id = ANY(v_session_ids);

    DELETE FROM public.auth_sessions AS stale
    WHERE stale.id = ANY(v_session_ids);
    GET DIAGNOSTICS v_sessions_deleted = ROW_COUNT;
  END IF;

  RETURN QUERY SELECT v_rate_limits_deleted,v_challenges_deleted,
    v_sessions_deleted;
END;
$function$;
