-- Case-rooted DFIR task receipts reuse the immutable ticket command ledger.
-- The legacy integer result_version column records the receipt envelope
-- revision (always 1); the exact bigint Task version is part of the bounded,
-- server-owned result snapshot and is returned by the ABI.
CREATE FUNCTION app.private_case_dfir_task_snapshot_valid_v1(
  p_snapshot jsonb,
  p_tenant_id uuid,
  p_case_id uuid,
  p_task_id uuid,
  p_task_version bigint
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  task_snapshot jsonb;
  created_at_value timestamptz;
  updated_at_value timestamptz;
  completed_at_value timestamptz;
  directional_controls text := chr(8206) || chr(8207) ||
    chr(8234) || chr(8235) || chr(8236) || chr(8237) || chr(8238) ||
    chr(8294) || chr(8295) || chr(8296) || chr(8297);
  canonical_instant_pattern constant text :=
    '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?Z$';
BEGIN
  IF p_snapshot IS NULL
     OR jsonb_typeof(p_snapshot) <> 'object'
     OR pg_column_size(p_snapshot) > 16777216
     OR (SELECT count(*) FROM jsonb_object_keys(p_snapshot)) <> 2
     OR p_snapshot ->> 'kind' <> 'case_task'
     OR jsonb_typeof(p_snapshot -> 'task') <> 'object' THEN
    RETURN false;
  END IF;
  task_snapshot := p_snapshot -> 'task';
  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(task_snapshot) AS field(name)
    WHERE field.name <> ALL (ARRAY[
      'id','tenantId','caseId','title','description','status','priority',
      'assigneeId','operatorTeamId','dueAt','checklist','completedAt',
      'completedBy','completionData','commentIds','slaInstanceId',
      'createdAt','updatedAt','version'
    ]::text[])
  ) OR NOT task_snapshot ?& ARRAY[
    'id','tenantId','caseId','title','description','status','priority',
    'checklist','commentIds','createdAt','updatedAt','version'
  ]::text[]
     OR jsonb_typeof(task_snapshot -> 'id') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'tenantId') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'caseId') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'title') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'description') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'status') <> 'string'
     OR task_snapshot ->> 'status' NOT IN (
       'todo','in_progress','blocked','done','cancelled'
     )
     OR jsonb_typeof(task_snapshot -> 'priority') <> 'string'
     OR task_snapshot ->> 'priority' NOT IN ('low','medium','high','urgent')
     OR jsonb_typeof(task_snapshot -> 'checklist') <> 'array'
     OR jsonb_array_length(task_snapshot -> 'checklist') > 100
     OR pg_column_size(task_snapshot -> 'checklist') > 65536
     OR jsonb_typeof(task_snapshot -> 'commentIds') <> 'array'
     OR jsonb_array_length(task_snapshot -> 'commentIds') > 1000
     OR jsonb_typeof(task_snapshot -> 'createdAt') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'updatedAt') <> 'string'
     OR jsonb_typeof(task_snapshot -> 'version') <> 'number'
     OR octet_length(task_snapshot ->> 'title') NOT BETWEEN 1 AND 512
     OR btrim(task_snapshot ->> 'title') <> task_snapshot ->> 'title'
     OR task_snapshot ->> 'title' ~ '[[:cntrl:]]'
     OR translate(
       task_snapshot ->> 'title',directional_controls,''
     ) <> task_snapshot ->> 'title'
     OR octet_length(task_snapshot ->> 'description') > 16384
     OR btrim(task_snapshot ->> 'description') <>
       task_snapshot ->> 'description'
     OR replace(replace(
       task_snapshot ->> 'description',E'\n',''
     ),E'\t','') ~ '[[:cntrl:]]'
     OR translate(
       task_snapshot ->> 'description',directional_controls,''
     ) <> task_snapshot ->> 'description'
     OR task_snapshot ->> 'createdAt' !~ canonical_instant_pattern
     OR task_snapshot ->> 'updatedAt' !~ canonical_instant_pattern
     OR task_snapshot ->> 'id' !~
       '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR task_snapshot ->> 'tenantId' !~
       '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR task_snapshot ->> 'caseId' !~
       '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	 OR task_snapshot ->> 'version' !~ '^[1-9][0-9]{0,18}$'
     OR (task_snapshot ->> 'id')::uuid <> p_task_id
     OR (task_snapshot ->> 'tenantId')::uuid <> p_tenant_id
     OR (task_snapshot ->> 'caseId')::uuid <> p_case_id
     OR (task_snapshot ->> 'version')::bigint <> p_task_version
	 OR p_task_version NOT BETWEEN 1 AND 9007199254740991
     OR task_snapshot ? 'completionData'
        AND (
          jsonb_typeof(task_snapshot -> 'completionData') <> 'object'
          OR pg_column_size(task_snapshot -> 'completionData') > 65536
        )
     OR task_snapshot ? 'assigneeId'
        AND jsonb_typeof(task_snapshot -> 'assigneeId') <> 'string'
     OR task_snapshot ? 'operatorTeamId'
        AND jsonb_typeof(task_snapshot -> 'operatorTeamId') <> 'string'
     OR task_snapshot ? 'slaInstanceId'
        AND jsonb_typeof(task_snapshot -> 'slaInstanceId') <> 'string'
     OR task_snapshot ? 'dueAt'
        AND (
          jsonb_typeof(task_snapshot -> 'dueAt') <> 'string'
          OR task_snapshot ->> 'dueAt' !~ canonical_instant_pattern
        )
     OR task_snapshot ? 'completedAt'
        AND (
          jsonb_typeof(task_snapshot -> 'completedAt') <> 'string'
          OR task_snapshot ->> 'completedAt' !~ canonical_instant_pattern
        )
     OR task_snapshot ? 'completedBy'
        AND jsonb_typeof(task_snapshot -> 'completedBy') <> 'string' THEN
    RETURN false;
  END IF;

  IF task_snapshot ? 'assigneeId' AND (
    task_snapshot ->> 'assigneeId' !~
      '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    OR NOT task_snapshot ? 'operatorTeamId'
  ) OR task_snapshot ? 'operatorTeamId' AND task_snapshot ->> 'operatorTeamId' !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR task_snapshot ? 'slaInstanceId' AND task_snapshot ->> 'slaInstanceId' !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR task_snapshot ? 'completedBy' AND task_snapshot ->> 'completedBy' !~
    '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR task_snapshot ->> 'status' IN ('done','cancelled') AND (
    NOT task_snapshot ? 'completedAt' OR NOT task_snapshot ? 'completedBy'
  ) OR task_snapshot ->> 'status' NOT IN ('done','cancelled') AND (
    task_snapshot ? 'completedAt' OR task_snapshot ? 'completedBy'
    OR task_snapshot ? 'completionData'
  ) OR task_snapshot ->> 'status' = 'done' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(task_snapshot -> 'checklist') AS item
    WHERE item -> 'completed' IS DISTINCT FROM 'true'::jsonb
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(task_snapshot -> 'checklist') AS item
    WHERE jsonb_typeof(item) <> 'object'
      OR NOT item ?& ARRAY['id','title','completed']::text[]
      OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(item) AS field(name)
        WHERE field.name <> ALL (
          ARRAY['id','title','completed','completedAt','completedBy']::text[]
        )
      )
      OR jsonb_typeof(item -> 'id') <> 'string'
      OR item ->> 'id' !~
        '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR jsonb_typeof(item -> 'title') <> 'string'
      OR octet_length(item ->> 'title') NOT BETWEEN 1 AND 512
      OR btrim(item ->> 'title') <> item ->> 'title'
      OR item ->> 'title' ~ '[[:cntrl:]]'
      OR translate(item ->> 'title',directional_controls,'') <>
        item ->> 'title'
      OR jsonb_typeof(item -> 'completed') <> 'boolean'
      OR item -> 'completed' = 'true'::jsonb AND (
        jsonb_typeof(item -> 'completedAt') IS DISTINCT FROM 'string'
        OR item ->> 'completedAt' !~ canonical_instant_pattern
        OR jsonb_typeof(item -> 'completedBy') IS DISTINCT FROM 'string'
        OR item ->> 'completedBy' !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      OR item -> 'completed' = 'false'::jsonb AND (
        item ? 'completedAt' OR item ? 'completedBy'
      )
  ) OR jsonb_array_length(task_snapshot -> 'checklist') <> (
    SELECT count(DISTINCT item ->> 'id')::integer
    FROM jsonb_array_elements(task_snapshot -> 'checklist') AS item
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(task_snapshot -> 'commentIds') AS comment_id
    WHERE jsonb_typeof(comment_id) <> 'string'
      OR comment_id #>> '{}' !~
        '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) OR jsonb_array_length(task_snapshot -> 'commentIds') <> (
    SELECT count(DISTINCT comment_id)::integer
    FROM jsonb_array_elements_text(task_snapshot -> 'commentIds') AS comment_id
  ) THEN
    RETURN false;
  END IF;

  -- Cast under the fail-closed exception handler so malformed instants cannot
  -- become durable replay state even when the caller bypasses the HTTP codec.
  created_at_value := (task_snapshot ->> 'createdAt')::timestamptz;
  updated_at_value := (task_snapshot ->> 'updatedAt')::timestamptz;
  IF updated_at_value < created_at_value THEN
    RETURN false;
  END IF;
  IF task_snapshot ? 'dueAt' THEN
    PERFORM (task_snapshot ->> 'dueAt')::timestamptz;
  END IF;
  IF task_snapshot ? 'completedAt' THEN
    completed_at_value := (task_snapshot ->> 'completedAt')::timestamptz;
    IF completed_at_value < created_at_value
       OR completed_at_value > updated_at_value THEN
      RETURN false;
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(task_snapshot -> 'checklist') AS item
    WHERE item ? 'completedAt' AND (
      (item ->> 'completedAt')::timestamptz < created_at_value
      OR (item ->> 'completedAt')::timestamptz > updated_at_value
    )
  ) THEN
    RETURN false;
  END IF;
  RETURN true;
EXCEPTION
  WHEN others THEN
    RETURN false;
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.private_case_dfir_task_snapshot_valid_v1(
  jsonb,uuid,uuid,uuid,bigint
) OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.private_case_dfir_task_snapshot_valid_v1(
  jsonb,uuid,uuid,uuid,bigint
) FROM PUBLIC, periapsis_api, periapsis_worker, periapsis_notifier,
       periapsis_auditor, periapsis_audit_reader_owner,
