CREATE FUNCTION app.reserve_case_dfir_command_v1(
  p_command_id uuid,
  p_case_id uuid,
  p_operation text,
  p_resource_id uuid,
  p_result_version bigint,
  p_key_digest bytea,
  p_request_digest bytea,
  p_result_snapshot jsonb DEFAULT NULL
)
RETURNS TABLE(
  command_id uuid,
  result_resource_id uuid,
  result_version bigint,
  result_snapshot jsonb,
  replayed boolean
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_user uuid := app.context_user_id();
  actor_membership uuid := app.current_tenant_membership_id();
  expected_permission text;
  operation_is_create boolean;
  command_record public.ticket_commands%ROWTYPE;
  inserted_rows bigint;
  stored_version bigint;
BEGIN
  SELECT mapping.permission_key,mapping.is_create
  INTO expected_permission,operation_is_create
  FROM (VALUES
    ('case.dfir.task.create','dfir.task.manage',true),
    ('case.dfir.task.transition','dfir.task.manage',false),
    ('case.dfir.task.replace_details','dfir.task.manage',false),
    ('case.dfir.task.assign','dfir.task.manage',false),
    ('case.dfir.task.reschedule','dfir.task.manage',false),
    ('case.dfir.task.replace_checklist','dfir.task.manage',false),
    ('case.dfir.task.comments.replace','dfir.task.manage',false)
  ) AS mapping(operation,permission_key,is_create)
  WHERE mapping.operation=p_operation;

  IF p_command_id IS NULL
     OR uuid_extract_version(p_command_id) IS DISTINCT FROM 7
     OR p_case_id IS NULL
     OR uuid_extract_version(p_case_id) IS DISTINCT FROM 7
     OR p_resource_id IS NULL
     OR uuid_extract_version(p_resource_id) IS DISTINCT FROM 7
     OR expected_permission IS NULL
    OR p_result_version IS NULL
    OR p_result_version NOT BETWEEN 1 AND 9007199254740991
     OR operation_is_create AND p_result_version <> 1
     OR NOT operation_is_create AND p_result_version < 2
     OR p_key_digest IS NULL OR octet_length(p_key_digest) <> 32
     OR p_request_digest IS NULL OR octet_length(p_request_digest) <> 32 THEN
    RAISE EXCEPTION 'Case DFIR command binding is invalid'
      USING ERRCODE='22023';
  END IF;

  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active'
    AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case DFIR human authority is unavailable'
      USING ERRCODE='42501';
  END IF;

  -- Serialize the entire replay namespace before locking a resource. This
  -- prevents two different Case/task coordinates from using the same key and
  -- lets a waiting READ COMMITTED caller observe the winner's receipt.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    context_tenant::text || ':' || actor_membership::text || ':' ||
    p_operation || ':' || encode(p_key_digest,'hex'),
    82419731
  ));

  PERFORM 1
  FROM public.cases AS case_row
  WHERE case_row.tenant_id=context_tenant
    AND case_row.id=p_case_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case is unavailable' USING ERRCODE='P0002';
  END IF;
  IF NOT app.private_current_dfir_scope_allows_v1(
    expected_permission,p_case_id
  ) THEN
    RAISE EXCEPTION 'Case DFIR authority is required'
      USING ERRCODE='42501';
  END IF;
	IF NOT operation_is_create AND NOT EXISTS (
	  SELECT 1
	  FROM public.dfir_tasks AS task
	  WHERE task.tenant_id=context_tenant
	    AND task.case_id=p_case_id
	    AND task.alert_id IS NULL
	    AND task.id=p_resource_id
	) THEN
	  RAISE EXCEPTION 'Case DFIR task is unavailable' USING ERRCODE='P0002';
	END IF;

  SELECT command.* INTO command_record
  FROM public.ticket_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.actor_membership_id=actor_membership
    AND command.operation=p_operation
    AND command.key_digest=p_key_digest
  FOR UPDATE;
  IF FOUND THEN
    IF command_record.actor_user_id IS DISTINCT FROM actor_user
       OR command_record.request_digest IS DISTINCT FROM p_request_digest
       OR command_record.result_alert_id IS NOT NULL
       OR command_record.result_case_id IS DISTINCT FROM p_case_id
       OR NOT app.private_case_dfir_task_snapshot_valid_v1(
         command_record.result_metadata,context_tenant,p_case_id,
         p_resource_id,p_result_version
       ) THEN
      RAISE EXCEPTION 'Case DFIR idempotency key conflicts'
        USING ERRCODE='23505',
              CONSTRAINT='ticket_commands_replay_key';
    END IF;
    IF p_operation='case.dfir.task.comments.replace' AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
        command_record.result_metadata#>'{task,commentIds}'
      ) AS referenced(comment_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.ticket_comments AS comment
        WHERE comment.tenant_id=context_tenant
          AND comment.case_id=p_case_id
          AND comment.alert_id IS NULL
          AND comment.id=referenced.comment_id::uuid
      )
    ) THEN
      RAISE EXCEPTION 'Case task replay references are unavailable'
        USING ERRCODE='23503';
    END IF;
    stored_version :=
      (command_record.result_metadata #>> '{task,version}')::bigint;
    RETURN QUERY SELECT command_record.id,p_resource_id,stored_version,
      command_record.result_metadata,true;
    RETURN;
  END IF;

  -- A NULL snapshot is lookup-only. It must not create a placeholder receipt.
  IF p_result_snapshot IS NULL THEN
    RETURN QUERY SELECT p_command_id,p_resource_id,p_result_version,NULL::jsonb,
      false;
    RETURN;
  END IF;
  IF NOT app.private_case_dfir_task_snapshot_valid_v1(
    p_result_snapshot,context_tenant,p_case_id,p_resource_id,p_result_version
  ) OR operation_is_create AND (
    p_result_snapshot #>> '{task,status}' <> 'todo'
    OR p_result_snapshot #> '{task,commentIds}' <> '[]'::jsonb
    OR p_result_snapshot #> '{task,completedAt}' IS NOT NULL
    OR p_result_snapshot #> '{task,completedBy}' IS NOT NULL
    OR p_result_snapshot #> '{task,completionData}' IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Case DFIR result snapshot is invalid'
      USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      p_result_snapshot #> '{task,commentIds}'
    ) AS referenced(comment_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.ticket_comments AS comment
      WHERE comment.tenant_id=context_tenant
        AND comment.case_id=p_case_id
        AND comment.alert_id IS NULL
        AND comment.id=referenced.comment_id::uuid
    )
  ) OR p_result_snapshot #>> '{task,slaInstanceId}' IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.sla_instances AS instance
    WHERE instance.tenant_id=context_tenant
      AND instance.id=(p_result_snapshot #>> '{task,slaInstanceId}')::uuid
      AND instance.object_type='case'
      AND instance.object_id=p_case_id
  ) THEN
    RAISE EXCEPTION 'Case DFIR result references are unavailable for its root'
      USING ERRCODE='23503';
  END IF;
  IF p_result_snapshot #>> '{task,operatorTeamId}' IS NOT NULL AND (
    1 <> (
      SELECT count(*)
      FROM public.operator_team_assignment_epochs AS epoch
      WHERE epoch.tenant_id=context_tenant
        AND epoch.operator_team_id=
          (p_result_snapshot #>> '{task,operatorTeamId}')::uuid
        AND epoch.ended_at IS NULL
    ) OR p_result_snapshot #>> '{task,assigneeId}' IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.tenant_memberships AS membership
      JOIN public.operator_team_roster_entries AS roster
        ON roster.tenant_id=membership.tenant_id
       AND roster.membership_id=membership.id
      JOIN public.operator_team_assignment_epochs AS epoch
        ON epoch.tenant_id=roster.tenant_id
       AND epoch.id=roster.assignment_epoch_id
      JOIN public.tenant_authorization_sources AS source
        ON source.tenant_id=roster.tenant_id
       AND source.id=roster.source_id
      WHERE membership.tenant_id=context_tenant
        AND membership.user_id=
          (p_result_snapshot #>> '{task,assigneeId}')::uuid
        AND membership.status='active'
        AND epoch.operator_team_id=
          (p_result_snapshot #>> '{task,operatorTeamId}')::uuid
        AND epoch.ended_at IS NULL
        AND roster.revoked_at IS NULL
        AND (
          roster.expires_at IS NULL
          OR roster.expires_at > transaction_timestamp()
        )
        AND source.retired_at IS NULL
    )
  ) THEN
    RAISE EXCEPTION 'Case DFIR result assignment is unavailable'
      USING ERRCODE='23503';
  END IF;

  INSERT INTO public.ticket_commands (
    id,tenant_id,operation,actor_membership_id,actor_user_id,
    key_digest,request_digest,result_alert_id,result_case_id,
    result_version,result_metadata
  ) VALUES (
    p_command_id,context_tenant,p_operation,actor_membership,actor_user,
    p_key_digest,p_request_digest,NULL,p_case_id,1,p_result_snapshot
  )
  ON CONFLICT (
    tenant_id,actor_membership_id,operation,key_digest
  ) DO NOTHING;
  GET DIAGNOSTICS inserted_rows=ROW_COUNT;

  SELECT command.* INTO STRICT command_record
  FROM public.ticket_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.actor_membership_id=actor_membership
    AND command.operation=p_operation
    AND command.key_digest=p_key_digest
  FOR UPDATE;
  IF command_record.actor_user_id IS DISTINCT FROM actor_user
     OR command_record.request_digest IS DISTINCT FROM p_request_digest
     OR command_record.result_alert_id IS NOT NULL
     OR command_record.result_case_id IS DISTINCT FROM p_case_id
     OR NOT app.private_case_dfir_task_snapshot_valid_v1(
       command_record.result_metadata,context_tenant,p_case_id,
       p_resource_id,p_result_version
     ) THEN
    RAISE EXCEPTION 'Case DFIR idempotency key conflicts'
      USING ERRCODE='23505',CONSTRAINT='ticket_commands_replay_key';
  END IF;
  stored_version :=
    (command_record.result_metadata #>> '{task,version}')::bigint;
  RETURN QUERY SELECT command_record.id,p_resource_id,stored_version,
    command_record.result_metadata,inserted_rows=0;
END;
$function$;
