-- Existing rows must be proven exact before the trigger begins protecting
-- future direct writes. Unknown, duplicate, cross-tenant and wrong-root links
-- abort the rollout instead of being silently grandfathered.
DO $case_dfir_task_link_preflight$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.dfir_tasks AS task
    WHERE cardinality(task.comment_ids) IS DISTINCT FROM (
      SELECT count(DISTINCT comment_id)::integer
      FROM unnest(task.comment_ids) AS comment_id
    ) OR EXISTS (
      SELECT 1
      FROM unnest(task.comment_ids) AS referenced(comment_id)
      WHERE referenced.comment_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.ticket_comments AS comment
        WHERE comment.tenant_id=task.tenant_id
          AND comment.id=referenced.comment_id
          AND (
            task.alert_id IS NOT NULL
            AND comment.alert_id=task.alert_id
            AND comment.case_id IS NULL
            OR task.case_id IS NOT NULL
            AND comment.case_id=task.case_id
            AND comment.alert_id IS NULL
          )
      )
    )
  ) THEN
    RAISE EXCEPTION '0228 found an invalid DFIR task comment reference'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.dfir_tasks AS task
    WHERE task.sla_instance_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.sla_instances AS instance
        WHERE instance.tenant_id=task.tenant_id
          AND instance.id=task.sla_instance_id
          AND (
            task.alert_id IS NOT NULL
            AND instance.object_type='alert'
            AND instance.object_id=task.alert_id
            OR task.case_id IS NOT NULL
            AND instance.object_type='case'
            AND instance.object_id=task.case_id
          )
      )
  ) THEN
    RAISE EXCEPTION '0228 found an invalid DFIR task SLA reference'
      USING ERRCODE='23514';
  END IF;
END;
