CREATE FUNCTION app.validate_dfir_task_links_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF cardinality(NEW.comment_ids) IS DISTINCT FROM (
    SELECT count(DISTINCT comment_id)::integer
    FROM unnest(NEW.comment_ids) AS comment_id
  ) THEN
    RAISE EXCEPTION 'DFIR task comment references must be unique and non-null'
      USING ERRCODE='23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(NEW.comment_ids) AS referenced(comment_id)
    WHERE referenced.comment_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.ticket_comments AS comment
      WHERE comment.tenant_id=NEW.tenant_id
        AND comment.id=referenced.comment_id
        AND (
          NEW.alert_id IS NOT NULL
          AND comment.alert_id=NEW.alert_id
          AND comment.case_id IS NULL
          OR NEW.case_id IS NOT NULL
          AND comment.case_id=NEW.case_id
          AND comment.alert_id IS NULL
        )
    )
  ) THEN
    RAISE EXCEPTION 'DFIR task comment reference is unavailable for its root'
      USING ERRCODE='23503';
  END IF;
  IF NEW.sla_instance_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.sla_instances AS instance
    WHERE instance.tenant_id=NEW.tenant_id
      AND instance.id=NEW.sla_instance_id
      AND (
        NEW.alert_id IS NOT NULL
        AND instance.object_type='alert'
        AND instance.object_id=NEW.alert_id
        OR NEW.case_id IS NOT NULL
        AND instance.object_type='case'
        AND instance.object_id=NEW.case_id
      )
  ) THEN
    RAISE EXCEPTION 'DFIR task SLA reference is unavailable for its root'
      USING ERRCODE='23503';
  END IF;
  RETURN NEW;
END;
