DO $case_dfir_task_contract_readiness$
DECLARE
  reserve_proc regprocedure :=
    'app.reserve_case_dfir_command_v1(uuid,uuid,text,uuid,bigint,bytea,bytea,jsonb)'::regprocedure;
  helper_proc regprocedure :=
    'app.private_case_dfir_task_snapshot_valid_v1(jsonb,uuid,uuid,uuid,bigint)'::regprocedure;
  guard_proc regprocedure :=
    'app.validate_dfir_task_links_v1()'::regprocedure;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_proc AS procedure
    WHERE procedure.oid=reserve_proc
      AND procedure.prosecdef
      AND pg_get_userbyid(procedure.proowner)='periapsis_migrator'
      AND procedure.proconfig @> ARRAY[
        'search_path=pg_catalog, public, app'
      ]::text[]
  ) OR NOT has_function_privilege(
    'periapsis_api',reserve_proc,'EXECUTE'
  ) OR EXISTS (
    SELECT 1
    FROM pg_proc AS procedure
    CROSS JOIN LATERAL aclexplode(
      coalesce(procedure.proacl,acldefault('f',procedure.proowner))
    ) AS privilege
    WHERE procedure.oid IN (reserve_proc,helper_proc,guard_proc)
      AND privilege.privilege_type='EXECUTE'
      AND NOT (
        privilege.grantee=procedure.proowner
        OR procedure.oid=reserve_proc
           AND privilege.grantee='periapsis_api'::regrole::oid
      )
  ) OR NOT EXISTS (
    SELECT 1
    FROM pg_trigger AS trigger_row
    WHERE trigger_row.tgrelid='public.dfir_tasks'::regclass
      AND trigger_row.tgname='dfir_tasks_links_validate_v1'
      AND trigger_row.tgenabled='O'
      AND NOT trigger_row.tgisinternal
      AND trigger_row.tgfoid=guard_proc
  ) THEN
    RAISE EXCEPTION 'Case DFIR task runtime contract is not ready'
      USING ERRCODE='55000';
  END IF;
END;
