-- DFIR resource versions cross the JSON/OpenAPI boundary as exact integers.
-- Refuse an unsafe predecessor before replacing the four legacy bigint-wide
-- checks that were not tightened by the Alert DFIR completion migration.
DO $dfir_json_safe_version_preflight$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.dfir_iocs
    WHERE version NOT BETWEEN 1 AND 9007199254740991
  ) OR EXISTS (
    SELECT 1 FROM public.dfir_assets
    WHERE version NOT BETWEEN 1 AND 9007199254740991
  ) OR EXISTS (
    SELECT 1 FROM public.dfir_storage_objects
    WHERE version NOT BETWEEN 1 AND 9007199254740991
  ) OR EXISTS (
    SELECT 1 FROM public.dfir_timeline_events
    WHERE version NOT BETWEEN 1 AND 9007199254740991
  ) THEN
    RAISE EXCEPTION '0228 found a DFIR resource version outside the exact JSON integer range'
      USING ERRCODE='22003';
  END IF;
END;
