CREATE FUNCTION app.append_dfir_custody_event_v1(
  p_evidence_id uuid,
  p_expected_version bigint,
  p_custody_event_id uuid,
  p_action public.dfir_custody_action,
  p_reason text,
  p_state_value text,
  p_previous_hash bytea,
  p_event_hash bytea,
  p_occurred_at timestamp with time zone,
  p_audit_event_id uuid,
  p_activity_id uuid,
  p_outbox_event_id uuid,
  p_request_id uuid,
  p_correlation_id uuid,
  p_ip_address inet,
  p_user_agent text,
  p_authentication_method text
)
RETURNS TABLE(evidence_id uuid,evidence_version bigint,replayed boolean)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  target public.dfir_evidence%ROWTYPE;
  storage_record public.dfir_storage_objects%ROWTYPE;
  attachment_record public.dfir_attachments%ROWTYPE;
  replay_exists boolean;
  changes_storage boolean;
  changes_attachment boolean;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_api','member') THEN
    RAISE EXCEPTION 'DFIR custody append requires API authority'
      USING ERRCODE='42501';
  END IF;
  IF p_evidence_id IS NULL
     OR uuid_extract_version(p_evidence_id) IS DISTINCT FROM 7
     OR p_expected_version NOT BETWEEN 1 AND 999
     OR p_custody_event_id IS NULL
     OR uuid_extract_version(p_custody_event_id) IS DISTINCT FROM 7 THEN
    RAISE EXCEPTION 'DFIR custody input is invalid'
      USING ERRCODE='22023';
  END IF;
  SELECT evidence.* INTO target
  FROM public.dfir_evidence AS evidence
  WHERE evidence.tenant_id=context_tenant
    AND evidence.id=p_evidence_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR evidence was not found'
      USING ERRCODE='P0002';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.dfir_custody_events AS event
    WHERE event.tenant_id=context_tenant
      AND event.id=p_custody_event_id
  ) INTO replay_exists;
  IF replay_exists THEN
    IF target.version NOT BETWEEN 1 AND 1000 THEN
      RAISE EXCEPTION 'DFIR evidence revision is outside the custody snapshot range'
        USING ERRCODE='40001';
    END IF;
  ELSE
    IF target.version IS DISTINCT FROM p_expected_version
       OR target.version NOT BETWEEN 1 AND 999 THEN
      RAISE EXCEPTION 'DFIR evidence version conflict'
        USING ERRCODE='40001';
    END IF;
    changes_storage:=p_action IN (
      'scan_state_changed','destroyed','retention_changed',
      'legal_hold_placed','legal_hold_released'
    );
    changes_attachment:=p_action='scan_state_changed'
      AND p_state_value<>'deleted';
    IF changes_storage THEN
      SELECT storage.* INTO storage_record
      FROM public.dfir_storage_objects AS storage
      WHERE storage.tenant_id=context_tenant
        AND storage.id=target.storage_object_id
      FOR UPDATE;
      IF NOT FOUND
         OR storage_record.version NOT BETWEEN 1 AND 9007199254740990 THEN
        RAISE EXCEPTION 'DFIR storage revision cannot advance'
          USING ERRCODE='40001';
      END IF;
    END IF;
    IF changes_attachment THEN
      SELECT attachment.* INTO attachment_record
      FROM public.dfir_attachments AS attachment
      WHERE attachment.tenant_id=context_tenant
        AND attachment.storage_object_id=target.storage_object_id
      FOR UPDATE;
      IF NOT FOUND
         OR attachment_record.version NOT BETWEEN 1 AND 9007199254740990 THEN
        RAISE EXCEPTION 'DFIR attachment revision cannot advance'
          USING ERRCODE='40001';
      END IF;
    END IF;
  END IF;
  RETURN QUERY
  SELECT result.evidence_id,result.evidence_version,result.replayed
  FROM app.private_append_dfir_custody_event_legacy_v1(
    p_evidence_id,p_expected_version,p_custody_event_id,p_action,p_reason,
    p_state_value,p_previous_hash,p_event_hash,p_occurred_at,
    p_audit_event_id,p_activity_id,p_outbox_event_id,p_request_id,
    p_correlation_id,p_ip_address,p_user_agent,p_authentication_method
  ) AS result;
END;
$function$;
--> statement-breakpoint
