-- DFIR storage scan queue runtime. Upload prepare owns this dedicated outbox
-- event; notification and domain-event consumers must never consume it.
CREATE FUNCTION app.enqueue_dfir_storage_scan_v1(
  p_event_id uuid,
  p_storage_object_id uuid,
  p_declared_mime text,
  p_occurred_at timestamp with time zone,
  p_correlation_id uuid,
  p_causation_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_membership uuid := app.current_tenant_membership_id();
  target public.dfir_storage_objects%ROWTYPE;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR actor_membership IS NULL THEN
    RAISE EXCEPTION 'DFIR scan enqueue requires API authority'
      USING ERRCODE='42501';
  END IF;
  IF p_event_id IS NULL OR uuid_extract_version(p_event_id) IS DISTINCT FROM 7
     OR p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_correlation_id IS NULL
     OR uuid_extract_version(p_correlation_id) IS DISTINCT FROM 7
     OR p_causation_id IS NULL
     OR uuid_extract_version(p_causation_id) IS DISTINCT FROM 7
     OR p_event_id=ANY(ARRAY[p_storage_object_id,p_correlation_id,p_causation_id])
     OR p_declared_mime IS NULL
     OR octet_length(p_declared_mime) NOT BETWEEN 1 AND 512
     OR btrim(p_declared_mime)<>p_declared_mime
     OR p_declared_mime~'[[:cntrl:]]'
     OR p_occurred_at IS NULL
     OR p_occurred_at>transaction_timestamp()+interval '1 minute'
     OR p_occurred_at<transaction_timestamp()-interval '1 hour' THEN
    RAISE EXCEPTION 'DFIR scan enqueue input is invalid'
      USING ERRCODE='22023';
  END IF;

  SELECT storage.* INTO target
  FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=context_tenant
    AND storage.id=p_storage_object_id
  FOR UPDATE;
  IF NOT FOUND OR target.state<>'pending_upload'
     OR target.version<>1
     OR target.created_by_membership_id<>actor_membership
     OR target.created_at<>p_occurred_at
     OR target.content_sha256 IS NOT NULL
     OR target.size_bytes IS NOT NULL
     OR target.detected_mime IS NOT NULL
     OR target.verified_at IS NOT NULL
     OR 1<>(
       SELECT count(*)
       FROM public.dfir_attachments AS attachment
       WHERE attachment.tenant_id=context_tenant
         AND attachment.storage_object_id=target.id
         AND attachment.scan_state='pending_upload'
         AND attachment.visibility='private'
     ) THEN
    RAISE EXCEPTION 'DFIR scan enqueue projection is invalid'
      USING ERRCODE='55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.outbox_events AS cause
    WHERE cause.tenant_id=context_tenant
      AND cause.id=p_causation_id
      AND cause.aggregate_type='dfir_storage_object'
      AND cause.aggregate_id=target.id
      AND cause.event_type='dfir.attachment.prepared'
  ) THEN
    RAISE EXCEPTION 'DFIR scan enqueue causation is unavailable'
      USING ERRCODE='23503';
  END IF;

  INSERT INTO public.outbox_events (
    id,tenant_id,aggregate_type,aggregate_id,aggregate_version,event_type,
    schema_version,payload,deduplication_key,correlation_id,causation_id,
    actor_kind,actor_id,producer,maximum_audience,traceparent,tracestate,
    occurred_at,available_at,attempts,max_attempts
  ) VALUES (
    p_event_id,context_tenant,'dfir_storage_object',target.id,1,
    'dfir.storage.scan.requested',1,
    jsonb_build_object(
      'tenantId',context_tenant,
      'resourceId',target.id,
      'declaredMime',p_declared_mime
    ),
    'dfir-scan:'||target.id::text,p_correlation_id,p_causation_id,
    'system',NULL,'api','operator',
    nullif(current_setting('app.traceparent',true),''),
    nullif(current_setting('app.tracestate',true),''),
    p_occurred_at,p_occurred_at,0,12
  );
  RETURN true;
END;
$function$;
