CREATE FUNCTION app.claim_dfir_storage_scan_v1(
  p_worker_id uuid,
  p_limit integer,
  p_lease_seconds integer,
  p_now timestamp with time zone
)
RETURNS TABLE(
  event_id uuid,tenant_id uuid,storage_object_id uuid,correlation_id uuid,
  lease_token uuid,attempt integer,maximum_attempts integer,
  execute_attempt boolean,lease_until timestamp with time zone,
  declared_mime text,bucket text,object_key text,original_filename text,
  classification text,expected_size_bytes bigint,
  upload_expires_at timestamp with time zone,created_by_membership_id uuid,
  created_at timestamp with time zone,updated_at timestamp with time zone,
  state text,content_sha256 bytea,size_bytes bigint,detected_mime text,
  verified_at timestamp with time zone,retention_until timestamp with time zone,
  legal_hold boolean,storage_version bigint
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR scan claim requires worker role'
      USING ERRCODE='42501';
  END IF;
  IF p_worker_id IS NULL OR uuid_extract_version(p_worker_id) IS DISTINCT FROM 7
     OR p_limit NOT BETWEEN 1 AND 16
     OR p_lease_seconds NOT BETWEEN 30 AND 1800
     OR p_now IS NULL
     OR p_now<transaction_timestamp()-interval '1 minute'
     OR p_now>transaction_timestamp()+interval '1 minute' THEN
    RAISE EXCEPTION 'DFIR scan claim input is invalid'
      USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.outbox_events AS queued
    WHERE queued.event_type='dfir.storage.scan.requested'
      AND queued.processed_at IS NULL
      AND (
        queued.schema_version IS DISTINCT FROM 1
        OR queued.aggregate_type IS DISTINCT FROM 'dfir_storage_object'
        OR queued.aggregate_version IS DISTINCT FROM 1
        OR queued.max_attempts IS DISTINCT FROM 12
        OR queued.attempts NOT BETWEEN 0 AND queued.max_attempts
        OR queued.correlation_id IS NULL
        OR uuid_extract_version(queued.correlation_id) IS DISTINCT FROM 7
        OR queued.causation_id IS NULL
        OR uuid_extract_version(queued.causation_id) IS DISTINCT FROM 7
        OR queued.actor_kind IS DISTINCT FROM 'system'
        OR queued.actor_id IS NOT NULL
        OR queued.producer IS DISTINCT FROM 'api'
        OR queued.maximum_audience IS DISTINCT FROM 'operator'
        OR jsonb_typeof(queued.payload) IS DISTINCT FROM 'object'
        OR (SELECT count(*) FROM jsonb_object_keys(queued.payload)) IS DISTINCT FROM 3::bigint
        OR queued.payload->>'tenantId' IS DISTINCT FROM queued.tenant_id::text
        OR queued.payload->>'resourceId' IS DISTINCT FROM queued.aggregate_id::text
        OR queued.payload->>'declaredMime' IS NULL
        OR octet_length(queued.payload->>'declaredMime') NOT BETWEEN 1 AND 512
        OR btrim(queued.payload->>'declaredMime')<>queued.payload->>'declaredMime'
        OR queued.payload->>'declaredMime'~'[[:cntrl:]]'
        OR NOT EXISTS (
          SELECT 1
          FROM public.dfir_storage_objects AS storage
          WHERE storage.tenant_id=queued.tenant_id
            AND storage.id=queued.aggregate_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'DFIR scan queue contains an invalid event'
      USING ERRCODE='55000';
  END IF;

  RETURN QUERY
  WITH candidate AS MATERIALIZED (
    SELECT queued.id,queued.attempts AS prior_attempts,queued.max_attempts,
           storage.state,storage.upload_expires_at
    FROM public.outbox_events AS queued
    JOIN public.dfir_storage_objects AS storage
      ON storage.tenant_id=queued.tenant_id
     AND storage.id=queued.aggregate_id
    WHERE queued.event_type='dfir.storage.scan.requested'
      AND queued.schema_version=1
      AND queued.processed_at IS NULL
      AND queued.dead_lettered_at IS NULL
      AND queued.available_at<=p_now
      AND queued.attempts<=queued.max_attempts
      AND (queued.lease_until IS NULL OR queued.lease_until<=p_now)
      AND (storage.cleanup_lease_expires_at IS NULL
        OR storage.cleanup_lease_expires_at<=p_now)
    ORDER BY queued.available_at,queued.occurred_at,queued.id
    LIMIT p_limit
    FOR UPDATE OF queued,storage SKIP LOCKED
  ), claimed AS (
    UPDATE public.outbox_events AS queued
    SET attempts=least(candidate.prior_attempts+1,candidate.max_attempts),
        locked_at=p_now,
        locked_by=p_worker_id::text,
        lease_token=uuidv7(),
        lease_until=p_now+make_interval(secs=>p_lease_seconds),
        last_error=NULL,
        failure_category=NULL
    FROM candidate
    WHERE queued.id=candidate.id
    RETURNING queued.*,candidate.prior_attempts,
      candidate.state AS claimed_state,
      candidate.upload_expires_at AS claimed_upload_expires_at
  )
  SELECT claimed.id,claimed.tenant_id,claimed.aggregate_id,
         claimed.correlation_id,claimed.lease_token,claimed.attempts,
         claimed.max_attempts,
         (claimed.prior_attempts<claimed.max_attempts
           OR claimed.claimed_state='pending_upload'
              AND claimed.claimed_upload_expires_at>p_now),
         claimed.lease_until,claimed.payload->>'declaredMime',
         storage.bucket,storage.object_key,storage.original_filename,
         storage.classification::text,storage.expected_size_bytes,
         storage.upload_expires_at,storage.created_by_membership_id,
         storage.created_at,storage.updated_at,storage.state::text,
         storage.content_sha256,storage.size_bytes,storage.detected_mime,
         storage.verified_at,storage.retention_until,storage.legal_hold,
         storage.version
  FROM claimed
  JOIN public.dfir_storage_objects AS storage
    ON storage.tenant_id=claimed.tenant_id
   AND storage.id=claimed.aggregate_id
  ORDER BY claimed.available_at,claimed.occurred_at,claimed.id;
END;
$function$;
--> statement-breakpoint
