-- A later link-lifecycle guard preserves this cap for new IOC/asset shares.
-- Refuse to activate the scan runtime when historical fan-out already exceeds
-- the amount one fenced transition can project atomically.
DO $dfir_scan_root_fanout_preflight$
BEGIN
  IF EXISTS (
    WITH roots AS (
      SELECT attachment.tenant_id,attachment.id AS attachment_id,
             'alert'::text AS root_kind,attachment.alert_id AS root_id
      FROM public.dfir_attachments AS attachment
      WHERE attachment.subject_kind='alert'
      UNION
      SELECT attachment.tenant_id,attachment.id,'case',attachment.case_id
      FROM public.dfir_attachments AS attachment
      WHERE attachment.subject_kind='case'
      UNION
      SELECT attachment.tenant_id,attachment.id,
             CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
             coalesce(link.alert_id,link.case_id)
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_iocs AS resource
        ON resource.tenant_id=attachment.tenant_id
       AND resource.id=attachment.ioc_id AND resource.archived_at IS NULL
      JOIN public.dfir_ioc_links AS link
        ON link.tenant_id=resource.tenant_id AND link.ioc_id=resource.id
      WHERE attachment.subject_kind='ioc'
      UNION
      SELECT attachment.tenant_id,attachment.id,
             CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
             coalesce(link.alert_id,link.case_id)
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_assets AS resource
        ON resource.tenant_id=attachment.tenant_id
       AND resource.id=attachment.asset_id AND resource.archived_at IS NULL
      JOIN public.dfir_asset_links AS link
        ON link.tenant_id=resource.tenant_id AND link.asset_id=resource.id
      WHERE attachment.subject_kind='asset'
      UNION
      SELECT attachment.tenant_id,attachment.id,
             CASE WHEN evidence.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
             coalesce(evidence.alert_id,evidence.case_id)
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_evidence AS evidence
        ON evidence.tenant_id=attachment.tenant_id
       AND evidence.id=attachment.evidence_id AND NOT evidence.destroyed
      WHERE attachment.subject_kind='evidence'
      UNION
      SELECT attachment.tenant_id,attachment.id,
             CASE WHEN task.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
             coalesce(task.alert_id,task.case_id)
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_tasks AS task
        ON task.tenant_id=attachment.tenant_id AND task.id=attachment.task_id
      WHERE attachment.subject_kind='task'
      UNION
      SELECT attachment.tenant_id,attachment.id,'alert',link.source_alert_id
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_attachment_case_links AS link
        ON link.tenant_id=attachment.tenant_id
       AND link.attachment_id=attachment.id
      UNION
      SELECT attachment.tenant_id,attachment.id,'case',link.case_id
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_attachment_case_links AS link
        ON link.tenant_id=attachment.tenant_id
       AND link.attachment_id=attachment.id
    )
    SELECT 1 FROM roots
    WHERE root_id IS NOT NULL
    GROUP BY tenant_id,attachment_id
    HAVING count(*)>64
  ) THEN
    RAISE EXCEPTION '0228 found a DFIR attachment with excessive root fan-out'
      USING ERRCODE='54000';
  END IF;
END;
$dfir_scan_root_fanout_preflight$;
--> statement-breakpoint

CREATE FUNCTION app.private_append_dfir_scan_ticket_activity_v1(
  p_tenant_id uuid,
  p_root_kind public.ticket_aggregate_kind,
  p_root_id uuid,
  p_attachment_id uuid,
  p_storage_object_id uuid,
  p_next_state public.dfir_scan_state,
  p_resource_version bigint,
  p_occurred_at timestamp with time zone
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  activity_id uuid := uuidv7();
  activity_sequence bigint;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member')
     OR p_tenant_id IS NULL
     OR uuid_extract_version(p_tenant_id) IS DISTINCT FROM 7
     OR p_root_kind NOT IN ('alert','case')
     OR p_root_id IS NULL OR uuid_extract_version(p_root_id) IS DISTINCT FROM 7
     OR p_attachment_id IS NULL
     OR uuid_extract_version(p_attachment_id) IS DISTINCT FROM 7
     OR p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_next_state IS NULL
     OR p_resource_version NOT BETWEEN 2 AND 9007199254740991
     OR p_occurred_at IS NULL THEN
    RAISE EXCEPTION 'DFIR scan ticket activity input is invalid'
      USING ERRCODE='22023';
  END IF;
  IF p_root_kind='alert' THEN
    PERFORM 1 FROM public.alerts AS alert
    WHERE alert.tenant_id=p_tenant_id AND alert.id=p_root_id
      AND alert.deleted_at IS NULL
    FOR UPDATE;
  ELSE
    PERFORM 1 FROM public.cases AS case_record
    WHERE case_record.tenant_id=p_tenant_id AND case_record.id=p_root_id
    FOR UPDATE;
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR scan ticket root is unavailable'
      USING ERRCODE='55000';
  END IF;
  SELECT coalesce(max(activity.sequence),0)::bigint+1
  INTO activity_sequence
  FROM public.ticket_activities AS activity
  WHERE activity.tenant_id=p_tenant_id
    AND (
      p_root_kind='alert' AND activity.alert_id=p_root_id
      OR p_root_kind='case' AND activity.case_id=p_root_id
    );
  IF activity_sequence NOT BETWEEN 1 AND 2147483647 THEN
    RAISE EXCEPTION 'DFIR scan ticket activity sequence is exhausted'
      USING ERRCODE='54000';
  END IF;
  IF activity_id=ANY(ARRAY[p_attachment_id,p_storage_object_id]) THEN
    RAISE EXCEPTION 'DFIR scan ticket activity identity collided'
      USING ERRCODE='55000';
  END IF;
  INSERT INTO public.ticket_activities (
    id,tenant_id,alert_id,case_id,sequence,kind,summary,
    actor_principal_kind,origin,details,occurred_at
  ) VALUES (
    activity_id,p_tenant_id,
    CASE WHEN p_root_kind='alert' THEN p_root_id END,
    CASE WHEN p_root_kind='case' THEN p_root_id END,
    activity_sequence::integer,'dfir.attachment.scan_state_changed',
    'DFIR attachment scan state changed','system','system',
    jsonb_build_object(
      'attachmentId',p_attachment_id,
      'resourceVersion',p_resource_version,
      'state',p_next_state,
      'contentRedacted',true
    ),p_occurred_at
  );
  RETURN activity_id;
END;
$function$;
--> statement-breakpoint
