CREATE FUNCTION app.advance_dfir_storage_scan_job_v1(
  p_event_id uuid,
  p_lease_token uuid,
  p_storage_object_id uuid,
  p_expected_version bigint,
  p_next_state public.dfir_scan_state,
  p_content_sha256 bytea,
  p_size_bytes bigint,
  p_detected_mime text,
  p_transitioned_at timestamp with time zone,
  p_operation_id uuid,
  p_request_id uuid,
  p_audit_event_id uuid,
  p_outbox_event_id uuid,
  p_failure_category text,
  p_complete_job boolean,
  p_file_type_class text DEFAULT NULL,
  p_file_type_reason text DEFAULT NULL
)
RETURNS TABLE(
  storage_object_id uuid,tenant_id uuid,bucket text,object_key text,
  original_filename text,classification text,expected_size_bytes bigint,
  upload_expires_at timestamp with time zone,created_by_membership_id uuid,
  created_at timestamp with time zone,updated_at timestamp with time zone,
  state text,content_sha256 bytea,size_bytes bigint,detected_mime text,
  verified_at timestamp with time zone,retention_until timestamp with time zone,
  legal_hold boolean,storage_version bigint
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  job public.outbox_events%ROWTYPE;
  target public.dfir_storage_objects%ROWTYPE;
  evidence_record public.dfir_evidence%ROWTYPE;
  attachment_record public.dfir_attachments%ROWTYPE;
  bound_evidence_id uuid;
  alert_root_ids uuid[] := ARRAY[]::uuid[];
  case_root_ids uuid[] := ARRAY[]::uuid[];
  root_id uuid;
  root_count integer;
  next_version bigint;
  next_evidence_version bigint;
  custody_hash bytea;
  attachment_rows bigint;
  effect_payload jsonb;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR scan transition requires worker role'
      USING ERRCODE='42501';
  END IF;
  IF p_event_id IS NULL OR uuid_extract_version(p_event_id) IS DISTINCT FROM 7
     OR p_lease_token IS NULL OR uuid_extract_version(p_lease_token) IS DISTINCT FROM 7
     OR p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_expected_version NOT BETWEEN 1 AND 9007199254740990
     OR p_next_state IS NULL OR p_transitioned_at IS NULL
     OR p_transitioned_at>transaction_timestamp()+interval '1 minute'
     OR p_operation_id IS NULL OR uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
     OR p_request_id IS NULL OR uuid_extract_version(p_request_id) IS DISTINCT FROM 7
     OR p_audit_event_id IS NULL OR uuid_extract_version(p_audit_event_id) IS DISTINCT FROM 7
     OR p_outbox_event_id IS NULL OR uuid_extract_version(p_outbox_event_id) IS DISTINCT FROM 7
     OR p_operation_id=ANY(ARRAY[p_request_id,p_audit_event_id,p_outbox_event_id])
     OR p_request_id=ANY(ARRAY[p_audit_event_id,p_outbox_event_id])
     OR p_audit_event_id=p_outbox_event_id
     OR p_event_id=ANY(ARRAY[p_operation_id,p_request_id,p_audit_event_id,p_outbox_event_id])
     OR p_lease_token=ANY(ARRAY[p_operation_id,p_request_id,p_audit_event_id,p_outbox_event_id])
     OR p_complete_job IS NULL
     OR p_failure_category IS NOT NULL AND (
       p_failure_category!~'^[a-z][a-z0-9_]{0,63}$'
     )
     OR (p_file_type_class IS NULL)<>(p_file_type_reason IS NULL)
     OR p_file_type_class IS NOT NULL AND p_file_type_class NOT IN (
       'passive','generic_binary','active_content','executable','script',
       'suspicious_mismatch','suspicious_content','suspicious_polyglot','unknown'
     )
     OR p_file_type_reason IS NOT NULL AND p_file_type_reason NOT IN (
       'consistent_passive','consistent_generic_binary','invalid_mime',
       'unknown_mime','active_content','executable','script','mime_mismatch',
       'invalid_content_prefix','content_mismatch','suspicious_content',
       'suspicious_polyglot'
     ) THEN
    RAISE EXCEPTION 'DFIR scan transition input is invalid'
      USING ERRCODE='22023';
  END IF;

  SELECT queued.* INTO job
  FROM public.outbox_events AS queued
  WHERE queued.id=p_event_id
  FOR UPDATE;
  IF NOT FOUND
     OR job.event_type IS DISTINCT FROM 'dfir.storage.scan.requested'
     OR job.schema_version IS DISTINCT FROM 1
     OR job.processed_at IS NOT NULL
     OR job.dead_lettered_at IS NOT NULL
     OR job.aggregate_type IS DISTINCT FROM 'dfir_storage_object'
     OR job.aggregate_id IS DISTINCT FROM p_storage_object_id
     OR job.lease_token IS DISTINCT FROM p_lease_token
     OR job.lease_until IS NULL
     OR job.lease_until<=transaction_timestamp()
     OR job.attempts NOT BETWEEN 1 AND job.max_attempts
     OR job.correlation_id IS NULL THEN
    RAISE EXCEPTION 'DFIR scan transition lease is stale'
      USING ERRCODE='40001';
  END IF;

  SELECT attachment.* INTO attachment_record
  FROM public.dfir_attachments AS attachment
  WHERE attachment.tenant_id=job.tenant_id
    AND attachment.storage_object_id=p_storage_object_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR scan attachment projection is unavailable'
      USING ERRCODE='55000';
  END IF;

  -- Resolve the active sharing graph once, then lock roots in deterministic
  -- alert/case and UUID order before any mutable projection is changed.
  WITH roots AS (
    SELECT 'alert'::text AS root_kind,attachment.alert_id AS root_id
    FROM public.dfir_attachments AS attachment
    WHERE attachment.tenant_id=job.tenant_id
      AND attachment.id=attachment_record.id
      AND attachment.subject_kind='alert'
    UNION
    SELECT 'case',attachment.case_id
    FROM public.dfir_attachments AS attachment
    WHERE attachment.tenant_id=job.tenant_id
      AND attachment.id=attachment_record.id
      AND attachment.subject_kind='case'
    UNION
    SELECT CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(link.alert_id,link.case_id)
    FROM public.dfir_ioc_links AS link
    JOIN public.dfir_iocs AS resource
      ON resource.tenant_id=link.tenant_id AND resource.id=link.ioc_id
     AND resource.archived_at IS NULL
    WHERE attachment_record.subject_kind='ioc'
      AND link.tenant_id=job.tenant_id
      AND link.ioc_id=attachment_record.ioc_id
    UNION
    SELECT CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(link.alert_id,link.case_id)
    FROM public.dfir_asset_links AS link
    JOIN public.dfir_assets AS resource
      ON resource.tenant_id=link.tenant_id AND resource.id=link.asset_id
     AND resource.archived_at IS NULL
    WHERE attachment_record.subject_kind='asset'
      AND link.tenant_id=job.tenant_id
      AND link.asset_id=attachment_record.asset_id
    UNION
    SELECT CASE WHEN evidence.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(evidence.alert_id,evidence.case_id)
    FROM public.dfir_evidence AS evidence
    WHERE attachment_record.subject_kind='evidence'
      AND evidence.tenant_id=job.tenant_id
      AND evidence.id=attachment_record.evidence_id
      AND NOT evidence.destroyed
    UNION
    SELECT CASE WHEN task.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(task.alert_id,task.case_id)
    FROM public.dfir_tasks AS task
    WHERE attachment_record.subject_kind='task'
      AND task.tenant_id=job.tenant_id
      AND task.id=attachment_record.task_id
    UNION
    SELECT 'alert',link.source_alert_id
    FROM public.dfir_attachment_case_links AS link
    WHERE link.tenant_id=job.tenant_id
      AND link.attachment_id=attachment_record.id
    UNION
    SELECT 'case',link.case_id
    FROM public.dfir_attachment_case_links AS link
    WHERE link.tenant_id=job.tenant_id
      AND link.attachment_id=attachment_record.id
  )
  SELECT
    coalesce(array_agg(resolved.root_id ORDER BY resolved.root_id)
      FILTER (WHERE resolved.root_kind='alert'),ARRAY[]::uuid[]),
    coalesce(array_agg(resolved.root_id ORDER BY resolved.root_id)
      FILTER (WHERE resolved.root_kind='case'),ARRAY[]::uuid[]),
    count(*)::integer
  INTO alert_root_ids,case_root_ids,root_count
  FROM roots AS resolved
  WHERE resolved.root_id IS NOT NULL;
  IF root_count NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'DFIR scan attachment root set is invalid'
      USING ERRCODE='55000';
  END IF;
  FOREACH root_id IN ARRAY alert_root_ids LOOP
    PERFORM 1 FROM public.alerts AS alert
    WHERE alert.tenant_id=job.tenant_id AND alert.id=root_id
      AND alert.deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR scan alert root is unavailable'
        USING ERRCODE='55000';
    END IF;
  END LOOP;
  FOREACH root_id IN ARRAY case_root_ids LOOP
    PERFORM 1 FROM public.cases AS case_record
    WHERE case_record.tenant_id=job.tenant_id AND case_record.id=root_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR scan case root is unavailable'
        USING ERRCODE='55000';
    END IF;
  END LOOP;

  SELECT evidence.id INTO bound_evidence_id
  FROM public.dfir_evidence AS evidence
  WHERE evidence.tenant_id=job.tenant_id
    AND evidence.storage_object_id=p_storage_object_id;
  IF bound_evidence_id IS NOT NULL THEN
    SELECT evidence.* INTO evidence_record
    FROM public.dfir_evidence AS evidence
    WHERE evidence.tenant_id=job.tenant_id
      AND evidence.id=bound_evidence_id
    FOR UPDATE;
  END IF;
  SELECT storage.* INTO target
  FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=job.tenant_id
    AND storage.id=p_storage_object_id
  FOR UPDATE;
  IF NOT FOUND
     OR target.cleanup_lease_expires_at>transaction_timestamp()
     OR target.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'DFIR scan storage fence is stale'
      USING ERRCODE='40001';
  END IF;
  IF target.expected_size_bytes NOT BETWEEN 1 AND 5000000000
     OR p_transitioned_at<target.updated_at
     OR target.version NOT BETWEEN 1 AND 9007199254740990
     OR attachment_record.scan_state IS DISTINCT FROM target.state
     OR attachment_record.version IS DISTINCT FROM target.version
     OR attachment_record.original_filename IS DISTINCT FROM target.original_filename THEN
    RAISE EXCEPTION 'DFIR scan storage projection is invalid'
      USING ERRCODE='55000';
  END IF;
  IF NOT (CASE target.state
    WHEN 'pending_upload' THEN p_next_state='uploaded'
    WHEN 'uploaded' THEN p_next_state='verifying'
    WHEN 'verifying' THEN p_next_state IN ('quarantined','rejected')
    WHEN 'quarantined' THEN p_next_state='scanning'
    WHEN 'scanning' THEN p_next_state IN ('available','rejected','scan_failed')
    WHEN 'scan_failed' THEN p_next_state='scanning'
    ELSE false END) THEN
    RAISE EXCEPTION 'DFIR scan state transition is invalid'
      USING ERRCODE='22023';
  END IF;
  IF p_next_state IN ('available','rejected') AND NOT p_complete_job
     OR p_next_state NOT IN ('available','rejected','scan_failed') AND p_complete_job
     OR p_next_state='scan_failed'
        AND p_complete_job<>(job.attempts>=job.max_attempts) THEN
    RAISE EXCEPTION 'DFIR scan terminal state and queue completion disagree'
      USING ERRCODE='22023';
  END IF;
  IF target.state='verifying' AND p_next_state='quarantined' THEN
    IF p_content_sha256 IS NULL OR octet_length(p_content_sha256)<>32
       OR p_size_bytes IS DISTINCT FROM target.expected_size_bytes
       OR p_size_bytes NOT BETWEEN 1 AND 5000000000
       OR p_detected_mime IS NULL
       OR octet_length(p_detected_mime) NOT BETWEEN 3 AND 512 THEN
      RAISE EXCEPTION 'DFIR verified content projection is invalid'
        USING ERRCODE='22023';
    END IF;
  ELSIF p_content_sha256 IS DISTINCT FROM target.content_sha256
        OR p_size_bytes IS DISTINCT FROM target.size_bytes
        OR p_detected_mime IS DISTINCT FROM target.detected_mime THEN
    RAISE EXCEPTION 'DFIR scan transition cannot replace content metadata'
      USING ERRCODE='55000';
  END IF;

  next_version:=target.version+1;
  IF bound_evidence_id IS NOT NULL THEN
    IF evidence_record.destroyed
       OR evidence_record.scan_state IS DISTINCT FROM target.state
       OR evidence_record.retention_until IS DISTINCT FROM target.retention_until
       OR evidence_record.legal_hold IS DISTINCT FROM target.legal_hold
       OR evidence_record.version IS DISTINCT FROM evidence_record.custody_count
       OR evidence_record.version NOT BETWEEN 1 AND 1000
       OR p_transitioned_at<evidence_record.updated_at THEN
      RAISE EXCEPTION 'DFIR scan evidence projection has drifted'
        USING ERRCODE='55000';
    END IF;
    IF evidence_record.version=1000 THEN
      RAISE EXCEPTION 'DFIR scan evidence custody limit is reached'
        USING ERRCODE='P5401';
    END IF;
    next_evidence_version:=evidence_record.version+1;
    custody_hash:=app.private_dfir_custody_hash_v1(
      evidence_record.custody_head_hash,p_operation_id,job.tenant_id,
      evidence_record.id,next_evidence_version,'scan_state_changed',p_request_id,
      'automated malware scan state transition',p_next_state::text,
      p_transitioned_at
    );
    INSERT INTO public.dfir_custody_events (
      id,tenant_id,evidence_id,sequence,action,actor_principal_kind,actor_id,
      actor_membership_id,actor_user_id,actor_service_account_id,reason,
      state_value,previous_hash,event_hash,occurred_at
    ) VALUES (
      p_operation_id,job.tenant_id,evidence_record.id,next_evidence_version,
      'scan_state_changed','system',p_request_id,NULL,NULL,NULL,
      'automated malware scan state transition',p_next_state::text,
      evidence_record.custody_head_hash,custody_hash,p_transitioned_at
    );
    UPDATE public.dfir_evidence AS evidence
    SET scan_state=p_next_state,custody_head_hash=custody_hash,
        custody_count=next_evidence_version,version=next_evidence_version,
        updated_at=p_transitioned_at
    WHERE evidence.tenant_id=job.tenant_id
      AND evidence.id=evidence_record.id;
  END IF;

  UPDATE public.dfir_storage_objects AS storage
  SET state=p_next_state,
      content_sha256=CASE
        WHEN target.state='verifying' AND p_next_state='quarantined'
        THEN p_content_sha256 ELSE storage.content_sha256 END,
      size_bytes=CASE
        WHEN target.state='verifying' AND p_next_state='quarantined'
        THEN p_size_bytes ELSE storage.size_bytes END,
      detected_mime=CASE
        WHEN target.state='verifying' AND p_next_state='quarantined'
        THEN p_detected_mime ELSE storage.detected_mime END,
      verified_at=CASE
        WHEN target.state='verifying' AND p_next_state='quarantined'
        THEN p_transitioned_at ELSE storage.verified_at END,
      version=next_version,updated_at=p_transitioned_at
  WHERE storage.tenant_id=job.tenant_id AND storage.id=target.id;
  UPDATE public.dfir_attachments AS attachment
  SET scan_state=p_next_state,
      visibility=CASE WHEN p_next_state='available'
        THEN attachment.visibility ELSE 'private'::public.dfir_visibility END,
      version=attachment.version+1
  WHERE attachment.tenant_id=job.tenant_id
    AND attachment.id=attachment_record.id
    AND attachment.storage_object_id=target.id
    AND attachment.version=attachment_record.version;
  GET DIAGNOSTICS attachment_rows=ROW_COUNT;
  IF attachment_rows<>1 THEN
    RAISE EXCEPTION 'DFIR scan attachment projection is incomplete'
      USING ERRCODE='55000';
  END IF;

  effect_payload:=jsonb_strip_nulls(jsonb_build_object(
    'tenantId',job.tenant_id,'resourceId',target.id,
    'resourceVersion',next_version,'state',p_next_state,
    'failureCategory',p_failure_category,
    'fileTypeClass',p_file_type_class,
    'fileTypeReason',p_file_type_reason
  ));
  INSERT INTO public.audit_events (
    id,tenant_id,sequence,actor_type,action,resource_type,resource_id,
    request_id,correlation_id,authentication_method,outcome,reason,
    before,after,metadata
  ) VALUES (
    p_audit_event_id,job.tenant_id,0,'system','dfir.storage.state_changed',
    'dfir_storage_object',target.id,p_request_id,job.correlation_id,
    'worker','success',coalesce(p_failure_category,'automated_scan_transition'),
    jsonb_build_object('state',target.state,'version',target.version),
    jsonb_build_object('state',p_next_state,'version',next_version),
    jsonb_strip_nulls(jsonb_build_object(
      'phase',4,'operationId',p_operation_id,
      'contentMetadataRedacted',true,
      'evidenceCustodyAppended',bound_evidence_id IS NOT NULL,
      'failureCategory',p_failure_category,
      'fileTypeClass',p_file_type_class,
      'fileTypeReason',p_file_type_reason
    ))
  );
  INSERT INTO public.outbox_events (
    id,tenant_id,aggregate_type,aggregate_id,aggregate_version,
    event_type,schema_version,
    payload,deduplication_key,correlation_id,causation_id,actor_kind,
    actor_id,producer,maximum_audience,traceparent,tracestate,occurred_at
  ) VALUES (
    p_outbox_event_id,job.tenant_id,'dfir_storage_object',target.id,next_version,
    'dfir.storage.state_changed',1,effect_payload,
    'dfir-scan-transition:'||p_operation_id::text,job.correlation_id,
    job.id,'system',NULL,'worker','operator',
    nullif(current_setting('app.traceparent',true),''),
    nullif(current_setting('app.tracestate',true),''),p_transitioned_at
  );
  FOREACH root_id IN ARRAY alert_root_ids LOOP
    PERFORM app.private_append_dfir_scan_ticket_activity_v1(
      job.tenant_id,'alert',root_id,attachment_record.id,target.id,
      p_next_state,next_version,p_transitioned_at
    );
  END LOOP;
  FOREACH root_id IN ARRAY case_root_ids LOOP
    PERFORM app.private_append_dfir_scan_ticket_activity_v1(
      job.tenant_id,'case',root_id,attachment_record.id,target.id,
      p_next_state,next_version,p_transitioned_at
    );
  END LOOP;
  IF p_complete_job THEN
    UPDATE public.outbox_events AS queued
    SET processed_at=p_transitioned_at,
        last_error=p_failure_category,
        failure_category=p_failure_category,
        dead_lettered_at=CASE WHEN p_next_state='scan_failed'
          THEN p_transitioned_at ELSE NULL END,
        locked_at=NULL,locked_by=NULL,lease_token=NULL,lease_until=NULL
    WHERE queued.id=job.id;
  END IF;

  RETURN QUERY
  SELECT storage.id,storage.tenant_id,storage.bucket,storage.object_key,
         storage.original_filename,storage.classification::text,
         storage.expected_size_bytes,storage.upload_expires_at,
         storage.created_by_membership_id,storage.created_at,storage.updated_at,
         storage.state::text,storage.content_sha256,storage.size_bytes,
         storage.detected_mime,storage.verified_at,storage.retention_until,
         storage.legal_hold,storage.version
  FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=job.tenant_id AND storage.id=target.id;
END;
$function$;
--> statement-breakpoint
