CREATE FUNCTION app.wait_dfir_storage_scan_job_v1(
  p_event_id uuid,p_lease_token uuid,p_observed_at timestamp with time zone,
  p_available_at timestamp with time zone
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  job public.outbox_events%ROWTYPE;
  target public.dfir_storage_objects%ROWTYPE;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR scan upload wait requires worker role'
      USING ERRCODE='42501';
  END IF;
  SELECT queued.* INTO job FROM public.outbox_events AS queued
  WHERE queued.id=p_event_id FOR UPDATE;
  IF NOT FOUND OR p_lease_token IS NULL
     OR uuid_extract_version(p_lease_token) IS DISTINCT FROM 7
     OR job.event_type<>'dfir.storage.scan.requested'
     OR job.processed_at IS NOT NULL OR job.dead_lettered_at IS NOT NULL
     OR job.lease_token IS DISTINCT FROM p_lease_token
     OR job.lease_until IS NULL
     OR job.lease_until<=transaction_timestamp()
     OR job.attempts NOT BETWEEN 1 AND job.max_attempts
     OR p_observed_at IS NULL OR p_available_at IS NULL
     OR p_observed_at<transaction_timestamp()-interval '1 minute'
     OR p_observed_at>transaction_timestamp()+interval '1 minute'
     OR p_available_at<=p_observed_at THEN
    RAISE EXCEPTION 'DFIR scan upload wait lease is stale'
      USING ERRCODE='40001';
  END IF;
  SELECT storage.* INTO target FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=job.tenant_id AND storage.id=job.aggregate_id
  FOR UPDATE;
  IF NOT FOUND OR target.state<>'pending_upload'
     OR target.upload_expires_at<=p_observed_at
     OR p_available_at>target.upload_expires_at
     OR target.cleanup_lease_expires_at>transaction_timestamp() THEN
    RAISE EXCEPTION 'DFIR scan upload is no longer waiting'
      USING ERRCODE='40001';
  END IF;
  UPDATE public.outbox_events AS queued
  SET attempts=greatest(queued.attempts-1,0),available_at=p_available_at,
      locked_at=NULL,locked_by=NULL,lease_token=NULL,lease_until=NULL,
      last_error=NULL,failure_category=NULL
  WHERE queued.id=job.id;
  RETURN true;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.retry_dfir_storage_scan_job_v1(
  p_event_id uuid,p_lease_token uuid,p_failed_at timestamp with time zone,
  p_retry_at timestamp with time zone,p_failure_category text
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE job public.outbox_events%ROWTYPE;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR scan retry requires worker role' USING ERRCODE='42501';
  END IF;
  SELECT queued.* INTO job FROM public.outbox_events AS queued
  WHERE queued.id=p_event_id FOR UPDATE;
  IF NOT FOUND OR p_lease_token IS NULL
     OR uuid_extract_version(p_lease_token) IS DISTINCT FROM 7
     OR p_failure_category IS NULL
     OR p_failure_category!~'^[a-z][a-z0-9_]{0,63}$'
     OR p_failed_at IS NULL OR p_retry_at IS NULL
     OR p_failed_at<transaction_timestamp()-interval '1 minute'
     OR p_failed_at>transaction_timestamp()+interval '1 minute'
     OR p_retry_at<p_failed_at+interval '1 second'
     OR p_retry_at>p_failed_at+interval '24 hours'
     OR job.event_type<>'dfir.storage.scan.requested'
     OR job.processed_at IS NOT NULL OR job.dead_lettered_at IS NOT NULL
     OR job.lease_token IS DISTINCT FROM p_lease_token
     OR job.lease_until IS NULL
     OR job.lease_until<=transaction_timestamp()
     OR job.attempts NOT BETWEEN 1 AND job.max_attempts-1 THEN
    RAISE EXCEPTION 'DFIR scan retry lease is stale' USING ERRCODE='40001';
  END IF;
  UPDATE public.outbox_events AS queued
  SET available_at=p_retry_at,last_error=p_failure_category,
      failure_category=p_failure_category,locked_at=NULL,locked_by=NULL,
      lease_token=NULL,lease_until=NULL
  WHERE queued.id=job.id;
  RETURN true;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.complete_dfir_storage_scan_job_v1(
  p_event_id uuid,p_lease_token uuid,p_completed_at timestamp with time zone,
  p_failure_category text,p_dead_letter boolean
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  job public.outbox_events%ROWTYPE;
  target public.dfir_storage_objects%ROWTYPE;
  blocked_evidence public.dfir_evidence%ROWTYPE;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR scan completion requires worker role' USING ERRCODE='42501';
  END IF;
  SELECT queued.* INTO job FROM public.outbox_events AS queued
  WHERE queued.id=p_event_id FOR UPDATE;
  IF NOT FOUND OR p_lease_token IS NULL
     OR uuid_extract_version(p_lease_token) IS DISTINCT FROM 7
     OR p_completed_at IS NULL
     OR p_completed_at<transaction_timestamp()-interval '1 minute'
     OR p_completed_at>transaction_timestamp()+interval '1 minute'
     OR p_dead_letter IS NULL
     OR p_failure_category IS NOT NULL
        AND p_failure_category!~'^[a-z][a-z0-9_]{0,63}$'
     OR job.event_type<>'dfir.storage.scan.requested'
     OR job.processed_at IS NOT NULL
     OR job.lease_token IS DISTINCT FROM p_lease_token
     OR job.lease_until IS NULL
     OR job.lease_until<=transaction_timestamp()
     OR job.attempts NOT BETWEEN 1 AND job.max_attempts THEN
    RAISE EXCEPTION 'DFIR scan completion lease is stale' USING ERRCODE='40001';
  END IF;
  IF p_dead_letter AND p_failure_category='evidence_custody_limit' THEN
    -- Match the transition lock order: evidence before storage. A terminal
    -- queue failure must not invent another custody event or expose the file.
    SELECT evidence.* INTO blocked_evidence
    FROM public.dfir_evidence AS evidence
    WHERE evidence.tenant_id=job.tenant_id
      AND evidence.storage_object_id=job.aggregate_id
    FOR UPDATE;
  END IF;
  SELECT storage.* INTO target FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=job.tenant_id AND storage.id=job.aggregate_id
  FOR UPDATE;
  IF NOT FOUND OR NOT (
       target.state IN ('available','rejected','deleted') AND NOT p_dead_letter
       OR target.state='scan_failed' AND p_dead_letter
       OR target.state='pending_upload' AND NOT p_dead_letter
          AND target.upload_expires_at<=p_completed_at
       OR p_dead_letter AND p_failure_category='evidence_custody_limit'
          AND target.state IN ('pending_upload','uploaded','verifying','quarantined','scanning')
          AND blocked_evidence.id IS NOT NULL
          AND NOT blocked_evidence.destroyed
          AND blocked_evidence.version=1000
          AND blocked_evidence.custody_count=1000
          AND blocked_evidence.scan_state=target.state
     ) THEN
    RAISE EXCEPTION 'DFIR scan job is not terminal' USING ERRCODE='55000';
  END IF;
  UPDATE public.outbox_events AS queued
  SET processed_at=p_completed_at,last_error=p_failure_category,
      failure_category=p_failure_category,
      dead_lettered_at=CASE WHEN p_dead_letter THEN p_completed_at ELSE NULL END,
      locked_at=NULL,locked_by=NULL,lease_token=NULL,lease_until=NULL
  WHERE queued.id=job.id;
  RETURN true;
END;
$function$;
