CREATE FUNCTION app.finalize_dfir_orphan_upload_cleanup_v2(
  p_storage_object_id uuid,
  p_cleanup_fence bigint,
  p_deleted_at timestamp with time zone,
  p_operation_id uuid,
  p_audit_event_id uuid,
  p_outbox_event_id uuid,
  p_request_id uuid,
  p_correlation_id uuid
)
RETURNS TABLE(storage_object_id uuid,storage_version bigint,replayed boolean)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  target public.dfir_storage_objects%ROWTYPE;
  attachment_record public.dfir_attachments%ROWTYPE;
  alert_root_ids uuid[] := ARRAY[]::uuid[];
  case_root_ids uuid[] := ARRAY[]::uuid[];
  root_id uuid;
  root_count integer;
  next_version bigint;
  attachment_rows bigint;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR orphan cleanup finalize requires worker role'
      USING ERRCODE='42501';
  END IF;
  IF p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_cleanup_fence NOT BETWEEN 1 AND 9223372036854775806
     OR p_deleted_at IS NULL
     OR p_deleted_at<transaction_timestamp()-interval '5 minutes'
     OR p_deleted_at>transaction_timestamp()+interval '1 minute'
     OR p_operation_id IS NULL
     OR uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
     OR p_audit_event_id IS NULL
     OR uuid_extract_version(p_audit_event_id) IS DISTINCT FROM 7
     OR p_outbox_event_id IS NULL
     OR uuid_extract_version(p_outbox_event_id) IS DISTINCT FROM 7
     OR p_request_id IS NULL
     OR uuid_extract_version(p_request_id) IS DISTINCT FROM 7
     OR p_correlation_id IS NULL
     OR uuid_extract_version(p_correlation_id) IS DISTINCT FROM 7
     OR p_storage_object_id=ANY(ARRAY[
       p_operation_id,p_audit_event_id,p_outbox_event_id,
       p_request_id,p_correlation_id
     ])
     OR 5<>(
       SELECT count(DISTINCT identifier)
       FROM unnest(ARRAY[
         p_operation_id,p_audit_event_id,p_outbox_event_id,
         p_request_id,p_correlation_id
       ]) AS supplied(identifier)
     ) THEN
    RAISE EXCEPTION 'DFIR orphan cleanup finalize input is invalid'
      USING ERRCODE='22023';
  END IF;

  SELECT storage.* INTO target
  FROM public.dfir_storage_objects AS storage
  WHERE storage.id=p_storage_object_id
  FOR UPDATE;
  IF NOT FOUND OR target.cleanup_fence IS DISTINCT FROM p_cleanup_fence THEN
    RAISE EXCEPTION 'DFIR orphan cleanup fence is stale'
      USING ERRCODE='40001';
  END IF;
  IF target.state='deleted' THEN
    SELECT count(*) INTO attachment_rows
    FROM public.dfir_attachments AS attachment
    WHERE attachment.tenant_id=target.tenant_id
      AND attachment.storage_object_id=target.id
      AND attachment.scan_state='deleted'
      AND attachment.visibility='private'
      AND attachment.version=target.version;
    IF attachment_rows<>1 OR NOT EXISTS (
      SELECT 1 FROM public.audit_events AS audit
      WHERE audit.tenant_id=target.tenant_id
        AND audit.resource_type='dfir_storage_object'
        AND audit.resource_id=target.id
        AND audit.action='dfir.storage.orphan_deleted'
        AND audit.metadata->>'cleanupFence'=p_cleanup_fence::text
    ) OR NOT EXISTS (
      SELECT 1 FROM public.outbox_events AS effect
      WHERE effect.tenant_id=target.tenant_id
        AND effect.aggregate_type='dfir_storage_object'
        AND effect.aggregate_id=target.id
        AND effect.aggregate_version=target.version
        AND effect.event_type='dfir.storage.orphan_deleted'
        AND effect.payload->>'cleanupFence'=p_cleanup_fence::text
    ) THEN
      RAISE EXCEPTION 'DFIR orphan cleanup replay projection is incomplete'
        USING ERRCODE='55000';
    END IF;
    RETURN QUERY SELECT target.id,target.version,true;
    RETURN;
  END IF;
  IF target.state<>'pending_upload'
     OR target.content_sha256 IS NOT NULL
     OR target.size_bytes IS NOT NULL
     OR target.detected_mime IS NOT NULL
     OR target.verified_at IS NOT NULL
     OR target.cleanup_claimed_at IS NULL
     OR target.cleanup_lease_expires_at IS NULL
     OR target.cleanup_lease_expires_at<=transaction_timestamp()
     OR p_deleted_at>=target.cleanup_lease_expires_at
     OR target.upload_expires_at+interval '5 minutes'>p_deleted_at
     OR p_deleted_at<target.updated_at
     OR target.version NOT BETWEEN 1 AND 9007199254740990
     OR EXISTS (
       SELECT 1 FROM public.dfir_evidence AS evidence
       WHERE evidence.tenant_id=target.tenant_id
         AND evidence.storage_object_id=target.id
     ) THEN
    RAISE EXCEPTION 'DFIR orphan cleanup claim is no longer finalizable'
      USING ERRCODE='40001';
  END IF;

  SELECT attachment.* INTO attachment_record
  FROM public.dfir_attachments AS attachment
  WHERE attachment.tenant_id=target.tenant_id
    AND attachment.storage_object_id=target.id
  FOR UPDATE;
  IF NOT FOUND
     OR attachment_record.scan_state IS DISTINCT FROM target.state
     OR attachment_record.version IS DISTINCT FROM target.version
     OR attachment_record.original_filename IS DISTINCT FROM target.original_filename THEN
    RAISE EXCEPTION 'DFIR orphan cleanup attachment projection is invalid'
      USING ERRCODE='55000';
  END IF;

  WITH roots AS (
    SELECT 'alert'::text AS root_kind,attachment.alert_id AS root_id
    FROM public.dfir_attachments AS attachment
    WHERE attachment.tenant_id=target.tenant_id
      AND attachment.id=attachment_record.id
      AND attachment.subject_kind='alert'
    UNION
    SELECT 'case',attachment.case_id
    FROM public.dfir_attachments AS attachment
    WHERE attachment.tenant_id=target.tenant_id
      AND attachment.id=attachment_record.id
      AND attachment.subject_kind='case'
    UNION
    SELECT CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(link.alert_id,link.case_id)
    FROM public.dfir_ioc_links AS link
    JOIN public.dfir_iocs AS resource
      ON resource.tenant_id=link.tenant_id AND resource.id=link.ioc_id
     AND resource.archived_at IS NULL
    WHERE attachment_record.subject_kind='ioc'
      AND link.tenant_id=target.tenant_id
      AND link.ioc_id=attachment_record.ioc_id
    UNION
    SELECT CASE WHEN link.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(link.alert_id,link.case_id)
    FROM public.dfir_asset_links AS link
    JOIN public.dfir_assets AS resource
      ON resource.tenant_id=link.tenant_id AND resource.id=link.asset_id
     AND resource.archived_at IS NULL
    WHERE attachment_record.subject_kind='asset'
      AND link.tenant_id=target.tenant_id
      AND link.asset_id=attachment_record.asset_id
    UNION
    SELECT CASE WHEN task.alert_id IS NOT NULL THEN 'alert' ELSE 'case' END,
           coalesce(task.alert_id,task.case_id)
    FROM public.dfir_tasks AS task
    WHERE attachment_record.subject_kind='task'
      AND task.tenant_id=target.tenant_id
      AND task.id=attachment_record.task_id
    UNION
    SELECT 'alert',link.source_alert_id
    FROM public.dfir_attachment_case_links AS link
    WHERE link.tenant_id=target.tenant_id
      AND link.attachment_id=attachment_record.id
    UNION
    SELECT 'case',link.case_id
    FROM public.dfir_attachment_case_links AS link
    WHERE link.tenant_id=target.tenant_id
      AND link.attachment_id=attachment_record.id
  )
  SELECT
    coalesce(array_agg(resolved.root_id ORDER BY resolved.root_id)
      FILTER (WHERE resolved.root_kind='alert'),ARRAY[]::uuid[]),
    coalesce(array_agg(resolved.root_id ORDER BY resolved.root_id)
      FILTER (WHERE resolved.root_kind='case'),ARRAY[]::uuid[]),
    count(*)::integer
  INTO alert_root_ids,case_root_ids,root_count
  FROM roots AS resolved
  WHERE resolved.root_id IS NOT NULL;
  IF root_count NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'DFIR orphan cleanup attachment root set is invalid'
      USING ERRCODE='55000';
  END IF;
  FOREACH root_id IN ARRAY alert_root_ids LOOP
    PERFORM 1 FROM public.alerts AS alert
    WHERE alert.tenant_id=target.tenant_id AND alert.id=root_id
      AND alert.deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR orphan cleanup alert root is unavailable'
        USING ERRCODE='55000';
    END IF;
  END LOOP;
  FOREACH root_id IN ARRAY case_root_ids LOOP
    PERFORM 1 FROM public.cases AS case_record
    WHERE case_record.tenant_id=target.tenant_id AND case_record.id=root_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR orphan cleanup case root is unavailable'
        USING ERRCODE='55000';
    END IF;
  END LOOP;

  next_version:=target.version+1;
  UPDATE public.dfir_storage_objects AS storage
  SET state='deleted',cleanup_claimed_at=NULL,
      cleanup_lease_expires_at=NULL,cleanup_last_failure_code=NULL,
      version=next_version,updated_at=p_deleted_at
  WHERE storage.id=target.id
    AND storage.cleanup_fence=p_cleanup_fence
    AND storage.state='pending_upload';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR orphan cleanup storage fence was lost'
      USING ERRCODE='40001';
  END IF;
  UPDATE public.dfir_attachments AS attachment
  SET scan_state='deleted',visibility='private',version=attachment.version+1
  WHERE attachment.tenant_id=target.tenant_id
    AND attachment.id=attachment_record.id
    AND attachment.storage_object_id=target.id
    AND attachment.version=attachment_record.version;
  GET DIAGNOSTICS attachment_rows=ROW_COUNT;
  IF attachment_rows<>1 THEN
    RAISE EXCEPTION 'DFIR orphan cleanup attachment projection is incomplete'
      USING ERRCODE='55000';
  END IF;

  INSERT INTO public.audit_events (
    id,tenant_id,sequence,actor_type,action,resource_type,resource_id,
    request_id,correlation_id,authentication_method,outcome,reason,
    before,after,metadata
  ) VALUES (
    p_audit_event_id,target.tenant_id,0,'system',
    'dfir.storage.orphan_deleted','dfir_storage_object',target.id,
    p_request_id,p_correlation_id,'worker','success',
    'expired upload object versions deleted',
    jsonb_build_object('state',target.state,'version',target.version),
    jsonb_build_object('state','deleted','version',next_version),
    jsonb_build_object(
      'phase',4,'operationId',p_operation_id,
      'cleanupFence',p_cleanup_fence,
      'objectLocationRedacted',true,'contentMetadataRedacted',true
    )
  );
  INSERT INTO public.outbox_events (
    id,tenant_id,aggregate_type,aggregate_id,aggregate_version,event_type,
    schema_version,payload,deduplication_key,correlation_id,causation_id,
    actor_kind,actor_id,producer,maximum_audience,traceparent,tracestate,
    occurred_at
  ) VALUES (
    p_outbox_event_id,target.tenant_id,'dfir_storage_object',target.id,
    next_version,'dfir.storage.orphan_deleted',1,
    jsonb_build_object(
      'tenantId',target.tenant_id,'resourceId',target.id,
      'resourceVersion',next_version,'state','deleted',
      'cleanupFence',p_cleanup_fence
    ),'dfir-cleanup:'||p_operation_id::text,p_correlation_id,p_request_id,
    'system',NULL,'worker','operator',
    nullif(current_setting('app.traceparent',true),''),
    nullif(current_setting('app.tracestate',true),''),p_deleted_at
  );
  FOREACH root_id IN ARRAY alert_root_ids LOOP
    PERFORM app.private_append_dfir_scan_ticket_activity_v1(
      target.tenant_id,'alert',root_id,attachment_record.id,target.id,
      'deleted',next_version,p_deleted_at
    );
  END LOOP;
  FOREACH root_id IN ARRAY case_root_ids LOOP
    PERFORM app.private_append_dfir_scan_ticket_activity_v1(
      target.tenant_id,'case',root_id,attachment_record.id,target.id,
      'deleted',next_version,p_deleted_at
    );
  END LOOP;
  RETURN QUERY SELECT target.id,next_version,false;
END;
$function$;
