-- Rolling workers still call v1. Generate its missing operation identity in
-- the trusted function and delegate to the fully fenced v2 implementation.
CREATE OR REPLACE FUNCTION app.finalize_dfir_orphan_upload_cleanup_v1(
  p_storage_object_id uuid,
  p_cleanup_fence bigint,
  p_deleted_at timestamp with time zone,
  p_audit_event_id uuid,
  p_outbox_event_id uuid,
  p_request_id uuid,
  p_correlation_id uuid
)
RETURNS TABLE(storage_object_id uuid,storage_version bigint,replayed boolean)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  generated_operation_id uuid := uuidv7();
BEGIN
  IF p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_audit_event_id IS NULL
     OR uuid_extract_version(p_audit_event_id) IS DISTINCT FROM 7
     OR p_outbox_event_id IS NULL
     OR uuid_extract_version(p_outbox_event_id) IS DISTINCT FROM 7
     OR p_request_id IS NULL
     OR uuid_extract_version(p_request_id) IS DISTINCT FROM 7
     OR p_correlation_id IS NULL
     OR uuid_extract_version(p_correlation_id) IS DISTINCT FROM 7
     OR p_storage_object_id=ANY(ARRAY[
       p_audit_event_id,p_outbox_event_id,p_request_id,p_correlation_id
     ])
     OR 4<>(
       SELECT count(DISTINCT identifier)
       FROM unnest(ARRAY[
         p_audit_event_id,p_outbox_event_id,p_request_id,p_correlation_id
       ]) AS supplied(identifier)
     )
     OR generated_operation_id=p_storage_object_id
     OR generated_operation_id=ANY(ARRAY[
       p_audit_event_id,p_outbox_event_id,p_request_id,p_correlation_id
     ]) THEN
    RAISE EXCEPTION 'DFIR orphan cleanup finalize input is invalid'
      USING ERRCODE='22023';
  END IF;
  RETURN QUERY
  SELECT result.storage_object_id,result.storage_version,result.replayed
  FROM app.finalize_dfir_orphan_upload_cleanup_v2(
    p_storage_object_id,p_cleanup_fence,p_deleted_at,
    generated_operation_id,p_audit_event_id,p_outbox_event_id,
    p_request_id,p_correlation_id
  ) AS result;
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.finalize_dfir_orphan_upload_cleanup_v1(
  uuid,bigint,timestamp with time zone,uuid,uuid,uuid,uuid
) OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.finalize_dfir_orphan_upload_cleanup_v1(
