-- The legacy Alert readiness probe treated the unfenced storage v3 function
-- as the current worker boundary. Scan jobs now use the leased/fenced ABI and
-- both direct storage mutation versions must remain unreachable.
CREATE OR REPLACE FUNCTION app.alert_dfir_runtime_schema_readiness_v2()
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  function_identity text;
  shape_definition text;
BEGIN
  IF to_regclass('public.alert_dfir_resource_command_results') IS NULL
     OR to_regclass('public.dfir_relationship_retractions') IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_class AS relation
       WHERE relation.oid='public.alert_dfir_resource_command_results'::regclass
         AND relation.relrowsecurity AND relation.relforcerowsecurity
         AND pg_catalog.pg_get_userbyid(relation.relowner)='periapsis_migrator'
     )
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_class AS relation
       WHERE relation.oid='public.dfir_relationship_retractions'::regclass
         AND relation.relrowsecurity AND relation.relforcerowsecurity
         AND pg_catalog.pg_get_userbyid(relation.relowner)='periapsis_migrator'
     )
     OR has_table_privilege('periapsis_api','public.alert_dfir_resource_command_results','SELECT,INSERT,UPDATE,DELETE')
     OR has_table_privilege('periapsis_worker','public.alert_dfir_resource_command_results','SELECT,INSERT,UPDATE,DELETE')
     OR has_table_privilege('periapsis_api','public.dfir_relationship_retractions','INSERT,UPDATE,DELETE')
     OR has_table_privilege('periapsis_worker','public.dfir_relationship_retractions','SELECT,INSERT,UPDATE,DELETE') THEN
    RETURN false;
  END IF;
  SELECT pg_catalog.pg_get_constraintdef(constraint_row.oid,true)
  INTO shape_definition
  FROM pg_catalog.pg_constraint AS constraint_row
  WHERE constraint_row.conrelid='public.alert_dfir_resource_commands'::regclass
    AND constraint_row.conname='alert_dfir_resource_commands_shape_check';
  IF shape_definition IS NULL
     OR position('dfir.alert.evidence.create' IN shape_definition)=0
     OR position('dfir.alert.task.checklist.replace' IN shape_definition)=0
     OR position('dfir.alert.relationship.retract' IN shape_definition)=0
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_constraint
       WHERE conrelid='public.alert_dfir_resource_command_results'::regclass
         AND conname='alert_dfir_resource_command_results_command_fk'
         AND contype='f'
     )
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_constraint
       WHERE conrelid='public.dfir_evidence'::regclass
         AND conname='dfir_evidence_root_check'
     )
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_constraint
       WHERE conrelid='public.dfir_tasks'::regclass
         AND conname='dfir_tasks_root_check'
     )
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_constraint
       WHERE conrelid='public.dfir_relationships'::regclass
         AND conname='dfir_relationships_root_check'
     )
     OR NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_constraint
       WHERE conrelid='public.dfir_activities'::regclass
         AND conname='dfir_activities_root_check'
     ) THEN
    RETURN false;
  END IF;
  IF (SELECT count(*) FROM pg_catalog.pg_trigger
      WHERE tgname IN (
        'alert_dfir_resource_command_results_immutable_v1',
        'alert_dfir_resource_commands_result_required_v1',
        'dfir_relationship_retractions_immutable_v1',
        'dfir_relationship_retractions_validate_root_v1',
        'dfir_relationships_identity_v1'
      ) AND tgenabled='O' AND NOT tgisinternal)<>5 THEN
    RETURN false;
  END IF;
  FOREACH function_identity IN ARRAY ARRAY[
    'app.reserve_alert_investigation_command_v1(uuid,uuid,text,uuid,bigint,bytea,bytea)',
    'app.store_alert_investigation_command_result_v1(uuid,jsonb)',
    'app.create_alert_dfir_evidence_v1(uuid,uuid,uuid,uuid,text,text,text,public.dfir_evidence_classification,timestamp with time zone,text,timestamp with time zone,boolean,uuid,bytea,bytea)',
    'app.append_alert_dfir_custody_event_v1(uuid,uuid,uuid,bigint,uuid,public.dfir_custody_action,text,text,bytea,bytea,timestamp with time zone)',
    'app.create_alert_dfir_relationship_v1(uuid,uuid,uuid,public.dfir_entity_kind,uuid,text,text,public.dfir_entity_kind,uuid,text,text,text,jsonb,timestamp with time zone)',
    'app.retract_alert_dfir_relationship_v1(uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone)',
    'app.append_alert_investigation_effects_v1(uuid,text,text,text,text,text,text,uuid,bigint,bytea,bytea,uuid,jsonb,jsonb,jsonb,uuid,uuid,uuid,uuid,inet,text,text)'
  ] LOOP
    IF to_regprocedure(function_identity) IS NULL
       OR NOT has_function_privilege('periapsis_api',function_identity,'EXECUTE')
       OR has_function_privilege('periapsis_worker',function_identity,'EXECUTE')
       OR has_function_privilege('periapsis_notifier',function_identity,'EXECUTE')
       OR has_function_privilege('periapsis_auditor',function_identity,'EXECUTE')
       OR EXISTS (
         SELECT 1 FROM pg_catalog.pg_proc AS procedure
         CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(
           procedure.proacl,pg_catalog.acldefault('f',procedure.proowner)
         )) AS privilege
         WHERE procedure.oid=to_regprocedure(function_identity)
           AND privilege.grantee=0 AND privilege.privilege_type='EXECUTE'
       ) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN to_regprocedure(
      'app.advance_dfir_storage_scan_job_v1(uuid,uuid,uuid,bigint,public.dfir_scan_state,bytea,bigint,text,timestamp with time zone,uuid,uuid,uuid,uuid,text,boolean,text,text)'
    ) IS NOT NULL
    AND has_function_privilege(
      'periapsis_worker',
      'app.advance_dfir_storage_scan_job_v1(uuid,uuid,uuid,bigint,public.dfir_scan_state,bytea,bigint,text,timestamp with time zone,uuid,uuid,uuid,uuid,text,boolean,text,text)',
      'EXECUTE'
    )
    AND NOT has_function_privilege(
      'periapsis_worker',
      'app.advance_dfir_storage_object_as_worker_v2(uuid,bigint,public.dfir_scan_state,bytea,bigint,text,timestamp with time zone,uuid,uuid,uuid,uuid)',
      'EXECUTE'
    )
    AND NOT has_function_privilege(
      'periapsis_worker',
      'app.advance_dfir_storage_object_as_worker_v3(uuid,bigint,public.dfir_scan_state,bytea,bigint,text,timestamp with time zone,uuid,uuid,uuid,uuid,uuid)',
      'EXECUTE'
    );
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.alert_dfir_runtime_schema_readiness_v2()
  OWNER TO periapsis_migrator;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.alert_dfir_runtime_schema_readiness_v2()
  FROM PUBLIC,periapsis_notifier,periapsis_auditor;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.alert_dfir_runtime_schema_readiness_v2()
  TO periapsis_api,periapsis_worker;
--> statement-breakpoint

DO $dfir_storage_scan_runtime_contract$
DECLARE
  worker_proc regprocedure;
BEGIN
  FOREACH worker_proc IN ARRAY ARRAY[
    'app.claim_dfir_storage_scan_v1(uuid,integer,integer,timestamp with time zone)'::regprocedure,
    'app.advance_dfir_storage_scan_job_v1(uuid,uuid,uuid,bigint,public.dfir_scan_state,bytea,bigint,text,timestamp with time zone,uuid,uuid,uuid,uuid,text,boolean,text,text)'::regprocedure,
    'app.wait_dfir_storage_scan_job_v1(uuid,uuid,timestamp with time zone,timestamp with time zone)'::regprocedure,
    'app.retry_dfir_storage_scan_job_v1(uuid,uuid,timestamp with time zone,timestamp with time zone,text)'::regprocedure,
    'app.complete_dfir_storage_scan_job_v1(uuid,uuid,timestamp with time zone,text,boolean)'::regprocedure,
    'app.claim_dfir_orphan_uploads_v1(integer,integer,timestamp with time zone)'::regprocedure,
    'app.retry_dfir_orphan_upload_cleanup_v1(uuid,bigint,text,timestamp with time zone,timestamp with time zone)'::regprocedure,
    'app.finalize_dfir_orphan_upload_cleanup_v1(uuid,bigint,timestamp with time zone,uuid,uuid,uuid,uuid)'::regprocedure,
    'app.finalize_dfir_orphan_upload_cleanup_v2(uuid,bigint,timestamp with time zone,uuid,uuid,uuid,uuid,uuid)'::regprocedure,
    'app.dfir_storage_scan_runtime_ready_v1()'::regprocedure
  ] LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_proc AS procedure
      WHERE procedure.oid=worker_proc AND procedure.prosecdef
        AND pg_get_userbyid(procedure.proowner)='periapsis_migrator'
        AND procedure.proconfig @> ARRAY[
          'search_path=pg_catalog, public, app'
        ]::text[]
    ) OR NOT has_function_privilege('periapsis_worker',worker_proc,'EXECUTE')
       OR has_function_privilege('periapsis_api',worker_proc,'EXECUTE')
       OR has_function_privilege('periapsis_notifier',worker_proc,'EXECUTE')
       OR has_function_privilege('periapsis_auditor',worker_proc,'EXECUTE') THEN
      RAISE EXCEPTION 'DFIR storage scan worker ABI is not isolated'
        USING ERRCODE='55000';
    END IF;
  END LOOP;
  IF NOT has_function_privilege(
    'periapsis_api',
    'app.enqueue_dfir_storage_scan_v1(uuid,uuid,text,timestamp with time zone,uuid,uuid)'::regprocedure,
    'EXECUTE'
  ) OR has_function_privilege(
    'periapsis_worker',
    'app.enqueue_dfir_storage_scan_v1(uuid,uuid,text,timestamp with time zone,uuid,uuid)'::regprocedure,
    'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'DFIR storage scan enqueue ABI is not isolated'
      USING ERRCODE='55000';
  END IF;
  IF has_function_privilege(
    'periapsis_worker',
    'app.private_append_dfir_scan_ticket_activity_v1(uuid,public.ticket_aggregate_kind,uuid,uuid,uuid,public.dfir_scan_state,bigint,timestamp with time zone)'::regprocedure,
    'EXECUTE'
  ) OR has_function_privilege(
    'periapsis_api',
    'app.private_append_dfir_scan_ticket_activity_v1(uuid,public.ticket_aggregate_kind,uuid,uuid,uuid,public.dfir_scan_state,bigint,timestamp with time zone)'::regprocedure,
    'EXECUTE'
  ) THEN
    RAISE EXCEPTION 'DFIR storage scan private activity helper is exposed'
      USING ERRCODE='55000';
  END IF;
END;
$dfir_storage_scan_runtime_contract$;
--> statement-breakpoint

-- DFIR_DOWNLOAD_GRANT_AUDIT_V1_BEGIN
-- A signed download capability is useful only after it has crossed this final
-- transactional authorization boundary. The ABI deliberately cannot carry the
-- signed URL, object location, filename, digest, or any other customer data.
CREATE FUNCTION app.append_dfir_download_grant_audit_v1(
  p_event_id uuid,
  p_actor_kind text,
  p_session_id uuid,
  p_actor_membership_id uuid,
  p_root_kind public.ticket_aggregate_kind,
  p_root_id uuid,
  p_root_version bigint,
  p_subject_kind public.dfir_entity_kind,
  p_subject_id uuid,
  p_attachment_id uuid,
  p_attachment_version bigint,
  p_storage_object_id uuid,
  p_storage_version bigint,
  p_attachment_state public.dfir_scan_state,
  p_storage_state public.dfir_scan_state,
  p_audience text,
  p_scope public.authorization_scope,
  p_portal_contact_id uuid,
  p_expires_at timestamp with time zone,
  p_request_id uuid,
  p_correlation_id uuid,
  p_ip_address inet,
  p_user_agent text,
  p_authentication_method text
)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  context_user uuid := app.context_user_id();
  context_membership uuid;
  live_authentication_method text;
  attachment_record public.dfir_attachments%ROWTYPE;
  storage_record public.dfir_storage_objects%ROWTYPE;
  root_assignee_user_id uuid;
  root_claimed_by_user_id uuid;
  root_assigned_team_id uuid;
  root_assigned_team_epoch_id uuid;
  root_workflow_id uuid;
  root_workflow_version integer;
  root_state_key text;
  root_customer_visible boolean;
  stored_root_version bigint;
  root_associated boolean := false;
  authorized_contact_id uuid;
  audit_action text;
BEGIN
  IF p_event_id IS NULL
     OR uuid_extract_version(p_event_id) IS DISTINCT FROM 7
     OR p_session_id IS NULL
     OR uuid_extract_version(p_session_id) IS DISTINCT FROM 7
     OR p_actor_membership_id IS NULL
     OR uuid_extract_version(p_actor_membership_id) IS DISTINCT FROM 7
     OR p_root_id IS NULL
     OR uuid_extract_version(p_root_id) IS DISTINCT FROM 7
     OR p_subject_id IS NULL
     OR uuid_extract_version(p_subject_id) IS DISTINCT FROM 7
     OR p_attachment_id IS NULL
     OR uuid_extract_version(p_attachment_id) IS DISTINCT FROM 7
     OR p_storage_object_id IS NULL
     OR uuid_extract_version(p_storage_object_id) IS DISTINCT FROM 7
     OR p_request_id IS NULL
     OR uuid_extract_version(p_request_id) IS DISTINCT FROM 7
     OR p_correlation_id IS NULL
     OR uuid_extract_version(p_correlation_id) IS DISTINCT FROM 7
     OR p_root_kind IS NULL OR p_root_kind NOT IN ('alert','case')
     OR p_subject_kind IS NULL OR p_subject_kind IN ('attachment','external')
     OR p_root_version IS NULL
     OR p_root_version NOT BETWEEN 1 AND 9007199254740991
     OR p_attachment_version IS NULL
     OR p_attachment_version NOT BETWEEN 1 AND 9007199254740991
     OR p_storage_version IS NULL
     OR p_storage_version NOT BETWEEN 1 AND 9007199254740991
     OR p_attachment_state IS DISTINCT FROM 'available'
     OR p_storage_state IS DISTINCT FROM 'available'
     OR p_expires_at IS NULL
     OR date_trunc('microseconds',p_expires_at) IS DISTINCT FROM p_expires_at
     OR p_expires_at<=transaction_timestamp()
     OR p_expires_at>transaction_timestamp()+interval '5 minutes'
     OR p_ip_address IS NULL
     OR NOT (
       family(p_ip_address)=4 AND masklen(p_ip_address)=32
       OR family(p_ip_address)=6 AND masklen(p_ip_address)=128
     )
     OR p_user_agent IS NULL OR p_user_agent<>btrim(p_user_agent)
     OR octet_length(p_user_agent) NOT BETWEEN 1 AND 512
     OR p_user_agent~'[[:cntrl:]]'
     OR p_user_agent~U&'[\00AD\061C\180E\200B-\200F\202A-\202E\2060-\206F\FEFF]'
     OR p_authentication_method IS NULL
     OR p_authentication_method<>btrim(p_authentication_method)
     OR p_authentication_method!~'^[a-z][a-z0-9_.-]{0,63}$'
     OR p_actor_kind IS NULL OR p_actor_kind NOT IN ('human','customer')
     OR p_audience IS NULL OR p_scope IS NULL
     OR p_actor_kind='human' AND (
       p_audience IS DISTINCT FROM 'operator'
       OR p_scope NOT IN ('assigned','operator_team','tenant')
       OR p_portal_contact_id IS NOT NULL
     )
     OR p_actor_kind='customer' AND (
       p_audience IS DISTINCT FROM 'customer'
       OR p_scope IS DISTINCT FROM 'own'
       OR p_portal_contact_id IS NULL
       OR uuid_extract_version(p_portal_contact_id) IS DISTINCT FROM 7
     ) THEN
    RAISE EXCEPTION 'DFIR download grant audit input is invalid'
      USING ERRCODE='22023';
  END IF;

  -- Freeze the caller's role graph before any object state is observed. This
  -- serializes the success audit with permission and membership revocation.
  PERFORM app.lock_current_tenant_authorization_state();
  live_authentication_method:=app.require_live_audit_session_v1(
    p_session_id,context_tenant
  );
  PERFORM 1
  FROM public.auth_sessions AS session
  WHERE session.id=p_session_id AND session.user_id=context_user
    AND session.active_tenant_id=context_tenant
    AND session.authentication_method=live_authentication_method
    AND session.revoked_at IS NULL
    AND session.created_at<=transaction_timestamp()
    AND session.last_seen_at<=transaction_timestamp()
    AND session.idle_expires_at>transaction_timestamp()
    AND session.absolute_expires_at>transaction_timestamp()
    AND session.mfa_satisfied_at IS NOT NULL
    AND session.mfa_satisfied_at<=transaction_timestamp()
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR download grant session is unavailable'
      USING ERRCODE='42501';
  END IF;
  context_membership:=app.current_tenant_membership_id();
  IF context_membership IS DISTINCT FROM p_actor_membership_id
     OR live_authentication_method IS DISTINCT FROM p_authentication_method THEN
    RAISE EXCEPTION 'DFIR download grant actor authority is unavailable'
      USING ERRCODE='42501';
  END IF;
  PERFORM 1
  FROM ONLY public.tenants AS tenant
  JOIN ONLY public.tenant_memberships AS membership
    ON membership.tenant_id=tenant.id
  JOIN ONLY public.users AS identity
    ON identity.id=membership.user_id
  WHERE tenant.id=context_tenant AND tenant.status='active'
    AND membership.id=context_membership
    AND membership.user_id=context_user
    AND membership.status='active' AND identity.active
  FOR SHARE OF tenant,membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR download grant actor authority is unavailable'
      USING ERRCODE='42501';
  END IF;

  -- Match the scan worker's attachment -> root -> storage lock order.
  SELECT attachment.* INTO attachment_record
  FROM public.dfir_attachments AS attachment
  WHERE attachment.tenant_id=context_tenant
    AND attachment.id=p_attachment_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR download attachment is unavailable'
      USING ERRCODE='P0002';
  END IF;

  IF p_root_kind='alert' THEN
    SELECT alert.version,alert.assignee_user_id,alert.claimed_by_user_id,
           alert.assigned_team_id,alert.assigned_team_epoch_id,
           alert.workflow_id,alert.workflow_version,alert.state_key,
           alert.customer_visible
    INTO stored_root_version,root_assignee_user_id,root_claimed_by_user_id,
         root_assigned_team_id,root_assigned_team_epoch_id,
         root_workflow_id,root_workflow_version,root_state_key,
         root_customer_visible
    FROM public.alerts AS alert
    WHERE alert.tenant_id=context_tenant AND alert.id=p_root_id
      AND alert.deleted_at IS NULL
    FOR UPDATE;
  ELSE
    SELECT case_record.version,case_record.assignee_user_id,
           case_record.claimed_by_user_id,case_record.assigned_team_id,
           case_record.assigned_team_epoch_id,case_record.workflow_id,
           case_record.workflow_version,case_record.state_key,
           case_record.customer_visible
    INTO stored_root_version,root_assignee_user_id,root_claimed_by_user_id,
         root_assigned_team_id,root_assigned_team_epoch_id,
         root_workflow_id,root_workflow_version,root_state_key,
         root_customer_visible
    FROM public.cases AS case_record
    WHERE case_record.tenant_id=context_tenant AND case_record.id=p_root_id
    FOR UPDATE;
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR download root is unavailable'
      USING ERRCODE='P0002';
  END IF;
  IF stored_root_version IS DISTINCT FROM p_root_version THEN
    RAISE EXCEPTION 'DFIR download root revision is stale'
      USING ERRCODE='40001';
  END IF;

  SELECT storage.* INTO storage_record
  FROM public.dfir_storage_objects AS storage
  WHERE storage.tenant_id=context_tenant
    AND storage.id=p_storage_object_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR download storage object is unavailable'
      USING ERRCODE='P0002';
  END IF;

  IF attachment_record.version IS DISTINCT FROM p_attachment_version
     OR storage_record.version IS DISTINCT FROM p_storage_version
     OR attachment_record.scan_state IS DISTINCT FROM p_attachment_state
     OR storage_record.state IS DISTINCT FROM p_storage_state THEN
    RAISE EXCEPTION 'DFIR download object revision or state is stale'
      USING ERRCODE='40001';
  END IF;
  IF attachment_record.storage_object_id IS DISTINCT FROM storage_record.id
     OR attachment_record.subject_kind IS DISTINCT FROM p_subject_kind
     OR (CASE attachment_record.subject_kind
       WHEN 'alert' THEN attachment_record.alert_id
       WHEN 'case' THEN attachment_record.case_id
       WHEN 'ioc' THEN attachment_record.ioc_id
       WHEN 'asset' THEN attachment_record.asset_id
       WHEN 'evidence' THEN attachment_record.evidence_id
       WHEN 'task' THEN attachment_record.task_id
       ELSE NULL END) IS DISTINCT FROM p_subject_id
     OR storage_record.object_key IS DISTINCT FROM
          context_tenant::text||'/'||storage_record.id::text
     OR octet_length(storage_record.bucket) NOT BETWEEN 3 AND 63
     OR storage_record.original_filename IS DISTINCT FROM
          attachment_record.original_filename
     OR storage_record.created_by_membership_id IS DISTINCT FROM
          attachment_record.uploaded_by_membership_id
     OR storage_record.created_at IS DISTINCT FROM attachment_record.uploaded_at
     OR storage_record.expected_size_bytes NOT BETWEEN 1 AND 5000000000
     OR storage_record.content_sha256 IS NULL
     OR octet_length(storage_record.content_sha256)<>32
     OR storage_record.size_bytes IS DISTINCT FROM
          storage_record.expected_size_bytes
     OR storage_record.detected_mime IS NULL
     OR octet_length(storage_record.detected_mime) NOT BETWEEN 3 AND 512
     OR storage_record.verified_at IS NULL THEN
    RAISE EXCEPTION 'DFIR download attachment purpose has drifted'
      USING ERRCODE='55000';
  END IF;

  IF p_root_kind='alert' THEN
    root_associated:=CASE attachment_record.subject_kind
      WHEN 'alert' THEN attachment_record.alert_id=p_root_id
      WHEN 'ioc' THEN EXISTS (
        SELECT 1
        FROM public.dfir_ioc_links AS link
        JOIN public.dfir_iocs AS resource
          ON resource.tenant_id=link.tenant_id AND resource.id=link.ioc_id
         AND resource.archived_at IS NULL
        WHERE link.tenant_id=context_tenant AND link.alert_id=p_root_id
          AND link.ioc_id=attachment_record.ioc_id
      )
      WHEN 'asset' THEN EXISTS (
        SELECT 1
        FROM public.dfir_asset_links AS link
        JOIN public.dfir_assets AS resource
          ON resource.tenant_id=link.tenant_id AND resource.id=link.asset_id
         AND resource.archived_at IS NULL
        WHERE link.tenant_id=context_tenant AND link.alert_id=p_root_id
          AND link.asset_id=attachment_record.asset_id
      )
      ELSE false END;
  ELSE
    root_associated:=CASE attachment_record.subject_kind
      WHEN 'case' THEN attachment_record.case_id=p_root_id
      WHEN 'evidence' THEN EXISTS (
        SELECT 1 FROM public.dfir_evidence AS evidence
        WHERE evidence.tenant_id=context_tenant
          AND evidence.id=attachment_record.evidence_id
          AND evidence.case_id=p_root_id
      )
      WHEN 'task' THEN EXISTS (
        SELECT 1 FROM public.dfir_tasks AS task
        WHERE task.tenant_id=context_tenant
          AND task.id=attachment_record.task_id AND task.case_id=p_root_id
      )
      WHEN 'alert' THEN EXISTS (
        SELECT 1 FROM public.dfir_attachment_case_links AS explicit_link
        WHERE explicit_link.tenant_id=context_tenant
          AND explicit_link.attachment_id=attachment_record.id
          AND explicit_link.case_id=p_root_id
      ) OR EXISTS (
        SELECT 1
        FROM public.alert_case_links AS link
        JOIN public.alerts AS source_alert
          ON source_alert.tenant_id=link.tenant_id
         AND source_alert.id=link.alert_id AND source_alert.deleted_at IS NULL
        WHERE link.tenant_id=context_tenant
          AND link.case_id=p_root_id
          AND link.alert_id=attachment_record.alert_id
          AND NOT EXISTS (
            SELECT 1
            FROM public.alert_case_link_retractions AS retraction
            WHERE retraction.tenant_id=link.tenant_id
              AND retraction.link_id=link.id
          )
      )
      WHEN 'ioc' THEN EXISTS (
        SELECT 1 FROM public.dfir_attachment_case_links AS explicit_link
        WHERE explicit_link.tenant_id=context_tenant
          AND explicit_link.attachment_id=attachment_record.id
          AND explicit_link.case_id=p_root_id
      ) OR EXISTS (
        SELECT 1
        FROM public.dfir_ioc_links AS link
        JOIN public.dfir_iocs AS resource
          ON resource.tenant_id=link.tenant_id AND resource.id=link.ioc_id
         AND resource.archived_at IS NULL
        WHERE link.tenant_id=context_tenant AND link.case_id=p_root_id
          AND link.ioc_id=attachment_record.ioc_id
      )
      WHEN 'asset' THEN EXISTS (
        SELECT 1 FROM public.dfir_attachment_case_links AS explicit_link
        WHERE explicit_link.tenant_id=context_tenant
          AND explicit_link.attachment_id=attachment_record.id
          AND explicit_link.case_id=p_root_id
      ) OR EXISTS (
        SELECT 1
        FROM public.dfir_asset_links AS link
        JOIN public.dfir_assets AS resource
          ON resource.tenant_id=link.tenant_id AND resource.id=link.asset_id
         AND resource.archived_at IS NULL
        WHERE link.tenant_id=context_tenant AND link.case_id=p_root_id
          AND link.asset_id=attachment_record.asset_id
      )
      ELSE false END;
  END IF;
  IF NOT root_associated THEN
    RAISE EXCEPTION 'DFIR download attachment is not associated with the root'
      USING ERRCODE='42501';
  END IF;

  IF p_actor_kind='human' THEN
    IF NOT app.current_tenant_human_has_exact_permission_v3(
         'dfir.attachment.read',p_scope
       ) OR (CASE p_scope
         WHEN 'tenant' THEN false
         WHEN 'assigned' THEN
           context_user IS DISTINCT FROM root_assignee_user_id
           AND context_user IS DISTINCT FROM root_claimed_by_user_id
         WHEN 'operator_team' THEN root_assigned_team_id IS NULL
           OR root_assigned_team_epoch_id IS NULL OR NOT EXISTS (
             SELECT 1
             FROM public.operator_team_assignment_epochs AS assignment
             JOIN public.operator_team_roster_entries AS roster
               ON roster.tenant_id=assignment.tenant_id
              AND roster.assignment_epoch_id=assignment.id
             JOIN public.tenant_authorization_sources AS source
               ON source.tenant_id=roster.tenant_id
              AND source.id=roster.source_id
             WHERE assignment.tenant_id=context_tenant
               AND assignment.id=root_assigned_team_epoch_id
               AND assignment.operator_team_id=root_assigned_team_id
               AND assignment.ended_at IS NULL
               AND roster.membership_id=context_membership
               AND roster.revoked_at IS NULL
               AND (roster.expires_at IS NULL
                 OR roster.expires_at>transaction_timestamp())
               AND source.retired_at IS NULL
           )
         ELSE true END) THEN
      RAISE EXCEPTION 'DFIR attachment read permission is required'
        USING ERRCODE='42501';
    END IF;
    audit_action:=CASE p_root_kind
      WHEN 'alert' THEN 'dfir.alert.attachment.download_grant_issued'
      ELSE 'dfir.case.attachment.download_grant_issued' END;
  ELSE
    IF attachment_record.visibility IS DISTINCT FROM 'public'
       OR NOT app.current_tenant_human_has_exact_permission_v3(
         'portal.attachment.read','own'
       ) OR NOT app.current_tenant_human_has_exact_permission_v3(
         CASE p_root_kind WHEN 'alert' THEN 'portal.alert.read'
           ELSE 'portal.case.read' END,'own'
       ) OR NOT root_customer_visible OR NOT EXISTS (
         SELECT 1
         FROM public.ticket_workflow_versions AS workflow
         CROSS JOIN LATERAL jsonb_array_elements(workflow.states) AS state(value)
         WHERE workflow.tenant_id=context_tenant
           AND workflow.workflow_id=root_workflow_id
           AND workflow.version=root_workflow_version
           AND workflow.aggregate_kind=p_root_kind
           AND state.value->>'key'=root_state_key
           AND state.value->>'visibility'='customer'
       ) THEN
      RAISE EXCEPTION 'portal DFIR attachment read permission is required'
        USING ERRCODE='42501';
    END IF;
    SELECT contact.id INTO authorized_contact_id
    FROM public.customer_contacts AS contact
    JOIN public.ticket_customer_contacts AS link
      ON link.tenant_id=contact.tenant_id
     AND link.contact_id=contact.id
     AND link.archived_at IS NULL
     AND CASE p_root_kind WHEN 'alert' THEN link.alert_id=p_root_id
       ELSE link.case_id=p_root_id END
    WHERE contact.tenant_id=context_tenant
      AND contact.id=p_portal_contact_id
      AND contact.linked_membership_id=context_membership
      AND contact.linked_user_id=context_user
      AND contact.active AND contact.archived_at IS NULL
    FOR SHARE OF contact,link;
    IF authorized_contact_id IS DISTINCT FROM p_portal_contact_id THEN
      RAISE EXCEPTION 'portal DFIR attachment contact link is unavailable'
        USING ERRCODE='42501';
    END IF;
    audit_action:='dfir.portal.attachment.download_grant_issued';
  END IF;

  INSERT INTO public.audit_events (
    id,tenant_id,sequence,actor_type,actor_user_id,action,resource_type,
    resource_id,request_id,correlation_id,ip_address,user_agent,
    authentication_method,outcome,reason,before,after,metadata
  ) VALUES (
    p_event_id,context_tenant,0,'user',context_user,audit_action,
    'dfir_attachment',attachment_record.id,p_request_id,p_correlation_id,
    p_ip_address,p_user_agent,p_authentication_method,'success',
    'short-lived DFIR attachment download grant issued',NULL,NULL,
    jsonb_build_object(
      'tenantId',context_tenant,
      'actorUserId',context_user,
      'actorSessionId',p_session_id,
      'actorMembershipId',context_membership,
      'rootKind',p_root_kind,
      'rootId',p_root_id,
      'attachmentId',attachment_record.id,
      'storageObjectId',storage_record.id,
      'audience',p_audience,
      'expiresAt',p_expires_at
    )
  );
  RETURN p_event_id;
END;
$function$;
