DO $dfir_download_grant_audit_contract$
DECLARE boundary regprocedure :=
  'app.append_dfir_download_grant_audit_v1(uuid,text,uuid,uuid,public.ticket_aggregate_kind,uuid,bigint,public.dfir_entity_kind,uuid,uuid,bigint,uuid,bigint,public.dfir_scan_state,public.dfir_scan_state,text,public.authorization_scope,uuid,timestamp with time zone,uuid,uuid,inet,text,text)'::regprocedure;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc AS procedure
    WHERE procedure.oid=boundary AND procedure.prosecdef
      AND pg_get_userbyid(procedure.proowner)='periapsis_migrator'
      AND procedure.proconfig @> ARRAY[
        'search_path=pg_catalog, public, app'
      ]::text[]
  ) OR NOT has_function_privilege('periapsis_api',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_worker',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',boundary,'EXECUTE') THEN
    RAISE EXCEPTION 'DFIR download grant audit ABI is not isolated'
      USING ERRCODE='55000';
  END IF;
END;
$dfir_download_grant_audit_contract$;
