-- DFIR_MUTATION_RECEIPTS_V1_BEGIN
-- Response snapshots are bounded and may be pruned, but caller-owned UUIDs
-- and idempotency keys are durable tombstones. A membership epoch remains
-- provenance; the replay namespace is tenant + user + operation + key so a
-- replaced membership can never make a consumed key reusable.
CREATE TYPE public.dfir_mutation_root_kind AS ENUM ('case','alert');
--> statement-breakpoint
CREATE TABLE public.dfir_mutation_resource_ids (
  tenant_id uuid NOT NULL,
  resource_kind text NOT NULL,
  resource_id uuid NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT dfir_mutation_resource_ids_pkey
    PRIMARY KEY (tenant_id,resource_kind,resource_id),
  CONSTRAINT dfir_mutation_resource_ids_tenant_id_tenants_id_fk
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id)
      ON DELETE restrict,
  CONSTRAINT dfir_mutation_resource_ids_shape_check CHECK (
    resource_kind IN (
      'ioc','asset','timeline_event','evidence','custody_event',
      'relationship','relationship_retraction','task','checklist_item',
      'storage_object','attachment'
    )
    AND (uuid_extract_version(resource_id)=7) IS TRUE
  )
);
--> statement-breakpoint
CREATE TABLE public.dfir_mutation_replay_keys (
  tenant_id uuid NOT NULL,
  actor_user_id uuid NOT NULL,
  actor_membership_id uuid NOT NULL,
  operation text NOT NULL,
  key_digest bytea NOT NULL,
  first_used_at timestamp with time zone DEFAULT now() NOT NULL,
  receipt_expires_at timestamp with time zone
    DEFAULT (now()+interval '24 hours') NOT NULL,
  CONSTRAINT dfir_mutation_replay_keys_pkey
    PRIMARY KEY (tenant_id,actor_user_id,operation,key_digest),
  CONSTRAINT dfir_mutation_replay_keys_tenant_id_tenants_id_fk
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id)
      ON DELETE restrict,
  CONSTRAINT dfir_mutation_replay_keys_actor_fk
    FOREIGN KEY (tenant_id,actor_membership_id,actor_user_id)
      REFERENCES public.tenant_memberships(tenant_id,id,user_id)
      ON UPDATE cascade ON DELETE restrict,
  CONSTRAINT dfir_mutation_replay_keys_shape_check CHECK (
    (uuid_extract_version(actor_user_id)=7) IS TRUE
    AND (uuid_extract_version(actor_membership_id)=7) IS TRUE
    AND operation IN (
      'dfir.ioc.create','dfir.ioc.replace',
      'dfir.asset.create','dfir.asset.replace','dfir.timeline.create',
      'dfir.evidence.create','dfir.evidence.custody.append',
      'dfir.relationship.create','dfir.relationship.retract',
      'dfir.attachment.prepare',
      'case.dfir.task.create','case.dfir.task.transition',
      'case.dfir.task.replace_details','case.dfir.task.assign',
      'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
      'case.dfir.task.comments.replace',
      'dfir.alert.evidence.create','dfir.alert.evidence.custody.append',
      'dfir.alert.task.create','dfir.alert.task.transition',
      'dfir.alert.task.replace_details','dfir.alert.task.assign',
      'dfir.alert.task.reschedule','dfir.alert.task.checklist.replace',
      'dfir.alert.task.comments.replace',
      'dfir.alert.relationship.create','dfir.alert.relationship.retract'
    )
    AND octet_length(key_digest)=32
    AND receipt_expires_at>=first_used_at+interval '24 hours'
    AND receipt_expires_at<=first_used_at+interval '7 days'
  )
);
