CREATE TABLE public.dfir_mutation_commands (
  command_id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  actor_user_id uuid NOT NULL,
  actor_membership_id uuid NOT NULL,
  root_kind public.dfir_mutation_root_kind NOT NULL,
  root_id uuid NOT NULL,
  operation text NOT NULL,
  resource_kind text NOT NULL,
  resource_id uuid NOT NULL,
  secondary_resource_id uuid,
  result_version bigint NOT NULL,
  key_digest bytea NOT NULL,
  request_digest bytea NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  expires_at timestamp with time zone
    DEFAULT (now()+interval '24 hours') NOT NULL,
  CONSTRAINT dfir_mutation_commands_tenant_id_tenants_id_fk
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id)
      ON DELETE restrict,
  CONSTRAINT dfir_mutation_commands_actor_fk
    FOREIGN KEY (tenant_id,actor_membership_id,actor_user_id)
      REFERENCES public.tenant_memberships(tenant_id,id,user_id)
      ON UPDATE cascade ON DELETE restrict,
  CONSTRAINT dfir_mutation_commands_replay_key
    UNIQUE (tenant_id,actor_user_id,operation,key_digest),
  CONSTRAINT dfir_mutation_commands_tenant_command_key
    UNIQUE (tenant_id,command_id),
  CONSTRAINT dfir_mutation_commands_result_coordinate_key
    UNIQUE (
      tenant_id,command_id,root_kind,root_id,operation,resource_kind,
      resource_id,result_version
    ),
  CONSTRAINT dfir_mutation_commands_shape_check CHECK (
    (uuid_extract_version(command_id)=7) IS TRUE
    AND (uuid_extract_version(root_id)=7) IS TRUE
    AND (uuid_extract_version(resource_id)=7) IS TRUE
    AND (
      secondary_resource_id IS NULL
      OR (uuid_extract_version(secondary_resource_id)=7) IS TRUE
    )
    AND (
      operation='dfir.ioc.create' AND resource_kind='ioc'
        AND result_version=1 AND secondary_resource_id IS NULL
      OR operation='dfir.ioc.replace' AND resource_kind='ioc'
        AND result_version BETWEEN 2 AND 9007199254740991
        AND secondary_resource_id IS NULL
      OR operation='dfir.asset.create' AND resource_kind='asset'
        AND result_version=1 AND secondary_resource_id IS NULL
      OR operation='dfir.asset.replace' AND resource_kind='asset'
        AND result_version BETWEEN 2 AND 9007199254740991
        AND secondary_resource_id IS NULL
      OR operation='dfir.timeline.create' AND resource_kind='timeline_event'
        AND result_version=1 AND secondary_resource_id IS NULL
      OR operation='dfir.evidence.create' AND root_kind='case'
        AND resource_kind='evidence' AND result_version=1
        AND secondary_resource_id IS NOT NULL
      OR operation='dfir.evidence.custody.append' AND root_kind='case'
        AND resource_kind='evidence' AND result_version BETWEEN 2 AND 1000
        AND secondary_resource_id IS NOT NULL
      OR operation='dfir.relationship.create' AND root_kind='case'
        AND resource_kind='relationship' AND result_version=1
        AND secondary_resource_id IS NULL
      OR operation='dfir.relationship.retract' AND root_kind='case'
        AND resource_kind='relationship' AND result_version=2
        AND secondary_resource_id IS NOT NULL
      OR operation='dfir.attachment.prepare'
        AND resource_kind='storage_object' AND result_version=1
        AND secondary_resource_id IS NOT NULL
    )
    AND octet_length(key_digest)=32
    AND octet_length(request_digest)=32
    AND expires_at>=created_at+interval '24 hours'
    AND expires_at<=created_at+interval '7 days'
  )
);
