CREATE TABLE public.dfir_mutation_command_results (
  command_id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  root_kind public.dfir_mutation_root_kind NOT NULL,
  root_id uuid NOT NULL,
  operation text NOT NULL,
  resource_kind text NOT NULL,
  resource_id uuid NOT NULL,
  result_version bigint NOT NULL,
  result_snapshot jsonb NOT NULL,
  CONSTRAINT dfir_mutation_command_results_tenant_id_tenants_id_fk
    FOREIGN KEY (tenant_id) REFERENCES public.tenants(id)
      ON DELETE restrict,
  CONSTRAINT dfir_mutation_command_results_coordinate_key UNIQUE (
    tenant_id,root_kind,root_id,operation,resource_kind,resource_id,
    result_version
  ),
  CONSTRAINT dfir_mutation_command_results_command_fk FOREIGN KEY (
    tenant_id,command_id,root_kind,root_id,operation,resource_kind,
    resource_id,result_version
  ) REFERENCES public.dfir_mutation_commands(
    tenant_id,command_id,root_kind,root_id,operation,resource_kind,
    resource_id,result_version
  ) ON UPDATE cascade ON DELETE cascade,
  CONSTRAINT dfir_mutation_command_results_shape_check CHECK (
    (uuid_extract_version(command_id)=7) IS TRUE
    AND (uuid_extract_version(root_id)=7) IS TRUE
    AND (uuid_extract_version(resource_id)=7) IS TRUE
    AND result_version BETWEEN 1 AND 9007199254740991
    AND jsonb_typeof(result_snapshot) IS NOT DISTINCT FROM 'object'
    AND result_snapshot ?& ARRAY[
      'schemaVersion','tenantId','rootKind','rootId','operation',
      'resourceKind','resourceId','resultVersion','projection'
    ]
    AND jsonb_typeof(result_snapshot->'schemaVersion')
      IS NOT DISTINCT FROM 'number'
    AND result_snapshot->>'schemaVersion' IS NOT DISTINCT FROM '1'
    AND jsonb_typeof(result_snapshot->'tenantId')
      IS NOT DISTINCT FROM 'string'
    AND (result_snapshot->>'tenantId')::uuid IS NOT DISTINCT FROM tenant_id
    AND jsonb_typeof(result_snapshot->'rootKind')
      IS NOT DISTINCT FROM 'string'
    AND result_snapshot->>'rootKind' IS NOT DISTINCT FROM root_kind::text
    AND jsonb_typeof(result_snapshot->'rootId')
      IS NOT DISTINCT FROM 'string'
    AND (result_snapshot->>'rootId')::uuid IS NOT DISTINCT FROM root_id
    AND jsonb_typeof(result_snapshot->'operation')
      IS NOT DISTINCT FROM 'string'
    AND result_snapshot->>'operation' IS NOT DISTINCT FROM operation
    AND jsonb_typeof(result_snapshot->'resourceKind')
      IS NOT DISTINCT FROM 'string'
    AND result_snapshot->>'resourceKind' IS NOT DISTINCT FROM resource_kind
    AND jsonb_typeof(result_snapshot->'resourceId')
      IS NOT DISTINCT FROM 'string'
    AND (result_snapshot->>'resourceId')::uuid
      IS NOT DISTINCT FROM resource_id
    AND jsonb_typeof(result_snapshot->'resultVersion')
      IS NOT DISTINCT FROM 'number'
    AND (result_snapshot->>'resultVersion')::numeric
      IS NOT DISTINCT FROM result_version
    AND jsonb_typeof(result_snapshot->'projection')
      IS NOT DISTINCT FROM 'object'
    AND octet_length(result_snapshot::text)<=CASE resource_kind
      WHEN 'storage_object' THEN 16384
      WHEN 'evidence' THEN 16777216
      ELSE 262144
    END
  )
);
