INSERT INTO public.dfir_mutation_resource_ids(
  tenant_id,resource_kind,resource_id
)
SELECT tenant_id,'ioc',id FROM public.dfir_iocs
UNION ALL SELECT tenant_id,'asset',id FROM public.dfir_assets
UNION ALL SELECT tenant_id,'timeline_event',id FROM public.dfir_timeline_events
UNION ALL SELECT tenant_id,'evidence',id FROM public.dfir_evidence
UNION ALL SELECT tenant_id,'custody_event',id FROM public.dfir_custody_events
UNION ALL SELECT tenant_id,'relationship',id FROM public.dfir_relationships
UNION ALL SELECT tenant_id,'relationship_retraction',id
  FROM public.dfir_relationship_retractions
UNION ALL SELECT tenant_id,'task',id FROM public.dfir_tasks
UNION ALL SELECT task.tenant_id,'checklist_item',(item.value->>'id')::uuid
  FROM public.dfir_tasks AS task
  CROSS JOIN LATERAL jsonb_array_elements(task.checklist) AS item(value)
UNION ALL SELECT tenant_id,'storage_object',id
  FROM public.dfir_storage_objects
UNION ALL SELECT tenant_id,'attachment',id FROM public.dfir_attachments;
