WITH replay_candidates AS (
  SELECT command.tenant_id,command.actor_user_id,
         command.actor_membership_id,command.operation,command.key_digest,
         command.created_at AS first_used_at,
         command.created_at+interval '24 hours' AS receipt_expires_at
  FROM public.alert_dfir_resource_commands AS command
  UNION ALL
  SELECT command.tenant_id,command.actor_user_id,
         command.actor_membership_id,command.operation,command.key_digest,
         command.created_at,command.created_at+interval '24 hours'
  FROM public.ticket_commands AS command
  WHERE command.operation IN (
    'case.dfir.task.create','case.dfir.task.transition',
    'case.dfir.task.replace_details','case.dfir.task.assign',
    'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
    'case.dfir.task.comments.replace'
  )
  UNION ALL
  SELECT command.tenant_id,membership.user_id,command.actor_membership_id,
         command.operation,command.key_digest,command.created_at,
         command.created_at+interval '24 hours'
  FROM public.tenant_authorization_commands AS command
  JOIN public.tenant_memberships AS membership
    ON membership.tenant_id=command.tenant_id
   AND membership.id=command.actor_membership_id
  WHERE command.operation='dfir.attachment.prepare'
), first_use AS (
  SELECT DISTINCT ON (tenant_id,actor_user_id,operation,key_digest)
         tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
         first_used_at,receipt_expires_at
  FROM replay_candidates
  ORDER BY tenant_id,actor_user_id,operation,key_digest,
           first_used_at,actor_membership_id
)
