-- This trigger is intentionally transaction-aware: a closed command ABI may
-- reserve the UUID first, and the corresponding row insert must consume that
-- reservation in the same transaction. An older tombstone is never accepted.
CREATE FUNCTION app.guard_dfir_mutation_resource_id_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE inserted_rows bigint;
BEGIN
  IF TG_NARGS<>1 OR TG_ARGV[0] IS NULL THEN
    RAISE EXCEPTION 'DFIR resource tombstone trigger is misconfigured'
      USING ERRCODE='55000';
  END IF;
  INSERT INTO public.dfir_mutation_resource_ids(
    tenant_id,resource_kind,resource_id
  ) VALUES (NEW.tenant_id,TG_ARGV[0],NEW.id)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS inserted_rows=ROW_COUNT;
  IF inserted_rows=0 AND NOT EXISTS (
    SELECT 1
    FROM public.dfir_mutation_resource_ids AS registry
    WHERE registry.tenant_id=NEW.tenant_id
      AND registry.resource_kind=TG_ARGV[0]
      AND registry.resource_id=NEW.id
      AND registry.xmin=pg_current_xact_id()::text::xid
  ) THEN
    RAISE EXCEPTION 'DFIR caller-owned resource identifier was already used'
      USING ERRCODE='23505',
            CONSTRAINT='dfir_mutation_resource_ids_pkey';
  END IF;
  RETURN NEW;
END;
$function$;
