CREATE FUNCTION app.private_dfir_json_object_shape_v1(
  p_document jsonb,
  p_required text[],
  p_allowed text[]
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
SET search_path=pg_catalog,public,app
AS $function$
BEGIN
  RETURN coalesce(
    jsonb_typeof(p_document)='object'
      AND p_document ?& p_required
      AND NOT EXISTS (
        SELECT 1 FROM unnest(p_required) AS required(name)
        WHERE p_document->required.name IS NULL
           OR p_document->required.name='null'::jsonb
      )
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_object_keys(p_document) AS field(name)
        WHERE NOT field.name=ANY(p_allowed)
      ),
    false
  );
EXCEPTION WHEN others THEN
  RETURN false;
END;
$function$;
