CREATE FUNCTION app.private_dfir_reference_snapshot_valid_v1(p_value jsonb)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
SET search_path=pg_catalog,public,app
AS $function$
DECLARE reference_kind text;
BEGIN
  IF NOT app.private_dfir_json_object_shape_v1(
    p_value,ARRAY['kind'],
    ARRAY['kind','id','externalType','externalId']
  ) OR jsonb_typeof(p_value->'kind') IS DISTINCT FROM 'string' THEN
    RETURN false;
  END IF;
  reference_kind:=p_value->>'kind';
  IF reference_kind='external' THEN
    RETURN coalesce(
      NOT p_value?'id'
        AND jsonb_typeof(p_value->'externalType')='string'
        AND jsonb_typeof(p_value->'externalId')='string'
        AND p_value->>'externalType'~'^[a-z][a-z0-9_.-]{0,63}$'
        AND octet_length(p_value->>'externalId') BETWEEN 1 AND 2048,
      false
    );
  END IF;
  RETURN coalesce(
    reference_kind IN (
      'alert','case','ioc','asset','evidence','task','attachment'
    )
      AND jsonb_typeof(p_value->'id')='string'
      AND (uuid_extract_version((p_value->>'id')::uuid)=7) IS TRUE
      AND NOT p_value?'externalType'
      AND NOT p_value?'externalId',
    false
  );
EXCEPTION WHEN others THEN
  RETURN false;
END;
$function$;
