CREATE FUNCTION app.private_dfir_mutation_snapshot_valid_v1(
  p_snapshot jsonb,
  p_tenant_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_operation text,
  p_resource_kind text,
  p_resource_id uuid,
  p_secondary_resource_id uuid,
  p_result_version bigint
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE projection jsonb;
DECLARE first_event jsonb;
DECLARE last_event jsonb;
BEGIN
  IF app.private_dfir_json_object_shape_v1(
    p_snapshot,
    ARRAY[
      'schemaVersion','tenantId','rootKind','rootId','operation',
      'resourceKind','resourceId','resultVersion','projection'
    ],
    ARRAY[
      'schemaVersion','tenantId','rootKind','rootId','operation',
      'resourceKind','resourceId','secondaryResourceId','resultVersion',
      'projection'
    ]
  ) IS NOT TRUE
     OR jsonb_typeof(p_snapshot->'schemaVersion') IS DISTINCT FROM 'number'
     OR p_snapshot->>'schemaVersion' IS DISTINCT FROM '1'
     OR jsonb_typeof(p_snapshot->'tenantId') IS DISTINCT FROM 'string'
     OR (p_snapshot->>'tenantId')::uuid IS DISTINCT FROM p_tenant_id
     OR jsonb_typeof(p_snapshot->'rootKind') IS DISTINCT FROM 'string'
     OR p_snapshot->>'rootKind' IS DISTINCT FROM p_root_kind::text
     OR jsonb_typeof(p_snapshot->'rootId') IS DISTINCT FROM 'string'
     OR (p_snapshot->>'rootId')::uuid IS DISTINCT FROM p_root_id
     OR jsonb_typeof(p_snapshot->'operation') IS DISTINCT FROM 'string'
     OR p_snapshot->>'operation' IS DISTINCT FROM p_operation
     OR jsonb_typeof(p_snapshot->'resourceKind') IS DISTINCT FROM 'string'
     OR p_snapshot->>'resourceKind' IS DISTINCT FROM p_resource_kind
     OR jsonb_typeof(p_snapshot->'resourceId') IS DISTINCT FROM 'string'
     OR (p_snapshot->>'resourceId')::uuid IS DISTINCT FROM p_resource_id
     OR jsonb_typeof(p_snapshot->'resultVersion') IS DISTINCT FROM 'number'
     OR (p_snapshot->>'resultVersion')::numeric IS DISTINCT FROM p_result_version
     OR p_result_version NOT BETWEEN 1 AND 9007199254740991
     OR (
       p_secondary_resource_id IS NULL
       AND p_snapshot?'secondaryResourceId'
     ) OR (
       p_secondary_resource_id IS NOT NULL
       AND (
         jsonb_typeof(p_snapshot->'secondaryResourceId')
           IS DISTINCT FROM 'string'
         OR (p_snapshot->>'secondaryResourceId')::uuid IS DISTINCT FROM
            p_secondary_resource_id
       )
     ) THEN
    RETURN false;
  END IF;
  projection:=p_snapshot->'projection';

  IF p_resource_kind='ioc' THEN
    RETURN coalesce(app.private_dfir_json_object_shape_v1(
      projection,
      ARRAY[
        'id','tenantId','type','value','normalizedValue','description',
        'source','confidence','tlp','firstSeen','lastSeen','malicious','tags'
      ],
      ARRAY[
        'id','tenantId','type','value','normalizedValue','description',
        'source','confidence','tlp','firstSeen','lastSeen','malicious','tags',
        'enrichment'
      ]
    )
      AND (projection->>'id')::uuid=p_resource_id
      AND (projection->>'tenantId')::uuid=p_tenant_id
      AND jsonb_typeof(projection->'tags')='array'
      AND jsonb_array_length(projection->'tags')<=256
      AND (
        NOT projection?'enrichment'
        OR jsonb_typeof(projection->'enrichment')='object'
      ),false);
  ELSIF p_resource_kind='asset' THEN
    RETURN coalesce(app.private_dfir_json_object_shape_v1(
      projection,
      ARRAY[
        'id','tenantId','hostname','normalizedHostname','fqdn',
        'normalizedFqdn','ipAddresses','macAddresses','assetType',
        'operatingSystem','owner','businessUnit','criticality','environment',
        'externalId','tags','firstSeen','lastSeen'
      ],
      ARRAY[
        'id','tenantId','hostname','normalizedHostname','fqdn',
        'normalizedFqdn','ipAddresses','macAddresses','assetType',
        'operatingSystem','owner','businessUnit','criticality','environment',
        'externalId','tags','firstSeen','lastSeen','customAttributes'
      ]
    )
      AND (projection->>'id')::uuid=p_resource_id
      AND (projection->>'tenantId')::uuid=p_tenant_id
      AND jsonb_typeof(projection->'ipAddresses')='array'
      AND jsonb_typeof(projection->'macAddresses')='array'
      AND jsonb_typeof(projection->'tags')='array'
      AND jsonb_array_length(projection->'tags')<=256
      AND (
        NOT projection?'customAttributes'
        OR jsonb_typeof(projection->'customAttributes')='object'
      ),false);
  ELSIF p_resource_kind='timeline_event' THEN
    RETURN coalesce(app.private_dfir_json_object_shape_v1(
      projection,
      ARRAY[
        'id','tenantId','eventTime','ingestedAt','originalTimezone',
        'precision','source','category','title','description','iocIds',
        'assetIds','evidenceIds','tags'
      ],
      ARRAY[
        'id','tenantId','alertId','caseId','eventTime','ingestedAt',
        'originalTimezone','precision','source','category','title',
        'description','actorId','iocIds','assetIds','evidenceIds','tags'
      ]
    )
      AND (projection->>'id')::uuid=p_resource_id
      AND (projection->>'tenantId')::uuid=p_tenant_id
      AND (
        p_root_kind='case'
        AND (projection->>'caseId')::uuid=p_root_id
        AND NOT projection?'alertId'
        OR p_root_kind='alert'
        AND (projection->>'alertId')::uuid=p_root_id
        AND NOT projection?'caseId'
      )
      AND jsonb_typeof(projection->'iocIds')='array'
      AND jsonb_typeof(projection->'assetIds')='array'
      AND jsonb_typeof(projection->'evidenceIds')='array'
      AND jsonb_typeof(projection->'tags')='array'
      AND jsonb_array_length(projection->'iocIds')<=256
      AND jsonb_array_length(projection->'assetIds')<=256
      AND jsonb_array_length(projection->'evidenceIds')<=256
      AND jsonb_array_length(projection->'tags')<=256,false);
  ELSIF p_resource_kind='relationship' THEN
    RETURN coalesce(p_root_kind='case'
      AND app.private_dfir_json_object_shape_v1(
        projection,
        ARRAY[
          'id','tenantId','source','target','relationshipType','createdBy',
          'createdAt','version'
        ],
        ARRAY[
          'id','tenantId','source','target','relationshipType','metadata',
          'createdBy','createdAt','version','retractions'
        ]
      )
      AND (projection->>'id')::uuid=p_resource_id
      AND (projection->>'tenantId')::uuid=p_tenant_id
      AND jsonb_typeof(projection->'version')='number'
      AND (projection->>'version')::numeric=p_result_version
      AND app.private_dfir_reference_snapshot_valid_v1(
        projection->'source'
      )
      AND app.private_dfir_reference_snapshot_valid_v1(
        projection->'target'
      )
      AND (
        projection#>>'{source,kind}'='case'
        AND (projection#>>'{source,id}')::uuid=p_root_id
        OR projection#>>'{target,kind}'='case'
        AND (projection#>>'{target,id}')::uuid=p_root_id
      )
      AND (
        p_operation='dfir.relationship.create'
        AND p_secondary_resource_id IS NULL
        AND p_result_version=1
        AND (
          NOT projection?'retractions'
          OR jsonb_typeof(projection->'retractions')='array'
             AND jsonb_array_length(projection->'retractions')=0
        )
        OR p_operation='dfir.relationship.retract'
        AND p_secondary_resource_id IS NOT NULL
        AND p_result_version=2
        AND jsonb_typeof(projection->'retractions')='array'
        AND jsonb_array_length(projection->'retractions')=1
        AND app.private_dfir_json_object_shape_v1(
          projection#>'{retractions,0}',
          ARRAY[
            'id','tenantId','relationshipId','sequence','actorId','reason',
            'occurredAt'
          ],
          ARRAY[
            'id','tenantId','relationshipId','sequence','actorId','reason',
            'occurredAt'
          ]
        )
        AND (projection#>>'{retractions,0,id}')::uuid=
          p_secondary_resource_id
        AND (projection#>>'{retractions,0,tenantId}')::uuid=p_tenant_id
        AND (projection#>>'{retractions,0,relationshipId}')::uuid=
          p_resource_id
        AND projection#>>'{retractions,0,sequence}'='1'
        AND jsonb_typeof(projection#>'{retractions,0,actorId}')='string'
        AND (uuid_extract_version(
          (projection#>>'{retractions,0,actorId}')::uuid
        )=7) IS TRUE
        AND jsonb_typeof(projection#>'{retractions,0,reason}')='string'
        AND jsonb_typeof(projection#>'{retractions,0,occurredAt}')='string'
      ),false);
  ELSIF p_resource_kind='evidence' THEN
    IF p_root_kind IS DISTINCT FROM 'case'::public.dfir_mutation_root_kind
       OR app.private_dfir_json_object_shape_v1(
         projection,
         ARRAY[
           'id','tenantId','caseId','storageObjectId','title','description',
           'evidenceType','classification','contentSha256','sizeBytes',
           'detectedMime','collectedAt','collectedBy','source','legalHold',
           'scanState','initialLegalHold','initialScanState','sealed',
           'destroyed','version','custodyEvents'
         ],
         ARRAY[
           'id','tenantId','caseId','storageObjectId','title','description',
           'evidenceType','classification','contentSha256','sizeBytes',
           'detectedMime','collectedAt','collectedBy','source',
           'retentionUntil','legalHold','scanState','initialRetentionUntil',
           'initialLegalHold','initialScanState','sealed','destroyed',
           'version','custodyEvents'
         ]
       ) IS NOT TRUE
       OR (projection->>'id')::uuid IS DISTINCT FROM p_resource_id
       OR (projection->>'tenantId')::uuid IS DISTINCT FROM p_tenant_id
       OR (projection->>'caseId')::uuid IS DISTINCT FROM p_root_id
       OR jsonb_typeof(projection->'version') IS DISTINCT FROM 'number'
       OR (projection->>'version')::numeric IS DISTINCT FROM p_result_version
       OR p_result_version NOT BETWEEN 1 AND 1000
       OR jsonb_typeof(projection->'custodyEvents') IS DISTINCT FROM 'array'
       OR jsonb_array_length(projection->'custodyEvents')
         IS DISTINCT FROM p_result_version
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(projection->'custodyEvents')
              WITH ORDINALITY AS event(value,ordinality)
         WHERE app.private_dfir_json_object_shape_v1(
           event.value,
           ARRAY[
             'id','tenantId','evidenceId','sequence','action','actorId',
             'reason','stateValue','previousHash','eventHash','occurredAt'
           ],
           ARRAY[
             'id','tenantId','evidenceId','sequence','action','actorId',
             'reason','stateValue','previousHash','eventHash','occurredAt'
           ]
         ) IS NOT TRUE
           OR (event.value->>'tenantId')::uuid IS DISTINCT FROM p_tenant_id
           OR (event.value->>'evidenceId')::uuid
             IS DISTINCT FROM p_resource_id
           OR (event.value->>'sequence')::numeric
             IS DISTINCT FROM event.ordinality
           OR event.ordinality>1000
           OR jsonb_typeof(event.value->'previousHash')
             IS DISTINCT FROM 'string'
           OR jsonb_typeof(event.value->'eventHash')
             IS DISTINCT FROM 'string'
       ) THEN
      RETURN false;
    END IF;
    first_event:=projection#>'{custodyEvents,0}';
    last_event:=projection->'custodyEvents'->(p_result_version::integer-1);
    RETURN coalesce(p_secondary_resource_id IS NOT NULL
      AND (
        p_operation='dfir.evidence.create'
        AND (first_event->>'id')::uuid=p_secondary_resource_id
        OR p_operation='dfir.evidence.custody.append'
        AND (last_event->>'id')::uuid=p_secondary_resource_id
      ),false);
  ELSIF p_resource_kind='storage_object' THEN
    RETURN coalesce(p_operation='dfir.attachment.prepare'
      AND p_secondary_resource_id IS NOT NULL
      AND app.private_dfir_json_object_shape_v1(
        projection,
        ARRAY[
          'storageId','tenantId','createdBy','createdAt','uploadExpiresAt',
          'storageVersion','storageState','attachment'
        ],
        ARRAY[
          'storageId','tenantId','createdBy','createdAt','uploadExpiresAt',
          'storageVersion','storageState','attachment'
        ]
      )
      AND (projection->>'storageId')::uuid=p_resource_id
      AND (projection->>'tenantId')::uuid=p_tenant_id
      AND projection->>'storageVersion'='1'
      AND projection->>'storageState'='pending_upload'
      AND app.private_dfir_json_object_shape_v1(
        projection->'attachment',
        ARRAY[
          'id','tenantId','subject','storageObjectId','originalFilename',
          'visibility','uploadedBy','uploadedAt','scanState'
        ],
        ARRAY[
          'id','tenantId','subject','storageObjectId','originalFilename',
          'visibility','uploadedBy','uploadedAt','scanState'
        ]
      )
      AND (projection#>>'{attachment,id}')::uuid=p_secondary_resource_id
      AND (projection#>>'{attachment,tenantId}')::uuid=p_tenant_id
      AND (projection#>>'{attachment,storageObjectId}')::uuid=p_resource_id
      AND projection#>>'{attachment,visibility}'='private'
      AND projection#>>'{attachment,scanState}'='pending_upload'
      AND app.private_dfir_reference_snapshot_valid_v1(
        projection#>'{attachment,subject}'
      )
      AND app.dfir_attachment_belongs_to_root_v1(
        p_tenant_id,p_root_kind::text,p_root_id,p_secondary_resource_id
      ),false);
  END IF;
  RETURN false;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$function$;
