CREATE FUNCTION app.store_dfir_mutation_command_result_v1(
  p_command_id uuid,
  p_result_snapshot jsonb
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  command_record public.dfir_mutation_commands%ROWTYPE;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE THEN
    RAISE EXCEPTION 'DFIR mutation result binding is invalid'
      USING ERRCODE='22023';
  END IF;
  SELECT command.* INTO command_record
  FROM public.dfir_mutation_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.command_id=p_command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
  FOR UPDATE;
  IF NOT FOUND OR command_record.expires_at<=transaction_timestamp() THEN
    RAISE EXCEPTION 'DFIR mutation command is unavailable'
      USING ERRCODE='23503';
  END IF;
  IF app.private_dfir_mutation_snapshot_valid_v1(
    p_result_snapshot,command_record.tenant_id,command_record.root_kind,
    command_record.root_id,command_record.operation,
    command_record.resource_kind,command_record.resource_id,
    command_record.secondary_resource_id,command_record.result_version
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'DFIR mutation result snapshot is invalid'
      USING ERRCODE='22023';
  END IF;
  INSERT INTO public.dfir_mutation_command_results(
    command_id,tenant_id,root_kind,root_id,operation,resource_kind,
    resource_id,result_version,result_snapshot
  ) VALUES (
    command_record.command_id,command_record.tenant_id,
    command_record.root_kind,command_record.root_id,
    command_record.operation,command_record.resource_kind,
    command_record.resource_id,command_record.result_version,
    p_result_snapshot
  );
  RETURN true;
END;
