-- CASE_DFIR_RELATIONSHIP_RETRACTION_V1_BEGIN
-- The generic receipt reserves the caller-owned retraction UUID before this
-- boundary is invoked. This function consumes that exact coordinate, appends
-- one immutable history row, and compare-and-swaps only the relationship
-- version; the original relationship identity and endpoints never change.
CREATE FUNCTION app.retract_case_dfir_relationship_v1(
  p_command_id uuid,
  p_relationship_id uuid,
  p_case_id uuid,
  p_expected_version bigint,
  p_retraction_id uuid,
  p_reason text,
  p_retracted_at timestamp with time zone
)
RETURNS TABLE(relationship_id uuid,relationship_version bigint)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  command_record public.dfir_mutation_commands%ROWTYPE;
  target public.dfir_relationships%ROWTYPE;
  next_version bigint;
  updated_rows bigint;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE
     OR p_relationship_id IS NULL
     OR (uuid_extract_version(p_relationship_id)=7) IS NOT TRUE
     OR p_case_id IS NULL OR (uuid_extract_version(p_case_id)=7) IS NOT TRUE
     OR p_expected_version NOT BETWEEN 1 AND 9007199254740990
     OR p_retraction_id IS NULL
     OR (uuid_extract_version(p_retraction_id)=7) IS NOT TRUE
     OR p_reason IS NULL OR btrim(p_reason) IS DISTINCT FROM p_reason
     OR octet_length(p_reason) NOT BETWEEN 1 AND 2000
     OR p_reason~'[[:cntrl:]]'
     OR strpos(p_reason,U&'\2028')>0 OR strpos(p_reason,U&'\2029')>0
     OR strpos(p_reason,U&'\200E')>0 OR strpos(p_reason,U&'\200F')>0
     OR p_reason~U&'[\202A-\202E\2066-\2069]'
     OR p_retracted_at IS NULL
     OR p_retracted_at>transaction_timestamp()+interval '5 minutes' THEN
    RAISE EXCEPTION 'Case relationship retraction input is invalid'
      USING ERRCODE='22023';
  END IF;

  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active' AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case relationship retraction authority is unavailable'
      USING ERRCODE='42501';
  END IF;

  SELECT command.* INTO command_record
  FROM public.dfir_mutation_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.command_id=p_command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
  FOR SHARE;
  IF NOT FOUND
     OR command_record.root_kind IS DISTINCT FROM 'case'
     OR command_record.root_id IS DISTINCT FROM p_case_id
     OR command_record.operation IS DISTINCT FROM 'dfir.relationship.retract'
     OR command_record.resource_kind IS DISTINCT FROM 'relationship'
     OR command_record.resource_id IS DISTINCT FROM p_relationship_id
     OR command_record.secondary_resource_id IS DISTINCT FROM p_retraction_id
     OR command_record.result_version IS DISTINCT FROM p_expected_version+1
     OR command_record.expires_at<=transaction_timestamp() THEN
    RAISE EXCEPTION 'Case relationship retraction command is unavailable'
      USING ERRCODE='23503';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.dfir_mutation_resource_ids AS registry
    WHERE registry.tenant_id=context_tenant
      AND registry.resource_kind='relationship_retraction'
      AND registry.resource_id=p_retraction_id
  ) THEN
    RAISE EXCEPTION 'Case relationship retraction identifier is not reserved'
      USING ERRCODE='23503';
  END IF;

  SELECT relationship.* INTO target
  FROM public.dfir_relationships AS relationship
  WHERE relationship.tenant_id=context_tenant
    AND relationship.id=p_relationship_id
    AND relationship.case_id=p_case_id
    AND relationship.alert_id IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case relationship was not found' USING ERRCODE='P0002';
  END IF;
  IF NOT (
    target.source_kind='case' AND target.source_id=p_case_id
    OR target.target_kind='case' AND target.target_id=p_case_id
  ) THEN
    RAISE EXCEPTION 'Case relationship root binding is invalid'
      USING ERRCODE='23503';
  END IF;
  IF target.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'Case relationship version conflict' USING ERRCODE='40001';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.dfir_relationship_retractions AS existing
    WHERE existing.tenant_id=context_tenant
      AND existing.relationship_id=target.id
  ) THEN
    RAISE EXCEPTION 'Case relationship is already retracted'
      USING ERRCODE='55000';
  END IF;
  IF p_retracted_at<target.created_at THEN
    RAISE EXCEPTION 'Case relationship retraction time is invalid'
      USING ERRCODE='22023';
  END IF;

  next_version:=target.version+1;
  INSERT INTO public.dfir_relationship_retractions(
    id,tenant_id,relationship_id,alert_id,case_id,
    retracted_by_membership_id,reason,prior_version,result_version,
    retracted_at
  ) VALUES (
    p_retraction_id,context_tenant,target.id,NULL,target.case_id,
    actor_membership,p_reason,target.version,next_version,p_retracted_at
  );
  UPDATE public.dfir_relationships AS relationship
  SET version=next_version
  WHERE relationship.tenant_id=context_tenant
    AND relationship.id=target.id
    AND relationship.case_id=p_case_id
    AND relationship.alert_id IS NULL
    AND relationship.version=p_expected_version;
  GET DIAGNOSTICS updated_rows=ROW_COUNT;
  IF updated_rows<>1 THEN
    RAISE EXCEPTION 'Case relationship version conflict' USING ERRCODE='40001';
  END IF;
  RETURN QUERY SELECT target.id,next_version;
END;
$function$;
--> statement-breakpoint
ALTER FUNCTION app.retract_case_dfir_relationship_v1(
  uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone
) OWNER TO periapsis_migrator;
--> statement-breakpoint
