GRANT EXECUTE ON FUNCTION app.retract_case_dfir_relationship_v1(
  uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone
) TO periapsis_api;
--> statement-breakpoint

DO $case_dfir_relationship_retraction_contract$
DECLARE boundary regprocedure:=
  'app.retract_case_dfir_relationship_v1(uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone)'::regprocedure;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc AS procedure
    WHERE procedure.oid=boundary AND procedure.prosecdef
      AND pg_get_userbyid(procedure.proowner)='periapsis_migrator'
      AND procedure.proconfig @> ARRAY[
        'search_path=pg_catalog, public, app'
      ]::text[]
  ) OR NOT has_function_privilege('periapsis_api',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_worker',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',boundary,'EXECUTE') THEN
    RAISE EXCEPTION 'Case DFIR relationship retraction ABI is not isolated'
      USING ERRCODE='55000';
  END IF;
END;
$case_dfir_relationship_retraction_contract$;
