CREATE OR REPLACE FUNCTION app.store_alert_investigation_command_result_v1(
  p_command_id uuid,
  p_result_snapshot jsonb
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  command_record public.alert_dfir_resource_commands%ROWTYPE;
  expected_kind text;
  resource_document jsonb;
BEGIN
  SELECT command.* INTO command_record
  FROM public.alert_dfir_resource_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.command_id=p_command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert investigation command is unavailable'
      USING ERRCODE='23503';
  END IF;

  expected_kind:=CASE
    WHEN command_record.operation IN (
      'dfir.alert.evidence.create','dfir.alert.evidence.custody.append'
    ) THEN 'alert_evidence'
    WHEN command_record.operation IN (
      'dfir.alert.task.create','dfir.alert.task.transition',
      'dfir.alert.task.replace_details','dfir.alert.task.assign',
      'dfir.alert.task.reschedule','dfir.alert.task.checklist.replace',
      'dfir.alert.task.comments.replace'
    ) THEN 'alert_task'
    WHEN command_record.operation IN (
      'dfir.alert.relationship.create','dfir.alert.relationship.retract'
    ) THEN 'alert_relationship'
  END;
  resource_document:=CASE expected_kind
    WHEN 'alert_evidence' THEN p_result_snapshot->'evidence'
    WHEN 'alert_task' THEN p_result_snapshot->'task'
    WHEN 'alert_relationship' THEN p_result_snapshot->'relationship'
  END;

  IF expected_kind IS NULL
     OR p_result_snapshot IS NULL
     OR jsonb_typeof(p_result_snapshot) IS DISTINCT FROM 'object'
     OR octet_length(p_result_snapshot::text)>16777216
     OR p_result_snapshot->>'kind' IS DISTINCT FROM expected_kind
     OR resource_document IS NULL
     OR jsonb_typeof(resource_document) IS DISTINCT FROM 'object'
     OR resource_document->>'tenantId' IS DISTINCT FROM context_tenant::text
     OR resource_document->>'alertId'
          IS DISTINCT FROM command_record.alert_id::text
     OR resource_document->>'id'
          IS DISTINCT FROM command_record.resource_id::text
     OR resource_document->>'version'
          IS DISTINCT FROM command_record.result_version::text THEN
    RAISE EXCEPTION 'Alert investigation result snapshot is invalid'
      USING ERRCODE='22023';
  END IF;

  IF expected_kind='alert_task' AND (
    jsonb_typeof(resource_document->'commentIds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(resource_document->'commentIds')>1000
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(resource_document->'commentIds')
        WITH ORDINALITY AS referenced(value,ordinality)
      WHERE jsonb_typeof(referenced.value) IS DISTINCT FROM 'string'
         OR referenced.value#>>'{}'
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         OR EXISTS (
           SELECT 1
           FROM jsonb_array_elements(resource_document->'commentIds')
             WITH ORDINALITY AS duplicate(value,ordinality)
           WHERE duplicate.ordinality<referenced.ordinality
             AND duplicate.value=referenced.value
         )
         OR NOT EXISTS (
           SELECT 1
           FROM public.ticket_comments AS comment
           WHERE comment.tenant_id=context_tenant
             AND comment.alert_id=command_record.alert_id
             AND comment.case_id IS NULL
             AND comment.id=CASE
               WHEN referenced.value#>>'{}'
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
               THEN (referenced.value#>>'{}')::uuid
             END
         )
    )
    OR NOT EXISTS (
      SELECT 1
      FROM public.dfir_tasks AS task
      WHERE task.tenant_id=context_tenant
        AND task.alert_id=command_record.alert_id
        AND task.case_id IS NULL
        AND task.id=command_record.resource_id
        AND task.version=command_record.result_version
        AND to_jsonb(task.comment_ids)=resource_document->'commentIds'
    )
  ) THEN
    RAISE EXCEPTION 'Alert task result references are invalid'
      USING ERRCODE='23503';
  END IF;

  INSERT INTO public.alert_dfir_resource_command_results(
    command_id,tenant_id,alert_id,operation,resource_id,
    result_version,result_snapshot
  ) VALUES (
    command_record.command_id,command_record.tenant_id,
    command_record.alert_id,command_record.operation,
    command_record.resource_id,command_record.result_version,
    p_result_snapshot
  );
  RETURN true;
END;
$function$;
