DO $alert_dfir_task_comments_contract$
DECLARE
  reserve_proc regprocedure:=
    'app.reserve_alert_investigation_command_v1(uuid,uuid,text,uuid,bigint,bytea,bytea)'::regprocedure;
  store_proc regprocedure:=
    'app.store_alert_investigation_command_result_v1(uuid,jsonb)'::regprocedure;
  effects_proc regprocedure:=
    'app.append_alert_investigation_effects_v1(uuid,text,text,text,text,text,text,uuid,bigint,bytea,bytea,uuid,jsonb,jsonb,jsonb,uuid,uuid,uuid,uuid,inet,text,text)'::regprocedure;
  replay_columns text[];
BEGIN
  SELECT array_agg(attribute.attname ORDER BY coordinate.ordinality)
  INTO replay_columns
  FROM pg_constraint AS constraint_row
  CROSS JOIN LATERAL unnest(constraint_row.conkey)
    WITH ORDINALITY AS coordinate(attnum,ordinality)
  JOIN pg_attribute AS attribute
    ON attribute.attrelid=constraint_row.conrelid
   AND attribute.attnum=coordinate.attnum
  WHERE constraint_row.conrelid=
          'public.alert_dfir_resource_commands'::regclass
    AND constraint_row.conname='alert_dfir_resource_commands_replay_key'
    AND constraint_row.contype='u';
  IF replay_columns IS DISTINCT FROM ARRAY[
       'tenant_id','actor_user_id','operation','key_digest'
     ]::text[]
     OR NOT EXISTS (
       SELECT 1
       FROM pg_constraint AS constraint_row
       WHERE constraint_row.conrelid=
               'public.alert_dfir_resource_commands'::regclass
         AND constraint_row.conname='alert_dfir_resource_commands_shape_check'
         AND pg_get_constraintdef(constraint_row.oid)
               LIKE '%dfir.alert.task.comments.replace%'
     )
     OR EXISTS (
       SELECT 1
       FROM pg_proc AS procedure
       WHERE procedure.oid IN (reserve_proc,store_proc,effects_proc)
         AND (
           NOT procedure.prosecdef
           OR pg_get_userbyid(procedure.proowner)<>'periapsis_migrator'
           OR NOT procedure.proconfig @> ARRAY[
             'search_path=pg_catalog, public, app'
           ]::text[]
         )
     )
     OR NOT has_function_privilege('periapsis_api',reserve_proc,'EXECUTE')
     OR NOT has_function_privilege('periapsis_api',store_proc,'EXECUTE')
     OR NOT has_function_privilege('periapsis_api',effects_proc,'EXECUTE')
     OR has_function_privilege('periapsis_worker',reserve_proc,'EXECUTE')
     OR has_function_privilege('periapsis_worker',store_proc,'EXECUTE')
     OR has_function_privilege('periapsis_worker',effects_proc,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',reserve_proc,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',store_proc,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',effects_proc,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',reserve_proc,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',store_proc,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',effects_proc,'EXECUTE') THEN
    RAISE EXCEPTION 'Alert task comment ABI is not isolated'
      USING ERRCODE='55000';
  END IF;
END;
$alert_dfir_task_comments_contract$;
-- ALERT_DFIR_TASK_COMMENTS_V1_END

-- SHARED_DFIR_RESOURCE_LIFECYCLE_V1_BEGIN
-- Constraint expressions generated from the canonical Drizzle check definitions.
ALTER TABLE public.dfir_mutation_resource_ids DROP CONSTRAINT dfir_mutation_resource_ids_shape_check;
--> statement-breakpoint
ALTER TABLE public.dfir_mutation_resource_ids ADD CONSTRAINT dfir_mutation_resource_ids_shape_check CHECK (resource_kind in ('ioc','asset','timeline_event','evidence','custody_event','relationship','relationship_retraction','task','checklist_item','storage_object','attachment','shared_link_event')
        and (uuid_extract_version(resource_id) = 7) is true);
--> statement-breakpoint
ALTER TABLE public.dfir_mutation_replay_keys DROP CONSTRAINT dfir_mutation_replay_keys_shape_check;
--> statement-breakpoint
ALTER TABLE public.dfir_mutation_replay_keys ADD CONSTRAINT dfir_mutation_replay_keys_shape_check CHECK ((uuid_extract_version(actor_user_id) = 7) is true
        and (uuid_extract_version(actor_membership_id) = 7) is true
        and operation in (
          'dfir.ioc.create','dfir.ioc.replace','dfir.asset.create','dfir.asset.replace',
          'dfir.ioc.link','dfir.ioc.unlink','dfir.asset.link','dfir.asset.unlink',
          'dfir.timeline.create','dfir.evidence.create','dfir.evidence.custody.append',
          'dfir.relationship.create','dfir.relationship.retract','dfir.attachment.prepare',
          'case.dfir.task.create','case.dfir.task.transition','case.dfir.task.replace_details',
          'case.dfir.task.assign','case.dfir.task.reschedule','case.dfir.task.replace_checklist',
          'dfir.alert.evidence.create','dfir.alert.evidence.custody.append',
