CREATE TABLE "dfir_shared_resource_link_events" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"resource_kind" text NOT NULL,
	"ioc_id" uuid,
	"asset_id" uuid,
	"case_id" uuid,
	"alert_id" uuid,
	"link_id" uuid NOT NULL,
	"event_kind" text NOT NULL,
	"prior_version" bigint NOT NULL,
	"result_version" bigint NOT NULL,
	"actor_membership_id" uuid NOT NULL,
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dfir_shared_link_events_shape_check" CHECK ((uuid_extract_version("dfir_shared_resource_link_events"."id") = 7) is true
      and (uuid_extract_version("dfir_shared_resource_link_events"."link_id") = 7) is true
      and num_nonnulls("dfir_shared_resource_link_events"."case_id", "dfir_shared_resource_link_events"."alert_id") = 1
      and (("dfir_shared_resource_link_events"."resource_kind" = 'ioc' and "dfir_shared_resource_link_events"."ioc_id" is not null and "dfir_shared_resource_link_events"."asset_id" is null)
        or ("dfir_shared_resource_link_events"."resource_kind" = 'asset' and "dfir_shared_resource_link_events"."asset_id" is not null and "dfir_shared_resource_link_events"."ioc_id" is null))
      and "dfir_shared_resource_link_events"."event_kind" in ('linked','unlinked','imported')
      and "dfir_shared_resource_link_events"."prior_version" between 0 and 9007199254740991
      and "dfir_shared_resource_link_events"."result_version" between 1 and 9007199254740991
      and (("dfir_shared_resource_link_events"."event_kind" = 'imported' and "dfir_shared_resource_link_events"."result_version" = "dfir_shared_resource_link_events"."prior_version")
        or ("dfir_shared_resource_link_events"."event_kind" <> 'imported' and "dfir_shared_resource_link_events"."result_version" = "dfir_shared_resource_link_events"."prior_version" + 1)))
);
