CREATE FUNCTION app.private_lock_shared_dfir_roots_v1(
  p_tenant_id uuid,p_kind text,p_resource_id uuid,
  p_case_id uuid,p_alert_id uuid,p_authorize boolean,p_permission_key text DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  roots jsonb;
  result_roots jsonb;
  candidate jsonb;
  root_id uuid;
  permission_key text;
  archived_at timestamp with time zone;
BEGIN
  IF p_tenant_id IS NULL OR p_resource_id IS NULL
     OR p_kind NOT IN ('ioc','asset')
     OR num_nonnulls(p_case_id,p_alert_id)>1 THEN
    RAISE EXCEPTION 'Shared DFIR root coordinates are invalid' USING ERRCODE='22023';
  END IF;
  IF p_authorize THEN
    IF p_tenant_id IS DISTINCT FROM app.context_tenant_id() THEN
      RAISE EXCEPTION 'Shared DFIR tenant authority is required' USING ERRCODE='42501';
    END IF;
    PERFORM app.lock_current_tenant_authorization_state();
    PERFORM 1 FROM public.tenant_memberships AS membership
    JOIN public.users AS identity ON identity.id=membership.user_id
    WHERE membership.tenant_id=p_tenant_id
      AND membership.id=app.current_tenant_membership_id()
      AND membership.user_id=app.context_user_id()
      AND membership.status='active' AND identity.active
    FOR SHARE OF membership,identity;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Shared DFIR human authority is unavailable' USING ERRCODE='42501';
    END IF;
  END IF;
  IF p_kind='ioc' THEN
    SELECT resource.archived_at INTO archived_at FROM public.dfir_iocs AS resource
    WHERE resource.tenant_id=p_tenant_id AND resource.id=p_resource_id FOR UPDATE;
    IF NOT FOUND OR archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'Shared IOC is unavailable' USING ERRCODE='P0002';
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'kind',CASE WHEN link.case_id IS NOT NULL THEN 'case' ELSE 'alert' END,
      'id',coalesce(link.case_id,link.alert_id),'active',true
    )),'[]'::jsonb) INTO roots
    FROM (SELECT case_id,alert_id FROM public.dfir_ioc_links
      WHERE tenant_id=p_tenant_id AND ioc_id=p_resource_id LIMIT 65) AS link;
  ELSE
    SELECT resource.archived_at INTO archived_at FROM public.dfir_assets AS resource
    WHERE resource.tenant_id=p_tenant_id AND resource.id=p_resource_id FOR UPDATE;
    IF NOT FOUND OR archived_at IS NOT NULL THEN
      RAISE EXCEPTION 'Shared asset is unavailable' USING ERRCODE='P0002';
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'kind',CASE WHEN link.case_id IS NOT NULL THEN 'case' ELSE 'alert' END,
      'id',coalesce(link.case_id,link.alert_id),'active',true
    )),'[]'::jsonb) INTO roots
    FROM (SELECT case_id,alert_id FROM public.dfir_asset_links
      WHERE tenant_id=p_tenant_id AND asset_id=p_resource_id LIMIT 65) AS link;
  END IF;
  IF jsonb_array_length(roots)>64 THEN
    RAISE EXCEPTION 'Shared DFIR resource root fanout exceeds 64' USING ERRCODE='54000';
  END IF;
  IF num_nonnulls(p_case_id,p_alert_id)=1 AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
    WHERE value->>'kind'=CASE WHEN p_case_id IS NOT NULL THEN 'case' ELSE 'alert' END
      AND (value->>'id')::uuid=coalesce(p_case_id,p_alert_id)
  ) THEN
    roots:=roots||jsonb_build_array(jsonb_build_object(
      'kind',CASE WHEN p_case_id IS NOT NULL THEN 'case' ELSE 'alert' END,
      'id',coalesce(p_case_id,p_alert_id),'active',false
    ));
  END IF;
  SELECT coalesce(jsonb_agg(value ORDER BY value->>'kind',(value->>'id')::uuid),'[]'::jsonb)
  INTO result_roots FROM jsonb_array_elements(roots) AS root(value);
  permission_key:=coalesce(p_permission_key,'dfir.'||p_kind||'.manage');
  IF permission_key NOT IN ('dfir.'||p_kind||'.manage','dfir.attachment.manage') THEN
    RAISE EXCEPTION 'Shared DFIR capability is invalid' USING ERRCODE='22023';
  END IF;
  FOR candidate IN SELECT value FROM jsonb_array_elements(result_roots) AS root(value)
  LOOP
    root_id:=(candidate->>'id')::uuid;
    IF candidate->>'kind'='case' THEN
      PERFORM 1 FROM public.cases WHERE tenant_id=p_tenant_id AND id=root_id FOR UPDATE;
      IF NOT FOUND OR (p_authorize AND app.private_current_dfir_scope_allows_v1(permission_key,root_id) IS NOT TRUE) THEN
        RAISE EXCEPTION 'Every linked Case requires DFIR mutation authority' USING ERRCODE='42501';
      END IF;
    ELSE
      PERFORM 1 FROM public.alerts WHERE tenant_id=p_tenant_id AND id=root_id AND deleted_at IS NULL FOR UPDATE;
      IF NOT FOUND OR (p_authorize AND app.private_current_alert_dfir_manage_scope_allows_v1(permission_key,root_id) IS NOT TRUE) THEN
        RAISE EXCEPTION 'Every linked Alert requires DFIR mutation authority' USING ERRCODE='42501';
      END IF;
    END IF;
  END LOOP;
  RETURN result_roots;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_append_shared_dfir_activity_v1(
  p_id uuid,p_tenant_id uuid,p_root_kind text,p_root_id uuid,
  p_kind text,p_resource_id uuid,p_version bigint,p_action text,
  p_command_id uuid,p_link_event_id uuid
)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  activity_sequence bigint;
  details jsonb:=jsonb_build_object('resourceId',p_resource_id,
    'resourceVersion',p_version,'contentRedacted',true);
BEGIN
  IF (uuid_extract_version(p_id)=7) IS NOT TRUE
     OR p_kind NOT IN ('ioc','asset','attachment')
     OR p_version NOT BETWEEN 1 AND 9007199254740991
     OR p_action NOT IN ('dfir.ioc.created','dfir.ioc.replaced','dfir.ioc.linked','dfir.ioc.unlinked',
       'dfir.asset.created','dfir.asset.replaced','dfir.asset.linked','dfir.asset.unlinked','dfir.attachment.prepared') THEN
    RAISE EXCEPTION 'Shared DFIR activity is invalid' USING ERRCODE='22023';
  END IF;
  IF p_command_id IS NOT NULL THEN details:=details||jsonb_build_object('commandId',p_command_id); END IF;
  IF p_link_event_id IS NOT NULL THEN details:=details||jsonb_build_object('linkEventId',p_link_event_id); END IF;
  IF p_root_kind='case' THEN
    IF p_command_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.dfir_activities AS activity WHERE activity.tenant_id=p_tenant_id AND activity.case_id=p_root_id
        AND activity.details->>'commandId'=p_command_id::text
    ) THEN
      RAISE EXCEPTION 'Shared DFIR activity already emitted' USING ERRCODE='23505';
    END IF;
    INSERT INTO public.dfir_activities(
      id,tenant_id,case_id,resource_kind,resource_id,action,summary,
      actor_principal_kind,actor_membership_id,actor_user_id,details
    ) VALUES (p_id,p_tenant_id,p_root_id,p_kind::public.dfir_entity_kind,p_resource_id,
      p_action,'Shared investigation resource changed','human',
      app.current_tenant_membership_id(),app.context_user_id(),details);
  ELSIF p_root_kind='alert' THEN
    IF p_command_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.ticket_activities AS activity
      WHERE activity.tenant_id=p_tenant_id AND activity.alert_id=p_root_id
        AND activity.details->>'commandId'=p_command_id::text
    ) THEN
      RAISE EXCEPTION 'Shared DFIR activity already emitted' USING ERRCODE='23505';
    END IF;
    SELECT coalesce(max(sequence),0)::bigint+1 INTO activity_sequence
    FROM public.ticket_activities WHERE tenant_id=p_tenant_id AND alert_id=p_root_id;
    IF activity_sequence NOT BETWEEN 1 AND 2147483647 THEN
      RAISE EXCEPTION 'Alert activity sequence is exhausted' USING ERRCODE='54000';
    END IF;
    INSERT INTO public.ticket_activities(
      id,tenant_id,alert_id,sequence,kind,summary,actor_principal_kind,
      actor_membership_id,actor_user_id,origin,details
    ) VALUES (p_id,p_tenant_id,p_root_id,activity_sequence::integer,p_action,
      'Shared investigation resource changed','human',
      app.current_tenant_membership_id(),app.context_user_id(),'api',details);
  ELSE
    RAISE EXCEPTION 'Shared DFIR activity root is invalid' USING ERRCODE='22023';
  END IF;
END;
$function$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION app.reserve_dfir_mutation_command_v1(
  p_command_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_operation text,
  p_resource_kind text,
  p_resource_id uuid,
  p_secondary_resource_id uuid,
  p_result_version bigint,
  p_key_digest bytea,
  p_request_digest bytea
)
RETURNS TABLE(
  command_id uuid,
  result_resource_id uuid,
  result_secondary_resource_id uuid,
  result_version bigint,
  result_snapshot jsonb,
  replayed boolean
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  expected_permission text;
  tombstone public.dfir_mutation_replay_keys%ROWTYPE;
  command_record public.dfir_mutation_commands%ROWTYPE;
  stored_snapshot jsonb;
  receipt_created_at timestamp with time zone:=transaction_timestamp();
  roots jsonb;
  shared_attachment public.dfir_attachments%ROWTYPE;
  resource_found boolean:=false;
BEGIN
  expected_permission:=CASE p_operation
    WHEN 'dfir.ioc.create' THEN 'dfir.ioc.manage'
    WHEN 'dfir.ioc.replace' THEN 'dfir.ioc.manage'
    WHEN 'dfir.ioc.link' THEN 'dfir.ioc.manage'
    WHEN 'dfir.ioc.unlink' THEN 'dfir.ioc.manage'
    WHEN 'dfir.asset.create' THEN 'dfir.asset.manage'
    WHEN 'dfir.asset.replace' THEN 'dfir.asset.manage'
    WHEN 'dfir.asset.link' THEN 'dfir.asset.manage'
    WHEN 'dfir.asset.unlink' THEN 'dfir.asset.manage'
    WHEN 'dfir.timeline.create' THEN 'dfir.timeline.manage'
    WHEN 'dfir.evidence.create' THEN 'dfir.evidence.manage'
    WHEN 'dfir.evidence.custody.append' THEN 'dfir.evidence.manage'
    WHEN 'dfir.relationship.create' THEN 'dfir.relationship.manage'
    WHEN 'dfir.relationship.retract' THEN 'dfir.relationship.manage'
    WHEN 'dfir.attachment.prepare' THEN 'dfir.attachment.manage'
    ELSE NULL END;
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE
     OR p_root_id IS NULL
     OR (uuid_extract_version(p_root_id)=7) IS NOT TRUE
     OR p_resource_id IS NULL
     OR (uuid_extract_version(p_resource_id)=7) IS NOT TRUE
     OR (
       p_secondary_resource_id IS NOT NULL
       AND (uuid_extract_version(p_secondary_resource_id)=7) IS NOT TRUE
     )
     OR expected_permission IS NULL
     OR p_key_digest IS NULL OR octet_length(p_key_digest)<>32
     OR p_request_digest IS NULL OR octet_length(p_request_digest)<>32
     OR NOT (
       p_operation='dfir.ioc.create' AND p_resource_kind='ioc'
         AND p_result_version=1 AND p_secondary_resource_id IS NULL
       OR p_operation='dfir.ioc.replace' AND p_resource_kind='ioc'
         AND p_result_version BETWEEN 2 AND 9007199254740991
         AND p_secondary_resource_id IS NULL
       OR p_operation IN ('dfir.ioc.link','dfir.ioc.unlink') AND p_resource_kind='ioc'
         AND p_result_version BETWEEN 2 AND 9007199254740991
         AND p_secondary_resource_id IS NOT NULL
       OR p_operation='dfir.asset.create' AND p_resource_kind='asset'
         AND p_result_version=1 AND p_secondary_resource_id IS NULL
       OR p_operation='dfir.asset.replace' AND p_resource_kind='asset'
         AND p_result_version BETWEEN 2 AND 9007199254740991
         AND p_secondary_resource_id IS NULL
       OR p_operation IN ('dfir.asset.link','dfir.asset.unlink') AND p_resource_kind='asset'
         AND p_result_version BETWEEN 2 AND 9007199254740991
         AND p_secondary_resource_id IS NOT NULL
       OR p_operation='dfir.timeline.create'
         AND p_resource_kind='timeline_event' AND p_result_version=1
         AND p_secondary_resource_id IS NULL
       OR p_operation='dfir.evidence.create' AND p_root_kind='case'
         AND p_resource_kind='evidence' AND p_result_version=1
         AND p_secondary_resource_id IS NOT NULL
       OR p_operation='dfir.evidence.custody.append'
         AND p_root_kind='case' AND p_resource_kind='evidence'
         AND p_result_version BETWEEN 2 AND 1000
         AND p_secondary_resource_id IS NOT NULL
       OR p_operation='dfir.relationship.create' AND p_root_kind='case'
         AND p_resource_kind='relationship' AND p_result_version=1
         AND p_secondary_resource_id IS NULL
       OR p_operation='dfir.relationship.retract' AND p_root_kind='case'
         AND p_resource_kind='relationship' AND p_result_version=2
         AND p_secondary_resource_id IS NOT NULL
       OR p_operation='dfir.attachment.prepare'
         AND p_resource_kind='storage_object' AND p_result_version=1
         AND p_secondary_resource_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'DFIR mutation command binding is invalid'
      USING ERRCODE='22023';
  END IF;

  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active'
    AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR mutation human authority is unavailable'
      USING ERRCODE='42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    context_tenant::text||':'||actor_user::text||':'||p_operation||':'||
    encode(p_key_digest,'hex'),82419733
  ));
  IF p_resource_kind IN ('ioc','asset') THEN
    IF p_resource_kind='ioc' THEN
      PERFORM 1 FROM public.dfir_iocs WHERE tenant_id=context_tenant AND id=p_resource_id FOR UPDATE;
    ELSE
      PERFORM 1 FROM public.dfir_assets WHERE tenant_id=context_tenant AND id=p_resource_id FOR UPDATE;
    END IF;
    resource_found:=FOUND;
    IF resource_found OR p_operation NOT IN ('dfir.ioc.create','dfir.asset.create') THEN
      roots:=app.private_lock_shared_dfir_roots_v1(context_tenant,p_resource_kind,p_resource_id,
        CASE WHEN p_root_kind='case' THEN p_root_id END,
        CASE WHEN p_root_kind='alert' THEN p_root_id END,true);
      IF p_operation IN ('dfir.ioc.create','dfir.ioc.replace','dfir.asset.create','dfir.asset.replace')
         AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
           WHERE value->>'kind'=p_root_kind::text AND (value->>'id')::uuid=p_root_id
             AND (value->>'active')::boolean) THEN
        RAISE EXCEPTION 'Shared DFIR resource is not linked to the path root' USING ERRCODE='23503';
      END IF;
    ELSIF p_root_kind='case' THEN
      PERFORM 1 FROM public.cases WHERE tenant_id=context_tenant AND id=p_root_id FOR UPDATE;
      IF NOT FOUND OR app.private_current_dfir_scope_allows_v1(expected_permission,p_root_id) IS NOT TRUE THEN
        RAISE EXCEPTION 'Case DFIR mutation authority is required' USING ERRCODE='42501';
      END IF;
    ELSE
      PERFORM 1 FROM public.alerts WHERE tenant_id=context_tenant AND id=p_root_id AND deleted_at IS NULL FOR UPDATE;
      IF NOT FOUND OR app.private_current_alert_dfir_manage_scope_allows_v1(expected_permission,p_root_id) IS NOT TRUE THEN
        RAISE EXCEPTION 'Alert DFIR mutation authority is required' USING ERRCODE='42501';
      END IF;
    END IF;
  ELSIF p_operation='dfir.attachment.prepare' AND EXISTS(
    SELECT 1 FROM public.dfir_attachments WHERE tenant_id=context_tenant
      AND storage_object_id=p_resource_id AND subject_kind IN ('ioc','asset')
  ) THEN
    SELECT * INTO STRICT shared_attachment FROM public.dfir_attachments
    WHERE tenant_id=context_tenant AND storage_object_id=p_resource_id;
    roots:=app.private_lock_shared_dfir_roots_v1(context_tenant,shared_attachment.subject_kind::text,
      coalesce(shared_attachment.ioc_id,shared_attachment.asset_id),NULL,NULL,true,'dfir.attachment.manage');
    IF shared_attachment.id IS DISTINCT FROM p_secondary_resource_id
       OR shared_attachment.scan_state='deleted'
       OR NOT EXISTS(SELECT 1 FROM public.dfir_storage_objects
         WHERE tenant_id=context_tenant AND id=p_resource_id AND state<>'deleted')
       OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
         WHERE value->>'kind'=p_root_kind::text AND (value->>'id')::uuid=p_root_id) THEN
      RAISE EXCEPTION 'Shared attachment replay authority is unavailable' USING ERRCODE='42501';
    END IF;
  ELSIF p_root_kind='case' THEN
    PERFORM 1 FROM public.cases AS root
    WHERE root.tenant_id=context_tenant AND root.id=p_root_id
    FOR UPDATE;
    IF NOT FOUND OR app.private_current_dfir_scope_allows_v1(
      expected_permission,p_root_id
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'Case DFIR mutation authority is required'
        USING ERRCODE='42501';
    END IF;
  ELSE
    PERFORM 1 FROM public.alerts AS root
    WHERE root.tenant_id=context_tenant AND root.id=p_root_id
      AND root.deleted_at IS NULL
    FOR UPDATE;
    IF NOT FOUND OR app.private_current_alert_dfir_manage_scope_allows_v1(
      expected_permission,p_root_id
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'Alert DFIR mutation authority is required'
        USING ERRCODE='42501';
    END IF;
  END IF;

  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry
  WHERE registry.tenant_id=context_tenant
    AND registry.actor_user_id=actor_user
    AND registry.operation=p_operation
    AND registry.key_digest=p_key_digest
  FOR UPDATE;
  IF FOUND THEN
    IF tombstone.actor_membership_id IS DISTINCT FROM actor_membership THEN
      RAISE EXCEPTION 'DFIR idempotency key belongs to another membership epoch'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    SELECT existing.* INTO command_record
    FROM public.dfir_mutation_commands AS existing
    WHERE existing.tenant_id=context_tenant
      AND existing.actor_user_id=actor_user
      AND existing.operation=p_operation
      AND existing.key_digest=p_key_digest
    FOR UPDATE;
    IF NOT FOUND OR command_record.expires_at<=transaction_timestamp()
       OR command_record.actor_membership_id IS DISTINCT FROM actor_membership
       OR command_record.root_kind IS DISTINCT FROM p_root_kind
       OR command_record.root_id IS DISTINCT FROM p_root_id
       OR command_record.resource_kind IS DISTINCT FROM p_resource_kind
       OR command_record.resource_id IS DISTINCT FROM p_resource_id
       OR command_record.secondary_resource_id IS DISTINCT FROM
          p_secondary_resource_id
       OR command_record.result_version IS DISTINCT FROM p_result_version
       OR command_record.request_digest IS DISTINCT FROM p_request_digest THEN
      RAISE EXCEPTION 'DFIR idempotency key conflicts or receipt expired'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    SELECT result.result_snapshot INTO stored_snapshot
    FROM public.dfir_mutation_command_results AS result
    WHERE result.command_id=command_record.command_id
      AND result.tenant_id=command_record.tenant_id
      AND result.root_kind=command_record.root_kind
      AND result.root_id=command_record.root_id
      AND result.operation=command_record.operation
      AND result.resource_kind=command_record.resource_kind
      AND result.resource_id=command_record.resource_id
      AND result.result_version=command_record.result_version;
    IF NOT FOUND OR app.private_dfir_mutation_snapshot_valid_v1(
      stored_snapshot,context_tenant,p_root_kind,p_root_id,p_operation,
      p_resource_kind,p_resource_id,p_secondary_resource_id,p_result_version
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'DFIR immutable result receipt is unavailable'
        USING ERRCODE='55000';
    END IF;
    IF p_operation IN ('dfir.ioc.link','dfir.asset.link') AND NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
      WHERE value->>'kind'=p_root_kind::text AND (value->>'id')::uuid=p_root_id
        AND (value->>'active')::boolean
    ) THEN
      RAISE EXCEPTION 'Shared DFIR link replay association is no longer active' USING ERRCODE='42501';
    END IF;
    RETURN QUERY SELECT command_record.command_id,p_resource_id,
      p_secondary_resource_id,p_result_version,stored_snapshot,true;
    RETURN;
  END IF;

  IF p_operation IN (
    'dfir.ioc.create','dfir.asset.create','dfir.timeline.create',
    'dfir.evidence.create','dfir.relationship.create',
    'dfir.attachment.prepare'
  ) THEN
    INSERT INTO public.dfir_mutation_resource_ids(
      tenant_id,resource_kind,resource_id,created_at
    ) VALUES (
      context_tenant,p_resource_kind,p_resource_id,receipt_created_at
    );
  END IF;
  IF p_secondary_resource_id IS NOT NULL THEN
    INSERT INTO public.dfir_mutation_resource_ids(
      tenant_id,resource_kind,resource_id,created_at
    ) VALUES (
      context_tenant,
      CASE p_operation
        WHEN 'dfir.attachment.prepare' THEN 'attachment'
        WHEN 'dfir.relationship.retract' THEN 'relationship_retraction'
        WHEN 'dfir.ioc.link' THEN 'shared_link_event'
        WHEN 'dfir.ioc.unlink' THEN 'shared_link_event'
        WHEN 'dfir.asset.link' THEN 'shared_link_event'
        WHEN 'dfir.asset.unlink' THEN 'shared_link_event'
        ELSE 'custody_event' END,
      p_secondary_resource_id,receipt_created_at
    );
  END IF;
  INSERT INTO public.dfir_mutation_replay_keys(
    tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
    first_used_at,receipt_expires_at
  ) VALUES (
    context_tenant,actor_user,actor_membership,p_operation,p_key_digest,
    receipt_created_at,receipt_created_at+interval '24 hours'
  );
  INSERT INTO public.dfir_mutation_commands(
    command_id,tenant_id,actor_user_id,actor_membership_id,root_kind,
    root_id,operation,resource_kind,resource_id,secondary_resource_id,
    result_version,key_digest,request_digest,created_at,expires_at
  ) VALUES (
    p_command_id,context_tenant,actor_user,actor_membership,p_root_kind,
    p_root_id,p_operation,p_resource_kind,p_resource_id,
    p_secondary_resource_id,p_result_version,p_key_digest,p_request_digest,
    receipt_created_at,receipt_created_at+interval '24 hours'
  );

  -- The established Alert effects ABI still reads the legacy reservation
  -- ledgers. Mirror only the non-secret coordinate until that ABI is retired;
  -- replay authority remains exclusively in the generic immutable receipt.
  IF p_root_kind='alert' AND p_operation IN (
    'dfir.ioc.create','dfir.ioc.replace','dfir.asset.create',
    'dfir.asset.replace','dfir.timeline.create'
  ) THEN
    INSERT INTO public.alert_dfir_resource_commands(
      command_id,tenant_id,actor_user_id,actor_membership_id,alert_id,
      operation,resource_id,result_version,key_digest,request_digest,
      created_at
    ) VALUES (
      p_command_id,context_tenant,actor_user,actor_membership,p_root_id,
      p_operation,p_resource_id,p_result_version,p_key_digest,
      p_request_digest,receipt_created_at
    );
  ELSIF p_root_kind='alert'
        AND p_operation='dfir.attachment.prepare' THEN
    INSERT INTO public.tenant_authorization_commands(
      id,tenant_id,actor_membership_id,operation,key_digest,request_digest,
      result_resource_id,result_version,created_at,expires_at
    ) VALUES (
      p_command_id,context_tenant,actor_membership,p_operation,p_key_digest,
      p_request_digest,p_resource_id,1,receipt_created_at,
      receipt_created_at+interval '24 hours'
    );
  END IF;
  RETURN QUERY SELECT p_command_id,p_resource_id,p_secondary_resource_id,
    p_result_version,NULL::jsonb,false;
END;
$function$;
--> statement-breakpoint

-- Every association writer, including ticket escalation, uses the same lock,
-- authorization, cardinality, revision and immutable history boundary.
CREATE FUNCTION app.guard_shared_dfir_link_v1()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  link_row jsonb;
  tenant_id uuid;
  resource_id uuid;
  resource_kind text;
  case_id uuid;
  alert_id uuid;
  link_id uuid;
  actor_membership uuid;
  event_id uuid;
  roots jsonb;
  candidate jsonb;
  active_count integer;
  current_version bigint;
  result_version bigint;
  prior_version bigint;
  runtime_write boolean;
  command_record public.dfir_mutation_commands%ROWTYPE;
  action text;
BEGIN
  IF TG_OP NOT IN ('INSERT','DELETE') OR TG_TABLE_NAME NOT IN ('dfir_ioc_links','dfir_asset_links') THEN
    RAISE EXCEPTION 'Shared DFIR links are replaced only through link/unlink' USING ERRCODE='55000';
  END IF;
  link_row:=CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END;
  tenant_id:=(link_row->>'tenant_id')::uuid;
  resource_kind:=CASE WHEN TG_TABLE_NAME='dfir_ioc_links' THEN 'ioc' ELSE 'asset' END;
  resource_id:=(link_row->>(resource_kind||'_id'))::uuid;
  case_id:=(link_row->>'case_id')::uuid;
  alert_id:=(link_row->>'alert_id')::uuid;
  link_id:=(link_row->>'id')::uuid;
  -- Only the migration trust boundary can seed/import without actor context.
  -- SET ROLE api during security tests remains subject to the runtime checks.
  runtime_write:=current_setting('role',true)='periapsis_api'
    OR NOT pg_has_role(session_user,'periapsis_migrator','member');
  roots:=app.private_lock_shared_dfir_roots_v1(
    tenant_id,resource_kind,resource_id,case_id,alert_id,runtime_write
  );
  SELECT count(*) INTO active_count FROM jsonb_array_elements(roots) AS root(value)
  WHERE (value->>'active')::boolean;
  IF resource_kind='ioc' THEN
    SELECT resource.version INTO current_version FROM public.dfir_iocs AS resource
    WHERE resource.tenant_id=tenant_id AND resource.id=resource_id;
    IF TG_OP='INSERT' AND EXISTS(
      SELECT 1 FROM public.dfir_ioc_links AS existing
      WHERE existing.id=link_id OR (existing.tenant_id=tenant_id AND existing.ioc_id=resource_id
        AND (existing.case_id=case_id OR existing.alert_id=alert_id))
    ) THEN RETURN NEW; END IF;
  ELSE
    SELECT resource.version INTO current_version FROM public.dfir_assets AS resource
    WHERE resource.tenant_id=tenant_id AND resource.id=resource_id;
    IF TG_OP='INSERT' AND EXISTS(
      SELECT 1 FROM public.dfir_asset_links AS existing
      WHERE existing.id=link_id OR (existing.tenant_id=tenant_id AND existing.asset_id=resource_id
        AND (existing.case_id=case_id OR existing.alert_id=alert_id))
    ) THEN RETURN NEW; END IF;
  END IF;
  IF current_version NOT BETWEEN 1 AND 9007199254740991
     OR (TG_OP='INSERT' AND active_count>=64)
     OR (TG_OP='DELETE' AND active_count<2) THEN
    RAISE EXCEPTION 'Shared DFIR association cardinality is invalid' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' AND (
    EXISTS (
      SELECT 1 FROM public.dfir_timeline_events AS event
      JOIN public.dfir_timeline_ioc_links AS relation
        ON relation.tenant_id=event.tenant_id AND relation.timeline_event_id=event.id
      WHERE resource_kind='ioc' AND event.tenant_id=tenant_id AND relation.ioc_id=resource_id
        AND (event.case_id=case_id OR event.alert_id=alert_id)
    ) OR EXISTS (
      SELECT 1 FROM public.dfir_timeline_events AS event
      JOIN public.dfir_timeline_asset_links AS relation
        ON relation.tenant_id=event.tenant_id AND relation.timeline_event_id=event.id
      WHERE resource_kind='asset' AND event.tenant_id=tenant_id AND relation.asset_id=resource_id
        AND (event.case_id=case_id OR event.alert_id=alert_id)
    ) OR EXISTS (
      SELECT 1 FROM public.dfir_relationships AS relation
      WHERE relation.tenant_id=tenant_id AND (relation.case_id=case_id OR relation.alert_id=alert_id)
        AND ((relation.source_kind::text=resource_kind AND relation.source_id=resource_id)
          OR (relation.target_kind::text=resource_kind AND relation.target_id=resource_id)
          OR EXISTS (
            SELECT 1 FROM public.dfir_attachments AS attachment
            WHERE attachment.tenant_id=tenant_id
              AND attachment.subject_kind::text=resource_kind
              AND (resource_kind='ioc' AND attachment.ioc_id=resource_id
                OR resource_kind='asset' AND attachment.asset_id=resource_id)
              AND (relation.source_kind='attachment' AND relation.source_id=attachment.id
                OR relation.target_kind='attachment' AND relation.target_id=attachment.id)
              -- Explicit Case copies retain their own path association after unlink.
              AND NOT (case_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM public.dfir_attachment_case_links AS copied
                WHERE copied.tenant_id=tenant_id AND copied.case_id=case_id
                  AND copied.attachment_id=attachment.id
              ))
          ))
    )
  ) THEN
    RAISE EXCEPTION 'Root-local DFIR references require this association' USING ERRCODE='23503';
  END IF;
  IF runtime_write AND TG_OP='INSERT' THEN
  IF NOT EXISTS(
    SELECT 1 FROM public.dfir_mutation_commands AS command
    WHERE command.tenant_id=tenant_id AND command.actor_user_id=app.context_user_id()
      AND command.actor_membership_id=app.current_tenant_membership_id()
      AND command.root_kind::text=CASE WHEN case_id IS NOT NULL THEN 'case' ELSE 'alert' END
      AND command.root_id=coalesce(case_id,alert_id)
      AND command.resource_kind=resource_kind AND command.resource_id=resource_id
      AND command.operation='dfir.'||resource_kind||CASE WHEN active_count=0 THEN '.create' ELSE '.link' END
      AND command.result_version=CASE WHEN active_count=0 THEN 1 ELSE current_version+1 END
      AND (active_count=0 OR command.secondary_resource_id=link_id)
      AND command.expires_at>transaction_timestamp()
      AND command.xmin=pg_current_xact_id()::text::xid
      AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result
        WHERE result.command_id=command.command_id)
  ) AND NOT (active_count>0 AND case_id IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.ticket_commands AS command
    JOIN public.alert_case_links AS escalation
      ON escalation.tenant_id=command.tenant_id AND escalation.case_id=command.result_case_id
      AND command.result_metadata->'linkIds' @> jsonb_build_array(escalation.id::text)
    WHERE command.tenant_id=tenant_id AND command.operation IN ('ticket.escalate','ticket.link')
      AND command.actor_user_id=app.context_user_id()
      AND command.actor_membership_id=app.current_tenant_membership_id()
      AND command.result_case_id=case_id
      AND command.xmin=pg_current_xact_id()::text::xid
      AND escalation.xmin=pg_current_xact_id()::text::xid
      AND escalation.linked_by_membership_id=app.current_tenant_membership_id()
      AND escalation.linked_by_user_id=app.context_user_id()
      AND escalation.item_ids->(resource_kind||'Ids') @> jsonb_build_array(resource_id::text)
  )) THEN
    RAISE EXCEPTION 'Fresh shared link command or escalation provenance is required' USING ERRCODE='42501';
  END IF;
  END IF;
  actor_membership:=CASE WHEN runtime_write THEN app.current_tenant_membership_id()
    ELSE (link_row->>'created_by_membership_id')::uuid END;
  IF actor_membership IS NULL OR (TG_OP='INSERT' AND runtime_write
      AND (link_row->>'created_by_membership_id')::uuid IS DISTINCT FROM actor_membership) THEN
    RAISE EXCEPTION 'Shared DFIR link actor is invalid' USING ERRCODE='42501';
  END IF;
  IF TG_OP='INSERT' AND active_count=0 THEN
    IF current_version<>1 THEN
      RAISE EXCEPTION 'An orphaned shared resource cannot be reattached' USING ERRCODE='23514';
    END IF;
    prior_version:=0;
    result_version:=1;
  ELSE
    IF current_version>=9007199254740991 THEN
      RAISE EXCEPTION 'Shared DFIR resource version is exhausted' USING ERRCODE='23514';
    END IF;
    prior_version:=current_version;
    result_version:=current_version+1;
  END IF;
  action:='dfir.'||resource_kind||CASE WHEN TG_OP='INSERT' THEN '.linked' ELSE '.unlinked' END;
  IF TG_OP='DELETE' THEN
    SELECT command.* INTO command_record FROM public.dfir_mutation_commands AS command
    WHERE command.tenant_id=tenant_id AND command.actor_membership_id=actor_membership
      AND command.actor_user_id=app.context_user_id()
      AND command.operation='dfir.'||resource_kind||'.unlink'
      AND command.resource_kind=resource_kind AND command.resource_id=resource_id
      AND command.root_kind::text=CASE WHEN case_id IS NOT NULL THEN 'case' ELSE 'alert' END
      AND command.root_id=coalesce(case_id,alert_id)
      AND command.result_version=result_version
      AND command.expires_at>transaction_timestamp()
      AND command.xmin=pg_current_xact_id()::text::xid
      AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result
        WHERE result.command_id=command.command_id)
    FOR SHARE;
    IF NOT FOUND OR command_record.secondary_resource_id IS NULL THEN
      RAISE EXCEPTION 'Fresh unlink reservation is required' USING ERRCODE='42501';
    END IF;
    event_id:=command_record.secondary_resource_id;
  ELSE
    event_id:=link_id;
  END IF;
  IF active_count>0 THEN
    IF resource_kind='ioc' THEN
      UPDATE public.dfir_iocs AS resource SET version=result_version,updated_at=transaction_timestamp(),
        updated_by_membership_id=actor_membership
      WHERE resource.tenant_id=tenant_id AND resource.id=resource_id;
    ELSE
      UPDATE public.dfir_assets AS resource SET version=result_version,updated_at=transaction_timestamp(),
        updated_by_membership_id=actor_membership
      WHERE resource.tenant_id=tenant_id AND resource.id=resource_id;
    END IF;
  END IF;
  INSERT INTO public.dfir_shared_resource_link_events(
    id,tenant_id,resource_kind,ioc_id,asset_id,case_id,alert_id,link_id,
    event_kind,prior_version,result_version,actor_membership_id
  ) VALUES (event_id,tenant_id,resource_kind,
    CASE WHEN resource_kind='ioc' THEN resource_id END,
    CASE WHEN resource_kind='asset' THEN resource_id END,case_id,alert_id,link_id,
    CASE WHEN TG_OP='INSERT' THEN 'linked' ELSE 'unlinked' END,
    prior_version,result_version,actor_membership);
  IF runtime_write AND active_count>0 THEN
    FOR candidate IN SELECT value FROM jsonb_array_elements(roots) AS root(value)
    LOOP
      PERFORM app.private_append_shared_dfir_activity_v1(uuidv7(),tenant_id,
        candidate->>'kind',(candidate->>'id')::uuid,resource_kind,resource_id,
        result_version,action,NULL,event_id);
    END LOOP;
  END IF;
  IF TG_OP='INSERT' THEN RETURN NEW; ELSE RETURN OLD; END IF;
END;
$function$;
--> statement-breakpoint
CREATE TRIGGER dfir_ioc_links_shared_guard_v1
BEFORE INSERT OR UPDATE OR DELETE ON public.dfir_ioc_links
FOR EACH ROW EXECUTE FUNCTION app.guard_shared_dfir_link_v1();
--> statement-breakpoint
CREATE TRIGGER dfir_asset_links_shared_guard_v1
BEFORE INSERT OR UPDATE OR DELETE ON public.dfir_asset_links
FOR EACH ROW EXECUTE FUNCTION app.guard_shared_dfir_link_v1();
--> statement-breakpoint

CREATE FUNCTION app.change_dfir_shared_link_v1(
  p_command_id uuid,p_audit_event_id uuid,p_outbox_event_id uuid,
  p_request_id uuid,p_correlation_id uuid,p_ip_address inet,
  p_user_agent text,p_authentication_method text
)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  command_record public.dfir_mutation_commands%ROWTYPE;
  resource_version bigint;
  roots jsonb;
  active_count integer;
  is_link boolean;
  is_linked boolean;
  root_case uuid;
  root_alert uuid;
  action text;
  affected bigint;
BEGIN
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_audit_event_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_outbox_event_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_request_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_correlation_id)=7) IS NOT TRUE
     OR p_ip_address IS NULL
     OR (family(p_ip_address)=4 AND masklen(p_ip_address)<>32)
     OR (family(p_ip_address)=6 AND masklen(p_ip_address)<>128)
     OR p_user_agent IS NULL OR octet_length(p_user_agent) NOT BETWEEN 1 AND 512
     OR p_authentication_method NOT IN ('bootstrap_totp','totp','recovery_code','ldap','oidc','saml','passkey') THEN
    RAISE EXCEPTION 'Shared DFIR mutation context is invalid' USING ERRCODE='22023';
  END IF;
  SELECT command.* INTO command_record FROM public.dfir_mutation_commands AS command
  WHERE command.tenant_id=context_tenant AND command.command_id=p_command_id
    AND command.actor_user_id=app.context_user_id()
    AND command.actor_membership_id=app.current_tenant_membership_id()
    AND command.operation IN ('dfir.ioc.link','dfir.ioc.unlink','dfir.asset.link','dfir.asset.unlink')
    AND command.expires_at>transaction_timestamp()
    AND command.xmin=pg_current_xact_id()::text::xid
    AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result WHERE result.command_id=p_command_id)
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fresh shared DFIR reservation is required' USING ERRCODE='42501';
  END IF;
  root_case:=CASE WHEN command_record.root_kind='case' THEN command_record.root_id END;
  root_alert:=CASE WHEN command_record.root_kind='alert' THEN command_record.root_id END;
  roots:=app.private_lock_shared_dfir_roots_v1(context_tenant,command_record.resource_kind,
    command_record.resource_id,root_case,root_alert,true);
  SELECT count(*) INTO active_count FROM jsonb_array_elements(roots) AS root(value)
  WHERE (value->>'active')::boolean;
  SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
    WHERE (value->>'active')::boolean
      AND value->>'kind'=command_record.root_kind::text
      AND (value->>'id')::uuid=command_record.root_id) INTO is_linked;
  is_link:=command_record.operation IN ('dfir.ioc.link','dfir.asset.link');
  IF active_count=0 OR is_link=is_linked OR (is_link AND active_count>=64) OR (NOT is_link AND active_count<2) THEN
    RAISE EXCEPTION 'Shared DFIR association cannot be changed' USING ERRCODE='23514';
  END IF;
  IF command_record.resource_kind='ioc' THEN
    SELECT version INTO resource_version FROM public.dfir_iocs
    WHERE tenant_id=context_tenant AND id=command_record.resource_id;
  ELSE
    SELECT version INTO resource_version FROM public.dfir_assets
    WHERE tenant_id=context_tenant AND id=command_record.resource_id;
  END IF;
  IF resource_version IS DISTINCT FROM command_record.result_version-1 THEN
    RAISE EXCEPTION 'Shared DFIR resource revision is stale' USING ERRCODE='40001';
  END IF;
  IF command_record.resource_kind='ioc' THEN
    IF is_link THEN
      INSERT INTO public.dfir_ioc_links(id,tenant_id,ioc_id,case_id,alert_id,created_by_membership_id)
      VALUES(command_record.secondary_resource_id,context_tenant,command_record.resource_id,root_case,root_alert,command_record.actor_membership_id);
    ELSE
      DELETE FROM public.dfir_ioc_links WHERE tenant_id=context_tenant AND ioc_id=command_record.resource_id
        AND (case_id=root_case OR alert_id=root_alert);
    END IF;
  ELSE
    IF is_link THEN
      INSERT INTO public.dfir_asset_links(id,tenant_id,asset_id,case_id,alert_id,created_by_membership_id)
      VALUES(command_record.secondary_resource_id,context_tenant,command_record.resource_id,root_case,root_alert,command_record.actor_membership_id);
    ELSE
      DELETE FROM public.dfir_asset_links WHERE tenant_id=context_tenant AND asset_id=command_record.resource_id
        AND (case_id=root_case OR alert_id=root_alert);
    END IF;
  END IF;
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 OR NOT EXISTS(
    SELECT 1 FROM public.dfir_shared_resource_link_events AS event
    WHERE event.id=command_record.secondary_resource_id AND event.tenant_id=context_tenant
      AND event.resource_kind=command_record.resource_kind
      AND coalesce(event.ioc_id,event.asset_id)=command_record.resource_id
      AND coalesce(event.case_id,event.alert_id)=command_record.root_id
      AND event.result_version=command_record.result_version
      AND event.event_kind=CASE WHEN is_link THEN 'linked' ELSE 'unlinked' END
  ) THEN
    RAISE EXCEPTION 'Shared DFIR mutation history is unavailable' USING ERRCODE='55000';
  END IF;
  action:='dfir.'||command_record.resource_kind||CASE WHEN is_link THEN '.linked' ELSE '.unlinked' END;
  PERFORM app.append_tenant_authorization_audit(
    p_audit_event_id,action,'dfir_'||command_record.resource_kind,command_record.resource_id,
    p_request_id,p_correlation_id,p_ip_address,p_user_agent,p_authentication_method,
    jsonb_build_object('resourceVersion',command_record.result_version-1,'linked',NOT is_link),
    jsonb_build_object('resourceVersion',command_record.result_version,'linked',is_link),
    jsonb_build_object('rootKind',command_record.root_kind,'rootId',command_record.root_id,
      'commandId',p_command_id,'linkEventId',command_record.secondary_resource_id,'contentRedacted',true)
  );
  INSERT INTO public.outbox_events(
    id,tenant_id,aggregate_type,aggregate_id,event_type,schema_version,payload,
    deduplication_key,correlation_id,causation_id,occurred_at
  ) VALUES(p_outbox_event_id,context_tenant,'dfir_'||command_record.resource_kind,
    command_record.resource_id,action,1,
    jsonb_build_object('tenantId',context_tenant,'rootKind',command_record.root_kind,
      'rootId',command_record.root_id,'resourceId',command_record.resource_id,
      'resourceVersion',command_record.result_version),
    'shared-dfir:'||p_command_id::text,p_correlation_id,p_request_id,transaction_timestamp());
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.append_shared_dfir_activities_v1(p_command_id uuid,p_activity_ids uuid[])
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  command_record public.dfir_mutation_commands%ROWTYPE;
  roots jsonb;
  candidate jsonb;
  position integer:=0;
  resource_version bigint;
  action text;
  subject_kind text;
  subject_id uuid;
  activity_kind text;
  activity_resource_id uuid;
  attachment_version bigint;
BEGIN
  SELECT command.* INTO command_record FROM public.dfir_mutation_commands AS command
  WHERE command.command_id=p_command_id AND command.tenant_id=app.context_tenant_id()
    AND command.actor_user_id=app.context_user_id()
    AND command.actor_membership_id=app.current_tenant_membership_id()
    AND command.operation IN ('dfir.ioc.create','dfir.ioc.replace','dfir.asset.create','dfir.asset.replace','dfir.attachment.prepare')
    AND command.expires_at>transaction_timestamp()
    AND command.xmin=pg_current_xact_id()::text::xid
    AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result WHERE result.command_id=p_command_id)
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fresh shared DFIR command is required' USING ERRCODE='42501'; END IF;
  activity_kind:=command_record.resource_kind;
  activity_resource_id:=command_record.resource_id;
  IF command_record.operation='dfir.attachment.prepare' THEN
    SELECT attachment.subject_kind::text,coalesce(attachment.ioc_id,attachment.asset_id),
      attachment.id,attachment.version,storage.version
    INTO subject_kind,subject_id,activity_resource_id,attachment_version,resource_version
    FROM public.dfir_attachments AS attachment
    JOIN public.dfir_storage_objects AS storage ON storage.tenant_id=attachment.tenant_id AND storage.id=attachment.storage_object_id
    WHERE attachment.tenant_id=command_record.tenant_id AND storage.id=command_record.resource_id
      AND attachment.subject_kind IN ('ioc','asset')
      AND attachment.scan_state='pending_upload' AND storage.state='pending_upload';
    IF NOT FOUND OR attachment_version<>1 OR resource_version<>1 THEN
      RAISE EXCEPTION 'Shared attachment projection is unavailable' USING ERRCODE='23503';
    END IF;
    activity_kind:='attachment';
    roots:=app.private_lock_shared_dfir_roots_v1(command_record.tenant_id,subject_kind,
      subject_id,NULL,NULL,true,'dfir.attachment.manage');
  ELSE
    roots:=app.private_lock_shared_dfir_roots_v1(command_record.tenant_id,command_record.resource_kind,
      command_record.resource_id,NULL,NULL,true);
  END IF;
  IF jsonb_array_length(roots)=0 OR NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
    WHERE value->>'kind'=command_record.root_kind::text AND (value->>'id')::uuid=command_record.root_id
  ) OR cardinality(p_activity_ids) IS DISTINCT FROM jsonb_array_length(roots)-1
     OR cardinality(p_activity_ids) IS DISTINCT FROM (SELECT count(DISTINCT id) FROM unnest(p_activity_ids) AS ids(id)) THEN
    RAISE EXCEPTION 'Shared DFIR activity root binding is invalid' USING ERRCODE='22023';
  END IF;
  IF command_record.resource_kind='ioc' THEN
    SELECT version INTO resource_version FROM public.dfir_iocs
    WHERE tenant_id=command_record.tenant_id AND id=command_record.resource_id;
  ELSIF command_record.resource_kind='asset' THEN
    SELECT version INTO resource_version FROM public.dfir_assets
    WHERE tenant_id=command_record.tenant_id AND id=command_record.resource_id;
  END IF;
  IF resource_version IS DISTINCT FROM command_record.result_version THEN
    RAISE EXCEPTION 'Shared DFIR activity revision is stale' USING ERRCODE='40001';
  END IF;
  action:=CASE WHEN command_record.operation='dfir.attachment.prepare' THEN 'dfir.attachment.prepared'
    ELSE replace(replace(command_record.operation,'.create','.created'),'.replace','.replaced') END;
  FOR candidate IN SELECT value FROM jsonb_array_elements(roots) AS root(value)
  LOOP
    IF candidate->>'kind'=command_record.root_kind::text AND (candidate->>'id')::uuid=command_record.root_id THEN CONTINUE; END IF;
    position:=position+1;
    PERFORM app.private_append_shared_dfir_activity_v1(p_activity_ids[position],command_record.tenant_id,
      candidate->>'kind',(candidate->>'id')::uuid,activity_kind,
      activity_resource_id,resource_version,action,p_command_id,NULL);
  END LOOP;
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.guard_shared_dfir_attachment_v1()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  command_record public.dfir_mutation_commands%ROWTYPE;
  roots jsonb;
BEGIN
  IF NEW.subject_kind NOT IN ('ioc','asset') THEN RETURN NEW; END IF;
  IF current_setting('role',true) IS DISTINCT FROM 'periapsis_api'
     AND pg_has_role(session_user,'periapsis_migrator','member') THEN
    RETURN NEW;
  END IF;
  SELECT command.* INTO command_record FROM public.dfir_mutation_commands AS command
  WHERE command.tenant_id=NEW.tenant_id AND command.operation='dfir.attachment.prepare'
    AND command.resource_kind='storage_object' AND command.resource_id=NEW.storage_object_id
    AND command.secondary_resource_id=NEW.id AND command.result_version=1
    AND command.actor_user_id=app.context_user_id()
    AND command.actor_membership_id=app.current_tenant_membership_id()
    AND command.actor_membership_id=NEW.uploaded_by_membership_id
    AND command.expires_at>transaction_timestamp()
    AND command.xmin=pg_current_xact_id()::text::xid
    AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result WHERE result.command_id=command.command_id)
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Fresh shared attachment reservation is required' USING ERRCODE='42501';
  END IF;
  roots:=app.private_lock_shared_dfir_roots_v1(NEW.tenant_id,NEW.subject_kind::text,
    coalesce(NEW.ioc_id,NEW.asset_id),
    CASE WHEN command_record.root_kind='case' THEN command_record.root_id END,
    CASE WHEN command_record.root_kind='alert' THEN command_record.root_id END,
    true,'dfir.attachment.manage');
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
    WHERE value->>'kind'=command_record.root_kind::text
      AND (value->>'id')::uuid=command_record.root_id AND (value->>'active')::boolean) THEN
    RAISE EXCEPTION 'Shared attachment subject is not linked to the path root' USING ERRCODE='23503';
  END IF;
  RETURN NEW;
END;
$function$;
--> statement-breakpoint
CREATE TRIGGER dfir_attachments_shared_guard_v1
BEFORE INSERT ON public.dfir_attachments
FOR EACH ROW EXECUTE FUNCTION app.guard_shared_dfir_attachment_v1();
--> statement-breakpoint

