CREATE FUNCTION app.append_alert_dfir_mutation_effects_v1(
  p_alert_id uuid,p_permission_key text,p_action text,p_resource_type text,
  p_resource_id uuid,p_resource_version bigint,p_command_operation text,
  p_key_digest bytea,p_request_digest bytea,p_activity_id uuid,
  p_before jsonb,p_after jsonb,p_metadata jsonb,p_audit_event_id uuid,
  p_outbox_event_id uuid,p_request_id uuid,p_correlation_id uuid,
  p_ip_address inet,p_user_agent text,p_authentication_method text
)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  command_record public.dfir_mutation_commands%ROWTYPE;
  attachment_record public.dfir_attachments%ROWTYPE;
  roots jsonb;
  safe_metadata jsonb;
BEGIN
  SELECT attachment.* INTO attachment_record FROM public.dfir_attachments AS attachment
  WHERE p_command_operation='dfir.attachment.prepare'
    AND attachment.tenant_id=context_tenant AND attachment.storage_object_id=p_resource_id
    AND attachment.subject_kind IN ('ioc','asset');
  IF NOT FOUND THEN
    PERFORM app.append_alert_dfir_mutation_effects_before_shared_v1(
      p_alert_id,p_permission_key,p_action,p_resource_type,p_resource_id,
      p_resource_version,p_command_operation,p_key_digest,p_request_digest,p_activity_id,
      p_before,p_after,p_metadata,p_audit_event_id,p_outbox_event_id,p_request_id,
      p_correlation_id,p_ip_address,p_user_agent,p_authentication_method);
    RETURN;
  END IF;
  IF NOT pg_has_role(session_user,'periapsis_api','member')
     OR p_permission_key IS DISTINCT FROM 'dfir.attachment.manage'
     OR p_action IS DISTINCT FROM 'dfir.attachment.prepared'
     OR p_resource_type IS DISTINCT FROM 'dfir_storage_object'
     OR p_resource_version IS DISTINCT FROM 1
     OR (uuid_extract_version(p_alert_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_activity_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_audit_event_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_outbox_event_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_request_id)=7) IS NOT TRUE
     OR (uuid_extract_version(p_correlation_id)=7) IS NOT TRUE
     OR p_ip_address IS NULL
     OR (family(p_ip_address)=4 AND masklen(p_ip_address)<>32)
     OR (family(p_ip_address)=6 AND masklen(p_ip_address)<>128)
     OR p_user_agent IS NULL OR octet_length(p_user_agent) NOT BETWEEN 1 AND 512
     OR p_authentication_method NOT IN ('bootstrap_totp','totp','recovery_code','ldap','oidc','saml','passkey')
     OR attachment_record.version<>1 OR attachment_record.scan_state<>'pending_upload' THEN
    RAISE EXCEPTION 'Shared Alert attachment effect context is invalid' USING ERRCODE='22023';
  END IF;
  SELECT command.* INTO command_record FROM public.dfir_mutation_commands AS command
  JOIN public.dfir_storage_objects AS storage
    ON storage.tenant_id=command.tenant_id AND storage.id=command.resource_id
  WHERE command.tenant_id=context_tenant AND command.root_kind='alert'
    AND command.root_id=p_alert_id AND command.operation=p_command_operation
    AND command.actor_user_id=app.context_user_id()
    AND command.actor_membership_id=app.current_tenant_membership_id()
    AND command.key_digest=p_key_digest AND command.request_digest=p_request_digest
    AND command.resource_kind='storage_object' AND command.resource_id=p_resource_id
    AND command.secondary_resource_id=attachment_record.id AND command.result_version=1
    AND command.expires_at>transaction_timestamp()
    AND command.xmin=pg_current_xact_id()::text::xid
    AND storage.version=1 AND storage.state='pending_upload'
    AND NOT EXISTS(SELECT 1 FROM public.dfir_mutation_command_results AS result WHERE result.command_id=command.command_id)
  FOR SHARE OF command,storage;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shared Alert attachment reservation is unavailable' USING ERRCODE='42501';
  END IF;
  roots:=app.private_lock_shared_dfir_roots_v1(context_tenant,attachment_record.subject_kind::text,
    coalesce(attachment_record.ioc_id,attachment_record.asset_id),NULL,p_alert_id,true,'dfir.attachment.manage');
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
    WHERE value->>'kind'='alert' AND (value->>'id')::uuid=p_alert_id AND (value->>'active')::boolean) THEN
    RAISE EXCEPTION 'Shared attachment is not linked to the Alert' USING ERRCODE='23503';
  END IF;
  PERFORM app.private_append_shared_dfir_activity_v1(p_activity_id,context_tenant,'alert',p_alert_id,
    'attachment',attachment_record.id,1,p_action,command_record.command_id,NULL);
  safe_metadata:=jsonb_build_object('alertId',p_alert_id,'commandId',command_record.command_id,
    'commandOperation',p_command_operation,'contentRedacted',true);
  PERFORM app.append_tenant_authorization_audit(p_audit_event_id,p_action,p_resource_type,p_resource_id,
    p_request_id,p_correlation_id,p_ip_address,p_user_agent,p_authentication_method,'{}'::jsonb,
    jsonb_build_object('resourceId',attachment_record.id,'resourceVersion',1,'contentRedacted',true),safe_metadata);
  INSERT INTO public.outbox_events(id,tenant_id,aggregate_type,aggregate_id,event_type,schema_version,
    payload,deduplication_key,correlation_id,causation_id,occurred_at)
  VALUES(p_outbox_event_id,context_tenant,p_resource_type,p_resource_id,p_action,1,
    jsonb_build_object('tenantId',context_tenant,'alertId',p_alert_id,'resourceId',attachment_record.id,'resourceVersion',1),
    'alert-dfir:'||command_record.command_id::text||':'||p_audit_event_id::text,
    p_correlation_id,p_request_id,transaction_timestamp());
END;
$function$;
--> statement-breakpoint

CREATE FUNCTION app.private_authorize_escalated_shared_resources_v1(
  p_tenant_id uuid,p_case_id uuid,p_link_ids jsonb
)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE selected_ids uuid[];
DECLARE candidate record;
DECLARE roots jsonb;
BEGIN
  IF p_tenant_id IS DISTINCT FROM app.context_tenant_id()
     OR jsonb_typeof(p_link_ids) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_link_ids) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Shared escalation replay provenance is invalid' USING ERRCODE='55000';
  END IF;
  SELECT array_agg(value::uuid ORDER BY value::uuid) INTO selected_ids
  FROM jsonb_array_elements_text(p_link_ids) AS selected(value);
  IF cardinality(selected_ids)<>(SELECT count(DISTINCT id) FROM unnest(selected_ids) AS selected(id))
     OR cardinality(selected_ids)<>(SELECT count(*) FROM public.alert_case_links AS link
       WHERE link.tenant_id=p_tenant_id AND link.case_id=p_case_id AND link.id=ANY(selected_ids)) THEN
    RAISE EXCEPTION 'Shared escalation replay provenance is unavailable' USING ERRCODE='55000';
  END IF;
  FOR candidate IN
    SELECT DISTINCT kind,resource_id FROM (
      SELECT 'ioc'::text AS kind,value::uuid AS resource_id
      FROM public.alert_case_links AS link
      CROSS JOIN LATERAL jsonb_array_elements_text(coalesce(link.item_ids->'iocIds','[]'::jsonb)) AS item(value)
      WHERE link.tenant_id=p_tenant_id AND link.case_id=p_case_id AND link.id=ANY(selected_ids)
      UNION ALL
      SELECT 'asset',value::uuid
      FROM public.alert_case_links AS link
      CROSS JOIN LATERAL jsonb_array_elements_text(coalesce(link.item_ids->'assetIds','[]'::jsonb)) AS item(value)
      WHERE link.tenant_id=p_tenant_id AND link.case_id=p_case_id AND link.id=ANY(selected_ids)
    ) AS selection
    ORDER BY kind,resource_id
  LOOP
    roots:=app.private_lock_shared_dfir_roots_v1(p_tenant_id,candidate.kind,
      candidate.resource_id,p_case_id,NULL,true);
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(roots) AS root(value)
      WHERE value->>'kind'='case' AND (value->>'id')::uuid=p_case_id AND (value->>'active')::boolean) THEN
      RAISE EXCEPTION 'Shared escalation replay association is no longer active' USING ERRCODE='42501';
    END IF;
  END LOOP;
END;
$function$;
--> statement-breakpoint

-- Guard both the API's early lookup and direct SQL commit replay branches.
DO $shared_dfir_escalation_replay_guards$
DECLARE boundary regprocedure;
DECLARE predecessor text;
DECLARE successor text;
DECLARE marker text;
DECLARE guard_sql text;
BEGIN
  FOREACH boundary IN ARRAY ARRAY[
    'app.lookup_tenant_ticket_escalation_replay_v3(bytea,bytea)'::regprocedure,
    'app.lookup_tenant_ticket_link_replay_v1(bytea,bytea)'::regprocedure,
    'app.commit_tenant_ticket_escalation_v4(uuid,uuid,boolean,jsonb,jsonb,text,text,bytea,bytea,text[],uuid,uuid,inet,text,text)'::regprocedure,
    'app.commit_tenant_ticket_link_v1(uuid,uuid,boolean,jsonb,jsonb,text,text,bytea,bytea,text[],uuid,uuid,inet,text,text)'::regprocedure
  ]
  LOOP
    predecessor:=pg_get_functiondef(boundary);
    IF strpos(boundary::text,'lookup_')>0 THEN
      marker:='RETURN QUERY SELECT replay.result_alert_id,replay.result_case_id,';
      guard_sql:='PERFORM app.private_authorize_escalated_shared_resources_v1(context_tenant,replay.result_case_id,replay.result_metadata->''linkIds'');';
    ELSE
      marker:='RETURN QUERY SELECT replay_command.result_case_id,';
      guard_sql:='PERFORM app.private_authorize_escalated_shared_resources_v1(context_tenant,replay_command.result_case_id,replay_command.result_metadata->''linkIds'');';
    END IF;
    IF length(predecessor)-length(replace(predecessor,marker,''))<>length(marker) THEN
      RAISE EXCEPTION 'Shared escalation replay guard anchor drifted: %',boundary USING ERRCODE='55000';
    END IF;
    successor:=replace(predecessor,marker,guard_sql||E'\n    '||marker);
    EXECUTE successor;
  END LOOP;
END;
$shared_dfir_escalation_replay_guards$;
--> statement-breakpoint

DO $shared_dfir_privileges$
DECLARE boundary regprocedure;
BEGIN
  FOREACH boundary IN ARRAY ARRAY[
    'app.private_lock_shared_dfir_roots_v1(uuid,text,uuid,uuid,uuid,boolean,text)'::regprocedure,
    'app.private_append_shared_dfir_activity_v1(uuid,uuid,text,uuid,text,uuid,bigint,text,uuid,uuid)'::regprocedure,
    'app.guard_shared_dfir_link_v1()'::regprocedure,
    'app.guard_shared_dfir_attachment_v1()'::regprocedure,
    'app.change_dfir_shared_link_v1(uuid,uuid,uuid,uuid,uuid,inet,text,text)'::regprocedure,
    'app.append_shared_dfir_activities_v1(uuid,uuid[])'::regprocedure,
    'app.private_authorize_escalated_shared_resources_v1(uuid,uuid,jsonb)'::regprocedure,
    'app.append_alert_dfir_mutation_effects_v1(uuid,text,text,text,uuid,bigint,text,bytea,bytea,uuid,jsonb,jsonb,jsonb,uuid,uuid,uuid,uuid,inet,text,text)'::regprocedure
  ]
  LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO periapsis_migrator',boundary);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,periapsis_api,periapsis_worker,periapsis_notifier,periapsis_auditor,periapsis_audit_reader_owner,periapsis_notification_dispatch_owner,periapsis_sla_api_owner,periapsis_sla_worker_owner,periapsis_sla_readiness_owner,periapsis_ticket_runtime_owner',boundary);
  END LOOP;
END;
$shared_dfir_privileges$;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.change_dfir_shared_link_v1(uuid,uuid,uuid,uuid,uuid,inet,text,text),
  app.append_shared_dfir_activities_v1(uuid,uuid[]),
  app.append_alert_dfir_mutation_effects_v1(uuid,text,text,text,uuid,bigint,text,bytea,bytea,uuid,jsonb,jsonb,jsonb,uuid,uuid,uuid,uuid,inet,text,text)
TO periapsis_api;
--> statement-breakpoint

-- The escalation ABI seals its selected resource IDs before the active-link
-- triggers consume that selection. The row/command xmin proves the closed ABI.
DO $shared_dfir_escalation_selection$
DECLARE boundary regprocedure;
DECLARE predecessor text;
DECLARE marker text:='    INSERT INTO public.dfir_ioc_links (';
DECLARE guard_sql text:='    UPDATE public.alert_case_links AS link
    SET copy_fields=selected_fields,item_ids=source_items
    WHERE link.tenant_id=context_tenant AND link.id=link_id
      AND link.alert_id=(source_value->>''alertId'')::uuid
      AND link.case_id=committed_case_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION ''Shared escalation selection is unavailable'' USING ERRCODE=''55000'';
    END IF;
';
BEGIN
  FOREACH boundary IN ARRAY ARRAY[
    'app.commit_tenant_ticket_escalation_v4(uuid,uuid,boolean,jsonb,jsonb,text,text,bytea,bytea,text[],uuid,uuid,inet,text,text)'::regprocedure,
    'app.commit_tenant_ticket_link_v1(uuid,uuid,boolean,jsonb,jsonb,text,text,bytea,bytea,text[],uuid,uuid,inet,text,text)'::regprocedure
  ]
  LOOP
    predecessor:=pg_get_functiondef(boundary);
    IF length(predecessor)-length(replace(predecessor,marker,''))<>length(marker) THEN
      RAISE EXCEPTION 'Shared escalation selection anchor drifted: %',boundary USING ERRCODE='55000';
    END IF;
    EXECUTE replace(predecessor,marker,guard_sql||marker);
  END LOOP;
END;
$shared_dfir_escalation_selection$;
