CREATE OR REPLACE FUNCTION app.require_dfir_mutation_result_v1()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.dfir_mutation_command_results AS result
    WHERE result.tenant_id=NEW.tenant_id AND result.command_id=NEW.command_id
      AND result.root_kind=NEW.root_kind AND result.root_id=NEW.root_id
      AND result.operation=NEW.operation AND result.resource_kind=NEW.resource_kind
      AND result.resource_id=NEW.resource_id AND result.result_version=NEW.result_version
  ) OR (NEW.operation IN ('dfir.ioc.link','dfir.ioc.unlink','dfir.asset.link','dfir.asset.unlink')
    AND NOT EXISTS(
      SELECT 1 FROM public.dfir_shared_resource_link_events AS event
      WHERE event.id=NEW.secondary_resource_id AND event.tenant_id=NEW.tenant_id
        AND event.resource_kind=NEW.resource_kind
        AND coalesce(event.ioc_id,event.asset_id)=NEW.resource_id
        AND CASE WHEN event.case_id IS NOT NULL THEN 'case' ELSE 'alert' END=NEW.root_kind::text
        AND coalesce(event.case_id,event.alert_id)=NEW.root_id
        AND event.actor_membership_id=NEW.actor_membership_id
        AND event.result_version=NEW.result_version AND event.prior_version=NEW.result_version-1
        AND event.event_kind=CASE WHEN NEW.operation IN ('dfir.ioc.link','dfir.asset.link') THEN 'linked' ELSE 'unlinked' END
    )) THEN
    RAISE EXCEPTION 'DFIR mutation result and exact lifecycle history are required' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END;
$function$;
