-- Re-run the replay registry across every finalized receipt family. The
-- earliest durable row is already present for legacy families created earlier
-- in this migration; ON CONFLICT is intentionally non-mutating.
WITH replay_candidates AS (
  SELECT command.tenant_id,command.actor_user_id,
         command.actor_membership_id,command.operation,command.key_digest,
         command.created_at AS first_used_at,
         command.expires_at AS receipt_expires_at
  FROM public.dfir_mutation_commands AS command
  UNION ALL
  SELECT command.tenant_id,command.actor_user_id,
         command.actor_membership_id,command.operation,command.key_digest,
         command.created_at,command.expires_at
  FROM public.alert_dfir_resource_commands AS command
  UNION ALL
  SELECT command.tenant_id,command.actor_user_id,
         command.actor_membership_id,command.operation,command.key_digest,
         command.created_at,retention.expires_at
  FROM public.ticket_commands AS command
  JOIN public.dfir_ticket_command_retentions AS retention
    ON retention.tenant_id=command.tenant_id
   AND retention.command_id=command.id
   AND retention.operation=command.operation
   AND retention.command_created_at=command.created_at
), first_use AS (
  SELECT DISTINCT ON (tenant_id,actor_user_id,operation,key_digest)
         tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
         first_used_at,receipt_expires_at
  FROM replay_candidates
  ORDER BY tenant_id,actor_user_id,operation,key_digest,
           first_used_at,actor_membership_id
)
INSERT INTO public.dfir_mutation_replay_keys(
  tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
  first_used_at,receipt_expires_at
)
SELECT tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
       first_used_at,receipt_expires_at
FROM first_use
ON CONFLICT (tenant_id,actor_user_id,operation,key_digest) DO NOTHING;
--> statement-breakpoint

-- Snapshot backfill matters even when the live aggregate is already gone:
-- cleanup may remove the only replay payload, but none of its caller-owned
-- identifiers can ever become available again.
WITH resource_candidates AS (
  SELECT command.tenant_id,command.resource_kind,
         command.resource_id,command.created_at AS used_at
  FROM public.dfir_mutation_commands AS command
  UNION ALL
  SELECT command.tenant_id,
         CASE command.operation
           WHEN 'dfir.attachment.prepare' THEN 'attachment'
           WHEN 'dfir.relationship.retract' THEN 'relationship_retraction'
           WHEN 'dfir.ioc.link' THEN 'shared_link_event'
           WHEN 'dfir.ioc.unlink' THEN 'shared_link_event'
           WHEN 'dfir.asset.link' THEN 'shared_link_event'
           WHEN 'dfir.asset.unlink' THEN 'shared_link_event'
           ELSE 'custody_event'
         END,
         command.secondary_resource_id,command.created_at
  FROM public.dfir_mutation_commands AS command
  WHERE command.secondary_resource_id IS NOT NULL
  UNION ALL
  SELECT command.tenant_id,
         CASE
           WHEN command.operation LIKE 'dfir.ioc.%' THEN 'ioc'
           WHEN command.operation LIKE 'dfir.asset.%' THEN 'asset'
           WHEN command.operation='dfir.timeline.create'
             THEN 'timeline_event'
           WHEN command.operation LIKE 'dfir.alert.evidence.%'
             THEN 'evidence'
           WHEN command.operation LIKE 'dfir.alert.task.%' THEN 'task'
           WHEN command.operation LIKE 'dfir.alert.relationship.%'
             THEN 'relationship'
         END,
         command.resource_id,command.created_at
  FROM public.alert_dfir_resource_commands AS command
  UNION ALL
  SELECT result.tenant_id,'custody_event',
         (item.value->>'id')::uuid,result.created_at
  FROM public.alert_dfir_resource_command_results AS result
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(result.result_snapshot#>'{evidence,custodyEvents}')
             ='array'
      THEN result.result_snapshot#>'{evidence,custodyEvents}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  UNION ALL
  SELECT result.tenant_id,'checklist_item',
         (item.value->>'id')::uuid,result.created_at
  FROM public.alert_dfir_resource_command_results AS result
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(result.result_snapshot#>'{task,checklist}')='array'
      THEN result.result_snapshot#>'{task,checklist}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  UNION ALL
  SELECT result.tenant_id,'relationship_retraction',
         (item.value->>'id')::uuid,result.created_at
  FROM public.alert_dfir_resource_command_results AS result
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(
        result.result_snapshot#>'{relationship,retractions}'
      )='array'
      THEN result.result_snapshot#>'{relationship,retractions}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  UNION ALL
  SELECT command.tenant_id,'task',
         (command.result_metadata#>>'{task,id}')::uuid,command.created_at
  FROM public.ticket_commands AS command
  WHERE command.operation IN (
    'case.dfir.task.create','case.dfir.task.transition',
    'case.dfir.task.replace_details','case.dfir.task.assign',
    'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
    'case.dfir.task.comments.replace'
  )
  UNION ALL
  SELECT command.tenant_id,'checklist_item',
         (item.value->>'id')::uuid,command.created_at
  FROM public.ticket_commands AS command
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(command.result_metadata#>'{task,checklist}')='array'
      THEN command.result_metadata#>'{task,checklist}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  WHERE command.operation IN (
    'case.dfir.task.create','case.dfir.task.transition',
    'case.dfir.task.replace_details','case.dfir.task.assign',
    'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
    'case.dfir.task.comments.replace'
  )
  UNION ALL
  SELECT command.tenant_id,'custody_event',
         (item.value->>'id')::uuid,command.created_at
  FROM public.dfir_mutation_command_results AS result
  JOIN public.dfir_mutation_commands AS command
    ON command.tenant_id=result.tenant_id
   AND command.command_id=result.command_id
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(result.result_snapshot#>'{projection,custodyEvents}')
             ='array'
      THEN result.result_snapshot#>'{projection,custodyEvents}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  UNION ALL
  SELECT command.tenant_id,'relationship_retraction',
         (item.value->>'id')::uuid,command.created_at
  FROM public.dfir_mutation_command_results AS result
  JOIN public.dfir_mutation_commands AS command
    ON command.tenant_id=result.tenant_id
   AND command.command_id=result.command_id
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(result.result_snapshot#>'{projection,retractions}')
             ='array'
      THEN result.result_snapshot#>'{projection,retractions}'
      ELSE '[]'::jsonb
    END
  ) AS item(value)
  UNION ALL
  SELECT task.tenant_id,'task',task.id,task.created_at
  FROM public.dfir_tasks AS task
  UNION ALL
  SELECT task.tenant_id,'checklist_item',(item.value->>'id')::uuid,
         task.created_at
  FROM public.dfir_tasks AS task
  CROSS JOIN LATERAL jsonb_array_elements(task.checklist) AS item(value)
  UNION ALL
  SELECT retraction.tenant_id,'relationship_retraction',retraction.id,
         retraction.retracted_at
  FROM public.dfir_relationship_retractions AS retraction
  UNION ALL
  SELECT event.tenant_id,'shared_link_event',event.id,event.occurred_at
  FROM public.dfir_shared_resource_link_events AS event
), first_resource_use AS (
  SELECT tenant_id,resource_kind,resource_id,min(used_at) AS used_at
  FROM resource_candidates
  WHERE resource_kind IS NOT NULL AND resource_id IS NOT NULL
  GROUP BY tenant_id,resource_kind,resource_id
)
INSERT INTO public.dfir_mutation_resource_ids(
  tenant_id,resource_kind,resource_id,created_at
)
SELECT tenant_id,resource_kind,resource_id,used_at
FROM first_resource_use
ON CONFLICT (tenant_id,resource_kind,resource_id) DO NOTHING;
