CREATE FUNCTION app.guard_dfir_task_checklist_ids_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  candidate jsonb;
  candidate_id uuid;
  inserted_rows bigint;
  accepts_current_tombstone boolean;
BEGIN
  IF TG_OP NOT IN ('INSERT','UPDATE')
     OR jsonb_typeof(NEW.checklist) IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(NEW.checklist) AS item(value)
       WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
          OR item.value->>'id' IS NULL
          OR (uuid_extract_version((item.value->>'id')::uuid)=7)
               IS NOT TRUE
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(NEW.checklist) AS item(value)
       GROUP BY item.value->>'id'
       HAVING count(*)>1
     ) THEN
    RAISE EXCEPTION 'DFIR task checklist identifiers are invalid'
      USING ERRCODE='23514';
  END IF;

  IF TG_OP='INSERT' THEN
    accepts_current_tombstone:=true;
  ELSE
    accepts_current_tombstone:=
      OLD.xmin IS DISTINCT FROM pg_current_xact_id()::text::xid;
  END IF;

  FOR candidate IN
    SELECT item.value
    FROM jsonb_array_elements(NEW.checklist) AS item(value)
  LOOP
    candidate_id:=(candidate->>'id')::uuid;
    IF TG_OP='UPDATE' AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements(OLD.checklist) AS old_item(value)
      WHERE old_item.value->>'id'=candidate_id::text
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.dfir_mutation_resource_ids(
      tenant_id,resource_kind,resource_id
    ) VALUES (NEW.tenant_id,'checklist_item',candidate_id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS inserted_rows=ROW_COUNT;

    IF inserted_rows=0 AND NOT (
      accepts_current_tombstone AND EXISTS (
        SELECT 1
        FROM public.dfir_mutation_resource_ids AS registry
        WHERE registry.tenant_id=NEW.tenant_id
          AND registry.resource_kind='checklist_item'
          AND registry.resource_id=candidate_id
          AND registry.xmin=pg_current_xact_id()::text::xid
      )
    ) THEN
      RAISE EXCEPTION
        'DFIR checklist identifier was already used or removed'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_resource_ids_pkey';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$;
--> statement-breakpoint
