CREATE FUNCTION app.reserve_case_dfir_command_v1(
  p_command_id uuid,
  p_case_id uuid,
  p_operation text,
  p_resource_id uuid,
  p_result_version bigint,
  p_key_digest bytea,
  p_request_digest bytea,
  p_result_snapshot jsonb DEFAULT NULL
)
RETURNS TABLE(
  command_id uuid,
  result_resource_id uuid,
  result_version bigint,
  result_snapshot jsonb,
  replayed boolean
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  caller_role text:=current_setting('role',true);
  operation_is_create boolean;
  tombstone public.dfir_mutation_replay_keys%ROWTYPE;
  retention public.dfir_ticket_command_retentions%ROWTYPE;
  command_record public.ticket_commands%ROWTYPE;
  reservation record;
BEGIN
  operation_is_create:=CASE p_operation
    WHEN 'case.dfir.task.create' THEN true
    WHEN 'case.dfir.task.transition' THEN false
    WHEN 'case.dfir.task.replace_details' THEN false
    WHEN 'case.dfir.task.assign' THEN false
    WHEN 'case.dfir.task.reschedule' THEN false
    WHEN 'case.dfir.task.replace_checklist' THEN false
    WHEN 'case.dfir.task.comments.replace' THEN false
    ELSE NULL END;
  IF caller_role IS NULL OR caller_role='none' THEN
    caller_role:=session_user;
  END IF;
  IF NOT pg_has_role(caller_role,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE
     OR p_case_id IS NULL
     OR (uuid_extract_version(p_case_id)=7) IS NOT TRUE
     OR p_resource_id IS NULL
     OR (uuid_extract_version(p_resource_id)=7) IS NOT TRUE
     OR operation_is_create IS NULL
     OR p_result_version IS NULL
     OR p_result_version NOT BETWEEN 1 AND 9007199254740991
     OR operation_is_create AND p_result_version<>1
     OR NOT operation_is_create AND p_result_version<2
     OR p_key_digest IS NULL OR octet_length(p_key_digest)<>32
     OR p_request_digest IS NULL OR octet_length(p_request_digest)<>32 THEN
    RAISE EXCEPTION 'Case DFIR command binding is invalid'
      USING ERRCODE='22023';
  END IF;

  -- Authorization precedes tombstone inspection so a consumed key is never
  -- an oracle for a root the current membership cannot access.
  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active' AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case DFIR human authority is unavailable'
      USING ERRCODE='42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    context_tenant::text||':'||actor_user::text||':'||p_operation||':'||
    encode(p_key_digest,'hex'),82419731
  ));
  PERFORM 1 FROM public.cases AS root
  WHERE root.tenant_id=context_tenant AND root.id=p_case_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case is unavailable' USING ERRCODE='P0002';
  END IF;
  IF app.private_current_dfir_scope_allows_v1(
    'dfir.task.manage',p_case_id
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'Case DFIR authority is required'
      USING ERRCODE='42501';
  END IF;
  IF NOT operation_is_create AND NOT EXISTS (
    SELECT 1 FROM public.dfir_tasks AS task
    WHERE task.tenant_id=context_tenant
      AND task.case_id=p_case_id AND task.alert_id IS NULL
      AND task.id=p_resource_id
  ) THEN
    RAISE EXCEPTION 'Case DFIR task is unavailable' USING ERRCODE='P0002';
  END IF;

  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry
  WHERE registry.tenant_id=context_tenant
    AND registry.actor_user_id=actor_user
    AND registry.operation=p_operation
    AND registry.key_digest=p_key_digest
  FOR UPDATE;
  IF FOUND THEN
    IF tombstone.actor_membership_id IS DISTINCT FROM actor_membership THEN
      RAISE EXCEPTION
        'Case DFIR idempotency key belongs to another membership epoch'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    SELECT receipt.* INTO retention
    FROM public.dfir_ticket_command_retentions AS receipt
    JOIN public.ticket_commands AS command
      ON command.tenant_id=receipt.tenant_id
     AND command.id=receipt.command_id
     AND command.operation=receipt.operation
     AND command.created_at=receipt.command_created_at
    WHERE command.tenant_id=context_tenant
      AND command.actor_user_id=actor_user
      AND command.operation=p_operation
      AND command.key_digest=p_key_digest
    FOR UPDATE OF receipt,command;
    IF NOT FOUND OR retention.expires_at<=transaction_timestamp() THEN
      RAISE EXCEPTION 'Case DFIR idempotency key conflicts or receipt expired'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    RETURN QUERY
    SELECT * FROM app.private_reserve_case_dfir_unretained_v1(
      p_command_id,p_case_id,p_operation,p_resource_id,p_result_version,
      p_key_digest,p_request_digest,p_result_snapshot
    );
    RETURN;
  END IF;

  SELECT * INTO reservation
  FROM app.private_reserve_case_dfir_unretained_v1(
    p_command_id,p_case_id,p_operation,p_resource_id,p_result_version,
    p_key_digest,p_request_digest,p_result_snapshot
  );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Case DFIR reservation returned no coordinate'
      USING ERRCODE='55000';
  END IF;
  SELECT command.* INTO command_record
  FROM public.ticket_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.id=reservation.command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
    AND command.operation=p_operation
    AND command.key_digest=p_key_digest
    AND command.request_digest=p_request_digest
    AND command.result_case_id=p_case_id
    AND command.result_alert_id IS NULL
  FOR UPDATE;
  IF FOUND THEN
    IF reservation.replayed THEN
      RAISE EXCEPTION 'Case DFIR receipt exists without durable tombstone'
        USING ERRCODE='55000';
    END IF;
    IF operation_is_create THEN
      INSERT INTO public.dfir_mutation_resource_ids(
        tenant_id,resource_kind,resource_id,created_at
      ) VALUES (
        context_tenant,'task',p_resource_id,command_record.created_at
      );
    END IF;
    INSERT INTO public.dfir_mutation_resource_ids(
      tenant_id,resource_kind,resource_id,created_at
    )
    SELECT context_tenant,'checklist_item',(item.value->>'id')::uuid,
           command_record.created_at
    FROM jsonb_array_elements(
      reservation.result_snapshot#>'{task,checklist}'
    ) AS item(value)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.dfir_tasks AS task
      CROSS JOIN LATERAL jsonb_array_elements(task.checklist)
        AS current_item(value)
      WHERE task.tenant_id=context_tenant
        AND task.id=p_resource_id
        AND current_item.value->>'id'=item.value->>'id'
    );
    INSERT INTO public.dfir_mutation_replay_keys(
      tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
      first_used_at,receipt_expires_at
    ) VALUES (
      context_tenant,actor_user,actor_membership,p_operation,p_key_digest,
      command_record.created_at,command_record.created_at+interval '24 hours'
    );
    INSERT INTO public.dfir_ticket_command_retentions(
      tenant_id,command_id,operation,command_created_at,expires_at
    ) VALUES (
      context_tenant,command_record.id,command_record.operation,
      command_record.created_at,command_record.created_at+interval '24 hours'
    );
  END IF;
  RETURN QUERY SELECT reservation.command_id::uuid,
    reservation.result_resource_id::uuid,reservation.result_version::bigint,
    reservation.result_snapshot::jsonb,reservation.replayed::boolean;
END;
$function$;
