CREATE FUNCTION app.reserve_alert_investigation_command_v1(
  p_command_id uuid,
  p_alert_id uuid,
  p_operation text,
  p_resource_id uuid,
  p_result_version bigint,
  p_key_digest bytea,
  p_request_digest bytea
)
RETURNS TABLE(
  command_id uuid,
  result_resource_id uuid,
  result_version bigint,
  result_snapshot jsonb,
  replayed boolean
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
#variable_conflict use_variable
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  caller_role text:=current_setting('role',true);
  expected_permission text;
  operation_is_create boolean;
  tombstone public.dfir_mutation_replay_keys%ROWTYPE;
  command_record public.alert_dfir_resource_commands%ROWTYPE;
  reservation record;
  durable_kind text;
BEGIN
  SELECT mapping.permission_key,mapping.is_create,mapping.resource_kind
  INTO expected_permission,operation_is_create,durable_kind
  FROM (VALUES
    ('dfir.alert.evidence.create','dfir.evidence.manage',true,'evidence'),
    ('dfir.alert.evidence.custody.append','dfir.evidence.manage',false,'evidence'),
    ('dfir.alert.task.create','dfir.task.manage',true,'task'),
    ('dfir.alert.task.transition','dfir.task.manage',false,'task'),
    ('dfir.alert.task.replace_details','dfir.task.manage',false,'task'),
    ('dfir.alert.task.assign','dfir.task.manage',false,'task'),
    ('dfir.alert.task.reschedule','dfir.task.manage',false,'task'),
    ('dfir.alert.task.checklist.replace','dfir.task.manage',false,'task'),
    ('dfir.alert.task.comments.replace','dfir.task.manage',false,'task'),
    ('dfir.alert.relationship.create','dfir.relationship.manage',true,'relationship'),
    ('dfir.alert.relationship.retract','dfir.relationship.manage',false,'relationship')
  ) AS mapping(operation,permission_key,is_create,resource_kind)
  WHERE mapping.operation=p_operation;
  IF caller_role IS NULL OR caller_role='none' THEN
    caller_role:=session_user;
  END IF;
  IF NOT pg_has_role(caller_role,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE
     OR p_alert_id IS NULL
     OR (uuid_extract_version(p_alert_id)=7) IS NOT TRUE
     OR p_resource_id IS NULL
     OR (uuid_extract_version(p_resource_id)=7) IS NOT TRUE
     OR expected_permission IS NULL
    OR p_result_version IS NULL
    OR p_result_version NOT BETWEEN 1 AND 9007199254740991
     OR operation_is_create AND p_result_version<>1
     OR NOT operation_is_create AND p_result_version<2
     OR p_key_digest IS NULL OR octet_length(p_key_digest)<>32
     OR p_request_digest IS NULL OR octet_length(p_request_digest)<>32 THEN
    RAISE EXCEPTION 'Alert investigation command binding is invalid'
      USING ERRCODE='22023';
  END IF;

  -- RELATIONSHIP_REPLAY_AUTHORIZATION_HOOK_V1: authorization and current
  -- resource validation remain before durable tombstone inspection.
  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active' AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert investigation human authority is unavailable'
      USING ERRCODE='42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    context_tenant::text||':'||actor_user::text||':'||p_operation||':'||
    encode(p_key_digest,'hex'),82419731
  ));
  PERFORM 1 FROM public.alerts AS root
  WHERE root.tenant_id=context_tenant AND root.id=p_alert_id
    AND root.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert is unavailable' USING ERRCODE='P0002';
  END IF;
  IF app.private_current_alert_dfir_manage_scope_allows_v1(
    expected_permission,p_alert_id
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'Alert investigation authority is required'
      USING ERRCODE='42501';
  END IF;
  IF NOT operation_is_create THEN
    IF p_operation='dfir.alert.evidence.custody.append' THEN
      PERFORM 1 FROM public.dfir_evidence AS evidence
      WHERE evidence.tenant_id=context_tenant
        AND evidence.alert_id=p_alert_id AND evidence.case_id IS NULL
        AND evidence.id=p_resource_id
      FOR SHARE;
    ELSIF p_operation LIKE 'dfir.alert.task.%' THEN
      PERFORM 1 FROM public.dfir_tasks AS task
      WHERE task.tenant_id=context_tenant
        AND task.alert_id=p_alert_id AND task.case_id IS NULL
        AND task.id=p_resource_id
      FOR SHARE;
    ELSE
      PERFORM 1 FROM public.dfir_relationships AS relationship
      WHERE relationship.tenant_id=context_tenant
        AND relationship.alert_id=p_alert_id
        AND relationship.case_id IS NULL
        AND relationship.id=p_resource_id
      FOR SHARE;
    END IF;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Alert investigation resource is unavailable'
        USING ERRCODE='P0002';
    END IF;
  END IF;

  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry
  WHERE registry.tenant_id=context_tenant
    AND registry.actor_user_id=actor_user
    AND registry.operation=p_operation
    AND registry.key_digest=p_key_digest
  FOR UPDATE;
  IF FOUND THEN
    IF tombstone.actor_membership_id IS DISTINCT FROM actor_membership THEN
      RAISE EXCEPTION
        'Alert idempotency key belongs to another membership epoch'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    SELECT command.* INTO command_record
    FROM public.alert_dfir_resource_commands AS command
    WHERE command.tenant_id=context_tenant
      AND command.actor_user_id=actor_user
      AND command.operation=p_operation
      AND command.key_digest=p_key_digest
    FOR UPDATE;
    IF NOT FOUND OR command_record.expires_at<=transaction_timestamp() THEN
      RAISE EXCEPTION
        'Alert idempotency key conflicts or receipt expired'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_mutation_replay_keys_pkey';
    END IF;
    RETURN QUERY
    SELECT * FROM app.private_reserve_alert_investigation_unretained_v1(
      p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
      p_key_digest,p_request_digest
    );
    RETURN;
  END IF;

  SELECT * INTO reservation
  FROM app.private_reserve_alert_investigation_unretained_v1(
    p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
    p_key_digest,p_request_digest
  );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert investigation reservation returned no coordinate'
      USING ERRCODE='55000';
  END IF;
  SELECT command.* INTO command_record
  FROM public.alert_dfir_resource_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.command_id=reservation.command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
    AND command.operation=p_operation
    AND command.key_digest=p_key_digest
    AND command.request_digest=p_request_digest
    AND command.alert_id=p_alert_id
  FOR UPDATE;
  IF NOT FOUND OR reservation.replayed THEN
    RAISE EXCEPTION 'Alert receipt exists without durable tombstone'
      USING ERRCODE='55000';
  END IF;
  IF operation_is_create THEN
    INSERT INTO public.dfir_mutation_resource_ids(
      tenant_id,resource_kind,resource_id,created_at
    ) VALUES (
      context_tenant,durable_kind,p_resource_id,command_record.created_at
    );
  END IF;
  INSERT INTO public.dfir_mutation_replay_keys(
    tenant_id,actor_user_id,actor_membership_id,operation,key_digest,
    first_used_at,receipt_expires_at
  ) VALUES (
    context_tenant,actor_user,actor_membership,p_operation,p_key_digest,
    command_record.created_at,command_record.expires_at
  );
  RETURN QUERY SELECT reservation.command_id::uuid,
    reservation.result_resource_id::uuid,reservation.result_version::bigint,
    reservation.result_snapshot::jsonb,reservation.replayed::boolean;
END;
$function$;
