CREATE FUNCTION app.store_alert_investigation_command_result_v1(
  p_command_id uuid,
  p_result_snapshot jsonb
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  context_tenant uuid:=app.context_tenant_id();
  actor_user uuid:=app.context_user_id();
  actor_membership uuid:=app.current_tenant_membership_id();
  caller_role text:=current_setting('role',true);
  expected_permission text;
  command_record public.alert_dfir_resource_commands%ROWTYPE;
  tombstone public.dfir_mutation_replay_keys%ROWTYPE;
  stored boolean;
BEGIN
  IF caller_role IS NULL OR caller_role='none' THEN
    caller_role:=session_user;
  END IF;
  IF NOT pg_has_role(caller_role,'periapsis_api','member')
     OR p_command_id IS NULL
     OR (uuid_extract_version(p_command_id)=7) IS NOT TRUE THEN
    RAISE EXCEPTION 'Alert investigation result binding is invalid'
      USING ERRCODE='22023';
  END IF;
  PERFORM app.lock_current_tenant_authorization_state();
  PERFORM 1
  FROM public.tenant_memberships AS membership
  JOIN public.users AS identity ON identity.id=membership.user_id
  WHERE membership.tenant_id=context_tenant
    AND membership.id=actor_membership
    AND membership.user_id=actor_user
    AND membership.status='active' AND identity.active
  FOR SHARE OF membership,identity;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert investigation human authority is unavailable'
      USING ERRCODE='42501';
  END IF;
  SELECT command.* INTO command_record
  FROM public.alert_dfir_resource_commands AS command
  WHERE command.tenant_id=context_tenant
    AND command.command_id=p_command_id
    AND command.actor_user_id=actor_user
    AND command.actor_membership_id=actor_membership
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert investigation command is unavailable'
      USING ERRCODE='23503';
  END IF;
  expected_permission:=CASE
    WHEN command_record.operation LIKE 'dfir.alert.evidence.%'
      THEN 'dfir.evidence.manage'
    WHEN command_record.operation LIKE 'dfir.alert.task.%'
      THEN 'dfir.task.manage'
    WHEN command_record.operation LIKE 'dfir.alert.relationship.%'
      THEN 'dfir.relationship.manage'
    ELSE NULL END;
  PERFORM 1 FROM public.alerts AS root
  WHERE root.tenant_id=context_tenant AND root.id=command_record.alert_id
    AND root.deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND OR expected_permission IS NULL
     OR app.private_current_alert_dfir_manage_scope_allows_v1(
       expected_permission,command_record.alert_id
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'Alert investigation authority is required'
      USING ERRCODE='42501';
  END IF;
  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry
  WHERE registry.tenant_id=command_record.tenant_id
    AND registry.actor_user_id=command_record.actor_user_id
    AND registry.operation=command_record.operation
    AND registry.key_digest=command_record.key_digest
  FOR SHARE;
  IF NOT FOUND
     OR tombstone.actor_membership_id IS DISTINCT FROM actor_membership
     OR command_record.expires_at<=transaction_timestamp() THEN
    RAISE EXCEPTION 'Alert result receipt expired or conflicts'
      USING ERRCODE='23505',
            CONSTRAINT='dfir_mutation_replay_keys_pkey';
  END IF;
  SELECT app.private_store_alert_investigation_result_unretained_v1(
    p_command_id,p_result_snapshot
  ) INTO stored;
  RETURN stored;
END;
$function$;
