-- Permit exactly the worker cleanup path to remove Case DFIR task receipts
-- from the otherwise shared append-only ticket journal.
CREATE OR REPLACE FUNCTION app.guard_ticketing_append_only_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  caller_role text:=current_setting('role',true);
BEGIN
  IF TG_OP='DELETE'
     AND TG_TABLE_SCHEMA='public'
     AND TG_TABLE_NAME='ticket_commands' THEN
    IF caller_role IS NULL OR caller_role='none' THEN
      caller_role:=session_user;
    END IF;
    IF current_setting('app.dfir_mutation_receipt_prune_v1',true)='on'
       AND pg_has_role(caller_role,'periapsis_worker','member')
       AND OLD.operation IN (
         'case.dfir.task.create','case.dfir.task.transition',
         'case.dfir.task.replace_details','case.dfir.task.assign',
         'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
         'case.dfir.task.comments.replace'
       ) THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'ticketing evidence is append-only'
    USING ERRCODE='55000';
END;
