CREATE FUNCTION app.prune_expired_dfir_mutation_commands_v1(
  p_batch_size integer
)
RETURNS TABLE(results_deleted bigint,commands_deleted bigint)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  caller_role text:=current_setting('role',true);
  generic_ids uuid[]:='{}'::uuid[];
  alert_ids uuid[]:='{}'::uuid[];
  case_ids uuid[]:='{}'::uuid[];
  affected bigint;
BEGIN
  IF caller_role IS NULL OR caller_role='none' THEN
    caller_role:=session_user;
  END IF;
  IF NOT pg_has_role(caller_role,'periapsis_worker','member') THEN
    RAISE EXCEPTION 'DFIR receipt cleanup requires the worker role'
      USING ERRCODE='42501';
  END IF;
  IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'DFIR receipt cleanup batch is invalid'
      USING ERRCODE='22023';
  END IF;

  -- Select and lock every family before deleting any rows. This keeps the
  -- legacy Alert pass from racing the generic-command compatibility mirror.
  SELECT coalesce(array_agg(candidate.command_id),'{}'::uuid[])
  INTO generic_ids
  FROM (
    SELECT command.command_id
    FROM public.dfir_mutation_commands AS command
    WHERE command.expires_at <= transaction_timestamp()
    ORDER BY command.expires_at,command.tenant_id,command.command_id
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  ) AS candidate;

  SELECT coalesce(array_agg(candidate.command_id),'{}'::uuid[])
  INTO alert_ids
  FROM (
    SELECT command.command_id
    FROM public.alert_dfir_resource_commands AS command
    WHERE command.expires_at <= transaction_timestamp()
      AND NOT EXISTS (
        SELECT 1 FROM public.dfir_mutation_commands AS authoritative
        WHERE authoritative.command_id=command.command_id
      )
    ORDER BY command.expires_at,command.tenant_id,command.command_id
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  ) AS candidate;

  SELECT coalesce(array_agg(candidate.command_id),'{}'::uuid[])
  INTO case_ids
  FROM (
    SELECT retention.command_id
    FROM public.dfir_ticket_command_retentions AS retention
    JOIN public.ticket_commands AS command
      ON command.tenant_id=retention.tenant_id
     AND command.id=retention.command_id
     AND command.operation=retention.operation
     AND command.created_at=retention.command_created_at
    WHERE retention.expires_at <= transaction_timestamp()
    ORDER BY retention.expires_at,retention.tenant_id,
             retention.command_id
    LIMIT p_batch_size
    FOR UPDATE OF retention,command SKIP LOCKED
  ) AS candidate;

  PERFORM set_config('app.dfir_mutation_receipt_prune_v1','on',true);
  results_deleted:=0;
  commands_deleted:=0;

  -- A generic Alert IOC/asset/timeline receipt may have an exact legacy
  -- command mirror for the established effects ABI. Delete that child/result
  -- and mirror command before the authoritative generic receipt.
  DELETE FROM public.alert_dfir_resource_command_results AS result
  USING public.alert_dfir_resource_commands AS mirror,
        public.dfir_mutation_commands AS authoritative
  WHERE authoritative.command_id=ANY(generic_ids)
    AND mirror.command_id=authoritative.command_id
    AND authoritative.root_kind='alert'
    AND mirror.tenant_id=authoritative.tenant_id
    AND mirror.actor_user_id=authoritative.actor_user_id
    AND mirror.actor_membership_id=authoritative.actor_membership_id
    AND mirror.alert_id=authoritative.root_id
    AND mirror.operation=authoritative.operation
    AND mirror.resource_id=authoritative.resource_id
    AND mirror.result_version=authoritative.result_version
    AND mirror.key_digest=authoritative.key_digest
    AND mirror.request_digest=authoritative.request_digest
    AND result.command_id=mirror.command_id;
  GET DIAGNOSTICS affected=ROW_COUNT;
  results_deleted:=results_deleted+affected;

  DELETE FROM public.alert_dfir_resource_commands AS mirror
  USING public.dfir_mutation_commands AS authoritative
  WHERE authoritative.command_id=ANY(generic_ids)
    AND mirror.command_id=authoritative.command_id
    AND authoritative.root_kind='alert'
    AND mirror.tenant_id=authoritative.tenant_id
    AND mirror.actor_user_id=authoritative.actor_user_id
    AND mirror.actor_membership_id=authoritative.actor_membership_id
    AND mirror.alert_id=authoritative.root_id
    AND mirror.operation=authoritative.operation
    AND mirror.resource_id=authoritative.resource_id
    AND mirror.result_version=authoritative.result_version
    AND mirror.key_digest=authoritative.key_digest
    AND mirror.request_digest=authoritative.request_digest;
  GET DIAGNOSTICS affected=ROW_COUNT;
  commands_deleted:=commands_deleted+affected;

  DELETE FROM public.dfir_mutation_command_results AS result
  WHERE result.command_id=ANY(generic_ids);
  GET DIAGNOSTICS affected=ROW_COUNT;
  results_deleted:=results_deleted+affected;

  DELETE FROM public.dfir_mutation_commands AS command
  WHERE command.command_id=ANY(generic_ids);
  GET DIAGNOSTICS affected=ROW_COUNT;
  commands_deleted:=commands_deleted+affected;

  DELETE FROM public.alert_dfir_resource_command_results AS result
  WHERE result.command_id=ANY(alert_ids);
  GET DIAGNOSTICS affected=ROW_COUNT;
  results_deleted:=results_deleted+affected;

  DELETE FROM public.alert_dfir_resource_commands AS command
  WHERE command.command_id=ANY(alert_ids);
  GET DIAGNOSTICS affected=ROW_COUNT;
  commands_deleted:=commands_deleted+affected;

  -- The retention row is an internal child, not a receipt count. Delete it
  -- first, then remove only the exact DFIR task command from the shared journal.
  DELETE FROM public.dfir_ticket_command_retentions AS retention
  WHERE retention.command_id=ANY(case_ids);

  DELETE FROM public.ticket_commands AS command
  WHERE command.id=ANY(case_ids)
    AND command.operation IN (
      'case.dfir.task.create','case.dfir.task.transition',
      'case.dfir.task.replace_details','case.dfir.task.assign',
      'case.dfir.task.reschedule','case.dfir.task.replace_checklist',
      'case.dfir.task.comments.replace'
    );
  GET DIAGNOSTICS affected=ROW_COUNT;
  commands_deleted:=commands_deleted+affected;

  RETURN NEXT;
END;
$function$;
--> statement-breakpoint
