-- The obsolete Alert resource reservation can create an unbounded legacy
-- receipt, so it remains unavailable after the generic receipt migration.
REVOKE ALL ON FUNCTION app.reserve_alert_dfir_resource_command_v1(
  uuid,uuid,text,uuid,bigint,bytea,bytea
) FROM PUBLIC,periapsis_api,periapsis_worker,periapsis_notifier,
  periapsis_auditor,periapsis_audit_reader_owner,
  periapsis_notification_dispatch_owner,periapsis_sla_api_owner,
  periapsis_sla_worker_owner,periapsis_sla_readiness_owner,
  periapsis_ticket_runtime_owner;
--> statement-breakpoint

DO $dfir_mutation_retention_contract$
DECLARE
  boundary regprocedure:=
    'app.prune_expired_dfir_mutation_commands_v1(integer)'::regprocedure;
  private_boundary regprocedure;
  relation_name text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_catalog.pg_proc AS procedure
    WHERE procedure.oid=boundary
      AND procedure.prosecdef
      AND pg_get_userbyid(procedure.proowner)='periapsis_migrator'
      AND procedure.proconfig @> ARRAY[
        'search_path=pg_catalog, public, app'
      ]::text[]
  ) OR NOT has_function_privilege('periapsis_worker',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_api',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_notifier',boundary,'EXECUTE')
     OR has_function_privilege('periapsis_auditor',boundary,'EXECUTE')
     OR has_function_privilege('public',boundary,'EXECUTE') THEN
    RAISE EXCEPTION 'DFIR receipt cleanup ABI is not worker-isolated'
      USING ERRCODE='55000';
  END IF;

  FOREACH private_boundary IN ARRAY ARRAY[
    'app.private_reserve_case_dfir_unretained_v1(uuid,uuid,text,uuid,bigint,bytea,bytea,jsonb)'::regprocedure,
    'app.private_reserve_alert_investigation_unretained_v1(uuid,uuid,text,uuid,bigint,bytea,bytea)'::regprocedure,
    'app.private_store_alert_investigation_result_unretained_v1(uuid,jsonb)'::regprocedure
  ]
  LOOP
    IF has_function_privilege('periapsis_api',private_boundary,'EXECUTE')
       OR has_function_privilege('periapsis_worker',private_boundary,'EXECUTE')
       OR has_function_privilege('public',private_boundary,'EXECUTE') THEN
      RAISE EXCEPTION 'Private unretained receipt ABI is executable: %',
        private_boundary USING ERRCODE='55000';
    END IF;
  END LOOP;

  FOREACH relation_name IN ARRAY ARRAY[
    'dfir_mutation_resource_ids','dfir_mutation_replay_keys',
    'dfir_mutation_commands','dfir_mutation_command_results',
    'alert_dfir_resource_commands','alert_dfir_resource_command_results',
    'dfir_ticket_command_retentions'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_class AS relation
      WHERE relation.oid=format('public.%I',relation_name)::regclass
        AND relation.relrowsecurity AND relation.relforcerowsecurity
        AND pg_get_userbyid(relation.relowner)='periapsis_migrator'
    ) THEN
      RAISE EXCEPTION 'DFIR receipt relation is not RLS sealed: %',
        relation_name USING ERRCODE='55000';
    END IF;
  END LOOP;
END;
$dfir_mutation_retention_contract$;
-- DFIR_MUTATION_RETENTION_V1_END
--> statement-breakpoint

-- DFIR_GENERIC_RELATIONSHIP_ROOT_CONTEXT_V1_BEGIN
-- A relationship is owned by its persisted Case/Alert workspace even when
-- neither endpoint is that root.  Current endpoint scope is deliberately
-- recomputed for every write and replay; immutable receipts never snapshot
-- dynamic authorization.
CREATE FUNCTION app.private_dfir_relationship_runtime_write_v1()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
  SELECT current_setting('role',true)='periapsis_api'
    OR (
      pg_has_role(session_user,'periapsis_api','member')
      AND NOT pg_has_role(session_user,'periapsis_migrator','member')
    )
$function$;
