CREATE FUNCTION app.private_dfir_relationship_endpoint_valid_for_root_v1(
  p_tenant_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_endpoint_kind public.dfir_entity_kind,
  p_endpoint_id uuid,
  p_external_type text,
  p_external_id text,
  p_require_authority boolean
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  runtime_write boolean:=app.private_dfir_relationship_runtime_write_v1();
  entity_found boolean:=false;
  attachment_record public.dfir_attachments%ROWTYPE;
BEGIN
  IF p_tenant_id IS NULL OR p_root_kind IS NULL OR p_root_id IS NULL
     OR p_endpoint_kind IS NULL OR p_require_authority IS NULL
     OR runtime_write AND p_tenant_id IS DISTINCT FROM app.context_tenant_id()
  THEN
    RETURN false;
  END IF;

  IF p_root_kind='case' THEN
    PERFORM 1 FROM public.cases AS root
    WHERE root.tenant_id=p_tenant_id AND root.id=p_root_id
    FOR SHARE;
    entity_found:=FOUND;
    IF NOT entity_found OR p_require_authority AND runtime_write
       AND app.private_current_dfir_scope_allows_v1(
         'dfir.relationship.manage',p_root_id
       ) IS NOT TRUE THEN
      RETURN false;
    END IF;
  ELSE
    PERFORM 1 FROM public.alerts AS root
    WHERE root.tenant_id=p_tenant_id AND root.id=p_root_id
      AND root.deleted_at IS NULL
    FOR SHARE;
    entity_found:=FOUND;
    IF NOT entity_found OR p_require_authority AND runtime_write
       AND app.private_current_alert_dfir_manage_scope_allows_v1(
         'dfir.relationship.manage',p_root_id
       ) IS NOT TRUE THEN
      RETURN false;
    END IF;
  END IF;

  IF p_endpoint_kind='external' THEN
    RETURN p_endpoint_id IS NULL
      AND p_external_type~'^[a-z][a-z0-9_.-]{0,63}$'
      AND octet_length(p_external_id) BETWEEN 1 AND 2048;
  END IF;
  IF p_endpoint_id IS NULL OR p_external_type IS NOT NULL
     OR p_external_id IS NOT NULL THEN
    RETURN false;
  END IF;

  CASE p_endpoint_kind
    WHEN 'case' THEN
      PERFORM 1 FROM public.cases AS endpoint
      WHERE endpoint.tenant_id=p_tenant_id AND endpoint.id=p_endpoint_id
      FOR SHARE;
      entity_found:=FOUND;
      RETURN entity_found AND (
        NOT p_require_authority OR NOT runtime_write
        OR app.private_current_dfir_scope_allows_v1(
          'dfir.relationship.manage',p_endpoint_id
        ) IS TRUE
      );
    WHEN 'alert' THEN
      PERFORM 1 FROM public.alerts AS endpoint
      WHERE endpoint.tenant_id=p_tenant_id AND endpoint.id=p_endpoint_id
        AND endpoint.deleted_at IS NULL
      FOR SHARE;
      entity_found:=FOUND;
      RETURN entity_found AND (
        NOT p_require_authority OR NOT runtime_write
        OR app.private_current_alert_dfir_manage_scope_allows_v1(
          'dfir.relationship.manage',p_endpoint_id
        ) IS TRUE
      );
    WHEN 'ioc' THEN
      IF p_root_kind='case' THEN
        PERFORM 1
        FROM public.dfir_iocs AS resource
        JOIN public.dfir_ioc_links AS link
          ON link.tenant_id=resource.tenant_id AND link.ioc_id=resource.id
        WHERE resource.tenant_id=p_tenant_id AND resource.id=p_endpoint_id
          AND resource.archived_at IS NULL
          AND link.case_id=p_root_id AND link.alert_id IS NULL
        FOR SHARE OF resource,link;
      ELSE
        PERFORM 1
        FROM public.dfir_iocs AS resource
        JOIN public.dfir_ioc_links AS link
          ON link.tenant_id=resource.tenant_id AND link.ioc_id=resource.id
        WHERE resource.tenant_id=p_tenant_id AND resource.id=p_endpoint_id
          AND resource.archived_at IS NULL
          AND link.alert_id=p_root_id AND link.case_id IS NULL
        FOR SHARE OF resource,link;
      END IF;
      RETURN FOUND;
    WHEN 'asset' THEN
      IF p_root_kind='case' THEN
        PERFORM 1
        FROM public.dfir_assets AS resource
        JOIN public.dfir_asset_links AS link
          ON link.tenant_id=resource.tenant_id AND link.asset_id=resource.id
        WHERE resource.tenant_id=p_tenant_id AND resource.id=p_endpoint_id
          AND resource.archived_at IS NULL
          AND link.case_id=p_root_id AND link.alert_id IS NULL
        FOR SHARE OF resource,link;
      ELSE
        PERFORM 1
        FROM public.dfir_assets AS resource
        JOIN public.dfir_asset_links AS link
          ON link.tenant_id=resource.tenant_id AND link.asset_id=resource.id
        WHERE resource.tenant_id=p_tenant_id AND resource.id=p_endpoint_id
          AND resource.archived_at IS NULL
          AND link.alert_id=p_root_id AND link.case_id IS NULL
        FOR SHARE OF resource,link;
      END IF;
      RETURN FOUND;
    WHEN 'evidence' THEN
      PERFORM 1 FROM public.dfir_evidence AS evidence
      WHERE evidence.tenant_id=p_tenant_id AND evidence.id=p_endpoint_id
        AND NOT evidence.destroyed AND evidence.scan_state<>'deleted'
        AND (
          p_root_kind='case' AND evidence.case_id=p_root_id
            AND evidence.alert_id IS NULL
          OR p_root_kind='alert' AND evidence.alert_id=p_root_id
            AND evidence.case_id IS NULL
        )
      FOR SHARE;
      RETURN FOUND;
    WHEN 'task' THEN
      PERFORM 1 FROM public.dfir_tasks AS task
      WHERE task.tenant_id=p_tenant_id AND task.id=p_endpoint_id
        AND (
          p_root_kind='case' AND task.case_id=p_root_id
            AND task.alert_id IS NULL
          OR p_root_kind='alert' AND task.alert_id=p_root_id
            AND task.case_id IS NULL
        )
      FOR SHARE;
      RETURN FOUND;
    WHEN 'attachment' THEN
      SELECT attachment.* INTO attachment_record
      FROM public.dfir_attachments AS attachment
      JOIN public.dfir_storage_objects AS storage
        ON storage.tenant_id=attachment.tenant_id
       AND storage.id=attachment.storage_object_id
      WHERE attachment.tenant_id=p_tenant_id
        AND attachment.id=p_endpoint_id
        AND attachment.scan_state<>'deleted'
        AND attachment.version BETWEEN 1 AND 9007199254740991
        AND storage.state<>'deleted'
        AND storage.version BETWEEN 1 AND 9007199254740991
      FOR SHARE OF attachment,storage;
      IF NOT FOUND THEN
        RETURN false;
      END IF;
      IF p_root_kind='alert' THEN
        RETURN CASE attachment_record.subject_kind
          WHEN 'alert' THEN attachment_record.alert_id=p_root_id
          WHEN 'ioc' THEN EXISTS (
            SELECT 1 FROM public.dfir_ioc_links AS link
            JOIN public.dfir_iocs AS resource
              ON resource.tenant_id=link.tenant_id
             AND resource.id=link.ioc_id
            WHERE link.tenant_id=p_tenant_id AND link.alert_id=p_root_id
              AND link.case_id IS NULL
              AND link.ioc_id=attachment_record.ioc_id
              AND resource.archived_at IS NULL
          )
          WHEN 'asset' THEN EXISTS (
            SELECT 1 FROM public.dfir_asset_links AS link
            JOIN public.dfir_assets AS resource
              ON resource.tenant_id=link.tenant_id
             AND resource.id=link.asset_id
            WHERE link.tenant_id=p_tenant_id AND link.alert_id=p_root_id
              AND link.case_id IS NULL
              AND link.asset_id=attachment_record.asset_id
              AND resource.archived_at IS NULL
          )
          WHEN 'evidence' THEN EXISTS (
            SELECT 1 FROM public.dfir_evidence AS evidence
            WHERE evidence.tenant_id=p_tenant_id
              AND evidence.alert_id=p_root_id AND evidence.case_id IS NULL
              AND evidence.id=attachment_record.evidence_id
              AND NOT evidence.destroyed AND evidence.scan_state<>'deleted'
          )
          WHEN 'task' THEN EXISTS (
            SELECT 1 FROM public.dfir_tasks AS task
            WHERE task.tenant_id=p_tenant_id AND task.alert_id=p_root_id
              AND task.case_id IS NULL AND task.id=attachment_record.task_id
          )
          ELSE false END;
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.dfir_attachment_case_links AS link
        WHERE link.tenant_id=p_tenant_id
          AND link.attachment_id=attachment_record.id
          AND link.case_id=p_root_id
      ) THEN
        RETURN true;
      END IF;
      RETURN CASE attachment_record.subject_kind
        WHEN 'case' THEN attachment_record.case_id=p_root_id
        WHEN 'ioc' THEN EXISTS (
          SELECT 1 FROM public.dfir_ioc_links AS link
          JOIN public.dfir_iocs AS resource
            ON resource.tenant_id=link.tenant_id AND resource.id=link.ioc_id
          WHERE link.tenant_id=p_tenant_id AND link.case_id=p_root_id
            AND link.alert_id IS NULL
            AND link.ioc_id=attachment_record.ioc_id
            AND resource.archived_at IS NULL
        )
        WHEN 'asset' THEN EXISTS (
          SELECT 1 FROM public.dfir_asset_links AS link
          JOIN public.dfir_assets AS resource
            ON resource.tenant_id=link.tenant_id
           AND resource.id=link.asset_id
          WHERE link.tenant_id=p_tenant_id AND link.case_id=p_root_id
            AND link.alert_id IS NULL
            AND link.asset_id=attachment_record.asset_id
            AND resource.archived_at IS NULL
        )
        WHEN 'evidence' THEN EXISTS (
          SELECT 1 FROM public.dfir_evidence AS evidence
          WHERE evidence.tenant_id=p_tenant_id
            AND evidence.case_id=p_root_id AND evidence.alert_id IS NULL
            AND evidence.id=attachment_record.evidence_id
            AND NOT evidence.destroyed AND evidence.scan_state<>'deleted'
        )
        WHEN 'task' THEN EXISTS (
          SELECT 1 FROM public.dfir_tasks AS task
          WHERE task.tenant_id=p_tenant_id AND task.case_id=p_root_id
            AND task.alert_id IS NULL AND task.id=attachment_record.task_id
        )
        ELSE false END;
    ELSE
      RETURN false;
  END CASE;
END;
$function$;
--> statement-breakpoint
