CREATE FUNCTION app.private_assert_current_dfir_relationship_for_root_v1(
  p_tenant_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_relationship_id uuid
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  relationship_record public.dfir_relationships%ROWTYPE;
  runtime_write boolean:=app.private_dfir_relationship_runtime_write_v1();
  actor_membership uuid;
  actor_user uuid;
BEGIN
  IF p_tenant_id IS NULL OR p_root_kind IS NULL OR p_root_id IS NULL
     OR p_relationship_id IS NULL THEN
    RAISE EXCEPTION 'DFIR relationship root coordinate is invalid'
      USING ERRCODE='22023';
  END IF;
  IF runtime_write THEN
    IF p_tenant_id IS DISTINCT FROM app.context_tenant_id() THEN
      RAISE EXCEPTION 'DFIR relationship authority is unavailable'
        USING ERRCODE='42501';
    END IF;
    PERFORM app.lock_current_tenant_authorization_state();
    actor_membership:=app.current_tenant_membership_id();
    actor_user:=app.context_user_id();
    PERFORM 1
    FROM public.tenant_memberships AS membership
    JOIN public.users AS identity ON identity.id=membership.user_id
    WHERE membership.tenant_id=p_tenant_id
      AND membership.id=actor_membership
      AND membership.user_id=actor_user
      AND membership.status='active' AND identity.active
    FOR SHARE OF membership,identity;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR relationship authority is unavailable'
        USING ERRCODE='42501';
    END IF;
  END IF;
  SELECT relationship.* INTO relationship_record
  FROM public.dfir_relationships AS relationship
  WHERE relationship.tenant_id=p_tenant_id
    AND relationship.id=p_relationship_id
    AND (
      p_root_kind='case' AND relationship.case_id=p_root_id
        AND relationship.alert_id IS NULL
      OR p_root_kind='alert' AND relationship.alert_id=p_root_id
        AND relationship.case_id IS NULL
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR relationship was not found for the path root'
      USING ERRCODE='P0002';
  END IF;
  IF app.private_dfir_relationship_endpoint_valid_for_root_v1(
       p_tenant_id,p_root_kind,p_root_id,
       relationship_record.source_kind,relationship_record.source_id,
       relationship_record.source_external_type,
       relationship_record.source_external_id,true
     ) IS NOT TRUE
     OR app.private_dfir_relationship_endpoint_valid_for_root_v1(
       p_tenant_id,p_root_kind,p_root_id,
       relationship_record.target_kind,relationship_record.target_id,
       relationship_record.target_external_type,
       relationship_record.target_external_id,true
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'DFIR relationship endpoint authority is unavailable'
      USING ERRCODE='42501';
  END IF;
END;
