CREATE OR REPLACE FUNCTION app.validate_dfir_relationship_v1()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  persisted_root_kind public.dfir_mutation_root_kind;
  persisted_root_id uuid;
  runtime_write boolean:=app.private_dfir_relationship_runtime_write_v1();
  actor_membership uuid;
  actor_user uuid;
BEGIN
  IF num_nonnulls(NEW.alert_id,NEW.case_id)<>1 THEN
    RAISE EXCEPTION 'DFIR relationship persisted root is invalid'
      USING ERRCODE='23514';
  END IF;
  persisted_root_kind:=CASE
    WHEN NEW.case_id IS NOT NULL THEN 'case'
    ELSE 'alert'
  END;
  persisted_root_id:=coalesce(NEW.case_id,NEW.alert_id);
  IF runtime_write THEN
    IF NEW.tenant_id IS DISTINCT FROM app.context_tenant_id() THEN
      RAISE EXCEPTION 'DFIR relationship authority is unavailable'
        USING ERRCODE='42501';
    END IF;
    PERFORM app.lock_current_tenant_authorization_state();
    actor_membership:=app.current_tenant_membership_id();
    actor_user:=app.context_user_id();
    PERFORM 1
    FROM public.tenant_memberships AS membership
    JOIN public.users AS identity ON identity.id=membership.user_id
    WHERE membership.tenant_id=NEW.tenant_id
      AND membership.id=actor_membership
      AND membership.user_id=actor_user
      AND membership.status='active' AND identity.active
    FOR SHARE OF membership,identity;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'DFIR relationship authority is unavailable'
        USING ERRCODE='42501';
    END IF;
    IF TG_OP='INSERT' AND persisted_root_kind='case' AND NOT EXISTS (
      SELECT 1 FROM public.dfir_mutation_commands AS command
      WHERE command.tenant_id=NEW.tenant_id
        AND command.actor_user_id=actor_user
        AND command.actor_membership_id=actor_membership
        AND command.root_kind='case'
        AND command.root_id=persisted_root_id
        AND command.operation='dfir.relationship.create'
        AND command.resource_kind='relationship'
        AND command.resource_id=NEW.id
        AND command.secondary_resource_id IS NULL
        AND command.result_version=1
        AND command.expires_at>transaction_timestamp()
    ) THEN
      RAISE EXCEPTION 'Case relationship create reservation is unavailable'
        USING ERRCODE='23503';
    ELSIF TG_OP='INSERT' AND persisted_root_kind='alert' AND NOT EXISTS (
      SELECT 1 FROM public.alert_dfir_resource_commands AS command
      WHERE command.tenant_id=NEW.tenant_id
        AND command.actor_user_id=actor_user
        AND command.actor_membership_id=actor_membership
        AND command.alert_id=persisted_root_id
        AND command.operation='dfir.alert.relationship.create'
        AND command.resource_id=NEW.id
        AND command.result_version=1
        AND command.expires_at>transaction_timestamp()
    ) THEN
      RAISE EXCEPTION 'Alert relationship create reservation is unavailable'
        USING ERRCODE='23503';
    END IF;
  END IF;

  IF app.private_dfir_relationship_endpoint_valid_for_root_v1(
       NEW.tenant_id,persisted_root_kind,persisted_root_id,
       NEW.source_kind,NEW.source_id,
       NEW.source_external_type,NEW.source_external_id,true
     ) IS NOT TRUE
     OR app.private_dfir_relationship_endpoint_valid_for_root_v1(
       NEW.tenant_id,persisted_root_kind,persisted_root_id,
       NEW.target_kind,NEW.target_id,
       NEW.target_external_type,NEW.target_external_id,true
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'DFIR relationship endpoint authority is unavailable'
      USING ERRCODE='42501';
  END IF;

  IF TG_OP='INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      jsonb_build_array(
        NEW.tenant_id,persisted_root_kind,persisted_root_id,
        NEW.source_kind,NEW.source_id,NEW.source_external_type,
        NEW.source_external_id,NEW.target_kind,NEW.target_id,
        NEW.target_external_type,NEW.target_external_id,
        NEW.relationship_type
      )::text,82419737
    ));
    IF EXISTS (
      SELECT 1 FROM public.dfir_relationships AS relationship
      WHERE relationship.tenant_id=NEW.tenant_id
        AND relationship.alert_id IS NOT DISTINCT FROM NEW.alert_id
        AND relationship.case_id IS NOT DISTINCT FROM NEW.case_id
        AND relationship.source_kind=NEW.source_kind
        AND relationship.source_id IS NOT DISTINCT FROM NEW.source_id
        AND relationship.source_external_type IS NOT DISTINCT FROM
            NEW.source_external_type
        AND relationship.source_external_id IS NOT DISTINCT FROM
            NEW.source_external_id
        AND relationship.target_kind=NEW.target_kind
        AND relationship.target_id IS NOT DISTINCT FROM NEW.target_id
        AND relationship.target_external_type IS NOT DISTINCT FROM
            NEW.target_external_type
        AND relationship.target_external_id IS NOT DISTINCT FROM
            NEW.target_external_id
        AND relationship.relationship_type=NEW.relationship_type
        AND NOT EXISTS (
          SELECT 1 FROM public.dfir_relationship_retractions AS retraction
          WHERE retraction.tenant_id=relationship.tenant_id
            AND retraction.relationship_id=relationship.id
        )
    ) THEN
      RAISE EXCEPTION 'active DFIR relationship already exists in root'
        USING ERRCODE='23505',
              CONSTRAINT='dfir_relationships_active_root_coordinate_key';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
