CREATE FUNCTION app.private_dfir_relationship_projection_matches_v1(
  p_projection jsonb,
  p_tenant_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_operation text,
  p_relationship_id uuid,
  p_retraction_id uuid,
  p_result_version bigint,
  p_alert_shape boolean
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE
  relationship_record public.dfir_relationships%ROWTYPE;
  retraction_record public.dfir_relationship_retractions%ROWTYPE;
  expected_source jsonb;
  expected_target jsonb;
  expected_projection jsonb;
  expected_retraction jsonb;
BEGIN
  IF p_projection IS NULL OR jsonb_typeof(p_projection)<>'object'
     OR p_tenant_id IS NULL OR p_root_kind IS NULL OR p_root_id IS NULL
     OR p_relationship_id IS NULL OR p_result_version NOT BETWEEN 1 AND 2
     OR p_alert_shape IS DISTINCT FROM (p_root_kind='alert')
     OR NOT (
       NOT p_alert_shape
         AND p_operation IN (
           'dfir.relationship.create','dfir.relationship.retract'
         )
       OR p_alert_shape
         AND p_operation IN (
           'dfir.alert.relationship.create',
           'dfir.alert.relationship.retract'
         )
     ) THEN
    RETURN false;
  END IF;
  SELECT relationship.* INTO relationship_record
  FROM public.dfir_relationships AS relationship
  WHERE relationship.tenant_id=p_tenant_id
    AND relationship.id=p_relationship_id
    AND (
      p_root_kind='case' AND relationship.case_id=p_root_id
        AND relationship.alert_id IS NULL
      OR p_root_kind='alert' AND relationship.alert_id=p_root_id
        AND relationship.case_id IS NULL
    );
  IF NOT FOUND OR relationship_record.version NOT BETWEEN 1 AND 2
     OR jsonb_typeof(p_projection->'id')<>'string'
     OR (p_projection->>'id')::uuid IS DISTINCT FROM p_relationship_id
     OR jsonb_typeof(p_projection->'tenantId')<>'string'
     OR (p_projection->>'tenantId')::uuid IS DISTINCT FROM p_tenant_id
     OR jsonb_typeof(p_projection->'createdBy')<>'string'
     OR (p_projection->>'createdBy')::uuid IS DISTINCT FROM
        relationship_record.created_by_membership_id
     OR jsonb_typeof(p_projection->'createdAt')<>'string'
     OR (p_projection->>'createdAt')::timestamp with time zone
        IS DISTINCT FROM relationship_record.created_at THEN
    RETURN false;
  END IF;

  expected_source:=CASE WHEN relationship_record.source_kind='external'
    THEN jsonb_build_object(
      'kind','external',
      'externalType',relationship_record.source_external_type,
      'externalId',relationship_record.source_external_id
    ) ELSE jsonb_build_object(
      'kind',relationship_record.source_kind::text,
      'id',relationship_record.source_id::text
    ) END;
  expected_target:=CASE WHEN relationship_record.target_kind='external'
    THEN jsonb_build_object(
      'kind','external',
      'externalType',relationship_record.target_external_type,
      'externalId',relationship_record.target_external_id
    ) ELSE jsonb_build_object(
      'kind',relationship_record.target_kind::text,
      'id',relationship_record.target_id::text
    ) END;
  expected_projection:=jsonb_build_object(
    'id',relationship_record.id::text,
    'tenantId',relationship_record.tenant_id::text,
    'source',expected_source,
    'target',expected_target,
    'relationshipType',relationship_record.relationship_type,
    'createdBy',relationship_record.created_by_membership_id::text,
    'createdAt',p_projection->'createdAt',
    'version',p_result_version
  );
  IF relationship_record.metadata IS NOT NULL THEN
    expected_projection:=expected_projection||jsonb_build_object(
      'metadata',relationship_record.metadata
    );
  END IF;
  IF p_alert_shape THEN
    expected_projection:=expected_projection||jsonb_build_object(
      'alertId',p_root_id::text
    );
  END IF;

  IF p_operation IN (
    'dfir.relationship.create','dfir.alert.relationship.create'
  ) THEN
    IF p_retraction_id IS NOT NULL OR p_result_version<>1 THEN
      RETURN false;
    END IF;
    IF p_alert_shape THEN
      expected_projection:=expected_projection||
        jsonb_build_object('retractions','[]'::jsonb);
    END IF;
    RETURN p_projection=expected_projection;
  END IF;

  IF p_alert_shape AND p_retraction_id IS NULL
     AND jsonb_typeof(p_projection#>'{retractions,0,id}')='string' THEN
    p_retraction_id:=(p_projection#>>'{retractions,0,id}')::uuid;
  END IF;
  IF p_retraction_id IS NULL OR p_result_version<>2
     OR relationship_record.version<>2 THEN
    RETURN false;
  END IF;
  SELECT retraction.* INTO retraction_record
  FROM public.dfir_relationship_retractions AS retraction
  WHERE retraction.tenant_id=p_tenant_id
    AND retraction.relationship_id=p_relationship_id
    AND retraction.id=p_retraction_id
    AND retraction.prior_version=1 AND retraction.result_version=2
    AND (
      p_root_kind='case' AND retraction.case_id=p_root_id
        AND retraction.alert_id IS NULL
      OR p_root_kind='alert' AND retraction.alert_id=p_root_id
        AND retraction.case_id IS NULL
    );
  IF NOT FOUND
     OR jsonb_typeof(p_projection#>'{retractions,0,occurredAt}')<>'string'
     OR (p_projection#>>'{retractions,0,occurredAt}')::timestamp with time zone
        IS DISTINCT FROM retraction_record.retracted_at THEN
    RETURN false;
  END IF;
  expected_retraction:=jsonb_build_object(
    'id',retraction_record.id::text,
    'tenantId',retraction_record.tenant_id::text,
    'relationshipId',retraction_record.relationship_id::text,
    'sequence',1,
    'actorId',retraction_record.retracted_by_membership_id::text,
    'reason',retraction_record.reason,
    'occurredAt',p_projection#>'{retractions,0,occurredAt}'
  );
  expected_projection:=expected_projection||jsonb_build_object(
    'retractions',jsonb_build_array(expected_retraction)
  );
  RETURN p_projection=expected_projection;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$function$;
--> statement-breakpoint
