CREATE FUNCTION app.private_dfir_mutation_snapshot_valid_v1(
  p_snapshot jsonb,
  p_tenant_id uuid,
  p_root_kind public.dfir_mutation_root_kind,
  p_root_id uuid,
  p_operation text,
  p_resource_kind text,
  p_resource_id uuid,
  p_secondary_resource_id uuid,
  p_result_version bigint
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path=pg_catalog,public,app
AS $function$
DECLARE sanitized_snapshot jsonb;
BEGIN
  IF p_resource_kind IS DISTINCT FROM 'relationship' THEN
    RETURN app.private_dfir_mutation_snapshot_valid_root_anchored_v1(
      p_snapshot,p_tenant_id,p_root_kind,p_root_id,p_operation,
      p_resource_kind,p_resource_id,p_secondary_resource_id,
      p_result_version
    );
  END IF;
  IF p_root_kind IS DISTINCT FROM 'case' THEN
    RETURN false;
  END IF;
  sanitized_snapshot:=jsonb_set(
    p_snapshot,'{projection,source}',
    jsonb_build_object('kind','case','id',p_root_id::text),false
  );
  RETURN app.private_dfir_mutation_snapshot_valid_root_anchored_v1(
      sanitized_snapshot,p_tenant_id,p_root_kind,p_root_id,p_operation,
      p_resource_kind,p_resource_id,p_secondary_resource_id,
      p_result_version
    ) IS TRUE
    AND app.private_dfir_relationship_projection_matches_v1(
      p_snapshot->'projection',p_tenant_id,p_root_kind,p_root_id,
      p_operation,p_resource_id,p_secondary_resource_id,p_result_version,
      false
    ) IS TRUE;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$function$;
--> statement-breakpoint
