--> statement-breakpoint
REVOKE ALL ON FUNCTION app.private_dfir_mutation_snapshot_valid_v1(
  jsonb,uuid,public.dfir_mutation_root_kind,uuid,text,text,uuid,uuid,bigint
) FROM PUBLIC,periapsis_api,periapsis_worker,periapsis_notifier,
  periapsis_auditor,periapsis_audit_reader_owner,
  periapsis_notification_dispatch_owner,periapsis_sla_api_owner,
  periapsis_sla_worker_owner,periapsis_sla_readiness_owner,
  periapsis_ticket_runtime_owner;
--> statement-breakpoint

-- Patch the finalized receipt functions in place.  Every replacement is
-- drift-checked so a future body change fails migration rather than silently
-- moving current endpoint authorization behind replay.
DO $dfir_generic_relationship_patch_v1$
DECLARE
  function_definition text;
  needle text;
  replacement text;
  occurrence_count integer;
BEGIN
  SELECT pg_get_functiondef(
    'app.reserve_dfir_mutation_command_v1(uuid,public.dfir_mutation_root_kind,uuid,text,text,uuid,uuid,bigint,bytea,bytea)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$
  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry$needle$;
  replacement:=$replacement$
  IF p_operation='dfir.relationship.retract' THEN
    PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
      context_tenant,p_root_kind,p_root_id,p_resource_id
    );
  END IF;

  -- GENERIC_RELATIONSHIP_CURRENT_AUTHORIZATION_V1
  SELECT registry.* INTO tombstone
  FROM public.dfir_mutation_replay_keys AS registry$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'generic relationship pre-receipt hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);

  needle:=$needle$
    SELECT result.result_snapshot INTO stored_snapshot
    FROM public.dfir_mutation_command_results AS result$needle$;
  replacement:=$replacement$
    IF p_resource_kind='relationship' THEN
      PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
        context_tenant,p_root_kind,p_root_id,p_resource_id
      );
    END IF;
    -- GENERIC_RELATIONSHIP_REPLAY_AUTHORIZATION_V1
    SELECT result.result_snapshot INTO stored_snapshot
    FROM public.dfir_mutation_command_results AS result$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'generic relationship replay hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;

  SELECT pg_get_functiondef(
    'app.reserve_alert_investigation_command_v1(uuid,uuid,text,uuid,bigint,bytea,bytea)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$
  SELECT * INTO reservation
  FROM app.private_reserve_alert_investigation_unretained_v1(
    p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
    p_key_digest,p_request_digest
  );$needle$;
  replacement:=$replacement$
  IF p_operation='dfir.alert.relationship.retract' THEN
    PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
      context_tenant,'alert',p_alert_id,p_resource_id
    );
  END IF;
  -- ALERT_RELATIONSHIP_FRESH_AUTHORIZATION_V1
  SELECT * INTO reservation
  FROM app.private_reserve_alert_investigation_unretained_v1(
    p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
    p_key_digest,p_request_digest
  );$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship fresh reservation hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);

  needle:=$needle$    RETURN QUERY
    SELECT * FROM app.private_reserve_alert_investigation_unretained_v1(
      p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
      p_key_digest,p_request_digest
    );
    RETURN;$needle$;
  replacement:=$replacement$    SELECT * INTO reservation
    FROM app.private_reserve_alert_investigation_unretained_v1(
      p_command_id,p_alert_id,p_operation,p_resource_id,p_result_version,
      p_key_digest,p_request_digest
    );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Alert replay returned no coordinate'
        USING ERRCODE='55000';
    END IF;
    IF p_operation IN (
      'dfir.alert.relationship.create','dfir.alert.relationship.retract'
    ) THEN
      PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
        context_tenant,'alert',p_alert_id,p_resource_id
      );
    END IF;
    -- ALERT_RELATIONSHIP_REPLAY_AUTHORIZATION_V1
    RETURN QUERY SELECT reservation.command_id::uuid,
      reservation.result_resource_id::uuid,
      reservation.result_version::bigint,
      reservation.result_snapshot::jsonb,reservation.replayed::boolean;
    RETURN;$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship replay hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;

  SELECT pg_get_functiondef(
    'app.store_alert_investigation_command_result_v1(uuid,jsonb)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$  SELECT app.private_store_alert_investigation_result_unretained_v1(
    p_command_id,p_result_snapshot
  ) INTO stored;$needle$;
  replacement:=$replacement$  IF command_record.operation IN (
    'dfir.alert.relationship.create','dfir.alert.relationship.retract'
  ) THEN
    PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
      context_tenant,'alert',command_record.alert_id,
      command_record.resource_id
    );
    IF app.private_dfir_json_object_shape_v1(
         p_result_snapshot,ARRAY['kind','relationship'],
         ARRAY['kind','relationship']
       ) IS NOT TRUE
       OR p_result_snapshot->>'kind'<>'alert_relationship'
       OR app.private_dfir_relationship_projection_matches_v1(
         p_result_snapshot->'relationship',context_tenant,'alert',
         command_record.alert_id,command_record.operation,
         command_record.resource_id,NULL,command_record.result_version,true
       ) IS NOT TRUE THEN
      RAISE EXCEPTION 'Alert relationship result snapshot is invalid'
        USING ERRCODE='22023';
    END IF;
  END IF;
  -- ALERT_RELATIONSHIP_EXACT_SNAPSHOT_V1
  SELECT app.private_store_alert_investigation_result_unretained_v1(
    p_command_id,p_result_snapshot
  ) INTO stored;$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship store hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;

  SELECT pg_get_functiondef(
    'app.create_alert_dfir_relationship_v1(uuid,uuid,uuid,public.dfir_entity_kind,uuid,text,text,public.dfir_entity_kind,uuid,text,text,text,jsonb,timestamp with time zone)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$     OR p_created_at IS NULL OR p_created_at > transaction_timestamp() + interval '5 minutes'
     OR NOT ((p_source_kind = 'alert' AND p_source_id = p_alert_id)
          OR (p_target_kind = 'alert' AND p_target_id = p_alert_id)) THEN$needle$;
  replacement:=$replacement$     OR p_created_at IS NULL OR p_created_at > transaction_timestamp() + interval '5 minutes' THEN$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship endpoint anchor drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  needle:=$needle$    WHERE relationship.tenant_id = context_tenant
      AND relationship.source_kind = p_source_kind$needle$;
  replacement:=$replacement$    WHERE relationship.tenant_id = context_tenant
      AND relationship.alert_id = p_alert_id
      AND relationship.case_id IS NULL
      AND relationship.source_kind = p_source_kind$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship duplicate root scope drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;

  SELECT pg_get_functiondef(
    'app.retract_case_dfir_relationship_v1(uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$  IF NOT (
    target.source_kind='case' AND target.source_id=p_case_id
    OR target.target_kind='case' AND target.target_id=p_case_id
  ) THEN
    RAISE EXCEPTION 'Case relationship root binding is invalid'
      USING ERRCODE='23503';
  END IF;$needle$;
  replacement:=$replacement$  PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
    context_tenant,'case',p_case_id,p_relationship_id
  );$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Case relationship retraction root anchor drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;

  SELECT pg_get_functiondef(
    'app.retract_alert_dfir_relationship_v1(uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone)'::regprocedure
  ) INTO function_definition;
  needle:=$needle$  IF NOT FOUND THEN RAISE EXCEPTION 'Alert relationship was not found' USING ERRCODE = 'P0002'; END IF;
  IF target.version IS DISTINCT FROM p_expected_version THEN$needle$;
  replacement:=$replacement$  IF NOT FOUND THEN RAISE EXCEPTION 'Alert relationship was not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM app.private_assert_current_dfir_relationship_for_root_v1(
    context_tenant,'alert',p_alert_id,p_relationship_id
  );
  IF target.version IS DISTINCT FROM p_expected_version THEN$replacement$;
  occurrence_count:=(length(function_definition)-length(replace(
    function_definition,needle,''
  )))/length(needle);
  IF occurrence_count<>1 THEN
    RAISE EXCEPTION 'Alert relationship retraction authorization hook drifted'
      USING ERRCODE='55000';
  END IF;
  function_definition:=replace(function_definition,needle,replacement);
  EXECUTE function_definition;
END;
$dfir_generic_relationship_patch_v1$;
--> statement-breakpoint

DO $dfir_generic_relationship_contract_v1$
DECLARE
  boundary regprocedure;
  definition text;
  constraint_record record;
BEGIN
  FOREACH boundary IN ARRAY ARRAY[
    'app.private_dfir_relationship_runtime_write_v1()'::regprocedure,
    'app.private_dfir_relationship_endpoint_valid_for_root_v1(uuid,public.dfir_mutation_root_kind,uuid,public.dfir_entity_kind,uuid,text,text,boolean)'::regprocedure,
    'app.private_assert_current_dfir_relationship_for_root_v1(uuid,public.dfir_mutation_root_kind,uuid,uuid)'::regprocedure,
    'app.private_dfir_relationship_projection_matches_v1(jsonb,uuid,public.dfir_mutation_root_kind,uuid,text,uuid,uuid,bigint,boolean)'::regprocedure,
    'app.private_dfir_mutation_snapshot_valid_root_anchored_v1(jsonb,uuid,public.dfir_mutation_root_kind,uuid,text,text,uuid,uuid,bigint)'::regprocedure
  ]
  LOOP
    IF has_function_privilege('periapsis_api',boundary,'EXECUTE')
       OR has_function_privilege('periapsis_worker',boundary,'EXECUTE')
       OR has_function_privilege('public',boundary,'EXECUTE') THEN
      RAISE EXCEPTION 'private generic relationship ABI is executable: %',
        boundary USING ERRCODE='55000';
    END IF;
  END LOOP;

  SELECT pg_get_functiondef(
    'app.reserve_dfir_mutation_command_v1(uuid,public.dfir_mutation_root_kind,uuid,text,text,uuid,uuid,bigint,bytea,bytea)'::regprocedure
  ) INTO definition;
  IF strpos(definition,'GENERIC_RELATIONSHIP_CURRENT_AUTHORIZATION_V1')=0
     OR strpos(definition,'GENERIC_RELATIONSHIP_REPLAY_AUTHORIZATION_V1')=0
  THEN
    RAISE EXCEPTION 'generic relationship replay authorization is absent'
      USING ERRCODE='55000';
  END IF;

  SELECT pg_get_functiondef(
    'app.reserve_alert_investigation_command_v1(uuid,uuid,text,uuid,bigint,bytea,bytea)'::regprocedure
  ) INTO definition;
  IF strpos(definition,'RELATIONSHIP_REPLAY_AUTHORIZATION_HOOK_V1')=0
     OR strpos(definition,'ALERT_RELATIONSHIP_FRESH_AUTHORIZATION_V1')=0
     OR strpos(definition,'ALERT_RELATIONSHIP_REPLAY_AUTHORIZATION_V1')=0
  THEN
    RAISE EXCEPTION 'Alert relationship replay authorization is absent'
      USING ERRCODE='55000';
  END IF;

  SELECT pg_get_functiondef(
    'app.store_alert_investigation_command_result_v1(uuid,jsonb)'::regprocedure
  ) INTO definition;
  IF strpos(definition,'ALERT_RELATIONSHIP_EXACT_SNAPSHOT_V1')=0 THEN
    RAISE EXCEPTION 'Alert relationship exact snapshot validation is absent'
      USING ERRCODE='55000';
  END IF;

  SELECT pg_get_functiondef(
    'app.create_alert_dfir_relationship_v1(uuid,uuid,uuid,public.dfir_entity_kind,uuid,text,text,public.dfir_entity_kind,uuid,text,text,text,jsonb,timestamp with time zone)'::regprocedure
  ) INTO definition;
  IF strpos(definition,
       'relationship.alert_id = p_alert_id')=0
     OR strpos(definition,
       'p_source_kind = ''alert'' AND p_source_id = p_alert_id')>0 THEN
    RAISE EXCEPTION 'Alert relationship create remains endpoint-anchored'
      USING ERRCODE='55000';
  END IF;

  SELECT pg_get_functiondef(
    'app.retract_case_dfir_relationship_v1(uuid,uuid,uuid,bigint,uuid,text,timestamp with time zone)'::regprocedure
  ) INTO definition;
  IF strpos(definition,
       'private_assert_current_dfir_relationship_for_root_v1')=0
     OR strpos(definition,
       'target.source_kind=''case'' AND target.source_id=p_case_id')>0 THEN
    RAISE EXCEPTION 'Case relationship retract remains endpoint-anchored'
      USING ERRCODE='55000';
  END IF;

  FOR constraint_record IN
    SELECT constraint_row.conname,
           pg_get_constraintdef(constraint_row.oid) AS definition
    FROM pg_constraint AS constraint_row
    WHERE constraint_row.conname=ANY(ARRAY[
      'dfir_mutation_resource_ids_tenant_id_tenants_id_fk',
      'dfir_mutation_replay_keys_tenant_id_tenants_id_fk',
      'dfir_mutation_commands_tenant_id_tenants_id_fk',
      'dfir_mutation_command_results_tenant_id_tenants_id_fk',
      'dfir_ticket_command_retentions_tenant_id_tenants_id_fk'
    ])
  LOOP
    IF constraint_record.definition NOT LIKE
         'FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT'
       OR constraint_record.definition LIKE '%ON UPDATE CASCADE%' THEN
      RAISE EXCEPTION 'DFIR tenant FK drifted: %',constraint_record.conname
        USING ERRCODE='55000';
    END IF;
  END LOOP;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DFIR tenant FK contract is unavailable'
      USING ERRCODE='55000';
  END IF;
END;
$dfir_generic_relationship_contract_v1$;
-- DFIR_GENERIC_RELATIONSHIP_ROOT_CONTEXT_V1_END
-- AUTHORIZATION_CURRENT_HUMAN_GRANTS_AND_MEMBER_LIFECYCLE_V1_BEGIN
-- Current replicas use explicit human-role grant ABIs; predecessor mutation
-- guards stay closed to policy keys they cannot represent. Tenant serialization,
-- exact live delegation, immutable request keys, audit and supersession are kept.
CREATE FUNCTION app.private_assert_current_human_role_grant_v1(
  p_role_id uuid, p_expires_at timestamp with time zone, p_fresh boolean
)
RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, app
AS $function$
DECLARE
  context_tenant uuid := app.context_tenant_id();
  actor_user uuid := app.context_user_id();
  target_kind public.tenant_principal_kind;
  target_archived timestamp with time zone;
  permission_tuple record;
BEGIN
  IF p_fresh IS NULL THEN
    RAISE EXCEPTION 'human role grant mode is required' USING ERRCODE='22023';
  END IF;
  IF p_fresh AND p_expires_at IS NOT NULL
     AND p_expires_at <= transaction_timestamp() THEN
    RAISE EXCEPTION 'role grant expiry must be in the future'
      USING ERRCODE='22023';
  END IF;
  SELECT role.principal_kind, role.archived_at
    INTO target_kind, target_archived
  FROM public.tenant_roles AS role
  WHERE role.tenant_id=context_tenant AND role.id=p_role_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant role was not found' USING ERRCODE='P0002';
  END IF;
  IF target_kind IS DISTINCT FROM 'human' THEN
    RAISE EXCEPTION 'human role grant cannot target a machine role'
      USING ERRCODE='55000';
  END IF;
  IF p_fresh AND target_archived IS NOT NULL THEN
    RAISE EXCEPTION 'active tenant role was not found' USING ERRCODE='P0002';
  END IF;
  -- Replays may describe an expired grant or an archived role. They still
  -- require the caller's current exact human delegation for every policy tuple.
  FOR permission_tuple IN
    SELECT permission.key, policy.scope
    FROM public.tenant_role_permissions AS policy
    JOIN public.tenant_permissions AS permission ON permission.id=policy.permission_id
    WHERE policy.tenant_id=context_tenant AND policy.role_id=p_role_id
  LOOP
    IF NOT app.tenant_human_can_delegate_exact_permission_v3(
      context_tenant, actor_user, permission_tuple.key,
      permission_tuple.scope, p_expires_at
    ) THEN
      RAISE EXCEPTION 'role grant exceeds the exact delegation ceiling or lifetime'
        USING ERRCODE='42501';
    END IF;
  END LOOP;
END;
$function$;
